window.BANK=[{"id":1,"ch":1,"t":"s","q":"化学实验室中发生最为频繁的一类创伤事故通常是（　）。","o":["冻伤事故","割伤事故（多为玻璃割伤）","雷击事故","挤压事故"],"a":"B","e":"玻璃仪器使用广泛、易碎，操作不当造成的割伤是化学实验室最常见的创伤事故。"},{"id":2,"ch":1,"t":"s","q":"海因里希法则揭示的事故数量统计关系是（　）。","o":["严重伤害:轻微伤害:无伤害约为1:29:300","死亡:重伤:轻伤约为1:1:1","火灾:爆炸:中毒约为3:2:1","事故:隐患:违章约为100:10:1"],"a":"A","e":"海因里希通过对大量事故的统计提出严重伤害:轻微伤害:无伤害约为1:29:300。"},{"id":3,"ch":1,"t":"s","q":"提出事故致因“瑞士奶酪模型”的学者是（　）。","o":["海因里希","法默","里森（Reason）","帕累托"],"a":"C","e":"瑞士奶酪模型由英国心理学家里森（James Reason）提出，用于解释事故的多重防线失效。"},{"id":4,"ch":1,"t":"s","q":"“安全文化”这一概念最早源于对下列哪一事故的反思（　）。","o":["三哩岛核事故","切尔诺贝利核事故","博帕尔毒气泄漏事故","瑞士桑多兹化工厂火灾"],"a":"B","e":"1986年切尔诺贝利核事故后，国际核安全咨询组（INSAG）在总结中率先提出“安全文化”概念。"},{"id":5,"ch":1,"t":"s","q":"我国安全生产工作的基本方针是（　）。","o":["安全第一、预防为主","生产优先、兼顾安全","效率第一、安全托底","事后追责、事前放任"],"a":"A","e":"我国安全生产长期坚持“安全第一、预防为主（、综合治理）”的方针，实验室安全管理同样遵循。"},{"id":6,"ch":1,"t":"s","q":"燃烧发生必须同时具备的三个条件中，不包括（　）。","o":["可燃物","助燃物（氧化剂）","点火源（着火源）","惰性气体"],"a":"D","e":"燃烧三要素为可燃物、助燃物和点火源，惰性气体不参与燃烧，还可用于阻燃抑爆。"},{"id":7,"ch":1,"t":"s","q":"化学毒物进入人体最主要的途径通常是（　）。","o":["经呼吸道吸入","经皮肤吸收","经消化道摄入","经伤口注射"],"a":"A","e":"实验室中气体、蒸气、粉尘形态的毒物经呼吸道吸入，吸收快、危害最大，是最主要的中毒途径。"},{"id":8,"ch":1,"t":"s","q":"事故的直接原因是指（　）。","o":["教育培训不足","管理监督缺位","人的不安全行为和物的不安全状态","法规标准不健全"],"a":"C","e":"直接原因是事故发生的近因，即人的不安全行为与物的不安全状态；教育、管理缺陷属于间接原因。"},{"id":9,"ch":1,"t":"s","q":"“三不伤害”原则中不包括的内容是（　）。","o":["不伤害自己","不伤害他人","不被他人伤害","不损坏仪器设备"],"a":"D","e":"三不伤害指不伤害自己、不伤害他人、不被他人伤害，设备保护不属于其内容。"},{"id":10,"ch":1,"t":"s","q":"高校三级安全教育在校（院）级和院系级之外，还包括（　）。","o":["国家级","省级","市级","实验室级"],"a":"D","e":"三级安全教育指学校级、院系级和实验室级，逐级落实，实验室级最贴近岗位实际。"},{"id":11,"ch":1,"t":"s","q":"事故金字塔给安全管理最重要的启示是（　）。","o":["重大事故纯属偶然","只需统计死亡和重伤事故","伤亡事故只是金字塔顶端，预防应从减少底层事件做起","隐患与事故之间没有联系"],"a":"C","e":"金字塔显示无伤害事件数量庞大，削减底层事件才能有效防止顶端重大事故。"},{"id":12,"ch":1,"t":"s","q":"瑞士奶酪模型中，奶酪上的“孔洞”代表（　）。","o":["实验室建筑的通风孔","各层安全防线上存在的缺陷漏洞","奶酪生产的工艺缺陷","通风柜的排风口"],"a":"B","e":"每片奶酪是一层防线，孔洞是该层防线的缺陷；各层孔洞连成一线时事故发生。"},{"id":13,"ch":1,"t":"s","q":"GB 13690 是关于（　）的国家标准。","o":["化学品分类和危险性公示","危险化学品重大危险源辨识","建筑设计防火","爆炸危险环境电力装置"],"a":"A","e":"GB 13690《化学品分类和危险性公示 通则》规定了化学品危险性分类与公示的基本要求。"},{"id":14,"ch":1,"t":"s","q":"实验室安全标志中，蓝底白图的“必须戴防护眼镜”标志属于（　）。","o":["禁止标志","警告标志","指令标志","提示标志"],"a":"C","e":"蓝色圆形为指令标志，强制要求采取防护行动；禁止为红圈斜杠，警告为黄色三角，提示为绿色。"},{"id":15,"ch":1,"t":"s","q":"高校实验室安全管理普遍实行的体制是（　）。","o":["学校、院系、实验室三级管理，分级负责","学校统一包揽，基层无需负责","保卫处一家独立负责","实验室负责人各自为政"],"a":"A","e":"高校普遍实行校、院系、实验室三级安全管理体制，层层落实安全责任。"},{"id":16,"ch":1,"t":"s","q":"实验室安全工作的现场直接责任人一般是（　）。","o":["校长","实验室负责人（安全责任人）","教学秘书","后勤维修人员"],"a":"B","e":"实验室负责人是本实验室安全的直接责任人，负责日常管理与现场安全。"},{"id":17,"ch":1,"t":"s","q":"研究生导师对学生实验安全应承担的主要职责是（　）。","o":["代替学生完成危险操作","只负责科研进度考核","对学生进行安全教育、指导与监督","负责实验材料的报销"],"a":"C","e":"导师应把安全教育融入科研指导，督促学生遵守规程，对学生的实验安全负有指导监督责任。"},{"id":18,"ch":1,"t":"s","q":"关于学生在实验室安全中的地位，最恰当的表述是（　）。","o":["安全与我无关，出事由学校负责","学生是安全的直接受益者，也是责任的共同承担者","学生只是实验室的临时过客","安全完全是导师和安全员的事"],"a":"B","e":"学生既是实验室安全的直接受益者，也必须自觉遵章守规，共同承担安全责任。"},{"id":19,"ch":1,"t":"s","q":"实验室安全准入制度的核心要求是（　）。","o":["可先实验、后补培训","凭学生证自由进入","只对新生适用","经安全培训并考核合格后方可进入"],"a":"D","e":"准入制度要求先培训、后考核、合格准入，未经培训考核合格不得进入实验室开展实验。"},{"id":20,"ch":1,"t":"s","q":"下列事故中属于化学灼伤的是（　）。","o":["被破损烧杯口割破手指","浓碱液溅到皮肤造成组织损伤","湿手触碰电器被电击","长期噪声致听力下降"],"a":"B","e":"酸、碱等腐蚀性化学品接触皮肤黏膜造成的损伤为化学灼伤；割伤、电击、噪声伤害不属于灼伤。"},{"id":21,"ch":1,"t":"s","q":"下列属于电离辐射的是（　）。","o":["无线电波","可见光","X射线","红外线"],"a":"C","e":"X射线能量足以使原子电离，属电离辐射；无线电波、可见光、红外线均属非电离辐射。"},{"id":22,"ch":1,"t":"s","q":"事故的间接原因通常指（　）。","o":["教育培训不足、管理缺陷等深层次因素","操作中的具体失误动作","设备运转的具体故障","人体受伤害的具体形式"],"a":"A","e":"间接原因包括教育培训不足、规章制度与监督管理缺陷等，是导致直接原因存在的深层条件。"},{"id":23,"ch":1,"t":"s","q":"实验室安全文化的核心是（　）。","o":["以罚款代替管理","张贴标语走形式","应付上级的检查","人人认同安全价值观并自觉规范行为"],"a":"D","e":"安全文化的内核是共同的价值观与自觉的行为方式，体现为“我要安全”而非“要我安全”。"},{"id":24,"ch":1,"t":"s","q":"化学实验室火灾爆炸事故最主要的诱因是（　）。","o":["气候异常干燥","建筑年久必然起火","纯粹出于运气不佳","违规操作与易燃易爆品管理不当"],"a":"D","e":"绝大多数实验室火灾爆炸源于违规操作、易燃易爆品存放使用不当等人为可控因素。"},{"id":25,"ch":1,"t":"s","q":"皮肤溅到浓酸发生化学灼伤后，第一步应当（　）。","o":["涂抹牙膏等民间“偏方”","用干净布包裹待其自愈","立即用碱液中和创面","立即用大量流动清水冲洗"],"a":"D","e":"化学灼伤急救首先是迅速用大量流动清水长时间冲洗，稀释并带走化学物质，忌盲目中和。"},{"id":26,"ch":1,"t":"s","q":"《危险化学品安全管理条例》的制定发布机关是（　）。","o":["全国人大常委会","最高人民法院","国务院","应急管理部"],"a":"C","e":"该条例是国务院发布的行政法规，对危险化学品生产、储存、使用、经营、运输等实施安全管理。"},{"id":27,"ch":1,"t":"s","q":"安全标志中黄底黑边三角形的“当心腐蚀”标志属于（　）。","o":["禁止标志","警告标志","指令标志","提示标志"],"a":"B","e":"黄底黑边三角形是警告标志，提醒注意周围环境中的潜在危险。"},{"id":28,"ch":1,"t":"s","q":"实验室安全自查与巡查的首要目的是（　）。","o":["及时发现并消除事故隐患","增加师生的日常工作量","评比排名发放奖金","留痕应付上级的检查"],"a":"A","e":"自查巡查是发现人的不安全行为与物的不安全状态、把事故消灭在萌芽状态的重要手段。"},{"id":29,"ch":1,"t":"s","q":"下列属于我国安全生产领域综合性法律的是（　）。","o":["《消防法》","《安全生产法》","《危险化学品安全管理条例》","GB 2894"],"a":"B","e":"《安全生产法》是安全生产领域的基本法律，消防法为专门法律，条例是行政法规，GB 2894是国家标准。"},{"id":30,"ch":1,"t":"s","q":"安全管理中的“事故隐患”是指（　）。","o":["已经造成人员伤亡的事件","洪水地震等自然灾害","实验数据的正常波动","可能导致事故的不安全状态、不安全行为和管理缺陷"],"a":"D","e":"隐患是事故的前兆与潜在原因，可被排查发现并通过治理消除，预防事故关键在治隐患。"},{"id":31,"ch":1,"t":"s","q":"高校实验室三级安全教育中的“三级”指的是：","o":["校级、省级、国家级","学校级、院系级、实验室级","班级、年级、学校级","本科生、研究生、教职工"],"a":"B","e":"三级安全教育指学校、院系（部门）和实验室三个层级开展的安全教育。"},{"id":32,"ch":1,"t":"s","q":"新进实验室的人员在开展实验前应当：","o":["先接受安全教育培训并通过准入考试","直接开始实验，边做边学","只需认真阅读实验讲义","由同实验室同学口头交代一下"],"a":"A","e":"准入制度要求先培训、考核合格后方可进入实验室开展实验。"},{"id":33,"ch":1,"t":"s","q":"GB 13690 是一项关于什么的强制性国家标准？","o":["实验室建筑设计防火","工业废水综合排放","电气装置安装施工","常用危险化学品的分类及标志"],"a":"D","e":"GB 13690《常用危险化学品的分类及标志》规定了常用危险化学品的分类和相应标志。"},{"id":34,"ch":1,"t":"s","q":"《危险化学品安全管理条例》在法律效力层级上属于：","o":["全国人大常委会通过的法律","国务院颁布的行政法规","地方人民代表大会制定的地方性法规","行业主管部门的推荐性标准"],"a":"B","e":"该条例由国务院公布，属于行政法规。"},{"id":35,"ch":1,"t":"s","q":"“三不伤害”原则的正确内容是：","o":["不伤害自己、不伤害他人、不被他人伤害","不损坏设备、不污染环境、不浪费药品","不迟到、不早退、不擅自离岗","不违章操作、不隐瞒事故、不推卸责任"],"a":"A","e":"三不伤害指不伤害自己、不伤害他人、不被他人伤害。"},{"id":36,"ch":1,"t":"s","q":"安全色中红色代表的基本含义是：","o":["提示与通行","指令与遵守","警告与注意","禁止与停止"],"a":"D","e":"红色表示禁止、停止等含义，用于禁止标志。"},{"id":37,"ch":1,"t":"s","q":"安全色中黄色的基本含义是：","o":["警告、注意","禁止、停止","指令、必须遵守","提示、安全状态"],"a":"A","e":"黄色表示警告、注意，用于警告标志。"},{"id":38,"ch":1,"t":"s","q":"实验室安全教育的首要目的是：","o":["应付上级和检查组的检查","完成培养方案规定的学时","增强安全意识与防护技能，防止事故发生","提升学校的知名度"],"a":"C","e":"安全教育的首要目的是增强师生安全意识与防护技能，从源头防止事故。"},{"id":39,"ch":1,"t":"s","q":"禁止标志的几何图形特征是：","o":["圆环加斜杠","等边三角形","正方形","菱形"],"a":"A","e":"禁止标志为带斜杠的圆环图形，表示禁止某种行为。"},{"id":40,"ch":1,"t":"s","q":"警告标志的几何图形是：","o":["带斜杠的圆环","圆形","三角形","正方形"],"a":"C","e":"警告标志采用三角形、黄底黑边图形，提醒注意危险。"},{"id":41,"ch":1,"t":"s","q":"《中华人民共和国消防法》确立的消防工作方针是：","o":["安全第一、预防为主","预防为主、防消结合","防消并举、以消为主","全民消防、预防为辅"],"a":"B","e":"消防工作贯彻“预防为主、防消结合”的方针。"},{"id":42,"ch":1,"t":"s","q":"实验室日常安全自查的责任主体主要是：","o":["实验室负责人及在室工作的师生","学校保卫部门","后勤物业人员","仪器厂商的维护人员"],"a":"A","e":"实验室负责人及在室人员是自查的第一责任主体，保卫部门负责监督。"},{"id":43,"ch":1,"t":"s","q":"关于实验室安全自查的正确做法是：","o":["集中突击检查一次，长期有效","定期开展，发现问题记录在案并及时整改","仅在上级来检查前临时准备","只检查大型贵重仪器"],"a":"B","e":"自查应定期开展、如实记录并及时整改，形成闭环管理。"},{"id":44,"ch":1,"t":"s","q":"海因里希法则（事故金字塔）给我们的启示是：","o":["重大事故纯属偶然，无法预防","未造成伤亡的小事故无需关注","事故风险完全取决于设备质量","只有减少不安全行为和隐患，才能减少重大事故"],"a":"D","e":"事故金字塔表明大量不安全行为和隐患背后隐藏着重大事故，须从基础抓起。"},{"id":45,"ch":1,"t":"s","q":"实验中发现操作规程与实际情况不符时，正确的做法是：","o":["按个人想法随意操作","继续照做，出了问题再说","停止操作，及时向导师或实验室负责人反映","自行修改规程且不告知他人"],"a":"C","e":"发现规程与实际不符应停止操作并及时反映，由责任主体修订完善。"},{"id":46,"ch":1,"t":"s","q":"实验操作规程的主要作用是：","o":["增加实验的操作步骤","规范操作行为，减少人为失误和事故","便于管理部门统计工作量","限制实验研究的进度"],"a":"B","e":"操作规程用于规范操作行为，减少人为失误，预防事故发生。"},{"id":47,"ch":1,"t":"s","q":"进入化学实验室工作时的着装要求是：","o":["按要求穿实验服，必要时佩戴防护眼镜","天热时可穿凉鞋、短裤","只要不裸露双手即可","仅在老师检查时才穿实验服"],"a":"A","e":"进入化学实验室应穿实验服，必要时佩戴防护眼镜等个人防护用品。"},{"id":48,"ch":1,"t":"s","q":"实验过程中发现安全隐患，应当首先：","o":["不论大小一律自行处理","不予理会，继续实验","及时报告老师或实验室负责人","拍照记录后离开现场"],"a":"C","e":"发现隐患应及时报告，由具备处置能力的人员或负责人组织处理。"},{"id":49,"ch":1,"t":"s","q":"按 GB 13690 的分类，常用危险化学品共分为：","o":["3 大类","5 大类","6 大类","8 大类"],"a":"D","e":"GB 13690 将常用危险化学品分为爆炸品、压缩气体和液化气体、易燃液体等八大类。"},{"id":50,"ch":1,"t":"s","q":"对本科生化学实验安全教育的一般安排是：","o":["不作专门安排，由学生自学","在第一门实验课开始时讲授安全知识并考核","毕业实习前集中补课","只对研究生开设"],"a":"B","e":"本科生一般在第一门实验课开始时接受安全教育并考核。"},{"id":51,"ch":1,"t":"s","q":"研究生实验室安全教育在培养环节中的定位是：","o":["进入课题组开展实验前的必要环节，不少学校设为必修或考核环节","可有可无的选修内容","与科研训练无关的内容","只需导师口头提醒即可"],"a":"A","e":"研究生进入课题组开展实验前必须接受安全教育，很多学校设为必修环节。"},{"id":52,"ch":1,"t":"s","q":"实验中发生初起小火且火势可控时，应当：","o":["立即逃离，不作任何处置","就近取用灭火器材扑救，同时报告","躲避等待火自行熄灭","继续实验，静观其变"],"a":"B","e":"初起小火应就近用灭火器材扑救并报告，防止火势蔓延。"},{"id":53,"ch":1,"t":"s","q":"对暂不能立即整改的事故隐患，正确的处理方式是：","o":["视而不见，暂不处理","直接锁闭实验室一走了之","等上级检查时再作说明","采取临时防控措施并及时上报"],"a":"D","e":"不能立即整改的隐患应采取临时防控措施并及时上报，跟踪落实整改。"},{"id":54,"ch":1,"t":"s","q":"对待实验室安全规章制度的态度应该是：","o":["严格遵照执行，发现不完善之处及时反映","根据个人情况灵活变通","只执行其中方便的部分","他人不遵守时自己也可不遵守"],"a":"A","e":"安全规章制度必须严格遵守，发现问题应通过正规渠道反映完善。"},{"id":55,"ch":1,"t":"s","q":"管理人员发现学生违章操作时，应当：","o":["视而不见，避免得罪人","立即制止并进行批评教育","等发生事故后再处理","只作记录，不作干预"],"a":"B","e":"发现违章操作应立即制止并批评教育，防止酿成事故。"},{"id":56,"ch":1,"t":"s","q":"“当心火灾”“当心中毒”等警示标识属于：","o":["禁止标志","指令标志","警告标志","提示标志"],"a":"C","e":"“当心××”类标识提醒注意危险，属于警告标志。"},{"id":57,"ch":1,"t":"s","q":"实验室准入考试未通过的人员：","o":["由导师担保后即可进入","可先做危险性小的实验","须重新参加培训并通过考核，此前不得独立开展实验","与他人同在一间实验室即可照常实验"],"a":"C","e":"准入考核不合格者须重新培训、考核合格后方可独立开展实验。"},{"id":58,"ch":1,"t":"s","q":"根据海因里希法则（事故金字塔），对大量事故的统计表明：每发生 1 起造成重大伤害的事故，其背后大约还对应多少起轻微伤害事故和多少起无伤害的意外事件？","o":["10 起轻微伤害事故、100 起无伤害事件","19 起轻微伤害事故、290 起无伤害事件","29 起轻微伤害事故、300 起无伤害事件","39 起轻微伤害事故、400 起无伤害事件"],"a":"C","e":"海因里希（H. W. Heinrich）对约 55 万起工伤事故的统计分析得出 1∶29∶300 的比例：每 1 起重伤或死亡事故背后，约有 29 起轻伤事故和 300 起未造成伤害但同样危险的事件（事故金字塔）。该法则说明必须重视无伤害的隐患和未遂事件，把它们消灭在萌芽状态，才能防止重大事故发生。"},{"id":59,"ch":1,"t":"s","q":"高校实验室普遍实行\"三级安全教育\"制度，新进入实验室学习或工作的人员必须逐级接受安全教育并考核合格。这里的\"三级\"指的是哪三级？","o":["学校、省教育厅、教育部","学校（校级）、院系（院级）、实验室（室级）","实验课教师、研究生导师、实验室安全员","入门教育、上岗教育、年度继续教育"],"a":"B","e":"三级安全教育指校级、院（系）级和实验室级三个层面的安全教育：校级侧重全校性安全法规与常识，院系级结合本学科专业特点讲授危险因素与防护要求，实验室级针对具体仪器、试剂和操作规程进行培训，逐级考核合格并签字存档后方可进入实验室。"},{"id":60,"ch":1,"t":"s","q":"实验室发生事故后，事故的调查与处理要坚持\"四不放过\"原则。下列选项中，哪一项不属于\"四不放过\"的内容？","o":["事故伤亡人员的赔偿未落实不放过","事故原因未查清不放过","事故责任人员未受到处理不放过","整改措施未落实不放过"],"a":"A","e":"\"四不放过\"指：事故原因未查清不放过、责任人员未受到处理不放过、整改措施未落实不放过、有关人员（群众）未受到教育不放过。\"赔偿未落实\"不属于其中内容，其精神在于查清原因、落实责任、吸取教训、防止同类事故再次发生，而非经济赔偿。"},{"id":61,"ch":1,"t":"m","q":"化学实验室常见的安全事故类型包括（　）。","o":["火灾与爆炸","中毒与窒息","化学灼伤","玻璃割伤","合同纠纷"],"a":"ABCD","e":"教材将火灾爆炸、中毒、灼伤、割伤、触电、辐射、生物危害等列为实验室常见事故类型。"},{"id":62,"ch":1,"t":"m","q":"对海因里希法则（1:29:300）的正确理解包括（　）。","o":["该比例指严重伤害、轻微伤害与无伤害事故的统计关系","大量无伤害事件背后潜伏着引发严重事故的因素","重视并消除未遂事件有助于防止重大事故","该法则证明重大事故纯属随机不可预防","只要无人员伤亡就不必统计事件"],"a":"ABC","e":"法则揭示事故数量的金字塔式分布，强调从小事件抓起；重大事故并非纯随机，无伤害事件也须统计分析。"},{"id":63,"ch":1,"t":"m","q":"关于瑞士奶酪模型，下列说法正确的有（　）。","o":["每片奶酪代表一层安全防线","奶酪上的孔洞代表该层防线的缺陷","当各层孔洞恰好连成一线时事故便会发生","该模型主张只需一层防线即可保证安全","该模型体现了纵深防御的思想"],"a":"ABCE","e":"模型强调多层设防、纵深防御；任何单层防线都有失效可能，不能依赖单一防线。"},{"id":64,"ch":1,"t":"m","q":"下列行为属于人的不安全行为的有（　）。","o":["不佩戴规定的防护眼镜","独自一人违规进行危险实验","实验前检查通风柜是否正常","擅自加大试剂用量","实验后如实记录异常现象"],"a":"ABD","e":"不戴防护用品、违规独自操作、擅改用量均属不安全行为；检查设备与如实记录是安全行为。"},{"id":65,"ch":1,"t":"m","q":"属于事故管理方面间接原因的有（　）。","o":["隐患排查治理规范且落实到位","安全教育培训流于形式","规章制度不健全或执行不力","安全管理责任不明确","规程完善且严格执行"],"a":"BCD","e":"培训形式化、制度不健全、责任不明是典型的管理缺陷即间接原因；A、E是管理到位的表现。"},{"id":66,"ch":1,"t":"m","q":"实验室安全文化的内涵包括（　）。","o":["共同的安全价值观","自觉遵守安全规范的行为习惯","人人重视安全的态度与氛围","人人参与、人人负责的责任意识","仅由安全员一人负责"],"a":"ABCD","e":"安全文化是群体共享的安全价值观与相应行为规范的总和，须全员参与共建。"},{"id":67,"ch":1,"t":"m","q":"高校实验室安全责任体系中的责任主体包括（　）。","o":["学校","院系","实验室负责人","导师","与实验室无关的物业公司"],"a":"ABCD","e":"责任体系涵盖学校、院系、实验室负责人、导师和学生，层层有责、人人有责。"},{"id":68,"ch":1,"t":"m","q":"化学毒物侵入人体的途径包括（　）。","o":["经呼吸道吸入","经皮肤黏膜吸收","经消化道摄入","经视觉传导","经听觉传导"],"a":"ABC","e":"毒物侵入途径为呼吸道、皮肤黏膜和消化道；视觉、听觉并非毒物吸收途径。"},{"id":69,"ch":1,"t":"m","q":"下列属于物的不安全状态的有（　）。","o":["通风柜故障失效","电气线路老化裸露","试剂按规定分类存放","废液桶无标签标识","气瓶未固定随意放置"],"a":"ABDE","e":"设备失效、线路裸露、无标识、气瓶未固定均为物的不安全状态；规范存放试剂属于安全状态。"},{"id":70,"ch":1,"t":"m","q":"关于实验室安全准入制度，正确的说法有（　）。","o":["未经培训考核即可直接进入实验室","进入实验室前须接受安全教育培训","须通过安全知识考核合格后方可进入","考核不合格者应重新学习并补考","准入考试只需走形式应付即可"],"a":"BCD","e":"准入制度坚持先培训、后考核、合格准入，不合格须补学补考，严禁形式化。"},{"id":71,"ch":1,"t":"m","q":"事故典型案例带给实验室人员的启示有（　）。","o":["多数事故与人的失误和违规行为有关","侥幸心理是酿成事故的重要诱因","案例都发生在别人身上与自己无关","严格制度并认真执行可大幅降低事故","应举一反三、及时排查整改自身隐患"],"a":"ABDE","e":"案例表明人为因素是事故主因，须克服侥幸心理，吸取他人教训、对照整改自身隐患。"},{"id":72,"ch":1,"t":"m","q":"与高校实验室安全直接相关的法律法规和标准包括（　）。","o":["《安全生产法》","《消防法》","《危险化学品安全管理条例》","GB 13690《化学品分类和危险性公示 通则》","《著作权法》"],"a":"ABCD","e":"前三部是安全领域法律法规，GB 13690是化学品分类公示标准；《著作权法》与实验室安全无关。"},{"id":73,"ch":1,"t":"m","q":"高校“三级安全教育”包括的层级是：","o":["学校级","院系级","实验室级","省级","国家级"],"a":"ABC","e":"三级安全教育由学校、院系、实验室三个层级构成。"},{"id":74,"ch":1,"t":"m","q":"实验室安全管理制度体系通常包括：","o":["安全责任制度","实验室准入制度","危险化学品管理制度","安全检查与事故报告制度","科研经费报销制度"],"a":"ABCD","e":"安全责任、准入、危化品管理、检查与报告等均属安全管理制度，经费报销不属于。"},{"id":75,"ch":1,"t":"m","q":"遵守实验操作规程的具体要求包括：","o":["实验前充分了解实验的危险性和注意事项","严格按照规程规定的步骤进行操作","实验前检查仪器设备是否完好","对不熟悉的操作凭感觉大胆尝试","结束实验后随手关闭水、电、气并整理台面"],"a":"ABCE","e":"凭感觉尝试不熟悉的操作严重违反规程，其余均为遵守规程的要求。"},{"id":76,"ch":1,"t":"m","q":"实验室安全自查的主要内容有：","o":["电气线路和用电是否规范","危险化学品存放是否合规","消防器材是否完好有效","通风等防护设施运行是否正常","办公电脑的品牌型号"],"a":"ABCD","e":"自查覆盖用电、危化品、消防、通风防护等方面，与电脑品牌无关。"},{"id":77,"ch":1,"t":"m","q":"与化学实验室安全直接相关的法律法规和标准有：","o":["《中华人民共和国安全生产法》","《中华人民共和国消防法》","《危险化学品安全管理条例》","《城市房地产管理法》","《广告法》"],"a":"ABC","e":"安全生产法、消防法、危化品安全管理条例直接规范实验室安全。"},{"id":78,"ch":1,"t":"m","q":"我国国家标准规定的安全色包括：","o":["红色","黄色","蓝色","绿色","紫色"],"a":"ABCD","e":"安全色为红、蓝、黄、绿四种，紫色不属于安全色。"},{"id":79,"ch":1,"t":"m","q":"实验室准入制度的一般要求包括：","o":["接受系统的安全教育培训","通过安全准入考试","熟悉实验室危险源和应急设施的位置","可自行决定是否参加培训","先开展实验、后补参加考试"],"a":"ABC","e":"准入制度要求先培训、后考核、合格后进入，培训不是可选项。"},{"id":80,"ch":1,"t":"m","q":"按国家标准，安全标志的类别有：","o":["禁止标志","警告标志","指令标志","提示标志","评比标志"],"a":"ABCD","e":"安全标志分为禁止、警告、指令、提示四大类。"},{"id":81,"ch":1,"t":"m","q":"安全巡查发现问题的正确处理方式：","o":["如实记录在案","能够整改的立即整改","整改后跟踪复查，防止隐患反弹","对重大隐患隐瞒不报","暂时无法整改的拖延不理"],"a":"ABC","e":"发现问题应记录、整改、复查形成闭环，隐瞒和拖延都会埋下事故隐患。"},{"id":82,"ch":1,"t":"m","q":"下列做法中符合实验室个人防护要求的有：","o":["接触危险化学品时佩戴防护眼镜","可能产生有毒气体的实验在通风橱内进行","不在实验室内存放和进食食物饮料","将饮料存放在实验冰箱中","穿着实验服进入食堂、宿舍"],"a":"ABC","e":"实验冰箱不得存放食品，实验服也不应穿出实验区域。"},{"id":83,"ch":1,"t":"m","q":"下列做法中体现“预防为主”方针的有：","o":["开展全员安全教育培训","制定并严格执行操作规程","定期检查、及时消除事故隐患","配备防护设施和急救器材","等事故发生后再追究个人责任"],"a":"ABCD","e":"教育、规程、检查、配备防护均属事前预防，事后追责不是预防措施。"},{"id":84,"ch":1,"t":"m","q":"违反实验操作规程可能导致的后果有：","o":["火灾、爆炸","中毒、灼伤","人身伤亡","仪器设备损坏","实验数据更加准确可靠"],"a":"ABCD","e":"违章操作可能引发火灾爆炸、中毒灼伤、人身伤亡和设备损坏，绝不会让数据更可靠。"},{"id":85,"ch":1,"t":"j","q":"“安全第一、预防为主”中的“预防为主”，强调把事故消灭在发生之前。","o":["对","错"],"a":"对","e":"预防为主即通过教育培训、隐患治理等事前措施控制风险，而非事后补救。"},{"id":86,"ch":1,"t":"j","q":"海因里希法则表明，重大事故与大量轻微事故及无伤害事件之间存在统计规律。","o":["对","错"],"a":"对","e":"1:29:300说明严重事故背后往往存在大量轻微事件与未遂事件。"},{"id":87,"ch":1,"t":"j","q":"只要没有造成人员伤亡，未遂事件就不必记录和分析。","o":["对","错"],"a":"错","e":"未遂事件是事故金字塔的塔基，不记录分析便失去预防重大事故的机会。"},{"id":88,"ch":1,"t":"j","q":"按瑞士奶酪模型的思想，实验室安全只需保证一层防线完好即可。","o":["对","错"],"a":"错","e":"模型强调多层设防、纵深防御，任何单层防线都可能失效，不能依赖单一防线。"},{"id":89,"ch":1,"t":"j","q":"实验室发生火灾爆炸，通常须同时具备可燃物、助燃物和点火源三个条件。","o":["对","错"],"a":"对","e":"破坏三要素中的任一环节（如移除点火源）即可防止燃烧发生。"},{"id":90,"ch":1,"t":"j","q":"化学灼伤专指高温烫伤，与酸、碱等腐蚀性化学品无关。","o":["对","错"],"a":"错","e":"化学灼伤正是由酸、碱等腐蚀性化学品接触皮肤黏膜造成的损伤，区别于热力烫伤。"},{"id":91,"ch":1,"t":"j","q":"化学实验室的割伤事故多与玻璃仪器的清洗、装配等操作不当有关。","o":["对","错"],"a":"对","e":"折断玻璃管、向软木塞强行插入等不当操作是割伤的主要成因。"},{"id":92,"ch":1,"t":"j","q":"毒物经皮肤吸收中毒的风险可以忽略，因为皮肤是天然屏障。","o":["对","错"],"a":"错","e":"不少化学品（如苯胺、酚类）可经完整皮肤迅速吸收中毒，皮肤并非可靠屏障。"},{"id":93,"ch":1,"t":"j","q":"触电事故的风险与实验设备的电气绝缘和接地状况无关。","o":["对","错"],"a":"错","e":"绝缘老化、缺接地保护是触电事故的主要物的不安全状态。"},{"id":94,"ch":1,"t":"j","q":"非电离辐射对人体没有任何危害，实验中无需采取防护措施。","o":["对","错"],"a":"错","e":"紫外线、激光、强射频等非电离辐射过量照射同样可造成眼、皮肤损伤，须加强防护。"},{"id":95,"ch":1,"t":"j","q":"安全文化建设的关键是人人讲安全、人人守规范，而不只是安全员一人的职责。","o":["对","错"],"a":"对","e":"安全文化是全员共享的价值观与行为习惯，须人人参与、人人尽责。"},{"id":96,"ch":1,"t":"j","q":"学生在实验室学习和工作，同时也是实验室安全责任的共同承担者。","o":["对","错"],"a":"对","e":"学生须遵守制度规程、正确防护、及时报告隐患，是安全责任链条的一环。"},{"id":97,"ch":1,"t":"j","q":"三级安全教育可通过一次讲座一次性完成，此后无需再接受安全教育。","o":["对","错"],"a":"错","e":"安全教育应持续开展、定期复训，随实验内容与风险变化不断更新。"},{"id":98,"ch":1,"t":"j","q":"GB 13690 对化学品分类和危险性公示作出了规定。","o":["对","错"],"a":"对","e":"该标准是化学品危险性分类与标签、 SDS 公示的通用依据。"},{"id":99,"ch":1,"t":"j","q":"安全标志中红色圆形加斜杠的标志属于指令标志。","o":["对","错"],"a":"错","e":"红圈加斜杠是禁止标志，表示严禁某种行为；指令标志为蓝底圆形。"},{"id":100,"ch":1,"t":"j","q":"隐患是可被排查发现并治理消除的，及时治理隐患是预防事故的关键环节。","o":["对","错"],"a":"对","e":"隐患排查治理把风险控制在事故发生之前，体现预防为主的方针。"},{"id":101,"ch":1,"t":"j","q":"高校三级安全教育一般指学校、院系和实验室三个层级的安全教育。","o":["对","错"],"a":"对","e":"三级安全教育即学校级、院系级、实验室级教育。"},{"id":102,"ch":1,"t":"j","q":"只要实验技能熟练，就可以不参加实验室安全准入考试。","o":["对","错"],"a":"错","e":"无论技能如何，都必须经培训考核合格取得准入资格。"},{"id":103,"ch":1,"t":"j","q":"三级安全教育只需在新生入学时进行一次，此后终身有效。","o":["对","错"],"a":"错","e":"安全教育应定期、持续开展，新环境和新危险源出现时须重新培训。"},{"id":104,"ch":1,"t":"j","q":"《危险化学品安全管理条例》是国务院颁布的行政法规。","o":["对","错"],"a":"对","e":"该条例由国务院公布，属于行政法规。"},{"id":105,"ch":1,"t":"j","q":"GB 13690 对常用危险化学品进行了分类并规定了相应的标志。","o":["对","错"],"a":"对","e":"GB 13690 即《常用危险化学品的分类及标志》。"},{"id":106,"ch":1,"t":"j","q":"实验室安全检查只是管理人员和教师的职责，与学生无关。","o":["对","错"],"a":"错","e":"人人都是安全责任的主体，学生也应参与和配合安全检查。"},{"id":107,"ch":1,"t":"j","q":"“预防为主”要求把预防事故放在首位，把事故消灭在萌芽状态。","o":["对","错"],"a":"对","e":"预防为主强调防患于未然，消除隐患于萌芽。"},{"id":108,"ch":1,"t":"j","q":"佩戴防护眼镜只是为了应付检查，做实验时戴不戴无所谓。","o":["对","错"],"a":"错","e":"防护眼镜是防止飞溅物伤害眼睛的必要防护，必须按要求佩戴。"},{"id":109,"ch":1,"t":"j","q":"指令标志的几何图形是圆形，背景为蓝色。","o":["对","错"],"a":"对","e":"指令标志为圆形、蓝底白图形，表示必须遵守的要求。"},{"id":110,"ch":1,"t":"j","q":"可以先进入实验室熟悉情况，安全教育等工作一段时间后再补。","o":["对","错"],"a":"错","e":"必须坚持“先培训、后上岗”，未经培训不得进入实验室工作。"},{"id":111,"ch":1,"t":"j","q":"在高校实验室安全责任体系中，导师对所指导学生的实验室安全负有教育和监管责任。","o":["对","错"],"a":"对","e":"导师是学生实验安全的重要责任人，负有教育、监督义务。"},{"id":112,"ch":1,"t":"j","q":"《危险化学品安全管理条例》对危险化学品生产、储存、使用、经营和运输等环节的安全管理作出了规定。","o":["对","错"],"a":"对","e":"该条例覆盖危化品生产、储存、使用、经营、运输各环节。"},{"id":113,"ch":1,"t":"j","q":"实验室发生事故后，为避免“小题大做”，应先自行处理，实在处理不了再向上报告。","o":["对","错"],"a":"错","e":"发生事故必须及时如实报告，不得隐瞒或拖延。"},{"id":114,"ch":1,"t":"j","q":"任何单位和个人都有维护消防安全、报告火警的义务，不得阻拦报警。","o":["对","错"],"a":"对","e":"消防法规定任何人都有报告火警的义务，严禁阻拦报警。"},{"id":115,"ch":1,"t":"j","q":"安全标志一经设置即长期有效，即使褪色、损坏也无需更换。","o":["对","错"],"a":"错","e":"安全标志应保持清晰完好，损坏、褪色应及时更换维护。"},{"id":116,"ch":1,"t":"j","q":"为了赶实验进度，可以适当简化或变通安全操作规程。","o":["对","错"],"a":"错","e":"安全操作规程必须严格执行，任何简化变通都可能引发事故。"},{"id":117,"ch":1,"t":"b","q":"我国安全生产的基本方针是“安全第一、____”。","a":["预防为主"]},{"id":118,"ch":1,"t":"b","q":"事故金字塔的塔基是大量的____事件。","a":["无伤害（未遂）"]},{"id":119,"ch":1,"t":"b","q":"事故的直接原因是人的不安全行为和物的____。","a":["不安全状态"]},{"id":120,"ch":1,"t":"b","q":"“三不伤害”是指不伤害自己、不伤害他人、____。","a":["不被他人伤害"]},{"id":121,"ch":1,"t":"b","q":"化学毒物侵入人体的主要途径有经____吸收、经____吸收和经消化道摄入。","a":["呼吸道","皮肤黏膜"]},{"id":122,"ch":1,"t":"b","q":"燃烧三要素是可燃物、助燃物（氧化剂）和____。","a":["点火源（着火源）"]},{"id":123,"ch":1,"t":"b","q":"提出事故致因“瑞士奶酪模型”的学者是____。","a":["里森（Reason）"]},{"id":124,"ch":1,"t":"b","q":"安全标志按类别分为禁止、警告、指令和____四类。","a":["提示"]},{"id":125,"ch":1,"t":"b","q":"三级安全教育一般指学校级、院系级、____级三个层次。","a":["实验室"]},{"id":126,"ch":1,"t":"b","q":"实验室准入制度要求：经安全教育培训并____后，方可进入实验室开展实验。","a":["考核合格"]},{"id":127,"ch":1,"t":"b","q":"事故的发生往往与人的不安全____和物的不安全状态有关。","a":["行为"]},{"id":128,"ch":1,"t":"b","q":"化学实验室中“禁止烟火”标识属于____标志。","a":["禁止"]},{"id":129,"ch":1,"t":"b","q":"在化学实验室中，长发人员应将头发____，避免接触火焰、药品或卷入转动设备。","a":["束起"]},{"id":130,"ch":1,"t":"b","q":"标准代号 GB 13690 中的“GB”表示____性国家标准。","a":["强制"]},{"id":131,"ch":1,"t":"b","q":"禁止标志为带斜杠的圆环图形，其安全色为____色。","a":["红"]},{"id":132,"ch":1,"t":"b","q":"实验室安全检查包括实验室自查和学校、院系组织的定期____。","a":["巡查"]},{"id":133,"ch":1,"t":"b","q":"安全标志分为禁止标志、警告标志、____标志和提示标志四类。","a":["指令"]},{"id":134,"ch":1,"t":"b","q":"新进人员须通过实验室安全____考试，合格后方可获得准入资格。","a":["准入"]},{"id":135,"ch":1,"t":"b","q":"高校实验室安全责任体系中，实验室____是本实验室安全的直接责任人。","a":["负责人"]},{"id":136,"ch":1,"t":"b","q":"按 GB 13690 的分类，常用危险化学品的第八类是____品。","a":["腐蚀"]},{"id":137,"ch":1,"t":"x","q":"简述海因里希法则（事故金字塔）的基本内容，并说明其对实验室安全管理的启示。","a":"1.基本内容：海因里希通过对大量事故的统计分析提出，同一类事故中严重伤害、轻微伤害和无伤害（未遂）事件的比例约为1:29:300，形如金字塔；2.含义：塔基数量庞大的无伤害事件与轻微伤害，正是顶端严重事故得以发生的土壤，重大事故并非孤立偶发；3.启示：（1）重视未遂事件和轻微事故的记录、报告与分析，不因“没出事”而放过；（2）抓早抓小，从消除底层隐患和不安全行为入手；（3）强化日常安全检查、教育培训和制度执行，把管理重心放在预防上；（4）克服侥幸心理，防止小隐患逐步演变为重大事故。"},{"id":138,"ch":1,"t":"x","q":"某高校实验室因学生违规超量存放易燃试剂、且未按操作规程进行实验而引发火灾，造成人员伤亡。请用瑞士奶酪模型分析该事故的成因，并提出预防对策。","a":"1.成因分析（各层防线的“孔洞”）：（1）学生个人层：违规存放易燃试剂、违反操作规程，属人的不安全行为；（2）教育培训层：安全准入教育未真正落实，学生风险意识淡薄；（3）管理监督层：院系安全巡查流于形式，未能及时发现试剂违规存放的隐患；（4）制度层：危险化学品采购、存放、使用管理制度存在漏洞。当各层孔洞恰好贯通时，事故即不可避免地发生；2.预防对策：（1）完善并严格执行危化品管理制度，控制易燃品存量；（2）落实安全准入培训与考核，强化应急处置能力；（3）加强院系和实验室的日常巡查与隐患整改闭环；（4）明确导师安全指导监督责任；（5）培育人人讲安全、人人查隐患的实验室安全文化，使多层防线真正发挥作用。"},{"id":139,"ch":1,"t":"x","q":"简述高校“三级安全教育”与实验室准入制度的主要内容及其意义。","a":"1.三级安全教育指学校、院系、实验室三个层级的安全教育：校级侧重法律法规、校纪校规和安全意识教育；院系级结合学科特点讲授危险源与防护要点；实验室级针对具体设备、试剂和操作规程进行培训。2.实验室准入制度要求人员经安全培训并通过考核后方可进入实验室开展实验，未通过者不得独立操作。3.其意义在于：层层落实安全责任，使安全教育全面而有针对性；以考核促学习，确保安全知识与技能真正掌握；从源头上防止未经培训人员进入实验室引发事故，体现“安全第一、预防为主”的方针。"},{"id":140,"ch":1,"t":"x","q":"结合“安全第一、预防为主”的方针，谈谈化学实验室应如何做好事故预防工作。","a":"1.制度上：健全安全责任体系与管理制度，制定并严格执行实验操作规程，落实危险化学品领用、存放和废弃物处置的有关规定。2.教育上：坚持“先培训、后上岗”，开展三级安全教育并实行准入考核，使人人掌握安全知识与应急技能。3.检查上：坚持实验室自查和学校、院系定期巡查，及时发现并整改隐患；暂不能整改的采取临时防控措施并上报。4.防护上：按要求穿戴实验服、防护眼镜等个人防护用品，规范个人行为，做到“三不伤害”。5.应急上：配备消防器材和应急设施，熟悉应急预案并定期演练，把可能发生的事故损失降到最低。"},{"id":141,"ch":2,"t":"s","q":"下列选项中，不属于燃烧三要素的是？","o":["可燃物","助燃物（氧化剂）","着火源","惰性气体"],"a":"D","e":"燃烧三要素为可燃物、助燃物、着火源，惰性气体不属于。"},{"id":142,"ch":2,"t":"s","q":"可燃物、助燃物、着火源三者同时存在却不一定发生燃烧，还须满足的条件是？","o":["可燃物与助燃物达到一定比例且着火源具备足够能量","环境温度持续升高","可燃物处于固态","空气相对湿度较低"],"a":"A","e":"三要素需同时具备并相互结合到一定程度，着火源还须有足够能量才会燃烧。"},{"id":143,"ch":2,"t":"s","q":"链式反应理论认为，燃烧得以持续发展的关键因素是？","o":["可燃物不断蒸发","自由基（游离基）的链式传递","氧气持续补充","温度保持恒定"],"a":"B","e":"燃烧中产生的自由基不断进行链式传递，使燃烧反应得以持续。"},{"id":144,"ch":2,"t":"s","q":"可燃液体表面蒸气与空气混合后，遇火源发生“一闪即灭”的燃烧现象称为？","o":["着火","自燃","闪燃","阴燃"],"a":"C","e":"闪燃是蒸气遇火源一闪即灭的瞬间燃烧。"},{"id":145,"ch":2,"t":"s","q":"可燃液体蒸气与空气的混合物，遇火源能发生闪燃的最低温度称为？","o":["闪点","燃点","自燃点","沸点"],"a":"A","e":"闪点是发生闪燃的最低温度。"},{"id":146,"ch":2,"t":"s","q":"物质在空气中遇火源能够持续燃烧（至少5秒）的最低温度称为？","o":["闪点","燃点","自燃点","熔点"],"a":"B","e":"燃点是物质遇火源持续燃烧的最低温度。"},{"id":147,"ch":2,"t":"s","q":"物质在没有外部火源的情况下，依靠自身氧化放热等作用达到某温度而自行着火的最低温度称为？","o":["闪点","燃点","自燃点","分解温度"],"a":"C","e":"自燃点是物质无外部火源而自行着火的最低温度。"},{"id":148,"ch":2,"t":"s","q":"对同一种可燃液体，闪点、燃点、自燃点三者的温度高低关系一般是？","o":["闪点最高","燃点最高","三者相等","自燃点＞燃点＞闪点"],"a":"D","e":"一般自燃点最高，燃点次之，闪点最低。"},{"id":149,"ch":2,"t":"s","q":"衡量可燃液体火灾危险性大小的主要指标是？","o":["闪点","燃点","自燃点","沸点"],"a":"A","e":"闪点越低，液体越易着火，火灾危险性越大，故闪点是主要指标。"},{"id":150,"ch":2,"t":"s","q":"可燃液体的闪点越低，其火灾危险性？","o":["越小","越大","不变","与闪点无关"],"a":"B","e":"闪点越低越易蒸发着火，火灾危险性越大。"},{"id":151,"ch":2,"t":"s","q":"燃烧波以亚音速传播的爆炸性燃烧称为？","o":["爆燃","爆轰","阴燃","闪燃"],"a":"A","e":"爆燃是亚音速传播的燃烧波，爆轰则为超音速。"},{"id":152,"ch":2,"t":"s","q":"阴燃的典型特征是？","o":["有明火且产烟多","火焰明亮刺眼","无火焰、缓慢燃烧并大量产烟","瞬间即灭"],"a":"C","e":"阴燃是没有火焰的缓慢燃烧，常伴随大量烟。"},{"id":153,"ch":2,"t":"s","q":"下列燃烧现象中，属于无火焰缓慢燃烧的是？","o":["闪燃","爆燃","着火","阴燃"],"a":"D","e":"阴燃是无火焰的缓慢燃烧，闪燃、着火、爆燃均有火焰或为瞬燃。"},{"id":154,"ch":2,"t":"s","q":"自燃按热源来源不同，可分为受热自燃和？","o":["化学自燃","物理自燃","本身自燃（自热自燃）","电自燃"],"a":"C","e":"自燃分为受热自燃和本身自燃（自热自燃）两类。"},{"id":155,"ch":2,"t":"s","q":"火灾中最常见、造成人员中毒伤亡最严重的气体是？","o":["二氧化碳","一氧化碳","二氧化硫","水蒸气"],"a":"B","e":"一氧化碳是火灾中导致中毒伤亡最主要的有毒气体。"},{"id":156,"ch":2,"t":"s","q":"一氧化碳使人中毒的主要机理是？","o":["与血红蛋白结合使其丧失携氧能力","强烈刺激呼吸道","腐蚀皮肤","大量消耗氧气"],"a":"A","e":"一氧化碳与血红蛋白结合生成碳氧血红蛋白，使其丧失携氧能力。"},{"id":157,"ch":2,"t":"s","q":"火灾现场烟气妨碍逃生并造成窒息的主要因素，除烟尘外还有？","o":["噪声","水汽","光线","高温与缺氧"],"a":"D","e":"浓烟的高温与缺氧会致人灼伤、窒息，是重要危险因素。"},{"id":158,"ch":2,"t":"s","q":"下列哪一项不属于火灾浓烟对人员逃生的危害？","o":["降低环境温度","遮挡视线","刺激呼吸道","造成缺氧窒息"],"a":"A","e":"浓烟会升温而非降温，遮挡视线、刺激呼吸道和致缺氧均为其危害。"},{"id":159,"ch":2,"t":"s","q":"锅炉、气瓶因内部压力超过强度极限而发生的爆炸属于？","o":["化学爆炸","物理爆炸","粉尘爆炸","蒸气云爆炸"],"a":"B","e":"因压力超限发生的爆炸属于物理爆炸，无化学反应。"},{"id":160,"ch":2,"t":"s","q":"可燃气体与空气混合后遇火源发生的爆炸属于？","o":["物理爆炸","粉尘爆炸","化学爆炸","蒸气云爆炸"],"a":"C","e":"可燃气体发生氧化反应的爆炸属于化学爆炸。"},{"id":161,"ch":2,"t":"s","q":"悬浮在空气中的可燃粉尘达到一定浓度后遇火源发生的爆炸称为？","o":["物理爆炸","蒸气云爆炸","化学爆炸","粉尘爆炸"],"a":"D","e":"可燃粉尘悬浮达到爆炸浓度遇火源即发生粉尘爆炸。"},{"id":162,"ch":2,"t":"s","q":"泄漏的可燃气体或蒸气在空气中形成云团后遇火源发生的爆炸称为？","o":["蒸气云爆炸","粉尘爆炸","物理爆炸","阴燃"],"a":"A","e":"蒸气云爆炸是泄漏蒸气云团遇火源发生的爆炸。"},{"id":163,"ch":2,"t":"s","q":"可燃气体与空气混合物中，遇火源能发生爆炸的最低浓度称为？","o":["爆炸上限","爆炸下限","临界浓度","饱和浓度"],"a":"B","e":"爆炸下限是能发生爆炸的最低浓度。"},{"id":164,"ch":2,"t":"s","q":"可燃气体浓度低于爆炸下限时，遇火源一般？","o":["立即爆炸","必然自燃","不会爆炸（可能燃烧）","立即爆轰"],"a":"C","e":"低于下限时混合物过稀，不会爆炸，边界处可能燃烧。"},{"id":165,"ch":2,"t":"s","q":"防止可燃气体在室内积聚并达到爆炸极限的最常用措施是？","o":["加强通风","紧闭门窗","增设火源","提高室温"],"a":"A","e":"加强通风可降低可燃气体浓度，使其低于爆炸下限。"},{"id":166,"ch":2,"t":"s","q":"用氮气、二氧化碳等气体置换可燃气体，使混合物失去爆炸性，这种防爆措施称为？","o":["抑爆","惰化","泄爆","防静电"],"a":"B","e":"通入惰性气体使混合物失去爆炸性，称为惰化（惰性气体保护）。"},{"id":167,"ch":2,"t":"s","q":"在爆炸危险场所采用防爆型电气设备，其主要目的是？","o":["提高照明亮度","节约用电","防止产生电火花等点火源","便于检修"],"a":"C","e":"防爆电器可防止产生电火花、高温等点火源引发爆炸。"},{"id":168,"ch":2,"t":"s","q":"为消除静电引发火灾爆炸，最有效、最常用的措施是？","o":["提高温度","增加压力","减少通风","设备接地"],"a":"D","e":"设备接地可将静电荷导走，是消除静电危害的基本措施。"},{"id":169,"ch":2,"t":"s","q":"我国火警报警电话号码是？","o":["119","110","120","122"],"a":"A","e":"我国火警电话为119。"},{"id":170,"ch":2,"t":"s","q":"木材、棉、纸张等固体物质火灾属于？","o":["B类火灾","A类火灾","C类火灾","D类火灾"],"a":"B","e":"A类火灾指固体物质火灾。"},{"id":171,"ch":2,"t":"s","q":"汽油、煤油等可燃液体火灾属于？","o":["A类火灾","C类火灾","B类火灾","E类火灾"],"a":"C","e":"B类火灾指液体或可熔化固体物质火灾。"},{"id":172,"ch":2,"t":"s","q":"天然气、氢气等可燃气体火灾属于？","o":["A类火灾","B类火灾","D类火灾","C类火灾"],"a":"D","e":"C类火灾指气体火灾。"},{"id":173,"ch":2,"t":"s","q":"金属钠、镁、铝粉等活泼金属火灾属于？","o":["D类火灾","A类火灾","B类火灾","C类火灾"],"a":"A","e":"D类火灾指金属火灾。"},{"id":174,"ch":2,"t":"s","q":"带电的电气设备火灾属于？","o":["D类火灾","E类火灾","F类火灾","C类火灾"],"a":"B","e":"E类火灾指带电的电气火灾。"},{"id":175,"ch":2,"t":"s","q":"用湿布覆盖燃烧物以隔绝空气灭火，采用的灭火基本方法是？","o":["隔离法","冷却法","窒息法","化学抑制法"],"a":"C","e":"隔绝空气使燃烧缺氧熄灭，属于窒息法。"},{"id":176,"ch":2,"t":"s","q":"用水浇灭木材火灾，主要利用的灭火基本方法是？","o":["隔离法","窒息法","化学抑制法","冷却法"],"a":"D","e":"水吸收热量使可燃物温度降至燃点以下，属于冷却法。"},{"id":177,"ch":2,"t":"s","q":"燃烧必须具备的三个基本条件（燃烧三要素）不包括下列哪一项？","o":["可燃物","助燃物","点火源","惰性气体"],"a":"D","e":"燃烧三要素是可燃物、助燃物和点火源，惰性气体不属于三要素。"},{"id":178,"ch":2,"t":"s","q":"化学抑制灭火法主要是抑制燃烧过程中的哪一环节？","o":["自由基链式反应","可燃物的挥发","助燃物的供给","热量的积聚"],"a":"A","e":"化学抑制法通过中断燃烧的自由基链式反应灭火。"},{"id":179,"ch":2,"t":"s","q":"按照 GB/T 4968 的火灾分类，木材、纸张、棉、麻燃烧引起的火灾属于：","o":["B类火灾","A类火灾","C类火灾","D类火灾"],"a":"B","e":"A类火灾指固体物质火灾，如木材、纸张等。"},{"id":180,"ch":2,"t":"s","q":"汽油、甲醇、乙醇等可燃液体燃烧引起的火灾属于：","o":["A类火灾","C类火灾","B类火灾","D类火灾"],"a":"C","e":"B类火灾指液体或可熔化固体物质火灾。"},{"id":181,"ch":2,"t":"s","q":"天然气、氢气、乙炔等可燃气体燃烧引起的火灾属于：","o":["B类火灾","C类火灾","D类火灾","E类火灾"],"a":"B","e":"C类火灾指气体火灾。"},{"id":182,"ch":2,"t":"s","q":"钾、钠、镁等金属燃烧引起的火灾属于：","o":["C类火灾","E类火灾","F类火灾","D类火灾"],"a":"D","e":"D类火灾指金属火灾。"},{"id":183,"ch":2,"t":"s","q":"电气设备带电燃烧引起的火灾属于：","o":["C类火灾","D类火灾","E类火灾","F类火灾"],"a":"C","e":"E类火灾指带电火灾。"},{"id":184,"ch":2,"t":"s","q":"烹饪器具内动植物油脂燃烧引起的火灾属于：","o":["D类火灾","E类火灾","B类火灾","F类火灾"],"a":"D","e":"F类火灾指烹饪器具内的烹饪物（如动植物油脂）火灾。"},{"id":185,"ch":2,"t":"s","q":"可燃物质被点燃后能持续燃烧（不少于规定时间）的最低温度称为：","o":["闪点","燃点","自燃点","沸点"],"a":"B","e":"燃点（着火点）是可燃物持续燃烧的最低温度。"},{"id":186,"ch":2,"t":"s","q":"可燃物质在无外来火源的条件下，靠自身发热达到并引起自行着火的最低温度称为：","o":["闪点","燃点","沸点","自燃点"],"a":"D","e":"自燃点是不依赖外来火源而自行着火的最低温度。"},{"id":187,"ch":2,"t":"s","q":"关于闪点、燃点、自燃点三者关系的正确说法是：","o":["闪点高于燃点","自燃点低于燃点","燃点高于闪点、低于自燃点","三者相等"],"a":"C","e":"一般燃点高于闪点，自燃点更高。"},{"id":188,"ch":2,"t":"s","q":"下列可燃气体的火灾爆炸危险性最大的是：","o":["爆炸下限高、范围窄","爆炸下限低、范围宽","爆炸上限高、范围窄","爆炸下限高、范围宽"],"a":"B","e":"爆炸下限越低、范围越宽，危险性越大。"},{"id":189,"ch":2,"t":"s","q":"温度升高时，可燃气体（蒸气）的爆炸极限范围将：","o":["变宽","变窄","保持不变","无法确定"],"a":"A","e":"温度升高使爆炸极限范围变宽。"},{"id":190,"ch":2,"t":"s","q":"压力升高时，可燃气体的爆炸极限范围通常：","o":["变窄","保持不变","变宽","先宽后窄"],"a":"C","e":"压力升高使爆炸极限范围变宽。"},{"id":191,"ch":2,"t":"s","q":"向可燃气体中通入惰性气体（如氮气、二氧化碳）后，其爆炸极限范围将：","o":["变宽","变窄","保持不变","先窄后宽"],"a":"B","e":"惰性气体使爆炸极限范围变窄甚至失去爆炸性。"},{"id":192,"ch":2,"t":"s","q":"容器的尺寸（直径）减小时，可燃气体（蒸气）的爆炸极限范围通常：","o":["变宽","保持不变","变窄","无影响"],"a":"C","e":"容器尺寸减小使爆炸极限范围变窄。"},{"id":193,"ch":2,"t":"s","q":"点火能量增大时，可燃混合气的爆炸极限范围将：","o":["变窄","保持不变","无法确定","变宽"],"a":"D","e":"点火能量越大，爆炸极限范围越宽。"},{"id":194,"ch":2,"t":"s","q":"实验室采用通风措施防爆，其主要目的是：","o":["降低环境温度","使可燃气体浓度低于爆炸下限","提高氧含量","增大环境压力"],"a":"B","e":"通风使可燃气体浓度稀释到爆炸下限以下。"},{"id":195,"ch":2,"t":"s","q":"采用惰性气体保护（惰化）防爆，其实质是：","o":["降低温度","降低可燃物浓度","降低着火区域的氧含量","增大压力"],"a":"C","e":"惰化的实质是降低氧含量使其达不到助燃浓度。"},{"id":196,"ch":2,"t":"s","q":"在设备或建筑物上设置防爆门、防爆膜、泄压口等装置属于：","o":["泄爆措施","抑爆措施","惰化措施","通风措施"],"a":"A","e":"防爆门、防爆膜、泄压口均属泄爆装置。"},{"id":197,"ch":2,"t":"s","q":"抑爆装置的主要作用是：","o":["在爆炸初期迅速喷出抑爆剂，抑制爆炸发展","将爆炸产物及时排出","降低系统氧含量","隔离点火源"],"a":"A","e":"抑爆装置在爆炸初期喷出抑爆剂抑制爆炸发展。"},{"id":198,"ch":2,"t":"s","q":"下列属于防止静电危害的措施是：","o":["设备接地","提高绝缘电阻","增大摩擦速度","减少环境湿度"],"a":"A","e":"接地是消除静电危害的基本措施。"},{"id":199,"ch":2,"t":"s","q":"在爆炸危险场所应选用的电气设备是：","o":["普通型","防爆型","敞开型","家用型"],"a":"B","e":"爆炸危险场所必须选用防爆型电气设备。"},{"id":200,"ch":2,"t":"s","q":"下列不属于灭火基本方法的是：","o":["隔离法","窒息法","冷却法","置换法"],"a":"D","e":"灭火基本方法为隔离、窒息、冷却、化学抑制四种。"},{"id":201,"ch":2,"t":"s","q":"将着火点周围的可燃物移开、切断可燃物来源的灭火方法称为：","o":["隔离法","窒息法","冷却法","化学抑制法"],"a":"A","e":"隔离法通过移开或隔绝可燃物灭火。"},{"id":202,"ch":2,"t":"s","q":"用石棉毯、湿棉被覆盖着火物或喷射二氧化碳灭火，属于：","o":["隔离法","窒息法","冷却法","化学抑制法"],"a":"B","e":"窒息法通过隔绝空气或降低氧含量灭火。"},{"id":203,"ch":2,"t":"s","q":"用水浇淋燃烧物使其温度降低到燃点以下的灭火方法属于：","o":["隔离法","窒息法","冷却法","化学抑制法"],"a":"C","e":"冷却法将可燃物温度降到燃点以下。"},{"id":204,"ch":2,"t":"s","q":"干粉灭火剂灭火，其最主要的灭火机理是：","o":["冷却","窒息","隔离","化学抑制（中断链式反应）"],"a":"D","e":"干粉主要通过化学抑制中断燃烧链式反应。"},{"id":205,"ch":2,"t":"s","q":"扑救带电设备火灾时，不宜选用的灭火剂是：","o":["二氧化碳","干粉","水","卤代烷"],"a":"C","e":"水能导电，不宜用于带电设备火灾。"},{"id":206,"ch":2,"t":"s","q":"D类金属火灾（如钠、镁着火）扑救时，不宜使用：","o":["专用金属干粉灭火剂","7150灭火剂","干燥砂土","水"],"a":"D","e":"水与活泼金属反应会加剧火势甚至爆炸。"},{"id":207,"ch":2,"t":"s","q":"我国规定的火警报警电话是：","o":["110","120","119","122"],"a":"C","e":"火警报警电话为119。"},{"id":208,"ch":2,"t":"s","q":"发现实验室初起火灾时，首先应当：","o":["立即报警并组织扑救","收拾个人物品","打开门窗通风","拍照留证"],"a":"A","e":"初起火灾应第一时间报警并扑救。"},{"id":209,"ch":2,"t":"s","q":"火灾中造成人员中毒伤亡最主要的气体是：","o":["二氧化碳","一氧化碳","氮气","氧气"],"a":"B","e":"一氧化碳是火灾中造成中毒伤亡的主要气体。"},{"id":210,"ch":2,"t":"s","q":"没有火焰、仅靠炽热表面缓慢氧化的燃烧现象称为：","o":["闪燃","爆燃","自燃","阴燃"],"a":"D","e":"阴燃是无火焰的缓慢燃烧现象。"},{"id":211,"ch":2,"t":"s","q":"黄磷、白磷在空气中常温下即可自行着火，这属于：","o":["自燃","闪燃","阴燃","爆燃"],"a":"A","e":"黄磷、白磷因自燃点低而发生自燃。"},{"id":212,"ch":2,"t":"s","q":"燃烧必须具备的三个基本要素是（　）。","o":["可燃物、助燃物、点火源","可燃物、温度、链式反应","助燃物、点火源、链式反应","可燃物、助燃物、温度"],"a":"A","e":"燃烧三要素为可燃物、助燃物（氧气）和点火源，缺一不可。"},{"id":213,"ch":2,"t":"s","q":"物质在无外部点火源的情况下自行发热并开始燃烧的最低温度称为（　）。","o":["闪点","燃点","自燃点","分解温度"],"a":"C","e":"自燃点是物质无需外部火源自行着火的最低温度。"},{"id":214,"ch":2,"t":"s","q":"物质被点燃后能够持续燃烧的最低温度称为（　）。","o":["闪点","自燃点","熔点","燃点"],"a":"D","e":"燃点是物质被点燃后能持续燃烧的最低温度。"},{"id":215,"ch":2,"t":"s","q":"可燃液体火灾在我国火灾分类中属于（　）。","o":["B类","A类","C类","D类"],"a":"A","e":"B类火灾指液体或可熔化固体物质火灾。"},{"id":216,"ch":2,"t":"s","q":"金属钠、钾等活泼金属引起的火灾按分类属于（　）。","o":["B类","D类","C类","E类"],"a":"B","e":"D类火灾指金属及其化合物火灾。"},{"id":217,"ch":2,"t":"s","q":"带电的电气设备或线路着火，按火灾分类属于（　）。","o":["C类","D类","E类","F类"],"a":"C","e":"E类火灾指带电物体的火灾。"},{"id":218,"ch":2,"t":"s","q":"用砂土覆盖燃烧物以隔绝空气，属于灭火方法中的（　）。","o":["隔离法","冷却法","化学抑制法","窒息法"],"a":"D","e":"窒息法是隔绝空气使燃烧物缺氧熄灭，砂土覆盖属之。"},{"id":219,"ch":2,"t":"s","q":"用水浇淋燃烧物表面以降低其温度，属于灭火方法中的（　）。","o":["冷却法","窒息法","隔离法","化学抑制法"],"a":"A","e":"冷却法通过降低温度至燃点以下灭火，浇水降温属之。"},{"id":220,"ch":2,"t":"s","q":"将着火的可燃物移离火源，属于灭火方法中的（　）。","o":["冷却法","隔离法","窒息法","化学抑制法"],"a":"B","e":"隔离法是把可燃物与火源隔开，搬移着火物属之。"},{"id":221,"ch":2,"t":"s","q":"利用卤代烷或干粉中断燃烧链式反应的灭火方法属于（　）。","o":["隔离法","窒息法","化学抑制法","冷却法"],"a":"C","e":"化学抑制法通过抑制自由基中断链式反应灭火。"},{"id":222,"ch":2,"t":"s","q":"一氧化碳对人体造成危害的主要机理是（　）。","o":["刺激呼吸道黏膜","直接腐蚀皮肤","破坏神经系统末梢","与血红蛋白结合导致组织缺氧"],"a":"D","e":"一氧化碳与血红蛋白结合使其丧失携氧能力，造成组织缺氧。"},{"id":223,"ch":2,"t":"s","q":"火灾中造成人员伤亡最常见、最主要的原因是（　）。","o":["吸入有毒烟气窒息","火焰直接烧伤","高温辐射灼伤","建筑物坍塌"],"a":"A","e":"火场中多数人员伤亡由吸入含一氧化碳等有毒烟气窒息所致。"},{"id":224,"ch":2,"t":"s","q":"扑救初起火灾应遵循的首要原则是（　）。","o":["先抢救贵重财物","先控制、后消灭，救人第一","先灭火后报警","静等消防队到达后处理"],"a":"B","e":"初起火灾扑救坚持先控制后消灭、救人第一的原则。"},{"id":225,"ch":2,"t":"s","q":"实验室发现火情后，第一时间的正确做法是（　）。","o":["立即收拾个人物品","打开门窗通风散热","迅速报警并采取初期处置","只顾自行逃离现场"],"a":"C","e":"发现火情应第一时间报警并在安全前提下进行初期处置。"},{"id":226,"ch":2,"t":"s","q":"拨打119报警时，应当首先说明的内容是（　）。","o":["起火地点和详细地址","起火的具体原因","火灾损失金额","起火时间"],"a":"A","e":"报警应先讲清起火详细地址，便于消防力量迅速定位。"},{"id":227,"ch":2,"t":"s","q":"实验室内电器设备起火时，首先应采取的措施是（　）。","o":["用水直接扑救","立即切断电源","用泡沫灭火器直接喷射","泼湿电气设备"],"a":"B","e":"电气火灾应先断电再扑救，避免触电和火势扩大。"},{"id":228,"ch":2,"t":"s","q":"穿过浓烟区域逃生时，正确的做法是（　）。","o":["直立快速奔跑","深呼吸快速通过","用湿毛巾捂住口鼻、弯腰低姿前进","闭眼盲目前行"],"a":"C","e":"低姿并用湿毛巾捂口鼻可减少吸入低处相对稀薄的烟气。"},{"id":229,"ch":2,"t":"s","q":"高层建筑发生火灾时，人员疏散应（　）。","o":["乘坐普通电梯下楼","跳楼逃生","躲在电梯间等待救援","走安全疏散楼梯，不乘电梯"],"a":"D","e":"火灾时电梯易断电停运，应走安全疏散楼梯撤离。"},{"id":230,"ch":2,"t":"s","q":"身上衣物着火时，正确的处置方法是（　）。","o":["就地打滚或用厚衣物覆盖压灭","奔跑呼救以借助风力","用嘴吹灭火焰","站在原地用手拍打"],"a":"A","e":"就地打滚或厚物覆盖可隔绝空气压灭火焰，奔跑会助燃。"},{"id":231,"ch":2,"t":"s","q":"保护火灾现场的主要目的是（　）。","o":["便于清点财物","便于查明火灾原因和责任","便于尽快恢复工作","便于拍照留念"],"a":"B","e":"保护现场有利于消防部门调查取证、查明原因并认定责任。"},{"id":232,"ch":2,"t":"s","q":"可燃气体在空气中能发生爆炸的最低浓度称为（　）。","o":["爆炸上限","闪点","爆炸下限","燃点"],"a":"C","e":"爆炸下限是可燃气体发生爆炸的最低浓度界限。"},{"id":233,"ch":2,"t":"s","q":"某种可燃气体爆炸极限范围越宽，其爆炸危险性越（　）。","o":["小","与范围无关","不变","大"],"a":"D","e":"爆炸极限范围越宽，越易处于爆炸范围内，危险性越大。"},{"id":234,"ch":2,"t":"s","q":"下列因素中，不影响可燃气体爆炸极限的是（　）。","o":["气体的颜色","温度","压力","惰性气体含量"],"a":"A","e":"温度、压力、惰性气体含量均影响爆炸极限，颜色无关。"},{"id":235,"ch":2,"t":"s","q":"粉尘在空气中形成爆炸性混合物并发生爆炸，属于（　）。","o":["物理爆炸","化学爆炸","蒸气云爆炸","核爆炸"],"a":"B","e":"粉尘爆炸是粉尘与空气发生剧烈氧化反应的化学爆炸。"},{"id":236,"ch":2,"t":"s","q":"大量泄漏的可燃气体或蒸气与空气混合形成云团，遇火源发生的爆炸属于（　）。","o":["物理爆炸","粉尘爆炸","蒸气云爆炸","爆裂"],"a":"C","e":"蒸气云爆炸是泄漏可燃气体或蒸气与空气混合遇火源所致。"},{"id":237,"ch":2,"t":"s","q":"防爆措施中“惰化”的实质是（　）。","o":["降低系统温度","增加系统压力","隔离点火源","充入惰性气体降低氧浓度"],"a":"D","e":"惰化是充入氮气等惰性气体降低氧浓度以抑制爆炸。"},{"id":238,"ch":2,"t":"s","q":"在容器或设备上设置爆破片、泄压门以降低爆炸压力的措施称为（　）。","o":["泄爆","抑爆","惰化","通风"],"a":"A","e":"泄爆通过泄压装置释放压力，防止容器整体破坏。"},{"id":239,"ch":2,"t":"s","q":"防止静电危害最常用、最有效的措施是（　）。","o":["提高环境温度","设备接地","降低环境温度","减少照明"],"a":"B","e":"接地可将静电荷导入大地，是防静电的基本措施。"},{"id":240,"ch":2,"t":"s","q":"使用手提式干粉灭火器的正确操作顺序是（　）。","o":["拔销—提瓶—握管—压把","握管—提瓶—拔销—压把","提瓶—拔销—握管—压把","压把—拔销—提瓶—握管"],"a":"C","e":"灭火器使用顺序为“提、拔、握、压”。"},{"id":241,"ch":2,"t":"s","q":"疏散逃生时应沿（　）指示的方向撤离。","o":["来时的入口","普通电梯","任意通道","安全出口疏散指示标志"],"a":"D","e":"应沿安全出口及疏散指示标志方向有序撤离。"},{"id":242,"ch":2,"t":"s","q":"没有火焰、仅缓慢氧化放热的燃烧形式称为（　）。","o":["阴燃","闪燃","爆燃","自燃"],"a":"A","e":"阴燃是无火焰、仅缓慢氧化放热的燃烧。"},{"id":243,"ch":2,"t":"s","q":"一般可燃液体的燃点与闪点的关系是（　）。","o":["燃点低于闪点","燃点高于闪点","燃点等于闪点","二者无固定关系"],"a":"B","e":"燃点一般比闪点高，二者之差随物质而异。"},{"id":244,"ch":2,"t":"s","q":"实验室日常隐患排查中，下列属于常见电气隐患的是（　）。","o":["灭火器压力正常","安全出口畅通","电线私拉乱接、超负荷用电","可燃物分类存放"],"a":"C","e":"私拉乱接、超负荷用电是典型电气火灾隐患。"},{"id":245,"ch":2,"t":"s","q":"拨打119报警结束前，报警人应当（　）。","o":["立即挂断电话","立即去灭火","索要出警费用","等对方确认信息无误后再挂断"],"a":"D","e":"报警后应等接警员确认信息无误后再挂断电话。"},{"id":246,"ch":2,"t":"s","q":"某有机溶剂闭杯闪点为15℃，按《建筑设计防火规范》对可燃液体火灾危险性的分类，该液体属于（ ）。","o":["甲类可燃液体","乙类可燃液体","丙类可燃液体","丁类可燃液体"],"a":"A","e":"可燃液体按闪点分类：甲类闪点＜28℃，乙类28℃≤闪点＜60℃，丙类闪点≥60℃。15℃＜28℃，故为甲类。"},{"id":247,"ch":2,"t":"s","q":"可燃气体检测报警器的一级报警设定值一般不应大于爆炸下限的（ ）。","o":["10%","25%","50%","75%"],"a":"B","e":"按GB 50493的规定，可燃气体一级报警设定值不应大于25%LEL，二级报警设定值不应大于50%LEL。"},{"id":248,"ch":2,"t":"s","q":"手提式干粉灭火器压力表的指针指向红色区域，说明（ ）。","o":["压力正常，可以继续使用","压力过高，有爆炸危险","驱动气体压力不足，应送修充装","灭火剂已经失效，必须报废"],"a":"C","e":"压力表绿区为正常，红区为压力不足，黄区为压力偏高；指针在红区时灭火器不能正常喷射，应送修充装。"},{"id":249,"ch":2,"t":"s","q":"使用二氧化碳灭火器时，不能用手直接握住喷筒，主要是因为（ ）。","o":["喷筒带有高压电，会触电","喷筒内会喷出有毒气体","喷筒内压力过高，会爆炸","喷筒温度极低，会冻伤手"],"a":"D","e":"液态二氧化碳喷出后迅速汽化并吸收大量热，喷筒温度很低，直接握持会造成冻伤，应握住绝热手柄。"},{"id":250,"ch":2,"t":"s","q":"室内火灾在缺氧状态下闷烧，突然打开门窗后新鲜空气涌入，引起火焰迅速传播甚至爆燃，这种现象称为（ ）。","o":["轰燃","回燃","沸溢","喷溅"],"a":"B","e":"回燃（backdraft）是缺氧燃烧的可燃烟气与涌入的空气混合后发生的爆燃；轰燃是室内可燃物全面燃烧，沸溢、喷溅是油罐火灾现象。"},{"id":251,"ch":2,"t":"m","q":"燃烧的三要素包括？","o":["可燃物","助燃物","着火源","惰性气体"],"a":"ABC","e":"燃烧三要素为可燃物、助燃物、着火源，惰性气体不属于。"},{"id":252,"ch":2,"t":"m","q":"下列属于燃烧现象类型的有？","o":["闪燃","着火","自燃","爆燃","冷凝"],"a":"ABCD","e":"闪燃、着火、自燃、爆燃均为燃烧类型，冷凝属物理变化。"},{"id":253,"ch":2,"t":"m","q":"燃烧产物对人员的主要危害包括？","o":["一氧化碳等有毒气体","烟尘遮挡视线","高温灼伤","缺氧窒息","噪声增大"],"a":"ABCD","e":"燃烧产物的危害主要为毒气、烟尘、高温和缺氧。"},{"id":254,"ch":2,"t":"m","q":"下列属于化学爆炸（含其具体形式）的是？","o":["粉尘爆炸","蒸气云爆炸","可燃气体爆炸","气瓶超压爆炸"],"a":"ABC","e":"粉尘爆炸、蒸气云爆炸、可燃气体爆炸均属化学爆炸，气瓶超压为物理爆炸。"},{"id":255,"ch":2,"t":"m","q":"影响可燃气体爆炸极限范围的因素有？","o":["温度","压力","惰性气体含量","容器尺寸","可燃物颜色"],"a":"ABCD","e":"温度、压力、惰性气体、容器尺寸、点火能量等均影响爆炸极限，颜色无关。"},{"id":256,"ch":2,"t":"m","q":"下列属于防爆基本措施的有？","o":["通风","惰化","抑爆","泄爆","提高温度"],"a":"ABCD","e":"通风、惰化、抑爆、泄爆均为防爆措施，提高温度反而增加爆炸危险。"},{"id":257,"ch":2,"t":"m","q":"防止静电引发火灾爆炸的措施有？","o":["设备接地","增加空气湿度","使用防静电材料","控制流速","提高温度"],"a":"ABCD","e":"接地、增湿、防静电材料、控制流速均可防静电，提高温度无效。"},{"id":258,"ch":2,"t":"m","q":"灭火的基本方法包括？","o":["隔离法","窒息法","冷却法","化学抑制法","加温法"],"a":"ABCD","e":"灭火四法为隔离、窒息、冷却、化学抑制，加温法不是灭火方法。"},{"id":259,"ch":2,"t":"m","q":"我国火灾分类中，下列类别与对应物质正确的是？","o":["A类——固体物质","B类——液体或可熔化固体","C类——气体","D类——金属","E类——气体"],"a":"ABCD","e":"A、B、C、D类对应正确，E类为带电火灾而非气体。"},{"id":260,"ch":2,"t":"m","q":"拨打119报警时，应向接警员报告的内容包括？","o":["起火地点","起火物质","火势大小","有无人员被困","与火灾无关的个人信息"],"a":"ABCD","e":"报警应报告地点、物质、火势、被困情况及联系方式等。"},{"id":261,"ch":2,"t":"m","q":"初起火灾扑救应遵循的原则包括？","o":["报警早、损失小","边报警、边扑救","先救人、后救物","先控制、后消灭","先抢贵重物品、后救人员"],"a":"ABCD","e":"初起火灾扑救应报警早、边报边扑、先救后物、先控后灭，救人优先于物。"},{"id":262,"ch":2,"t":"m","q":"火灾现场安全疏散与逃生的正确做法有？","o":["用湿毛巾捂住口鼻","低姿（弯腰）前进","沿疏散指示标志撤离","不乘坐电梯","乘坐电梯快速下楼"],"a":"ABCD","e":"逃生应捂口鼻、低姿、沿指示撤离且不乘电梯。"},{"id":263,"ch":2,"t":"m","q":"火灾浓烟中逃生时，下列正确的做法是？","o":["用湿毛巾捂住口鼻","低姿沿墙壁移动","关闭身后防火门","盲目跳楼","乘坐电梯"],"a":"ABC","e":"捂口鼻、低姿、关防火门均正确，盲目跳楼与乘电梯均危险。"},{"id":264,"ch":2,"t":"m","q":"实验室常见的起火源（着火源）包括？","o":["明火","电火花","高温表面","静电","惰性气体"],"a":"ABCD","e":"明火、电火花、高温表面、静电、化学反应放热等均为起火源，惰性气体不可燃。"},{"id":265,"ch":2,"t":"m","q":"下列爆炸中，属于物理爆炸的是？","o":["气瓶超压爆裂","锅炉爆炸","粉尘爆炸","蒸气云爆炸"],"a":"AB","e":"气瓶超压、锅炉超压爆裂属物理爆炸，粉尘、蒸气云爆炸属化学爆炸。"},{"id":266,"ch":2,"t":"m","q":"下列关于燃烧三要素与链式反应的说法，正确的有？","o":["燃烧需可燃物、助燃物、着火源三要素同时具备","三要素相互结合并达到一定条件才会燃烧","链式反应理论认为自由基的链式传递维持燃烧","灭火即破坏燃烧条件之一或中断链式反应","只要有可燃物和氧气就一定会燃烧"],"a":"ABCD","e":"三要素须同时具备并结合到一定程度才燃烧，灭火即破坏条件或中断链式反应。"},{"id":267,"ch":2,"t":"m","q":"影响可燃气体爆炸极限的主要因素包括哪些？","o":["温度","压力","惰性气体含量","容器尺寸","环境湿度"],"a":"ABCD","e":"温度、压力、惰性气体、容器尺寸及点火能量均影响爆炸极限。"},{"id":268,"ch":2,"t":"m","q":"实验室防爆的基本措施包括哪些？","o":["通风","惰化（惰性气体保护）","抑爆","泄爆","提高温度"],"a":"ABCD","e":"通风、惰化、抑爆、泄爆是防爆的基本措施。"},{"id":269,"ch":2,"t":"m","q":"下列属于防止静电危害的措施有？","o":["设备接地","适当增湿","使用防静电（导电）地面","控制液体流速","提高绝缘电阻"],"a":"ABCD","e":"接地、增湿、防静电地面、控制流速均可防静电。"},{"id":270,"ch":2,"t":"m","q":"燃烧产物对人体的危害包括哪些？","o":["一氧化碳中毒","烟尘降低能见度","高温灼伤","缺氧窒息","噪声"],"a":"ABCD","e":"一氧化碳、烟尘、高温、缺氧是燃烧产物的主要危害。"},{"id":271,"ch":2,"t":"m","q":"按照 GB/T 4968 火灾分类，下列对应关系正确的有？","o":["A类——固体物质火灾","B类——液体或可熔化固体火灾","C类——气体火灾","D类——带电火灾","E类——金属火灾"],"a":"ABC","e":"D类为金属火灾、E类为带电火灾，选项D、E对应颠倒。"},{"id":272,"ch":2,"t":"m","q":"下列属于爆炸分类的有？","o":["物理爆炸","化学爆炸","粉尘爆炸","蒸气云爆炸","核爆炸"],"a":"ABCD","e":"按性质分物理爆炸、化学爆炸，及粉尘爆炸、蒸气云爆炸。"},{"id":273,"ch":2,"t":"m","q":"实验室火灾的特点包括哪些？","o":["易燃易爆危险品多","火灾蔓延快","燃烧产物有毒有害","可能发生二次爆炸","不易发生"],"a":"ABCD","e":"实验室危险品多、蔓延快、产物有毒、易二次爆炸。"},{"id":274,"ch":2,"t":"m","q":"扑救初起火灾的正确做法包括哪些？","o":["立即报警","选用合适的灭火器扑救","切断电源、气源","组织人员疏散","盲目用水扑救一切火灾"],"a":"ABCD","e":"不可盲目用水扑救，应视火灾类别选灭火剂。"},{"id":275,"ch":2,"t":"m","q":"拨打119报警时应说明的内容包括哪些？","o":["火灾地点","起火物质和火势大小","有无人员被困","报警人姓名和联系电话","单位的财务状况"],"a":"ABCD","e":"报警需说明地点、火情、被困情况及联系方式。"},{"id":276,"ch":2,"t":"m","q":"下列灭火器中，适用于扑救带电设备火灾的有？","o":["二氧化碳灭火器","干粉灭火器","水基型灭火器","泡沫灭火器","卤代烷灭火器"],"a":"ABE","e":"二氧化碳、干粉、卤代烷不导电，可用于带电火灾。"},{"id":277,"ch":2,"t":"m","q":"下列关于爆炸极限的说法正确的有？","o":["爆炸下限越低越危险","爆炸范围越宽越危险","惰性气体可使范围变窄","温度升高使范围变窄","点火能量增大使范围变宽"],"a":"ABCE","e":"温度升高使爆炸极限范围变宽，故D错误。"},{"id":278,"ch":2,"t":"m","q":"下列爆炸中，属于化学爆炸的有？","o":["炸药爆炸","可燃气体混合物爆炸","锅炉爆炸","高压气瓶爆炸","轮胎爆裂"],"a":"AB","e":"锅炉、气瓶、轮胎爆炸为物理爆炸。"},{"id":279,"ch":2,"t":"m","q":"下列关于灭火方法实质的对应，正确的有？","o":["隔离法——移走或隔绝可燃物","窒息法——隔绝空气或降低氧含量","冷却法——降低温度至燃点以下","化学抑制法——抑制链式反应","冷却法——隔绝空气"],"a":"ABCD","e":"冷却法的实质是降温而非隔绝空气，故E错误。"},{"id":280,"ch":2,"t":"m","q":"火灾烟气对人员的危害主要有（　）。","o":["一氧化碳等有毒气体使人中毒窒息","高温烟气灼伤呼吸道","烟尘遮蔽视线、阻碍逃生","烟气消耗氧气导致缺氧"],"a":"ABCD","e":"烟气有毒、高温、遮光、耗氧，四项均为其危害。"},{"id":281,"ch":2,"t":"m","q":"扑救初起火灾时正确的做法有（　）。","o":["电气火灾先切断电源","使用就近适用的灭火器材","火势蔓延时及时报警并撤离","有人员被困时优先抢救","为抢救财物长时间滞留现场"],"a":"ABCD","e":"应断电、就近扑救、及时报警、救人第一；滞留抢财物错误。"},{"id":282,"ch":2,"t":"m","q":"安全疏散与逃生自救的要领包括（　）。","o":["用湿毛巾捂住口鼻、低姿前进","沿疏散指示标志和安全出口撤离","不乘坐普通电梯逃生","身上着火时就地打滚压灭","在浓烟中直立快速奔跑"],"a":"ABCD","e":"低姿捂口鼻、沿标志、不乘电梯、就地打滚均正确；直立快跑易吸入烟气。"},{"id":283,"ch":2,"t":"m","q":"拨打119报火警时应说明的内容有（　）。","o":["火灾发生的详细地址","起火物质和火势大小","有无人员被困","报警人姓名和联系电话","起火房间的装修风格"],"a":"ABCD","e":"报警要点为地点、火情、被困情况和联系方式，装修风格无关。"},{"id":284,"ch":2,"t":"m","q":"保护火灾现场的意义包括（　）。","o":["便于消防机构调查取证","有利于查明火灾原因","有利于认定事故责任","便于开展技术鉴定","便于立即恢复现场生产"],"a":"ABCD","e":"保护现场利于调查、定性、定责；立即恢复生产与之相悖。"},{"id":285,"ch":2,"t":"m","q":"防爆的基本技术措施包括（　）。","o":["通风换气","惰化处理","泄爆装置","防爆电器","敞开火源"],"a":"ABCD","e":"通风、惰化、泄爆、防爆电器均为防爆措施；敞开火源错误。"},{"id":286,"ch":2,"t":"m","q":"下列关于一氧化碳中毒的说法正确的有（　）。","o":["一氧化碳与血红蛋白结合导致组织缺氧","中毒初期可有头晕、恶心等症状","火场中应防止吸入含一氧化碳的烟气","一氧化碳有强烈刺激性气味"],"a":"ABC","e":"一氧化碳无色无味，故D错误；其余三项正确。"},{"id":287,"ch":2,"t":"m","q":"关于初起火灾扑救，下列说法正确的有（　）。","o":["发现火情应第一时间报警","使用灭火器时站在上风方向","电气火灾可用水直接扑救","火势失控时应立即撤离并疏散"],"a":"ABD","e":"电气火灾应先断电忌用水，故C错误；其余正确。"},{"id":288,"ch":2,"t":"m","q":"火场中人员疏散逃生的正确做法有（　）。","o":["沿安全出口疏散指示标志撤离","不贪恋财物","在烟雾中低姿并用湿毛巾捂口鼻","乘坐普通电梯快速下楼"],"a":"ABC","e":"火灾时不得乘电梯，故D错误；其余正确。"},{"id":289,"ch":2,"t":"m","q":"燃烧必须具备的条件包括（　）。","o":["可燃物","助燃物","点火源","链式反应","惰性气体"],"a":"ABCD","e":"燃烧需可燃物、助燃物、点火源三要素及链式反应，惰性气体非必需。"},{"id":290,"ch":2,"t":"m","q":"下列灭火措施中属于“窒息法”范畴的有（　）。","o":["用砂土覆盖燃烧物","用湿棉被捂盖起火点","用水浇淋燃烧物降温","将可燃物搬离火源"],"a":"AB","e":"砂土覆盖和湿棉被捂盖均隔绝空气属窒息法；C为冷却法，D为隔离法。"},{"id":291,"ch":2,"t":"m","q":"关于粉尘爆炸，下列说法正确的有（ ）。","o":["粉尘必须悬浮成云并达到爆炸浓度","常发生二次爆炸，破坏性更大","压力上升较慢，持续时间较长","粉尘爆炸只可能发生在完全密闭的容器中"],"a":"ABC","e":"粉尘爆炸需可燃粉尘悬浮成云并达到爆炸浓度，常因冲击波扬起积尘引发二次爆炸；与气体爆炸相比压力上升慢、持续时间长，但并非只能在完全密闭容器中发生。"},{"id":292,"ch":2,"t":"m","q":"扑救电气火灾时，下列做法正确的有（ ）。","o":["先切断电源，再根据情况灭火","未切断电源时可用水或泡沫灭火器直接扑救","带电灭火可使用二氧化碳灭火器","电视机着火时应从侧面靠近，防止显像管爆炸","火灾扑灭后应检查设备，防止复燃"],"a":"ACDE","e":"水、泡沫导电，未断电时直接扑救有触电危险；应先断电，带电时可用二氧化碳等不导电灭火剂，电视机从侧面灭火，扑灭后检查复燃。"},{"id":293,"ch":2,"t":"m","q":"下列化学品火灾的扑救方法中，正确的有（ ）。","o":["金属钠着火禁用水扑救","电石着火禁用水扑救","遇水燃烧物质可用泡沫灭火器扑救","可燃气体火灾应先切断气源再灭火","扑救氧化剂火灾可使用易燃液体作灭火剂"],"a":"ABD","e":"钠、电石遇水反应放热并生成可燃气体，泡沫含水也不能用；气体火灾应先切断气源；氧化剂会助燃，不能用易燃液体扑救。"},{"id":294,"ch":2,"t":"m","q":"关于爆炸性气体环境电气设备的选型与标志，正确的有（ ）。","o":["0区应采用本质安全型（ia）设备","1区可采用隔爆型（d）设备","2区可采用增安型（e）设备","隔爆型设备的防爆标志为“d”","防爆电气设备的外壳可以不接地"],"a":"ABCD","e":"0区危险程度最高，应采用ia型；1区可用隔爆型d等；2区可用增安型e等；防爆电气设备必须可靠接地，故E错误。"},{"id":295,"ch":2,"t":"m","q":"关于重质油品储罐火灾中的沸溢，下列说法正确的有（ ）。","o":["沸溢多发生在重质油品储罐火灾中","沸溢的根本原因是油品下部水垫层受热汽化","水变成蒸汽体积约膨胀1700倍，是沸溢破坏力的重要来源","沸溢只可能发生在汽油等轻质油品火灾中"],"a":"ABC","e":"重质油品燃烧形成热波向下传播，使底部水垫层汽化，水变蒸汽体积急剧膨胀，导致油品沸溢；轻质油品不易形成热波，故D错误。"},{"id":296,"ch":2,"t":"m","q":"关于实验室配备的手提式灭火器，下列说法正确的有（　）。","o":["一个计算单元内配置的灭火器数量不得少于2具","干粉灭火器出厂期满10年应当报废","灭火器顶部压力表指针位于绿区，表示瓶内驱动压力正常","灭火器应设置在明显、便于取用的地点，且不得影响安全疏散","二氧化碳灭火器可以倒置使用，以便把瓶内药剂全部喷出"],"a":"ABCD","e":"按GB 50140，一个计算单元内配置的灭火器数量不得少于2具；按GB 50444，手提式干粉灭火器出厂期满10年报废（水基型6年、洁净气体10年、二氧化碳12年）；贮压式灭火器压力表绿区表示压力正常；灭火器应设在明显、便于取用且不影响疏散的位置。二氧化碳灭火器必须直立使用，倒置后虹吸管脱离液面，喷出的是气相二氧化碳、灭火效率骤降且易冻伤，故E错误。"},{"id":297,"ch":2,"t":"j","q":"燃烧三要素即可燃物、助燃物和着火源。","o":["对","错"],"a":"对","e":"可燃物、助燃物、着火源是燃烧的三个基本要素。"},{"id":298,"ch":2,"t":"j","q":"可燃物、助燃物、着火源三者同时存在就一定会发生燃烧。","o":["对","错"],"a":"错","e":"三要素还须相互结合并达到一定比例和能量才会燃烧。"},{"id":299,"ch":2,"t":"j","q":"闪燃是液体蒸气遇火源发生的一闪即灭的燃烧现象。","o":["对","错"],"a":"对","e":"闪燃是蒸气遇火源瞬间一闪即灭的燃烧。"},{"id":300,"ch":2,"t":"j","q":"同一种可燃液体的燃点高于其自燃点。","o":["对","错"],"a":"错","e":"一般自燃点最高，燃点低于自燃点。"},{"id":301,"ch":2,"t":"j","q":"可燃液体的闪点越高，火灾危险性越大。","o":["对","错"],"a":"错","e":"闪点越低才越易着火，火灾危险性越大。"},{"id":302,"ch":2,"t":"j","q":"阴燃是在没有火焰的情况下进行的缓慢燃烧。","o":["对","错"],"a":"对","e":"阴燃即无火焰的缓慢燃烧，伴随大量烟。"},{"id":303,"ch":2,"t":"j","q":"一氧化碳是火灾中造成人员中毒伤亡的主要气体。","o":["对","错"],"a":"对","e":"一氧化碳是火灾中导致中毒伤亡最主要的气体。"},{"id":304,"ch":2,"t":"j","q":"火灾浓烟中的高温与缺氧是造成人员伤亡的重要原因。","o":["对","错"],"a":"对","e":"浓烟高温致灼伤、缺氧致窒息，均威胁人员生命。"},{"id":305,"ch":2,"t":"j","q":"锅炉、气瓶因内部压力超过强度极限而爆炸属于化学爆炸。","o":["对","错"],"a":"错","e":"压力超限爆炸为物理爆炸，无化学反应。"},{"id":306,"ch":2,"t":"j","q":"粉尘爆炸属于化学爆炸的一种具体形式。","o":["对","错"],"a":"对","e":"粉尘爆炸是可燃粉尘发生的剧烈氧化反应，属化学爆炸。"},{"id":307,"ch":2,"t":"j","q":"可燃气体浓度低于爆炸下限时，遇火源仍会发生爆炸。","o":["对","错"],"a":"错","e":"低于下限时混合物过稀，不会发生爆炸。"},{"id":308,"ch":2,"t":"j","q":"可燃气体浓度高于爆炸上限时，遇火源会立即爆炸。","o":["对","错"],"a":"错","e":"高于上限时混合物过浓，不会立即爆炸，遇空气混合后才可能燃烧。"},{"id":309,"ch":2,"t":"j","q":"温度升高会使可燃混合物的爆炸极限范围变宽。","o":["对","错"],"a":"对","e":"温度升高使爆炸下限降低、上限升高，范围变宽。"},{"id":310,"ch":2,"t":"j","q":"加入惰性气体可以缩小可燃混合物的爆炸极限范围甚至使其失去爆炸性。","o":["对","错"],"a":"对","e":"惰性气体可稀释可燃物、降低爆炸性，使范围变窄甚至不爆炸。"},{"id":311,"ch":2,"t":"j","q":"通风会使可燃气体浓度升高，增加爆炸风险。","o":["对","错"],"a":"错","e":"通风会降低可燃气体浓度，降低爆炸风险。"},{"id":312,"ch":2,"t":"j","q":"我国火警报警电话号码是119。","o":["对","错"],"a":"对","e":"我国火警电话为119。"},{"id":313,"ch":2,"t":"j","q":"未切断电源时，可以直接用水扑救带电的电气设备火灾。","o":["对","错"],"a":"错","e":"带电设备用水扑救易触电，应切断电源或用不导电灭火剂。"},{"id":314,"ch":2,"t":"j","q":"发生火灾时，为尽快逃生应乘坐电梯下楼。","o":["对","错"],"a":"错","e":"火灾时电梯易断电被困，应走安全疏散通道。"},{"id":315,"ch":2,"t":"j","q":"金属钠、镁等活泼金属火灾可以直接用水扑救。","o":["对","错"],"a":"错","e":"活泼金属遇水反应剧烈，应用专用灭火剂扑救。"},{"id":316,"ch":2,"t":"j","q":"火灾逃生时用湿毛巾捂住口鼻、低姿前进可减少烟气吸入。","o":["对","错"],"a":"对","e":"湿毛巾可过滤部分烟尘，低姿可避开上部浓烟。"},{"id":317,"ch":2,"t":"j","q":"燃烧必须具备可燃物、助燃物和点火源三个条件，三者缺一不可。","o":["对","错"],"a":"对","e":"燃烧三要素缺一不可。"},{"id":318,"ch":2,"t":"j","q":"液体的燃点通常低于其闪点。","o":["对","错"],"a":"错","e":"燃点通常高于闪点。"},{"id":319,"ch":2,"t":"j","q":"自燃必须依靠外来点火源才能发生。","o":["对","错"],"a":"错","e":"自燃不依赖外来火源，靠自身发热着火。"},{"id":320,"ch":2,"t":"j","q":"可燃气的爆炸下限越低、爆炸范围越宽，其火灾爆炸危险性越大。","o":["对","错"],"a":"对","e":"下限低、范围宽意味着更易形成爆炸性混合物。"},{"id":321,"ch":2,"t":"j","q":"温度升高会使可燃气体的爆炸极限范围变窄。","o":["对","错"],"a":"错","e":"温度升高使爆炸极限范围变宽。"},{"id":322,"ch":2,"t":"j","q":"向可燃气体中通入惰性气体可以扩大其爆炸极限范围。","o":["对","错"],"a":"错","e":"惰性气体使爆炸极限范围变窄。"},{"id":323,"ch":2,"t":"j","q":"容器尺寸越小，可燃气体的爆炸极限范围越窄。","o":["对","错"],"a":"对","e":"容器尺寸减小使爆炸极限范围变窄。"},{"id":324,"ch":2,"t":"j","q":"点火能量越大，可燃混合气的爆炸极限范围越宽。","o":["对","错"],"a":"对","e":"点火能量增大使爆炸极限范围变宽。"},{"id":325,"ch":2,"t":"j","q":"D类金属火灾可以直接用水扑救。","o":["对","错"],"a":"错","e":"水与活泼金属反应会加剧火势。"},{"id":326,"ch":2,"t":"j","q":"带电设备火灾可以用普通泡沫灭火器扑救。","o":["对","错"],"a":"错","e":"泡沫灭火器导电，不宜用于带电火灾。"},{"id":327,"ch":2,"t":"j","q":"二氧化碳灭火器适用于扑救带电设备火灾。","o":["对","错"],"a":"对","e":"二氧化碳不导电，适用于带电火灾。"},{"id":328,"ch":2,"t":"j","q":"使用灭火器扑救火灾时，应将喷嘴对准火焰的上部喷射。","o":["对","错"],"a":"错","e":"应瞄准火焰根部喷射。"},{"id":329,"ch":2,"t":"j","q":"我国火灾报警电话是119。","o":["对","错"],"a":"对","e":"火警电话为119。"},{"id":330,"ch":2,"t":"j","q":"化学抑制灭火法的实质是抑制燃烧的链式反应。","o":["对","错"],"a":"对","e":"化学抑制法中断自由基链式反应。"},{"id":331,"ch":2,"t":"j","q":"窒息灭火法的实质是隔绝空气或降低着火区域氧含量。","o":["对","错"],"a":"对","e":"窒息法隔绝助燃物（氧）。"},{"id":332,"ch":2,"t":"j","q":"冷却灭火法是将可燃物的温度降至其自燃点以下。","o":["对","错"],"a":"错","e":"冷却法是将温度降至燃点以下。"},{"id":333,"ch":2,"t":"j","q":"阴燃是没有火焰的缓慢燃烧现象。","o":["对","错"],"a":"对","e":"阴燃为无火焰的缓慢氧化。"},{"id":334,"ch":2,"t":"j","q":"火灾扑灭后，为便于查明起火原因，应尽量保护火灾现场。","o":["对","错"],"a":"对","e":"保护现场有利于查明起火原因。"},{"id":335,"ch":2,"t":"j","q":"燃烧必须具备可燃物、助燃物和点火源三个基本要素，缺一不可。","o":["对","错"],"a":"对","e":"燃烧三要素缺一则不能发生燃烧。"},{"id":336,"ch":2,"t":"j","q":"爆炸极限范围越窄，可燃物质的爆炸危险性越大。","o":["对","错"],"a":"错","e":"爆炸极限范围越宽，越易进入爆炸范围，危险性越大。"},{"id":337,"ch":2,"t":"j","q":"可燃气体爆炸下限越低，越容易发生爆炸。","o":["对","错"],"a":"对","e":"爆炸下限越低，较低浓度即可形成爆炸性混合物。"},{"id":338,"ch":2,"t":"j","q":"一氧化碳有强烈的刺激性气味，容易被人们察觉。","o":["对","错"],"a":"错","e":"一氧化碳无色无味，不易察觉，故危害极大。"},{"id":339,"ch":2,"t":"j","q":"金属钠、镁等着火时可以直接用水扑救。","o":["对","错"],"a":"错","e":"活泼金属遇水反应放热放氢，会加剧燃烧甚至爆炸。"},{"id":340,"ch":2,"t":"j","q":"电气设备着火时，应先切断电源再行扑救。","o":["对","错"],"a":"对","e":"先断电可避免触电并防止火势因带电扩大。"},{"id":341,"ch":2,"t":"j","q":"火场逃生时应乘坐普通电梯快速撤离。","o":["对","错"],"a":"错","e":"火灾时电梯易断电停运，应走安全疏散楼梯。"},{"id":342,"ch":2,"t":"j","q":"穿过浓烟区域时应尽量贴近地面、低姿前进。","o":["对","错"],"a":"对","e":"贴近地面的烟气浓度相对较低，可减少烟气吸入。"},{"id":343,"ch":2,"t":"j","q":"身上衣物着火时，应快速奔跑以借助风力灭火。","o":["对","错"],"a":"错","e":"奔跑加速空气流动会助长火势，应就地打滚压灭。"},{"id":344,"ch":2,"t":"j","q":"拨打119报警后，应立即挂断电话去扑救火灾。","o":["对","错"],"a":"错","e":"应等接警员确认信息无误后再挂断电话。"},{"id":345,"ch":2,"t":"j","q":"扑救初起火灾应遵循“先控制、后消灭，救人第一”的原则。","o":["对","错"],"a":"对","e":"初起火灾扑救坚持先控制后消灭、救人第一。"},{"id":346,"ch":2,"t":"j","q":"火灾发生后，无关人员不应随意破坏或清理火灾现场。","o":["对","错"],"a":"对","e":"保护现场有利于查明火灾原因和认定责任。"},{"id":347,"ch":2,"t":"j","q":"用砂土覆盖燃烧物以隔绝空气，属于窒息法灭火。","o":["对","错"],"a":"对","e":"窒息法即隔绝空气使燃烧物缺氧熄灭。"},{"id":348,"ch":2,"t":"j","q":"用水浇淋燃烧物以降低温度，属于隔离法灭火。","o":["对","错"],"a":"错","e":"降低燃烧物温度属于冷却法，而非隔离法。"},{"id":349,"ch":2,"t":"j","q":"静电放电是实验室的一种潜在点火源。","o":["对","错"],"a":"对","e":"静电放电产生的火花可引燃易燃蒸气或粉尘。"},{"id":350,"ch":2,"t":"j","q":"灭火器使用的一般顺序可概括为“提、拔、握、压”。","o":["对","错"],"a":"对","e":"提、拔、握、压是手提式灭火器的标准操作顺序。"},{"id":351,"ch":2,"t":"j","q":"阴燃是伴有明显火焰的快速燃烧。","o":["对","错"],"a":"错","e":"阴燃是无火焰、仅缓慢氧化放热的燃烧。"},{"id":352,"ch":2,"t":"j","q":"惰化防爆是通过充入惰性气体降低氧浓度实现的。","o":["对","错"],"a":"对","e":"充入惰性气体稀释氧气，可抑制爆炸发生。"},{"id":353,"ch":2,"t":"j","q":"常闭式防火门应保持关闭状态，不能为了通行方便而用灭火器、木楔等使其常开。","o":["对","错"],"a":"对","e":"常闭式防火门是阻挡烟气蔓延的重要设施，人为使其常开会失去隔烟阻火作用。"},{"id":354,"ch":2,"t":"j","q":"使用手提式干粉灭火器扑救地面火灾时，应站在下风方向，对准火焰上部喷射。","o":["对","错"],"a":"错","e":"应站在上风方向，对准火焰根部左右扫射，才能有效覆盖燃烧物；站在下风方向易被烟气和火焰伤害。"},{"id":355,"ch":2,"t":"b","q":"燃烧的三个基本条件是____、____和____，通常称为燃烧三要素。","a":["可燃物","助燃物","着火源"]},{"id":356,"ch":2,"t":"b","q":"可燃液体表面蒸气与空气混合后，遇火源发生一闪即灭的燃烧现象称为____。","a":["闪燃"]},{"id":357,"ch":2,"t":"b","q":"物质在空气中遇火源能够持续燃烧（至少5秒）的最低温度称为____。","a":["燃点"]},{"id":358,"ch":2,"t":"b","q":"物质在没有外部火源的情况下，依靠自身氧化放热等作用达到某温度而自行着火的最低温度称为____。","a":["自燃点"]},{"id":359,"ch":2,"t":"b","q":"燃烧产物中，与血红蛋白结合、使其丧失携氧能力的有毒气体是____。","a":["一氧化碳"]},{"id":360,"ch":2,"t":"b","q":"可燃气体与空气的混合物中，遇火源能发生爆炸的最低浓度称为____，最高浓度称为____。","a":["爆炸下限","爆炸上限"]},{"id":361,"ch":2,"t":"b","q":"爆炸按性质可分为____爆炸和____爆炸两大类。","a":["物理","化学"]},{"id":362,"ch":2,"t":"b","q":"我国火灾分类中，金属火灾属于____类火灾。","a":["D"]},{"id":363,"ch":2,"t":"b","q":"带电的电气设备火灾属于____类火灾。","a":["E"]},{"id":364,"ch":2,"t":"b","q":"灭火的四种基本方法是隔离法、____法、冷却法和____法。","a":["窒息","化学抑制"]},{"id":365,"ch":2,"t":"b","q":"我国火警报警电话号码是____。","a":["119"]},{"id":366,"ch":2,"t":"b","q":"在爆炸危险场所，为消除静电引发火灾爆炸而采取的最有效措施是____。","a":["接地"]},{"id":367,"ch":2,"t":"b","q":"在可燃气体环境中通入氮气、二氧化碳等气体，使混合物失去爆炸性，这种防爆措施称为____。","a":["惰化"]},{"id":368,"ch":2,"t":"b","q":"燃烧必须具备的三个基本条件（燃烧三要素）是____、____和____。","a":["可燃物","助燃物","点火源"]},{"id":369,"ch":2,"t":"b","q":"燃烧过程中还伴有自由基的____反应，它是化学抑制灭火法的作用对象。","a":["链式"]},{"id":370,"ch":2,"t":"b","q":"可燃液体表面的蒸气与空气混合物遇火源能发生闪燃的最低温度称为____。","a":["闪点"]},{"id":371,"ch":2,"t":"b","q":"可燃物质在无外来火源条件下，靠自身发热达到自行着火的最低温度称为____。","a":["自燃点"]},{"id":372,"ch":2,"t":"b","q":"可燃气体（蒸气）与空气混合后，遇火源能发生爆炸的浓度范围称为____。","a":["爆炸极限"]},{"id":373,"ch":2,"t":"b","q":"爆炸浓度范围的下限和上限分别称为____和____。","a":["爆炸下限","爆炸上限"]},{"id":374,"ch":2,"t":"b","q":"我国规定的火警报警电话是____。","a":["119"]},{"id":375,"ch":2,"t":"b","q":"A类火灾是指____物质火灾。","a":["固体"]},{"id":376,"ch":2,"t":"b","q":"B类火灾是指____或可熔化固体物质火灾。","a":["液体"]},{"id":377,"ch":2,"t":"b","q":"C类火灾是指____火灾。","a":["气体"]},{"id":378,"ch":2,"t":"b","q":"灭火的基本方法有隔离法、窒息法、冷却法和____法。","a":["化学抑制"]},{"id":379,"ch":2,"t":"b","q":"通风是实验室防爆的基本措施之一，其目的是使可燃气体（蒸气）的浓度低于其____。","a":["爆炸下限"]},{"id":380,"ch":2,"t":"b","q":"燃烧必须具备的三个基本要素是可燃物、助燃物和____。","a":["点火源"]},{"id":381,"ch":2,"t":"b","q":"物质在无外部点火源的情况下自行着火的最低温度称为____。","a":["自燃点"]},{"id":382,"ch":2,"t":"b","q":"我国火灾分类中，带电物体火灾属于____类火灾。","a":["E"]},{"id":383,"ch":2,"t":"b","q":"灭火的基本方法中，用水降低燃烧物温度属于____法。","a":["冷却"]},{"id":384,"ch":2,"t":"b","q":"可燃气体在空气中能发生爆炸的最低浓度称为____。","a":["爆炸下限"]},{"id":385,"ch":2,"t":"b","q":"大量泄漏的可燃气体或蒸气与空气混合遇火源发生的爆炸称为____爆炸。","a":["蒸气云"]},{"id":386,"ch":2,"t":"b","q":"防爆措施中，向系统充入惰性气体以降低氧浓度的方法称为____。","a":["惰化"]},{"id":387,"ch":2,"t":"b","q":"使用手提式干粉灭火器的操作顺序可概括为“提、拔、____、压”。","a":["握"]},{"id":388,"ch":2,"t":"b","q":"没有火焰、仅缓慢氧化放热的燃烧形式称为____。","a":["阴燃"]},{"id":389,"ch":2,"t":"b","q":"发现火灾后应立即拨打火警电话____；报警后应派人到____等候，引导消防车进入火场。","a":["119","路口"],"e":"火警电话为119；报警时应讲清地址、燃烧物质、火势和有无人员被困，并到路口引导消防车。"},{"id":390,"ch":2,"t":"b","q":"氧气瓶与乙炔瓶的工作间距不应小于____m；气瓶与明火的距离不应小于____m。","a":["5","10"],"e":"为防止氧气与乙炔混合爆炸及气瓶受明火烘烤，氧气瓶与乙炔瓶间距不得小于5m，气瓶与明火距离不得小于10m。"},{"id":391,"ch":2,"t":"b","q":"在实验室进行动火作业前，必须办理____；动火分析时，若可燃气体或蒸气的爆炸下限大于或等于4%，其浓度应不大于____%（体积分数）方为合格。","a":["动火许可证","0.5"],"e":"动火作业应履行动火审批手续；按动火分析标准，爆炸下限≥4%时可燃气体浓度应≤0.5%，爆炸下限＜4%时应≤0.2%。"},{"id":392,"ch":2,"t":"b","q":"火灾烟气中导致人员窒息和中毒的主要气体是____；据统计，火灾死亡人数中约____%与烟气吸入有关。","a":["一氧化碳","80"],"e":"一氧化碳与血红蛋白结合能力远强于氧气，是烟气中毒的主要成分；火灾死亡人员中约80%与烟气吸入有关。"},{"id":393,"ch":2,"t":"x","q":"简述燃烧的三要素及链式反应理论的基本内容，并说明灭火的基本思路。","a":"1.燃烧三要素：即可燃物、助燃物（氧化剂）和着火源，三者缺一不可；2.链式反应理论：燃烧过程中不断产生自由基（游离基），自由基的链式传递使燃烧反应得以持续发展；3.灭火基本思路：破坏燃烧条件或中断链式反应，具体包括移走可燃物（隔离法）、隔绝氧气（窒息法）、把温度降到燃点以下（冷却法）以及加入抑制剂中断链式反应（化学抑制法）。"},{"id":394,"ch":2,"t":"x","q":"简述闪点、燃点、自燃点的概念，并说明三者之间的关系。","a":"1.闪点：可燃液体蒸气与空气的混合物遇火源能发生闪燃的最低温度，是衡量液体火灾危险性的主要指标；2.燃点：物质在空气中遇火源能够持续燃烧（至少5秒）的最低温度；3.自燃点：物质在没有外部火源的情况下，依靠自身氧化放热等作用而自行着火的最低温度；4.三者关系：对同一种可燃液体，一般自燃点＞燃点＞闪点，且闪点越低，火灾危险性越大。"},{"id":395,"ch":2,"t":"x","q":"某实验室突发初起火灾，请简述正确的应急处置程序。","a":"1.立即报警：拨打119，讲清起火地点、起火物质、火势大小、有无人员被困以及报警人姓名和联系电话；2.及时扑救：在确保自身安全的前提下，用灭火器等扑救初起火灾，坚持报警早损失小、边报警边扑救、先控制后消灭、先救人后救物的原则；3.疏散逃生：沿疏散通道低姿撤离，用湿毛巾捂住口鼻，不乘坐电梯；4.切断电源、关闭可燃气体阀门，防止火势扩大；5.保护火灾现场，配合事后调查。"},{"id":396,"ch":2,"t":"x","q":"简述影响可燃气体（蒸气）爆炸极限的主要因素及其影响规律。","a":"1.温度：温度升高，爆炸极限范围变宽（下限降低、上限升高），危险性增大；2.压力：压力升高，爆炸极限范围变宽，危险性增大；3.惰性气体：混入惰性气体可使爆炸极限范围变窄，惰性气体含量足够大时可使其失去爆炸性；4.容器尺寸：容器尺寸（直径）减小，爆炸极限范围变窄；5.点火能量：点火能量越大，爆炸极限范围越宽。"},{"id":397,"ch":2,"t":"x","q":"简述灭火的四种基本方法及其实质，并各举一例。","a":"1.隔离法：将可燃物与火源隔离或移走，切断可燃物来源，例如移开着火点周围可燃物、关闭阀门切断可燃气体；2.窒息法：隔绝空气或降低着火区域氧含量，使燃烧因缺氧停止，例如用石棉毯覆盖着火物、喷射二氧化碳；3.冷却法：将可燃物温度降低到燃点以下，使其不能继续燃烧，例如用水浇淋燃烧物；4.化学抑制法：喷入抑燃剂抑制燃烧的链式反应，例如干粉灭火剂中断自由基链式反应。"},{"id":398,"ch":2,"t":"x","q":"案例分析：实验室发生初起火灾时应如何处置？报警时应说明哪些内容？","a":"处置：1.保持冷静，立即切断电源、气源并移走附近可燃物；2.迅速拨打119报警，同时组织现场人员利用就近灭火器扑救初起火灾；3.若火势蔓延或危及安全，立即按疏散路线撤离，切勿贪恋财物、切勿乘坐电梯；4.扑救后保护现场，配合查明原因。报警内容：应说明火灾发生的具体地点（单位、楼层、房间号）、起火物质和火势大小、有无人员被困或受伤、报警人姓名及联系电话，并到路口引导消防车。"},{"id":399,"ch":2,"t":"x","q":"简述实验室发生火灾后正确的处置程序。","a":"1.立即报警：第一时间拨打119，讲清火灾详细地址、起火物质、火势大小、有无人员被困及本人姓名和电话，等对方确认后再挂断。2.切断电源：在确保安全的前提下切断起火区域的电源和气源，防止火势扩大并避免触电。3.扑救初起火灾：火势尚小且有把握时，选用就近、适用的灭火器材，站在上风方向对准火焰根部扑救；电气火灾应先断电，切忌用水扑救。4.疏散逃生：若火势失控，立即组织人员沿安全出口和疏散指示标志低姿撤离，用湿毛巾捂口鼻，不乘电梯、不贪恋财物。5.保护现场：灭火后保留现场原状，协助消防部门查明起火原因。"},{"id":400,"ch":2,"t":"x","q":"简述火场中安全疏散与逃生自救的主要要领。","a":"1.保持冷静，迅速判明火势和疏散方向，沿安全出口、疏散指示标志有序撤离，不拥挤、不乘普通电梯。2.穿过烟雾区时，用湿毛巾或衣物捂住口鼻，尽量弯腰低姿或匍匐前进，减少吸入有毒烟气。3.身上衣物着火时，应就地打滚或用厚衣物覆盖压灭，切忌奔跑。4.被困室内时，紧闭门窗、用湿布堵塞门缝防止烟气渗入，并在窗口呼救、晃动醒目物品等待救援，不盲目跳楼。5.撤离后切勿重返火场，及时清点人数并报告，协助开展后续处置。"},{"id":401,"ch":3,"t":"s","q":"火灾自动报警系统的基本组成不包括下列哪一项？","o":["火灾探测器","火灾报警控制器","自动喷水灭火喷头","消防联动控制设备"],"a":"C","e":"自动喷水灭火喷头属于自动喷水灭火系统的组件，不是火灾自动报警系统的组成部分。"},{"id":402,"ch":3,"t":"s","q":"能够探测火灾初期产生的烟雾并发出报警信号的器件是？","o":["感烟探测器","感温探测器","感光探测器","可燃气体探测器"],"a":"A","e":"感烟探测器对火灾初期的烟雾敏感，适用于早期报警。"},{"id":403,"ch":3,"t":"s","q":"离子式和光电式火灾探测器都属于？","o":["感温探测器","感光探测器","复合探测器","感烟探测器"],"a":"D","e":"离子式和光电式都是依据烟雾对探测器内部电信号的影响来工作的感烟探测器。"},{"id":404,"ch":3,"t":"s","q":"定温式、差温式和差定温式火灾探测器属于？","o":["感烟探测器","感温探测器","感光探测器","可燃气体探测器"],"a":"B","e":"这三类探测器均以环境温度变化为动作依据，属感温探测器。"},{"id":405,"ch":3,"t":"s","q":"厨房、锅炉房等经常有烟气和粉尘的场所不宜选用？","o":["感温探测器","感烟探测器","感光探测器","可燃气体探测器"],"a":"B","e":"感烟探测器易受烟尘干扰而误报，此类场所宜选用感温探测器。"},{"id":406,"ch":3,"t":"s","q":"火灾自动报警系统中承担接收、显示和传递火灾报警信号的核心设备是？","o":["火灾探测器","手动报警按钮","声光警报器","火灾报警控制器"],"a":"D","e":"火灾报警控制器是系统的核心，负责接收信号、发出报警并控制联动。"},{"id":407,"ch":3,"t":"s","q":"火灾探测器、手动火灾报警按钮等能够自动或手动产生火灾报警信号的器件统称为？","o":["触发器件","警报器件","联动器件","电源器件"],"a":"A","e":"触发器件是火灾自动报警系统中首先动作、产生报警信号的部件。"},{"id":408,"ch":3,"t":"s","q":"消防控制室值班人员接到火灾报警信号后，首先应当？","o":["立即启动喷淋泵","直接拨打火警电话","确认火情并按预案处置","切断消防电源"],"a":"C","e":"应先通过现场或视频等方式确认火情，再按应急预案处置，避免盲目操作。"},{"id":409,"ch":3,"t":"s","q":"火灾报警控制器发出声响报警后，为便于核对报警信息，通常先进行？","o":["消音","复位","屏蔽","关机"],"a":"A","e":"消音可暂时停止声响而不丢失报警信息，便于值班人员核查。"},{"id":410,"ch":3,"t":"s","q":"发现探测器频繁误报时，正确的处理方式是？","o":["立即复位了事","长期屏蔽该探测器","查明原因、记录后复位","直接拆下探测器"],"a":"C","e":"应查明误报原因并做好记录，不能以长期屏蔽或拆除的方式掩盖问题。"},{"id":411,"ch":3,"t":"s","q":"火灾自动报警系统投入运行后，应当？","o":["每年全部更换一次","定期进行功能检查和维护保养","仅在发生故障时检查","长期关闭以减少误报"],"a":"B","e":"系统需定期维护保养和功能试验，才能保证火灾时可靠动作。"},{"id":412,"ch":3,"t":"s","q":"探测器表面积尘会影响其探测灵敏度，正确的做法是？","o":["调高报警灵敏度","提高供电电压","将该探测器屏蔽","及时清洗维护"],"a":"D","e":"积尘会改变探测器的响应特性，应按要求清洗并做功能试验。"},{"id":413,"ch":3,"t":"s","q":"消防控制室值班人员的任职要求是？","o":["可由保安临时兼任","只需会接听电话","允许短时无人值守","持证上岗并熟悉应急处置程序"],"a":"D","e":"消防控制室值班人员须经培训持证上岗，熟练掌握设施操作和应急程序。"},{"id":414,"ch":3,"t":"s","q":"消防控制室接到火灾报警后，值班人员应当？","o":["先拨打火警电话再确认","按程序确认并组织处置","先通知物业领导","关闭报警器以免扰民"],"a":"B","e":"应按消防控制室应急程序确认火情、启动设施并报警，各环节有序进行。"},{"id":415,"ch":3,"t":"s","q":"消防控制室的值班记录应当？","o":["每月集中补填一次","无须保存","如实填写并保存备查","只记录设备故障"],"a":"C","e":"值班记录须真实完整，包括报警、故障和处置情况，并按规定保存。"},{"id":416,"ch":3,"t":"s","q":"消防应急广播系统在火灾时的主要作用是？","o":["发布疏散指令、引导人员疏散","播放背景音乐","发布日常行政通知","记录消防电话通话"],"a":"A","e":"消防应急广播用于火灾时发布疏散指令，指挥人员安全撤离。"},{"id":417,"ch":3,"t":"s","q":"消防专用电话系统的主要特点是？","o":["与普通电话共用线路","独立布线、可直接呼叫消防控制室","只能拨打外线","仅供单位领导使用"],"a":"B","e":"消防专用电话独立设置，火灾时可直接与消防控制室及有关部位通话。"},{"id":418,"ch":3,"t":"s","q":"消防控制室与消防水泵房之间的火灾应急通信应依靠？","o":["消防专用电话","普通手机","应急广播","口头传话"],"a":"A","e":"消防专用电话是消防控制室与水泵房、配电室等关键部位的规定通信手段。"},{"id":419,"ch":3,"t":"s","q":"室内消火栓系统使用的主要灭火介质是？","o":["泡沫","水","干粉","二氧化碳"],"a":"B","e":"室内消火栓系统属水灭火系统，通过水带水枪输送压力水灭火。"},{"id":420,"ch":3,"t":"s","q":"室内消火栓箱内通常不配备下列哪一项？","o":["灭火器","消防水带","水枪","消火栓接口"],"a":"A","e":"消火栓箱的标配为消火栓接口、水带、水枪和消火栓按钮，灭火器另行配置。"},{"id":421,"ch":3,"t":"s","q":"使用室内消火栓灭火的正确操作顺序是？","o":["先开阀、再接水带、最后开水枪","先开水枪、再接水带","只开阀不接水带","接好水带水枪、开启阀门、握紧水枪对准火源根部"],"a":"D","e":"应先连接水带与水枪，再缓慢开启阀门，防止水锤伤人并保证射流有效。"},{"id":422,"ch":3,"t":"s","q":"使用室内消火栓灭火一般需要几人配合操作？","o":["1人","3人","2人","4人"],"a":"C","e":"通常由两人配合，一人开启阀门，一人握持水枪灭火。"},{"id":423,"ch":3,"t":"s","q":"室内消火栓的水枪射流应当对准？","o":["燃烧物根部","火焰上部","火焰中部","烟雾最浓处"],"a":"A","e":"射流对准燃烧物根部才能有效降温灭火，对准火焰上部效果很差。"},{"id":424,"ch":3,"t":"s","q":"室外消火栓的主要用途是？","o":["供应生活用水","供消防车取水和灭火","绿化浇灌","排放污水"],"a":"B","e":"室外消火栓为消防车提供水源，也可直接连接水带灭火。"},{"id":425,"ch":3,"t":"s","q":"室外消火栓按设置形式可分为？","o":["地上式和地下式","高压式和低压式","单口式和双口式","室内式和室外式"],"a":"A","e":"按安装位置形式，室外消火栓分为地上式和地下式两类。"},{"id":426,"ch":3,"t":"s","q":"室外消火栓周围不得堆放物品、停放车辆，主要是为了？","o":["保持环境美观","防止栓体冻裂","便于绿化养护","保证消防车取水和正常使用"],"a":"D","e":"消火栓被埋压、圈占或遮挡会延误取水，必须保持通道畅通。"},{"id":427,"ch":3,"t":"s","q":"火灾自动报警系统的传输线路应当采用？","o":["普通铝芯导线","阻燃或耐火铜芯导线","任意绝缘导线","普通电话线"],"a":"B","e":"火灾时线路需保持一定时间通电，应采用阻燃或耐火铜芯导线。"},{"id":428,"ch":3,"t":"s","q":"手动火灾报警按钮应当设置在？","o":["隐蔽不易发现的部位","吊顶内部","明显且便于操作的部位","配电箱内"],"a":"C","e":"手动报警按钮需便于人员发现和操作，一般设在疏散通道等明显部位。"},{"id":429,"ch":3,"t":"s","q":"感光探测器适用于下列哪类场所？","o":["火灾初期阴燃、产生大量烟雾的场所","火灾发展迅速、有强烈火焰辐射的场所","温度缓慢升高的场所","可燃气体易泄漏的场所"],"a":"B","e":"感光探测器对火焰辐射敏感，适用于起火迅速、火焰强烈的场所。"},{"id":430,"ch":3,"t":"s","q":"可燃气体探测器应当安装在？","o":["可能发生可燃气体泄漏的场所","卫生间","封闭楼梯间","普通办公室"],"a":"A","e":"可燃气体探测器用于监测泄漏，应设在使用或储存可燃气体的危险部位。"},{"id":431,"ch":3,"t":"s","q":"复合式火灾探测器的含义是？","o":["只能探测烟雾","只能探测温度","只报警不参与联动","能同时或分别探测两种以上火灾参数"],"a":"D","e":"复合探测器综合感烟、感温等多种参数，可降低误报、提高可靠性。"},{"id":432,"ch":3,"t":"s","q":"火灾自动报警系统按报警形式可分为？","o":["感烟式、感温式和感光式","定温式、差温式和差定温式","区域报警、集中报警和控制中心报警系统","手动报警和自动报警系统"],"a":"C","e":"按报警与控制范围，系统分为区域、集中和控制中心三种基本形式。"},{"id":433,"ch":3,"t":"s","q":"消防联动控制器在火灾时的主要作用是？","o":["记录火警发生时间","按预设逻辑启动相关消防设备","播放疏散语音指令","显示探测器所在地址"],"a":"B","e":"消防联动控制器按预定逻辑联动消防泵、排烟机、防火卷帘等设备。"},{"id":434,"ch":3,"t":"s","q":"消防控制室的设置位置应当满足？","o":["设在首层或地下一层，并有直通室外的安全出口","设在建筑物顶层","可设在任意楼层","设在最底层地下室"],"a":"A","e":"消防控制室需设在交通便利、便于消防人员到达且能直通室外的部位。"},{"id":435,"ch":3,"t":"s","q":"湿式自动喷水灭火系统在准工作状态时管道内充满有压水，其适用的环境温度范围是","o":["4℃~70℃","0℃~100℃","-10℃~50℃","不受温度限制"],"a":"A","e":"湿式系统适用于温度不低于4℃且不高于70℃的环境。"},{"id":436,"ch":3,"t":"s","q":"某北方城市一座不采暖的地下车库，冬季室内温度可降至0℃以下，该场所宜采用的自动喷水灭火系统是","o":["湿式系统","预作用系统","雨淋系统","干式系统"],"a":"D","e":"干式系统管道内充有压气体，适用于环境温度低于4℃或高于70℃的场所。"},{"id":437,"ch":3,"t":"s","q":"计算机房、档案馆等既不允许误喷、也不允许管道渗漏的场所，宜采用的自动喷水灭火系统是","o":["预作用系统","湿式系统","干式系统","雨淋系统"],"a":"A","e":"预作用系统平时管内不充水，火灾报警后才充水，可避免误喷和渗漏。"},{"id":438,"ch":3,"t":"s","q":"剧院舞台葡萄架下部火灾蔓延迅速，闭式喷头难以及时有效控火，该部位应设置的自动喷水灭火系统是","o":["湿式系统","雨淋系统","干式系统","预作用系统"],"a":"B","e":"雨淋系统采用开式喷头，动作后整组喷头同时喷水，适合蔓延迅速的场所。"},{"id":439,"ch":3,"t":"s","q":"自动喷水灭火系统中，主要用于防火分隔和冷却保护、不以直接灭火为主要目的的是","o":["湿式系统","水喷雾系统","雨淋系统","水幕系统"],"a":"D","e":"水幕系统喷水形成水幕，用于防火分隔、冷却保护，而非直接灭火。"},{"id":440,"ch":3,"t":"s","q":"消防电梯的载重量不应小于","o":["800kg","630kg","450kg","1000kg"],"a":"A","e":"消防电梯需运送消防员和器材，载重量不应小于800kg。"},{"id":441,"ch":3,"t":"s","q":"消防电梯前室的门应采用","o":["甲级防火门","丙级防火门","钢制防盗门","乙级防火门"],"a":"D","e":"消防电梯前室属疏散通道上的重要分隔部位，门应采用乙级防火门。"},{"id":442,"ch":3,"t":"s","q":"消防电梯从首层到顶层的运行时间不宜大于","o":["30s","60s","90s","120s"],"a":"B","e":"为保证灭火救援及时，消防电梯从首层到顶层的运行时间不宜大于60s。"},{"id":443,"ch":3,"t":"s","q":"灯光疏散指示标志中的安全出口标志灯，应设置在","o":["疏散走道的地面上","房间吊顶内","楼梯踏步上","安全出口和疏散门的正上方"],"a":"D","e":"安全出口标志灯应设在安全出口和疏散门的正上方，便于人员识别。"},{"id":444,"ch":3,"t":"s","q":"沿疏散走道设置的灯光疏散指示标志，其间距不应大于","o":["20m","10m","15m","30m"],"a":"A","e":"疏散走道上标志灯间距不应大于20m，袋形走道内不应大于10m。"},{"id":445,"ch":3,"t":"s","q":"设置在墙面上的灯光疏散指示标志，其底边距地面的高度不宜大于","o":["0.5m","1.0m","1.5m","2.0m"],"a":"B","e":"标志灯宜设在距地面1m以下的墙面或地面上，以便在烟气中辨认。"},{"id":446,"ch":3,"t":"s","q":"火灾确认后，消防应急照明和疏散指示系统的应急启动时间不应大于","o":["1s","3s","5s","15s"],"a":"C","e":"系统应在火灾确认后5s内完成应急启动，及时提供照明和指示。"},{"id":447,"ch":3,"t":"s","q":"甲级防火门的耐火极限不应低于","o":["0.50h","1.00h","1.50h","2.00h"],"a":"C","e":"防火门分甲、乙、丙三级，甲级耐火极限不低于1.50h。"},{"id":448,"ch":3,"t":"s","q":"建筑物内管道井、电缆井的检查门应采用","o":["丙级防火门","乙级防火门","甲级防火门","普通木门"],"a":"A","e":"管道井、电缆井检查门采用丙级防火门，可阻止火势沿竖井蔓延。"},{"id":449,"ch":3,"t":"s","q":"对常闭式防火门的日常管理要求是","o":["平时保持开启以方便通行","用杂物抵住使其半开","仅在火灾时关闭","平时保持关闭，且不得上锁"],"a":"D","e":"常闭防火门平时须保持关闭状态，防止烟气侵入楼梯间，且不得上锁。"},{"id":450,"ch":3,"t":"s","q":"当防火卷帘用于替代防火墙进行防火分隔时，其耐火极限不应低于","o":["1.00h","2.00h","3.00h","该部位墙体的耐火极限"],"a":"D","e":"替代防火墙的防火卷帘，耐火极限不应低于所设置部位墙体的要求。"},{"id":451,"ch":3,"t":"s","q":"公共建筑内每个防火分区安全出口的数量应经计算确定，且不应少于","o":["1个","2个","3个","4个"],"a":"B","e":"每个防火分区安全出口不应少于2个，以保证疏散路径互为备用。"},{"id":452,"ch":3,"t":"s","q":"建筑内两个安全出口最近边缘之间的水平距离不应小于","o":["3m","5m","8m","10m"],"a":"B","e":"安全出口应分散布置，最近边缘水平距离不应小于5m。"},{"id":453,"ch":3,"t":"s","q":"公共建筑内疏散门和安全出口的净宽度不应小于","o":["0.8m","0.9m","1.0m","1.1m"],"a":"B","e":"疏散门和安全出口净宽度不应小于0.90m，疏散走道不应小于1.10m。"},{"id":454,"ch":3,"t":"s","q":"防烟楼梯间通向前室和楼梯间的门应采用","o":["甲级防火门","乙级防火门","丙级防火门","防火卷帘"],"a":"B","e":"防烟楼梯间前室的门应采用乙级防火门，以阻挡烟气进入楼梯间。"},{"id":455,"ch":3,"t":"s","q":"封闭楼梯间应靠外墙设置，并宜能","o":["自然采光和自然通风","设置烧水间","存放可燃材料","敷设可燃气体管道"],"a":"A","e":"封闭楼梯间靠外墙并宜自然通风采光，可有效排出可能进入的烟气。"},{"id":456,"ch":3,"t":"s","q":"安装在通风、空调系统送、回风管道上的防火阀，其公称动作温度为","o":["70℃","100℃","150℃","280℃"],"a":"A","e":"通风空调系统防火阀动作温度为70℃，防止火势沿风管蔓延。"},{"id":457,"ch":3,"t":"s","q":"机械排烟系统管道上设置的排烟防火阀，当烟气温度达到多少时自动关闭","o":["70℃","150℃","280℃","400℃"],"a":"C","e":"排烟防火阀在烟气温度达到280℃时关闭，防止火势通过排烟管道蔓延。"},{"id":458,"ch":3,"t":"s","q":"排烟风机应能在烟气温度为280℃的条件下连续工作","o":["10min","20min","30min","60min"],"a":"C","e":"排烟风机应保证在280℃时连续工作30min，满足火灾初期排烟需要。"},{"id":459,"ch":3,"t":"s","q":"配电房、精密电子设备等场所发生火灾，灭火后要求不留残渣、不损坏设备，宜选用的灭火器是","o":["六氟丙烷灭火器","泡沫灭火器","干粉灭火器","清水灭火器"],"a":"A","e":"六氟丙烷属洁净气体灭火剂，灭火后不留残渣，适用于电子设备场所。"},{"id":460,"ch":3,"t":"s","q":"泡沫灭火器不宜用于扑救的火灾是","o":["木材等固体火灾","汽油等液体火灾","纸张火灾","带电设备火灾"],"a":"D","e":"泡沫含水导电，不宜用于带电设备火灾，以免造成触电和短路。"},{"id":461,"ch":3,"t":"s","q":"ABC干粉灭火器不宜用于扑救的火灾是","o":["木材火灾","汽油火灾","天然气火灾","钾、钠等金属火灾"],"a":"D","e":"钾、钠等金属火灾属D类火灾，应使用专用金属干粉灭火器扑救。"},{"id":462,"ch":3,"t":"s","q":"清水灭火器仅适用于扑救","o":["A类固体火灾","B类液体火灾","C类气体火灾","E类带电火灾"],"a":"A","e":"清水灭火器依靠水的冷却作用灭火，仅适用于A类固体火灾。"},{"id":463,"ch":3,"t":"s","q":"一个计算单元内配置的灭火器数量不应少于","o":["1具","2具","3具","4具"],"a":"B","e":"一个计算单元内配置的灭火器数量不得少于2具，以保证扑救能力。"},{"id":464,"ch":3,"t":"s","q":"A类火灾中危险级场所，手提式灭火器的最大保护距离为","o":["10m","15m","20m","25m"],"a":"C","e":"A类火灾中危险级场所手提式灭火器最大保护距离为20m。"},{"id":465,"ch":3,"t":"s","q":"手提式灭火器设置在挂钩、托架上时，其顶部离地面的高度不应大于","o":["1.0m","1.2m","1.5m","1.8m"],"a":"C","e":"灭火器顶部离地面高度不应大于1.50m，底部离地面不宜小于0.08m。"},{"id":466,"ch":3,"t":"s","q":"对有视线障碍的灭火器设置点，应设置","o":["警示围栏","指示其位置的发光标识","专人看管","临时隔离带"],"a":"B","e":"设置发光标识可指示灭火器位置，便于人员在紧急情况下迅速取用。"},{"id":467,"ch":3,"t":"s","q":"手提式干粉灭火器出厂期满5年进行首次维修后，其维修周期为","o":["每半年","每满1年","每满2年","每满3年"],"a":"C","e":"干粉灭火器首次维修以后每满2年维修一次，以保证其可靠性。"},{"id":468,"ch":3,"t":"s","q":"手提式干粉灭火器的报废年限为","o":["6年","8年","10年","12年"],"a":"C","e":"干粉灭火器自出厂之日起满10年应报废，不得继续使用。"},{"id":469,"ch":3,"t":"m","q":"火灾自动报警系统一般由下列哪些部分组成？","o":["触发器件","火灾报警装置","火灾警报装置","消防联动控制设备"],"a":"ABCD","e":"系统由触发器件、报警装置、警报装置、联动控制设备和电源等组成。"},{"id":470,"ch":3,"t":"m","q":"感烟探测器主要包括下列哪些类型？","o":["离子式","光电式","定温式","红外光束式"],"a":"ABD","e":"定温式属于感温探测器，其余均为感烟探测器的形式。"},{"id":471,"ch":3,"t":"m","q":"属于感温探测器的有？","o":["光电式","定温式","差温式","差定温式"],"a":"BCD","e":"光电式为感烟探测器，定温、差温、差定温均以温度变化为动作条件。"},{"id":472,"ch":3,"t":"m","q":"下列哪些场所不宜选用感烟探测器？","o":["厨房","办公室","锅炉房","有大量粉尘的车间"],"a":"ACD","e":"厨房、锅炉房和粉尘场所的烟尘易引起感烟探测器误报。"},{"id":473,"ch":3,"t":"m","q":"火灾报警控制器的主要功能包括？","o":["直接扑灭初起火灾","接收火灾报警信号","发出声光报警","记录和显示报警信息"],"a":"BCD","e":"控制器负责信号接收、报警、显示记录和联动控制，本身不能灭火。"},{"id":474,"ch":3,"t":"m","q":"火灾自动报警系统维护检查的内容包括？","o":["探测器清洗","功能试验","线路检查","备用电源检查","随意拆除探测器"],"a":"ABCD","e":"维护应涵盖探测器、线路、电源及功能试验，拆除探测器属违规行为。"},{"id":475,"ch":3,"t":"m","q":"消防控制室值班人员应当做到？","o":["持证上岗","熟悉消防设施位置和操作方法","如实填写值班记录","及时确认和处置报警","擅自关闭报警系统"],"a":"ABCD","e":"值班人员须持证、熟悉设施、如实记录并及时处置，不得擅自关闭系统。"},{"id":476,"ch":3,"t":"m","q":"消防应急广播系统在火灾时的作用有？","o":["发布疏散指令","引导人员有序疏散","播放背景音乐","稳定人员情绪"],"a":"ABD","e":"应急广播用于发布疏散指令、引导撤离并稳定情绪，火灾时不应播放音乐。"},{"id":477,"ch":3,"t":"m","q":"消防专用电话通常设置在下列哪些部位？","o":["消防控制室","普通办公室","消防水泵房","变配电室"],"a":"ACD","e":"消防专用电话设在控制室及水泵房、配电室、电梯机房等关键部位。"},{"id":478,"ch":3,"t":"m","q":"室内消火栓箱内通常配置有？","o":["消火栓接口","消防水带","水枪","灭火器"],"a":"ABC","e":"消火栓箱标配为接口、水带、水枪和按钮，灭火器不属其标准配置。"},{"id":479,"ch":3,"t":"m","q":"使用室内消火栓灭火时应注意？","o":["确认现场已切断电源","两人配合操作","由一人独自操作","水枪对准燃烧物根部"],"a":"ABD","e":"带电火灾应先断电，操作需两人配合，射流对准燃烧物根部。"},{"id":480,"ch":3,"t":"m","q":"室外消火栓的设置和使用应满足？","o":["便于消防车取水","可任意设在绿化带深处","周围不得堆放物品","不得埋压、圈占"],"a":"ACD","e":"室外消火栓须便于取水，周围保持畅通，严禁埋压、圈占和遮挡。"},{"id":481,"ch":3,"t":"m","q":"火灾探测器选型时应考虑的因素有？","o":["场所的火灾特点","房间高度","环境条件","探测器性能","价格越高越好"],"a":"ABCD","e":"选型应综合火灾特点、空间高度、环境条件和产品性能，价格不是依据。"},{"id":482,"ch":3,"t":"m","q":"造成火灾自动报警系统误报的常见原因有？","o":["探测器积尘","环境湿度大","人为吸烟","探测器清洗"],"a":"ABC","e":"积尘、潮湿和吸烟烟雾均可能引起误报，定期清洗则是减少误报的措施。"},{"id":483,"ch":3,"t":"m","q":"关于湿式自动喷水灭火系统的说法，正确的有","o":["准工作状态时管道内充满有压水","系统采用闭式喷头，喷头动作后自动喷水","喷头动作后能及时出水，控火速度快","适用于严寒地区无采暖的场所","系统需设置排气装置以排出管内空气"],"a":"ABC","e":"湿式系统充有压水、响应快；严寒无采暖场所应用干式系统，排气装置属干式系统。"},{"id":484,"ch":3,"t":"m","q":"关于雨淋系统与水幕系统的说法，正确的有","o":["雨淋系统采用开式喷头","雨淋系统可由火灾自动报警系统或传动管控制启动","雨淋系统启动后，保护区内的开式喷头同时喷水","水幕系统采用闭式喷头，喷头逐个动作","水幕系统喷水形成的屏障只能用于灭火，不能用于冷却"],"a":"ABC","e":"雨淋与水幕系统均采用开式喷头，水幕主要用于防火分隔和冷却。"},{"id":485,"ch":3,"t":"m","q":"下列属于自动喷水灭火系统的有","o":["湿式系统","干式系统","预作用系统","水喷雾系统","泡沫枪"],"a":"ABCD","e":"自动喷水灭火系统包括湿式、干式、预作用、雨淋、水幕和水喷雾等类型。"},{"id":486,"ch":3,"t":"m","q":"关于消防电梯的设置要求，正确的有","o":["消防电梯应能每层停靠","轿厢内应设置专用消防对讲电话","轿厢内应设置专用操作按钮","消防电梯应分别设置在不同防火分区内，且每个防火分区不应少于1台","消防电梯可与客梯合用，火灾时无需专用操作按钮"],"a":"ABCD","e":"消防电梯应每层停靠并设专用按钮和对讲电话，且按防火分区分别设置。"},{"id":487,"ch":3,"t":"m","q":"关于消防应急照明设置的说法，正确的有","o":["疏散走道的地面最低水平照度应满足疏散要求","楼梯间、前室的地面最低水平照度要求高于疏散走道","应急照明灯具可采用蓄电池作为备用电源","应急照明灯在火灾时应能自动点亮","应急照明灯可被装饰物遮挡"],"a":"ABCD","e":"应急照明应保证疏散走道照度并能在火灾时自动点亮，灯具不得被遮挡。"},{"id":488,"ch":3,"t":"m","q":"关于防火窗和防火卷帘的说法，正确的有","o":["防火窗按耐火极限分为甲、乙、丙三级","防火窗可用于防火墙、防火隔墙上需要采光或通风的开口部位","防火卷帘应具有防烟性能，其与楼板、梁、墙、柱之间的空隙应封堵","防火卷帘应能在火灾时靠自重自动关闭","防火卷帘只能设置在外墙洞口"],"a":"ABCD","e":"防火窗分三级并可用于墙体开口，防火卷帘须能自动关闭且空隙应封堵。"},{"id":489,"ch":3,"t":"m","q":"关于安全出口和疏散走道的说法，正确的有","o":["安全出口应分散布置","疏散走道内不得堆放物品或设置影响疏散的障碍物","疏散走道内可采用转门、卷帘门作为疏散门","安全出口的门应向疏散方向开启"],"a":"ABD","e":"安全出口应分散布置并保持畅通，疏散门应向疏散方向开启，不得用转门、卷帘门。"},{"id":490,"ch":3,"t":"m","q":"关于疏散楼梯间的说法，正确的有","o":["楼梯间内不应设置烧水间、可燃材料储藏室","楼梯间内不应敷设甲、乙、丙类液体管道","楼梯间内宜设置应急照明","楼梯间内可存放少量杂物"],"a":"ABC","e":"楼梯间内不得设置烧水间、可燃材料储藏室，不得敷设可燃液体管道，不得堆物。"},{"id":491,"ch":3,"t":"m","q":"关于建筑防烟排烟设施的说法，正确的有","o":["防烟楼梯间及其前室可采用自然通风方式防烟","不具备自然通风条件时，应设置机械加压送风系统","机械加压送风应使楼梯间、前室的压力高于走道","排烟口应设在储烟仓内","机械加压送风系统可与排烟系统合并设置"],"a":"ABCD","e":"防烟优先采用自然通风，否则机械加压；加压送风与排烟系统功能不同，不应合并。"},{"id":492,"ch":3,"t":"m","q":"选择灭火器时，应考虑的因素有","o":["火灾的种类","场所的火灾危险等级","灭火器的外观颜色","灭火器筒体的容积越大越好","灭火剂的毒性和对保护物品的污损程度"],"a":"ABE","e":"灭火器选择依据火灾种类、危险等级以及灭火剂的毒性和污损程度等因素。"},{"id":493,"ch":3,"t":"m","q":"关于二氧化碳灭火器使用方法的说法，正确的有","o":["应握住喇叭筒根部的木柄，防止手部冻伤","在狭小密闭空间使用后应及时通风","不宜用于扑救钾、钠等活泼金属火灾","灭火后不留残迹，适用于精密仪器和电子设备","可将筒体倒置使用以加快喷射"],"a":"ABCD","e":"二氧化碳灭火器应握木柄防冻伤，用后通风，不适用金属火灾，且不得倒置使用。"},{"id":494,"ch":3,"t":"m","q":"关于灭火器类型的说法，正确的有","o":["干粉灭火器按所装干粉的种类可分为BC类和ABC类","泡沫灭火器按发泡倍数可分为低倍数、中倍数和高倍数","二氧化碳灭火器内充装的是液化二氧化碳","清水灭火器可加入防冻剂以适应低温环境","各类灭火器的喷射距离均相同"],"a":"ABCD","e":"不同类型灭火器的灭火剂形态和性能不同，喷射距离并不相同。"},{"id":495,"ch":3,"t":"m","q":"关于灭火器配置的说法，正确的有","o":["灭火器的配置应与场所的火灾种类相适应","灭火器的配置应与场所的火灾危险等级相适应","同一计算单元内可任意配置不相容的灭火器","灭火器的设置点应保证其最大保护距离覆盖保护区域","灭火器的配置数量应经计算确定"],"a":"ABDE","e":"灭火器配置须与火灾种类、危险等级相适应，数量经计算确定，且不得混配不相容灭火剂。"},{"id":496,"ch":3,"t":"m","q":"下列情形中，灭火器应予以报废的有","o":["筒体严重锈蚀、明显变形","出厂时间超过规定的报废年限","筒体被火烧过","灭火器曾经开启使用过","器头存在裂纹、无泄压机构"],"a":"ABCE","e":"筒体严重锈蚀变形、超期、被火烧过或器头损坏的灭火器应报废；开启使用后可重新充装。"},{"id":497,"ch":3,"t":"j","q":"火灾自动报警系统能在火灾初期自动探测火情并发出报警信号。","o":["对","错"],"a":"对","e":"早期探测报警正是自动报警系统的基本功能。"},{"id":498,"ch":3,"t":"j","q":"感烟探测器适合安装在厨房、锅炉房等经常有烟气的场所。","o":["对","错"],"a":"错","e":"此类场所烟气易导致误报，宜选用感温探测器。"},{"id":499,"ch":3,"t":"j","q":"感温探测器按动作原理分为定温式、差温式和差定温式三种。","o":["对","错"],"a":"对","e":"这是感温探测器的三种基本形式。"},{"id":500,"ch":3,"t":"j","q":"火灾报警控制器只能接收报警信号，不能控制消防联动设备。","o":["对","错"],"a":"错","e":"控制器兼具报警与联动控制功能，可启动消防水泵、排烟风机等设备。"},{"id":501,"ch":3,"t":"j","q":"消防控制室只要安装了报警设备，平时可以无人值守。","o":["对","错"],"a":"错","e":"消防控制室须实行每日值班制度，值班人员应坚守岗位。"},{"id":502,"ch":3,"t":"j","q":"消防控制室值班人员应当经过培训并持证上岗。","o":["对","错"],"a":"对","e":"值班人员须掌握设施操作和应急处置程序，持证上岗。"},{"id":503,"ch":3,"t":"j","q":"探测器出现误报时，可以将其长期屏蔽而不必处理。","o":["对","错"],"a":"错","e":"长期屏蔽会使该部位失去探测保护，应查明原因并及时修复。"},{"id":504,"ch":3,"t":"j","q":"火灾探测器应定期清洗并进行功能试验。","o":["对","错"],"a":"对","e":"定期清洗和试验是保证探测器灵敏可靠的必要维护措施。"},{"id":505,"ch":3,"t":"j","q":"消防应急广播系统平时可兼作业务广播，火灾时用于引导人员疏散。","o":["对","错"],"a":"对","e":"应急广播通常与背景广播合用，火灾时强制切换为疏散指令。"},{"id":506,"ch":3,"t":"j","q":"消防专用电话可以与普通电话共用同一套交换设备。","o":["对","错"],"a":"错","e":"消防专用电话应独立设置，保证火灾时通信畅通。"},{"id":507,"ch":3,"t":"j","q":"使用室内消火栓一般由两人配合，一人开启阀门，一人握持水枪。","o":["对","错"],"a":"对","e":"两人配合可控制水压反作用力，保证操作安全有效。"},{"id":508,"ch":3,"t":"j","q":"室内消火栓的水枪射流应直接对准火焰上部。","o":["对","错"],"a":"错","e":"射流应对准燃烧物根部，才能有效降温灭火。"},{"id":509,"ch":3,"t":"j","q":"室外消火栓可以被埋压、圈占，只要不影响建筑物外观。","o":["对","错"],"a":"错","e":"埋压、圈占消火栓会延误取水，属于禁止行为。"},{"id":510,"ch":3,"t":"j","q":"室外消火栓按设置形式分为地上式和地下式两种。","o":["对","错"],"a":"对","e":"按栓体安装位置可分为地上式和地下式。"},{"id":511,"ch":3,"t":"j","q":"手动火灾报警按钮应安装在明显且便于人员操作的部位。","o":["对","错"],"a":"对","e":"设置位置明显、便于操作，才能在火灾时及时报警。"},{"id":512,"ch":3,"t":"j","q":"可燃气体探测器应安装在可能发生可燃气体泄漏的场所。","o":["对","错"],"a":"对","e":"其作用就是监测可燃气体泄漏，应设在相应的危险部位。"},{"id":513,"ch":3,"t":"j","q":"火灾自动报警系统的传输线路可以使用普通铝芯导线。","o":["对","错"],"a":"错","e":"应采用阻燃或耐火铜芯导线，保证火灾时线路可靠。"},{"id":514,"ch":3,"t":"j","q":"火灾报警控制器报警后，值班人员应先复位再确认火情。","o":["对","错"],"a":"错","e":"应先确认火情并按预案处置，盲目复位会丢失报警信息、延误处置。"},{"id":515,"ch":3,"t":"j","q":"干式系统喷头动作后需先排出管道内的气体，因此出水时间比湿式系统滞后。","o":["对","错"],"a":"对","e":"干式系统需先排气充水，喷水时间较湿式系统滞后。"},{"id":516,"ch":3,"t":"j","q":"预作用系统在火灾探测器报警后先向管道充水，再由闭式喷头喷水灭火。","o":["对","错"],"a":"对","e":"预作用系统由火灾报警信号开启预作用阀充水，兼具干式与湿式系统的优点。"},{"id":517,"ch":3,"t":"j","q":"自动喷水灭火系统的喷头可被货架、管道等遮挡，不影响喷水效果。","o":["对","错"],"a":"错","e":"喷头被遮挡会阻碍水流分布，影响控火效果，喷头周围应保持通畅。"},{"id":518,"ch":3,"t":"j","q":"消防电梯井底应设置排水设施，以排除灭火时进入井道的积水。","o":["对","错"],"a":"对","e":"消防电梯井底应设排水设施，防止积水影响电梯正常运行。"},{"id":519,"ch":3,"t":"j","q":"消防应急照明和疏散指示标志的备用电源连续供电时间，建筑高度大于100m的民用建筑不应小于1.5h。","o":["对","错"],"a":"对","e":"超高层建筑疏散时间长，其应急照明连续供电时间要求更高。"},{"id":520,"ch":3,"t":"j","q":"常开防火门在火灾时应能自动关闭，并将关闭信号反馈至消防控制室。","o":["对","错"],"a":"对","e":"常开防火门须具备火灾时自动关闭和信号反馈功能，确保防火分隔有效。"},{"id":521,"ch":3,"t":"j","q":"防火卷帘下方可以堆放货物，不会影响卷帘降落。","o":["对","错"],"a":"错","e":"卷帘下方堆放货物会阻碍卷帘降落到底，破坏防火分隔，必须保持畅通。"},{"id":522,"ch":3,"t":"j","q":"设置自动灭火系统的建筑，其防火分区最大允许建筑面积可比规定值增加一倍。","o":["对","错"],"a":"对","e":"自动灭火系统能有效控火，防火分区面积可按规定增加一倍。"},{"id":523,"ch":3,"t":"j","q":"营业期间安全出口的门可以上锁，只要安排专人保管钥匙即可。","o":["对","错"],"a":"错","e":"营业期间安全出口不得锁闭，锁闭会延误疏散，造成严重后果。"},{"id":524,"ch":3,"t":"j","q":"封闭楼梯间不能自然通风时，仍可采用封闭楼梯间而不必设置机械加压送风系统。","o":["对","错"],"a":"错","e":"不能自然通风时应设机械加压送风系统，或改用防烟楼梯间。"},{"id":525,"ch":3,"t":"j","q":"防火阀平时处于关闭状态，火灾时自动开启进行排烟。","o":["对","错"],"a":"错","e":"防火阀平时开启，火灾时当管道内气温达到70℃时自动关闭。"},{"id":526,"ch":3,"t":"j","q":"手提式干粉灭火器使用前应上下颠倒摇动几次，使筒内干粉松散。","o":["对","错"],"a":"对","e":"摇动可使干粉松散，避免喷射时结块堵塞，保证喷射效果。"},{"id":527,"ch":3,"t":"j","q":"扑救容器内的易燃液体火灾时，应把灭火剂直接对准液面喷射，以加快灭火。","o":["对","错"],"a":"错","e":"直接对准液面易使液体飞溅扩大火势，应沿容器内壁喷射或对准火焰根部。"},{"id":528,"ch":3,"t":"j","q":"灭火器的最大保护距离只与灭火器的类型有关，与火灾危险等级无关。","o":["对","错"],"a":"错","e":"最大保护距离与火灾种类、危险等级和灭火器类型均有关。"},{"id":529,"ch":3,"t":"j","q":"灭火器箱可以上锁，以防灭火器丢失。","o":["对","错"],"a":"错","e":"灭火器箱不得上锁，紧急情况下应能迅速取用灭火器。"},{"id":530,"ch":3,"t":"j","q":"灭火器应放置在潮湿、有腐蚀性气体的场所，以便就近取用。","o":["对","错"],"a":"错","e":"潮湿和腐蚀性气体会损坏灭火器筒体和器头，应避免在此类场所设置。"},{"id":531,"ch":3,"t":"j","q":"贮压式灭火器压力表指针指向绿色区域，表示其压力正常。","o":["对","错"],"a":"对","e":"压力表绿区为正常，红区表示压力不足，黄区表示压力过高。"},{"id":532,"ch":3,"t":"j","q":"灭火器一经开启使用，即使灭火剂未喷完，也必须重新充装。","o":["对","错"],"a":"对","e":"灭火器开启后密封被破坏，必须重新充装并检验合格后方可继续使用。"},{"id":533,"ch":3,"t":"b","q":"火灾自动报警系统一般由触发器件、火灾报警装置、火灾警报装置、____和电源等组成。","a":["消防联动控制设备"]},{"id":534,"ch":3,"t":"b","q":"感烟探测器主要有离子式和____两种形式。","a":["光电式"]},{"id":535,"ch":3,"t":"b","q":"感温探测器按动作原理分为定温式、差温式和____。","a":["差定温式"]},{"id":536,"ch":3,"t":"b","q":"火灾自动报警系统按报警形式分为区域报警系统、集中报警系统和____。","a":["控制中心报警系统"]},{"id":537,"ch":3,"t":"b","q":"火灾报警控制器通过____按预设逻辑启动消防水泵、排烟风机等设备。","a":["消防联动控制"]},{"id":538,"ch":3,"t":"b","q":"消防控制室应实行每日____小时值班制度。","a":["24"]},{"id":539,"ch":3,"t":"b","q":"消防控制室应设在建筑物的首层或地下一层，并应有直通____的安全出口。","a":["室外"]},{"id":540,"ch":3,"t":"b","q":"火灾时消防应急广播系统用于发布____指令，引导人员安全撤离。","a":["疏散"]},{"id":541,"ch":3,"t":"b","q":"消防专用电话采用独立布线，可直接呼叫____。","a":["消防控制室"]},{"id":542,"ch":3,"t":"b","q":"室内消火栓箱内通常配置消火栓接口、消防水带和____。","a":["水枪"]},{"id":543,"ch":3,"t":"b","q":"使用室内消火栓灭火时，水枪射流应对准燃烧物的____。","a":["根部"]},{"id":544,"ch":3,"t":"b","q":"室外消火栓按设置形式分为____和地下式两种。","a":["地上式"]},{"id":545,"ch":3,"t":"b","q":"湿式报警阀组上设置的____，可防止因水压波动而引起的误报警。","a":["延迟器"]},{"id":546,"ch":3,"t":"b","q":"水喷雾灭火系统喷出的水雾具有冷却、____和乳化等作用。","a":["窒息"]},{"id":547,"ch":3,"t":"b","q":"一、二级耐火等级的高层民用建筑，每个防火分区的最大允许建筑面积为____m²。","a":["1500"]},{"id":548,"ch":3,"t":"b","q":"公共建筑内疏散走道的净宽度不应小于____m。","a":["1.1"]},{"id":549,"ch":3,"t":"b","q":"防烟楼梯间前室的使用面积，公共建筑不应小于____m²。","a":["6.0"]},{"id":550,"ch":3,"t":"b","q":"机械加压送风时，防烟楼梯间与走道之间的压差应为____Pa，前室与走道之间的压差应为____Pa。","a":["40~50","25~30"]},{"id":551,"ch":3,"t":"b","q":"排烟口至防烟分区内最远点的水平距离不应大于____m。","a":["30"]},{"id":552,"ch":3,"t":"b","q":"每个灭火器设置点配置的灭火器数量不宜多于____具。","a":["5"]},{"id":553,"ch":3,"t":"b","q":"灭火器应设置在明显和便于取用的地点，且不得影响____。","a":["安全疏散"]},{"id":554,"ch":3,"t":"b","q":"手提式水基型灭火器的报废年限为____年。","a":["6"]},{"id":555,"ch":3,"t":"b","q":"灭火器的配置、外观等应____检查一次。","a":["每月"]},{"id":556,"ch":3,"t":"x","q":"简述火灾自动报警系统的主要组成部分及各部分的作用。","a":"1.触发器件：包括火灾探测器和手动火灾报警按钮，自动或手动产生火灾报警信号；2.火灾报警装置：即火灾报警控制器，接收、显示和传递报警信号，是系统的核心；3.火灾警报装置：声光警报器等，向现场人员发出火灾警示；4.消防联动控制设备：按预设逻辑启动消防水泵、排烟风机、防火卷帘等；5.电源：主电源和备用电源，保证系统不间断供电。"},{"id":557,"ch":3,"t":"x","q":"火灾探测器有哪些主要类型？选型时应考虑哪些因素？","a":"主要类型：1.感烟探测器，包括离子式、光电式和红外光束式，适于火灾初期有阴燃冒烟的场所；2.感温探测器，包括定温式、差温式和差定温式，适于温度变化明显的场所；3.感光探测器，适于起火迅速、火焰辐射强烈的场所；4.可燃气体探测器，用于监测可燃气体泄漏；5.复合探测器，同时探测两种以上参数。选型时应考虑场所的火灾特点、房间高度、环境条件（烟尘、湿度、腐蚀性气体）、探测器性能及是否便于维护，并注意避免误报。"},{"id":558,"ch":3,"t":"x","q":"消防控制室值班人员接到火灾报警信号后应如何处置？","a":"1.接收报警：控制器发出声光报警后先消音，查看报警部位、时间和探测器编号；2.确认火情：通过视频监控、现场查看或通知巡查人员核实，排除误报；3.报警与处置：确认火灾后立即拨打火警电话，报告单位负责人，按预案启动消防应急广播，组织人员疏散；4.联动设备：确认消防水泵、排烟风机、防火卷帘、消防电梯等按逻辑动作，必要时手动控制；5.记录与保护：如实填写值班记录，保护报警和联动信息，配合消防部门调查。"},{"id":559,"ch":3,"t":"x","q":"某高校化学实验楼内设有有机合成实验室、仪器分析室和金属钠储存间。请说明这三类场所应分别选用何种灭火器，并简述灭火器配置与设置的基本要求。","a":"1.有机合成实验室存在有机溶剂等B类火灾，可选用泡沫灭火器或ABC干粉灭火器，并配二氧化碳灭火器扑救初起小火；2.仪器分析室有精密仪器和带电设备，应选用二氧化碳或六氟丙烷灭火器，灭火后不留残渣、不损坏设备；3.金属钠储存间属D类金属火灾，应选用专用金属干粉灭火器，严禁使用水、泡沫和二氧化碳灭火器。配置与设置要求：一个计算单元内灭火器不少于2具，每个设置点不宜多于5具；灭火器应设置在明显、便于取用的地点，不得影响安全疏散，铭牌朝外，顶部离地面高度不大于1.5m；应每月检查一次，按规定期限维修和报废。"},{"id":560,"ch":3,"t":"x","q":"某商场营业期间，常闭式防火门被货物挡住无法关闭，防火卷帘下方堆放了促销商品，部分疏散指示标志被广告牌遮挡。请分析这些做法可能造成的后果，并说明正确的管理要求。","a":"1.常闭防火门被挡住无法关闭：火灾时烟气和火焰会直接进入楼梯间，破坏防烟防火分隔，影响人员安全疏散，正确做法是保持常闭防火门关闭，不得上锁、不得用物品阻挡；2.防火卷帘下方堆放商品：火灾时卷帘无法降落到底，防火分区被破坏，火势迅速蔓延，正确做法是卷帘下方及两侧不得堆放物品，并定期试验其自动降落功能；3.疏散指示标志被遮挡：人员难以辨认疏散方向和出口位置，易造成拥挤踩踏，正确做法是保持标志完好、醒目、不被遮挡，损坏时及时修复；4.商场还应保持安全出口和疏散走道畅通，营业期间不得锁闭安全出口。"},{"id":561,"ch":4,"t":"s","q":"全球化学品统一分类和标签制度（GHS）中，用于标示危险严重程度的信号词是","o":["危险、警告","有毒、有害","注意、当心","一级、二级"],"a":"A","e":"GHS 只设“危险”和“警告”两个信号词。"},{"id":562,"ch":4,"t":"s","q":"按国家标准编排，化学品安全技术说明书（SDS）由几个部分组成","o":["8 个","12 个","16 个","20 个"],"a":"C","e":"SDS 按 GB/T 16483 编写，共 16 个部分。"},{"id":563,"ch":4,"t":"s","q":"在危险货物分类中，第一类危险货物是","o":["爆炸品","气体","易燃液体","腐蚀性物质"],"a":"A","e":"第一类为爆炸品，其后依次为气体、易燃液体等。"},{"id":564,"ch":4,"t":"s","q":"GHS 象形图中，火焰图案所表示的危险特性是","o":["氧化性","易燃性","腐蚀性","毒性"],"a":"B","e":"火焰图案表示易燃；圆圈上方火焰才表示氧化性。"},{"id":565,"ch":4,"t":"s","q":"GHS 标签上骷髅和交叉骨象形图警示的主要危害是","o":["致癌性","生殖毒性","急性毒性","皮肤致敏"],"a":"C","e":"骷髅交叉骨表示急性毒性，可经口、经皮或吸入致命。"},{"id":566,"ch":4,"t":"s","q":"SDS 中“接触控制/个体防护”所在的部分是","o":["第 2 部分","第 5 部分","第 7 部分","第 8 部分"],"a":"D","e":"第 8 部分为接触控制/个体防护，给出职业接触限值和防护措施。"},{"id":567,"ch":4,"t":"s","q":"爆炸品储存时，下列做法正确的是","o":["与酸类物质同库存放","专库储存并远离火源热源","与起爆器材混存以便取用","库房内使用明火照明"],"a":"B","e":"爆炸品须专库储存，严禁与酸碱、起爆器材等混存，库内禁用明火。"},{"id":568,"ch":4,"t":"s","q":"按闪点划分，低闪点液体的闪点范围是","o":["低于 0 ℃","低于 10 ℃","低于 -18 ℃","低于 -40 ℃"],"a":"C","e":"低闪点液体闪点低于 -18 ℃，中闪点为 -18 ℃至 23 ℃，高闪点为 23 ℃至 61 ℃。"},{"id":569,"ch":4,"t":"s","q":"下列物质中属于遇湿易燃物品的是","o":["乙醇","汽油","硫黄","碳化钙"],"a":"D","e":"碳化钙遇水放出乙炔气体并可自燃，属遇湿易燃物品。"},{"id":570,"ch":4,"t":"s","q":"稀释浓硫酸的正确操作是","o":["将浓硫酸沿器壁缓慢加入水中并不断搅拌","将水缓慢加入浓硫酸中并不断搅拌","将两者迅速混合后静置","在密闭容器中振荡混合"],"a":"A","e":"酸入水且缓慢加入、持续搅拌，可避免局部过热暴沸。"},{"id":571,"ch":4,"t":"s","q":"氧气钢瓶瓶阀和减压器严禁沾染油脂，主要原因是","o":["油脂会腐蚀瓶阀","油脂会使气体纯度下降","油脂在高压氧中易氧化并可能燃烧爆炸","油脂会堵塞减压器"],"a":"C","e":"高压氧使油脂剧烈氧化，极易引发燃烧甚至爆炸。"},{"id":572,"ch":4,"t":"s","q":"关于乙炔钢瓶的使用，正确的是","o":["可卧放使用","必须直立使用并可靠固定","可放置在通道旁","用完可直接放倒滚动搬运"],"a":"B","e":"乙炔瓶内充有丙酮和填料，卧放会使丙酮流出，故须直立使用。"},{"id":573,"ch":4,"t":"s","q":"金属钠着火时，应选用的灭火材料是","o":["水","泡沫灭火器","二氧化碳灭火器","干燥砂土"],"a":"D","e":"钠与水、二氧化碳均反应，只能用干燥砂土等覆盖窒息灭火。"},{"id":574,"ch":4,"t":"s","q":"危险化学品安全技术说明书的主要作用是","o":["提供危害信息及安全操作、应急处置指导","作为产品出厂合格证明","用于计算化学品用量","代替实验室安全培训"],"a":"A","e":"SDS 传递危害信息，是安全使用和应急处理的技术依据。"},{"id":575,"ch":4,"t":"s","q":"根据《危险化学品安全管理条例》，危险化学品是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、环境造成危害的","o":["所有化学试剂","剧毒化学品和其他化学品","易燃液体和气体","放射性物质"],"a":"B","e":"定义涵盖剧毒化学品和其他具有危害性的化学品。"},{"id":576,"ch":4,"t":"s","q":"GHS 体系规定的象形图共有","o":["6 个","7 个","9 个","12 个"],"a":"C","e":"GHS 共设 9 个象形图，覆盖物理、健康和环境危害。"},{"id":577,"ch":4,"t":"s","q":"GHS 象形图中，两支试管分别向金属和手上倾倒液体的图案表示","o":["腐蚀性","氧化性","易燃性","加压气体"],"a":"A","e":"该图案表示腐蚀性，可腐蚀金属并损伤皮肤。"},{"id":578,"ch":4,"t":"s","q":"有机过氧化物最主要的危险特性是","o":["易挥发","易潮解","易升华","受热、摩擦或撞击易剧烈分解甚至爆炸"],"a":"D","e":"有机过氧化物含过氧键，受热、摩擦、撞击易分解放热并爆炸。"},{"id":579,"ch":4,"t":"s","q":"购买易制爆化学品时，通常需要","o":["无需任何手续","向公安机关备案并经许可","仅需实验室负责人签字","由学生自行采购"],"a":"B","e":"易制爆化学品实行备案和流向登记管理，购买须依法办理手续。"},{"id":580,"ch":4,"t":"s","q":"危险化学品储存中，分类隔离的根本目的是","o":["便于盘点数量","节省库房面积","防止性质相抵触的物质接触后发生反应","方便领用登记"],"a":"C","e":"分类隔离可避免禁配物接触引发燃烧、爆炸或释放有毒气体。"},{"id":581,"ch":4,"t":"s","q":"爆炸品运输时应","o":["与普通货物混装以节省运力","由普通客车捎带","可随身携带少量上车","使用专用车辆并由专人押运"],"a":"D","e":"爆炸品须专车专运、专人押运，严禁与普通货物混装或随身携带。"},{"id":582,"ch":4,"t":"s","q":"下列气体中属于冷冻液化气体的是","o":["液氮","溶解乙炔","钢瓶装压缩空气","管道输送的天然气"],"a":"A","e":"液氮由气体深度冷却液化制得，属冷冻液化气体。"},{"id":583,"ch":4,"t":"s","q":"自燃物品的主要危险特性是","o":["需明火才能燃烧","遇水放出可燃气体","自燃点低，在空气中易自行燃烧","受撞击即爆炸"],"a":"C","e":"自燃物品无需明火，在空气中氧化放热即可自行燃烧。"},{"id":584,"ch":4,"t":"s","q":"氧化剂与还原剂在同一库房存放时","o":["可分区少量存放","必须隔离存放，严禁混存","只要包装完好即可","可放在同一货架的不同层"],"a":"B","e":"两者接触会发生剧烈氧化还原反应，必须严格隔离。"},{"id":585,"ch":4,"t":"s","q":"取用有挥发性、有毒的液体试剂时，应","o":["在实验台上开窗自然挥发","在走廊内取用","戴手套后直接倾倒","在通风橱内操作并佩戴防护用品"],"a":"D","e":"挥发性毒物应在通风橱内取用，并做好呼吸和皮肤防护。"},{"id":586,"ch":4,"t":"s","q":"将大瓶试剂分装到小瓶时，首先应","o":["在分装容器上粘贴标签","将小瓶置于阳光下","用嘴吸移液管","把剩余试剂倒回原瓶"],"a":"A","e":"先贴标签可防止分装后混淆误用；剩余试剂不得倒回原瓶。"},{"id":587,"ch":4,"t":"s","q":"废弃危险化学品的正确处置方式是","o":["倒入下水道冲走","分类收集后交有资质单位处置","与生活垃圾一起丢弃","露天焚烧"],"a":"B","e":"危险废物须分类收集，交由具备资质的单位处理。"},{"id":588,"ch":4,"t":"s","q":"爆炸品仓库的环境要求是","o":["保持高温干燥","密闭不通风","通风干燥、避免阳光直射","保持高湿以防静电"],"a":"C","e":"爆炸品库房应通风、干燥、避光，并远离火源热源。"},{"id":589,"ch":4,"t":"s","q":"SDS 中“危险性说明”的主要作用是","o":["用简短语句描述危险的严重程度和类型","列出化学品的价格","说明产品的生产日期","给出物质的分子式"],"a":"A","e":"危险性说明是标准短语，用于描述危害类别和严重程度。"},{"id":590,"ch":4,"t":"s","q":"压缩气体钢瓶在实验室内的存放要求是","o":["可靠墙倾斜堆放","放在暖气片旁","无特殊要求","直立固定，空瓶与实瓶分开存放"],"a":"D","e":"钢瓶应直立固定，避免曝晒和热源，空瓶实瓶分区存放。"},{"id":591,"ch":4,"t":"s","q":"为防止易燃液体作业时产生静电，应","o":["加快倾倒速度","使用塑料桶盛装","设备接地并控制流速","穿化纤工作服"],"a":"C","e":"接地、控制流速可减少静电积聚，塑料桶和化纤衣物易起静电。"},{"id":592,"ch":4,"t":"s","q":"生物危险标志用于标示","o":["放射性物品","感染性物质","腐蚀性物品","氧化性物质"],"a":"B","e":"生物危险标志用于标示含有或可能含有病原微生物的感染性物质。"},{"id":593,"ch":4,"t":"s","q":"腐蚀品通常分为","o":["有机腐蚀品和无机腐蚀品","强腐蚀品和弱腐蚀品","液体腐蚀品和固体腐蚀品","酸性、碱性和其他腐蚀品"],"a":"D","e":"危险货物分类中腐蚀品按酸碱性分为酸性、碱性和其他腐蚀品。"},{"id":594,"ch":4,"t":"s","q":"验收危险化学品时，应重点查验","o":["包装、安全标签、SDS 及许可证件","生产厂家的广告","运输车辆的颜色","试剂瓶外观是否美观"],"a":"A","e":"验收须核查包装完好性、标签与 SDS 是否齐全、来源是否合法。"},{"id":595,"ch":4,"t":"s","q":"危险化学品使用登记的主要目的是","o":["便于评比考核","增加实验工作量","掌握流向和存量，实现可追溯管理","减少试剂用量"],"a":"C","e":"登记台账可追溯化学品的来源、去向和存量，便于安全管理。"},{"id":596,"ch":4,"t":"s","q":"SDS 中“理化特性”位于","o":["第 3 部分","第 9 部分","第 10 部分","第 14 部分"],"a":"B","e":"第 9 部分为理化特性，包括外观、闪点、沸点、溶解性等。"},{"id":597,"ch":4,"t":"s","q":"炸药 A 爆炸引起邻近炸药 B 爆炸的现象称为","o":["爆热","爆速","感度","殉爆"],"a":"D","e":"殉爆是爆炸冲击波引发邻近爆炸品爆炸的现象，储存时须控制存量与间距。"},{"id":598,"ch":4,"t":"s","q":"同种易燃液体，闪点越低说明","o":["火灾危险性越大","火灾危险性越小","挥发性越低","越不易被点燃"],"a":"A","e":"闪点越低，液体在常温下越易形成可燃蒸气，火灾危险性越大。"},{"id":599,"ch":4,"t":"s","q":"GHS 标签上的产品标识符是指","o":["供应商联系电话","化学品的名称或编号","危险类别的代码","生产批号"],"a":"B","e":"产品标识符是标签上标明物质或混合物名称、编号的部分。"},{"id":600,"ch":4,"t":"s","q":"乙炔在钢瓶中溶解于丙酮并吸附于多孔填料上，按气体物理状态分类，乙炔属于（ ）","o":["压缩气体","液化气体","溶解气体","冷冻液化气体"],"a":"C","e":"溶解气体是溶解于溶剂（丙酮）中的气体，乙炔瓶即属此类。"},{"id":601,"ch":4,"t":"s","q":"按气瓶颜色标记的规定，氧气瓶的瓶体颜色是（ ）","o":["淡绿色","银灰色","淡蓝色","黑色"],"a":"C","e":"氧气瓶为淡（酞）蓝色瓶体、黑色字样。"},{"id":602,"ch":4,"t":"s","q":"氢气瓶的瓶体颜色和字样颜色分别是（ ）","o":["白色、大红色","淡绿色、大红色","淡蓝色、黑色","黑色、淡黄色"],"a":"B","e":"氢气瓶为淡绿色瓶体、大红色字样。"},{"id":603,"ch":4,"t":"s","q":"关于溶解乙炔气瓶的使用，正确的做法是（ ）","o":["可以卧放使用","可以倒置使用","可以随意倾斜滚动","必须直立使用并可靠固定"],"a":"D","e":"乙炔瓶卧放会使丙酮流出，必须直立使用并固定。"},{"id":604,"ch":4,"t":"s","q":"气瓶使用或存放时，与明火的距离一般不应小于（ ）","o":["3 m","5 m","10 m","15 m"],"a":"C","e":"气瓶与明火距离一般不应小于10 m。"},{"id":605,"ch":4,"t":"s","q":"同时使用氧气瓶和乙炔瓶时，两瓶之间的距离不应小于（ ）","o":["2 m","3 m","4 m","5 m"],"a":"D","e":"氧气瓶与乙炔瓶间距不应小于5 m，以防泄漏后混合。"},{"id":606,"ch":4,"t":"s","q":"永久气体气瓶使用后，瓶内剩余压力一般不应低于（ ）","o":["0.01 MPa","0.02 MPa","0.05 MPa","0.10 MPa"],"a":"C","e":"留有余压可防止空气倒灌，永久气体余压一般不低于0.05 MPa。"},{"id":607,"ch":4,"t":"s","q":"液化气体气瓶充装时，正确的做法是（ ）","o":["按最大质量满液充装","充装后加热检查液位","留出气化空间，不得满液充装","充装至瓶口可见液体"],"a":"C","e":"液化气体受热膨胀，满液充装会导致瓶体超压。"},{"id":608,"ch":4,"t":"s","q":"冷冻液化气体（如液氮、液氧）的主要危险特征是（ ）","o":["极易燃烧","有强烈腐蚀性","遇水剧烈反应","温度极低，可造成冻伤和低温脆化"],"a":"D","e":"冷冻液化气体沸点极低，主要危险是低温冻伤和材质脆化。"},{"id":609,"ch":4,"t":"s","q":"闪点的定义是（ ）","o":["液体表面蒸气与空气混合遇火源发生闪燃的最低温度","液体开始沸腾的温度","液体持续燃烧5 s以上的最低温度","液体受热自燃的最低温度"],"a":"A","e":"闪点是发生闪燃的最低温度，不是持续燃烧或自燃温度。"},{"id":610,"ch":4,"t":"s","q":"按闪点分级，低闪点液体的闪点（ ）","o":["低于－18 ℃","在－18 ℃至23 ℃之间","在23 ℃至61 ℃之间","高于61 ℃"],"a":"A","e":"低闪点液体闪点低于－18 ℃，火灾危险性最大。"},{"id":611,"ch":4,"t":"s","q":"中闪点液体的闪点范围是（ ）","o":["低于－18 ℃","高于61 ℃","－18 ℃至23 ℃","23 ℃至61 ℃"],"a":"C","e":"中闪点液体闪点为－18 ℃至23 ℃。"},{"id":612,"ch":4,"t":"s","q":"汽油的闪点很低，按闪点分级属于（ ）","o":["低闪点液体","中闪点液体","高闪点液体","不属于易燃液体"],"a":"A","e":"汽油闪点远低于－18 ℃，属低闪点液体。"},{"id":613,"ch":4,"t":"s","q":"防止易燃液体静电危害最直接的措施是（ ）","o":["提高储存温度","加大输液流速","对储罐和管道进行防静电接地","用塑料容器盛装"],"a":"C","e":"接地可及时导走静电荷，是防静电的基本措施。"},{"id":614,"ch":4,"t":"s","q":"易燃液体储存场所的电气设备应（ ）","o":["采用防爆型","使用普通照明灯具","安装在储罐上方","不设任何开关"],"a":"A","e":"易燃液体蒸气与空气可形成爆炸性混合物，须用防爆电气设备。"},{"id":615,"ch":4,"t":"s","q":"易燃液体的闪点越低，说明其（ ）","o":["火灾危险性越小","火灾危险性越大","毒性越小","腐蚀性越强"],"a":"B","e":"闪点越低越易挥发起火，火灾危险性越大。"},{"id":616,"ch":4,"t":"s","q":"黄磷在空气中易自燃，实验室保存黄磷的方法是（ ）","o":["保存在水中","保存在煤油中","保存在干燥器中","敞口放置"],"a":"A","e":"黄磷须浸没在水中保存，隔绝空气防止自燃。"},{"id":617,"ch":4,"t":"s","q":"金属钠、金属钾应保存在（ ）","o":["水中","煤油中","乙醇中","稀酸中"],"a":"B","e":"钠、钾遇水或醇剧烈反应，须浸没在煤油中保存。"},{"id":618,"ch":4,"t":"s","q":"电石（碳化钙）遇水会放出（ ）","o":["氧气","氢气","乙炔","甲烷"],"a":"C","e":"电石遇水生成乙炔，属遇湿易燃物品。"},{"id":619,"ch":4,"t":"s","q":"遇湿易燃物品着火时，宜选用的灭火剂是（ ）","o":["水","泡沫","水蒸气","干砂或干粉"],"a":"D","e":"遇湿易燃物品禁用水及含水灭火剂，应用干砂、干粉。"},{"id":620,"ch":4,"t":"s","q":"自燃物品是指在常温下（ ）","o":["遇明火立即燃烧的物质","与氧化剂接触才燃烧的物质","受潮后放热的物质","不需要明火作用即可自行燃烧的物质"],"a":"D","e":"自燃物品在常温空气中靠自身氧化放热即可着火。"},{"id":621,"ch":4,"t":"s","q":"三乙基铝暴露在空气中会自燃，其储存和使用时应（ ）","o":["用水密封","用惰性气体保护","敞口存放","与醇类共存"],"a":"B","e":"三乙基铝遇空气、水均剧烈反应，须在惰性气体保护下操作。"},{"id":622,"ch":4,"t":"s","q":"下列物质中属于易燃固体的是（ ）","o":["红磷","食盐","碳酸钙","玻璃粉"],"a":"A","e":"红磷燃点低、易燃烧，属易燃固体。"},{"id":623,"ch":4,"t":"s","q":"含氮量较高的硝化棉在危险货物分类中属于（ ）","o":["腐蚀品","氧化性物质","易燃液体","爆炸品"],"a":"D","e":"含氮量高的硝化棉具有爆炸性，按爆炸品管理。"},{"id":624,"ch":4,"t":"s","q":"氧化性物质的主要危险特性是（ ）","o":["本身可燃且闪点低","本身不一定可燃，但能引起或促进可燃物燃烧","遇水放出可燃气体","具有强腐蚀性"],"a":"B","e":"氧化性物质多为助燃物，本身不一定可燃。"},{"id":625,"ch":4,"t":"s","q":"有机过氧化物的突出危险特性是（ ）","o":["热不稳定，受热、撞击易分解甚至爆炸","极易挥发且无毒","遇水生成酸","不与其他物质反应"],"a":"A","e":"有机过氧化物含过氧键，热不稳定，易分解放热。"},{"id":626,"ch":4,"t":"s","q":"下列物质中属于有机过氧化物的是（ ）","o":["过氧化氢","高锰酸钾","过氧化苯甲酰","氯酸钾"],"a":"C","e":"过氧化苯甲酰含过氧键和有机基团，属有机过氧化物。"},{"id":627,"ch":4,"t":"s","q":"高锰酸钾与甘油混合后可能发生的危险是（ ）","o":["缓慢溶解","生成无害气体","立即凝固","自燃甚至起火"],"a":"D","e":"强氧化剂与有机物混合可剧烈氧化放热引起自燃。"},{"id":628,"ch":4,"t":"s","q":"工业生产中，毒性物质进入人体最主要的途径是（ ）","o":["呼吸道吸入","消化道食入","皮肤吸收","伤口感染"],"a":"A","e":"职业接触中毒以呼吸道吸入蒸气、粉尘和烟尘为主。"},{"id":629,"ch":4,"t":"s","q":"在危险货物分类中，毒性物质和感染性物质属于第（ ）类","o":["第3类","第6类","第5类","第8类"],"a":"B","e":"第6类为毒性物质和感染性物质。"},{"id":630,"ch":4,"t":"s","q":"有机过氧化物在危险货物分类中属于（ ）","o":["第4.1项","第5.1项","第5.2项","第6.1项"],"a":"C","e":"第5.2项为有机过氧化物，第5.1项为氧化性物质。"},{"id":631,"ch":4,"t":"s","q":"搬运气瓶时，正确的做法是（ ）","o":["戴上瓶帽和防震圈，轻装轻卸","用电磁起重机吊运","在地上滚动搬运","肩扛瓶阀"],"a":"A","e":"瓶帽和防震圈可保护瓶阀、瓶体，搬运须轻装轻卸。"},{"id":632,"ch":4,"t":"s","q":"关于气瓶检验，下列说法正确的是（ ）","o":["气瓶不需要检验","气瓶只需外观完好即可长期使用","气瓶由使用单位自行决定是否检验","气瓶必须按规定定期检验，超期不得使用"],"a":"D","e":"气瓶属特种设备，须定期检验，超期报废或不得使用。"},{"id":633,"ch":4,"t":"s","q":"溶解乙炔气瓶中多孔填料的主要作用是（ ）","o":["增加瓶体强度","降低乙炔纯度","吸附和分散丙酮，防止乙炔聚积分解","防止瓶体腐蚀"],"a":"C","e":"多孔填料吸附丙酮，使乙炔分散溶解，避免聚积发生分解爆炸。"},{"id":634,"ch":4,"t":"s","q":"扑救比水轻的易燃液体火灾时，不能直接用水的原因是（ ）","o":["水会与液体发生反应","液体浮于水面随水流动，扩大火势","水会降低液体闪点","水会分解液体"],"a":"B","e":"比水轻的液体浮在水面随水流散，用水扑救会扩大火面。"},{"id":635,"ch":4,"t":"s","q":"气瓶入库储存时，正确的做法是（ ）","o":["空瓶与实瓶分开存放，分类分区","所有气瓶混放以节省空间","氧气瓶与乙炔瓶同库存放","气瓶靠近暖气片存放"],"a":"A","e":"气瓶应分类分区、空实瓶分开存放，并远离热源。"},{"id":636,"ch":4,"t":"s","q":"剧毒化学品“五双”管理制度中，不包括下列哪一项？","o":["双人保管","双人收发","双把锁","双人销毁"],"a":"D","e":"“五双”指双人保管、双人收发、双人使用、双把锁、双本账，不含“双人销毁”。"},{"id":637,"ch":4,"t":"s","q":"剧毒化学品管理中所说的“双本账”，通常是指（　）。","o":["由两人分别记账并定期核对，保证账物相符","将同一账目复印两份分别存档","只记录剧毒化学品的购入总量","用一本账记录实验室内全部危险化学品"],"a":"A","e":"双本账强调保管与使用两本账各自记录、定期核对。"},{"id":638,"ch":4,"t":"s","q":"感染性物质包装的外部应当贴有（　）。","o":["生物危险标识","骷髅交叉骨标识","腐蚀品标识","氧化剂标识"],"a":"A","e":"感染性物质具有生物危害，外包装须有生物危险标识。"},{"id":639,"ch":4,"t":"s","q":"采购危险化学品前，必须确认供货单位具备（　）。","o":["产品出口资质","广告审查证明","危险化学品经营许可证","计量认证证书"],"a":"C","e":"危险化学品须从取得经营许可证的单位采购。"},{"id":640,"ch":4,"t":"s","q":"下列物质中，不得与浓硝酸同库储存的是（　）。","o":["玻璃器皿","乙醇","蒸馏水","陶瓷托盘"],"a":"B","e":"浓硝酸是强氧化剂，与乙醇等可燃物接触有燃烧爆炸危险。"},{"id":641,"ch":4,"t":"s","q":"按化学性质划分，腐蚀品通常分为（　）。","o":["一类","五类","四类","三类"],"a":"D","e":"腐蚀品分为酸性腐蚀品、碱性腐蚀品和其他腐蚀品三类。"},{"id":642,"ch":4,"t":"s","q":"酸液溅入眼睛后，应当首先（　）。","o":["用大量流动清水持续冲洗，并尽快就医","用稀碱液中和","用干布反复擦拭","闭眼休息观察"],"a":"A","e":"眼部化学灼伤应立即用大量流动清水冲洗，不能自行中和。"},{"id":643,"ch":4,"t":"s","q":"储存易燃液体的防爆柜，其柜体应当（　）。","o":["放置在地毯上","紧靠热源","可靠接地","保持密闭不通风"],"a":"C","e":"防爆柜可靠接地可导除静电，防止静电放电引燃蒸气。"},{"id":644,"ch":4,"t":"s","q":"储存易挥发腐蚀品的库房，应当设置（　）。","o":["蒸汽采暖设施","机械通风装置","明火照明","密闭门窗"],"a":"B","e":"机械通风可及时排出腐蚀性蒸气，降低人员接触和腐蚀风险。"},{"id":645,"ch":4,"t":"s","q":"教学实验室领用危险化学品时，应遵循（　）原则。","o":["一次领足一学期用量","数量越多越省事","由学生自行取用","按需领取、用多少领多少"],"a":"D","e":"按需领取、控制存量，可减少储存环节的事故风险。"},{"id":646,"ch":4,"t":"s","q":"危险化学品入库验收时，下列哪项不属于验收内容？","o":["供货单位的销售业绩","品名与规格","包装是否完好","标签与安全技术说明书"],"a":"A","e":"验收核查的是物品本身及随附资料，与供货方销售业绩无关。"},{"id":647,"ch":4,"t":"s","q":"金属钠应当保存在（　）中。","o":["蒸馏水","乙醇","煤油","稀盐酸"],"a":"C","e":"金属钠遇水剧烈反应，须浸没在煤油中隔绝空气和水分。"},{"id":648,"ch":4,"t":"s","q":"感染性物质实验产生的废弃物，通常应先（　）再按医疗废物处置。","o":["直接倒入下水道","高压蒸汽灭菌","与生活垃圾混装","敞口晾干"],"a":"B","e":"高压蒸汽灭菌可杀灭病原微生物，是感染性废弃物处置的常规环节。"},{"id":649,"ch":4,"t":"s","q":"操作感染性物质时，为减少气溶胶产生，应在（　）内进行。","o":["生物安全柜","超净工作台","普通实验台","手套箱"],"a":"A","e":"生物安全柜可同时保护操作者、样品和环境；超净工作台只保护样品。"},{"id":650,"ch":4,"t":"s","q":"剧毒化学品领用后如有剩余，正确的处理是（　）。","o":["留在实验台下次再用","转交他人保管","自行稀释后倒掉","及时退回专用库房并登记"],"a":"D","e":"剩余剧毒品须及时退库、登记，不得私自留存或处置。"},{"id":651,"ch":4,"t":"s","q":"危险化学品验收入库后，应当（　）。","o":["先使用后补记","只记总量不记品名","及时登记台账，做到账物相符","由使用人各自记录"],"a":"C","e":"入库即登记、账物相符，是危险化学品流向管理的基本要求。"},{"id":652,"ch":4,"t":"s","q":"危险化学品的储存场所应当（　）。","o":["与办公区合并使用","专用并设置明显警示标识","设在走廊便于取用","设在楼梯间内"],"a":"B","e":"专用储存场所并设警示标识，便于管理和应急识别。"},{"id":653,"ch":4,"t":"s","q":"若将水倒入浓硫酸中，可能造成的后果是（　）。","o":["局部剧烈放热使酸液飞溅","温度降低难以溶解","生成易燃气体","无明显现象"],"a":"A","e":"水密度小浮于酸面，局部放热使水沸腾，导致酸液飞溅伤人。"},{"id":654,"ch":4,"t":"s","q":"关于酸性腐蚀品与碱性腐蚀品的存放，正确的是（　）。","o":["可以同柜存放","混合后更稳定","不得混存，应分区隔离","中和后可长期共存"],"a":"C","e":"酸与碱相互反应放热，须分区隔离存放。"},{"id":655,"ch":4,"t":"s","q":"“双人收发”对剧毒化学品收发环节的要求是（　）。","o":["由门卫代为登记","一人收货一人发货即可","由学生代为签收","收发时由两人共同核对并签字"],"a":"D","e":"双人收发要求两人共同核对品种、数量并签字确认。"},{"id":656,"ch":4,"t":"s","q":"使用危险化学品时，产生有毒气体的操作应在（　）中进行。","o":["密闭房间","通风橱","走廊","办公桌"],"a":"B","e":"通风橱可有效排出有毒气体，保护操作人员。"},{"id":657,"ch":4,"t":"s","q":"搬运危险化学品时，正确的做法是（　）。","o":["轻拿轻放，防止包装破损","肩扛大桶快速行走","随意堆放于车厢内","将液体瓶倒置搬运"],"a":"A","e":"轻拿轻放可避免容器破损造成泄漏。"},{"id":658,"ch":4,"t":"s","q":"危险化学品分装后，容器上必须（　）。","o":["保留原标签即可","不贴标签以免混淆","仅用颜色区分","粘贴清晰的名称标签"],"a":"D","e":"分装容器须标明名称、浓度等信息，防止误用。"},{"id":659,"ch":4,"t":"s","q":"购买易制毒化学品时，应当（　）。","o":["在超市自由购买","由学生个人网购","按规定备案或申请许可，并如实记录流向","无需任何记录"],"a":"C","e":"易制毒化学品实行备案或许可管理，流向须如实记录。"},{"id":660,"ch":4,"t":"s","q":"感染性物质发生溢洒时，首先应当（　）。","o":["徒手用抹布擦净","划定区域、做好个人防护后再处理","用风扇吹干","直接用水冲入下水道"],"a":"B","e":"先隔离区域并做好防护，可避免暴露和污染扩散。"},{"id":661,"ch":4,"t":"s","q":"危险化学品库房的照明和电气设备应当（　）。","o":["使用普通开关","随意拉接临时线","使用明火灯具","符合防爆要求"],"a":"D","e":"库房内易燃蒸气可能积聚，电气设备须符合防爆要求。"},{"id":662,"ch":4,"t":"s","q":"剧毒化学品应当存放在（　）。","o":["专用保险柜并实行双人双锁","普通试剂柜","实验台抽屉","学生储物柜"],"a":"A","e":"专柜存放、双人双锁是剧毒化学品管理的核心措施。"},{"id":663,"ch":4,"t":"s","q":"腐蚀性化学品灼伤皮肤后，应当立即（　）。","o":["涂抹油膏后包扎","脱去污染衣物并用大量清水冲洗","用毛巾用力擦拭","等待自行恢复"],"a":"B","e":"先脱去污染衣物，再用大量清水冲洗，以稀释并去除腐蚀性物质。"},{"id":664,"ch":4,"t":"s","q":"危险化学品的采购计划应当（　）。","o":["经审批后由具备资质的单位供应","由使用人自行向任何商家购买","先用后批","通过个人渠道代购"],"a":"A","e":"采购须履行审批手续，并由有资质的单位供应。"},{"id":665,"ch":4,"t":"s","q":"关于实验室内危险化学品的存量，正确的做法是（　）。","o":["越多越好","不受任何限制","一次囤积一年用量","控制存量，随用随领"],"a":"D","e":"控制存量可减少事故后果，是储存管理的基本要求。"},{"id":666,"ch":4,"t":"s","q":"“双人使用”对剧毒化学品操作的要求是（　）。","o":["一人独立操作","使用时两人在场、共同监督","可由一人代签","使用无需记录"],"a":"B","e":"双人使用要求两人同时在场、相互监督并记录。"},{"id":667,"ch":4,"t":"s","q":"危险化学品管理台账应当记录（　）。","o":["只需记录购买金额","由供货方单独保存","品名、数量、用途和流向","每年口头汇报一次"],"a":"C","e":"台账须如实记录品名、数量、用途、流向等，实现可追溯。"},{"id":668,"ch":4,"t":"s","q":"危险化学品与非危险化学品在同一储存场所内应当（　）。","o":["分区存放，不得混放","任意混放","按包装颜色混放","按购买时间混放"],"a":"A","e":"分区存放可避免误取误用和禁忌物接触。"},{"id":669,"ch":4,"t":"s","q":"运输感染性物质时，其包装应当采用（　）。","o":["普通纸箱","单层塑料袋","敞口玻璃瓶","由主容器、辅助包装和外包装组成的三层包装"],"a":"D","e":"三层包装可保证内容物在运输中不泄漏，符合感染性物质运输要求。"},{"id":670,"ch":4,"t":"s","q":"腐蚀品的储存方式应当是（　）。","o":["与氧化剂同柜存放","与氧化剂、易燃物分开存放","与食品一起存放","露天堆放"],"a":"B","e":"腐蚀品与氧化剂、易燃物性质相忌，须分开存放。"},{"id":671,"ch":4,"t":"s","q":"危险化学品使用后剩余的残液，应当（　）。","o":["倒入下水道","倒入生活垃圾桶","分类收集，交专业机构处置","随意放置在实验台"],"a":"C","e":"残液须分类收集，交由有资质单位处置，不得随意排放。"},{"id":672,"ch":4,"t":"s","q":"实验中需要取用少量易燃液体时，正确的做法是","o":["在实验台上快速取用","在通风橱内按需取用最小量","一次配足一周的用量备用","在走廊通风处敞口取用"],"a":"B","e":"易燃液体应在通风橱内按最小量取用，减少挥发和存量。"},{"id":673,"ch":4,"t":"s","q":"搬运装有压缩气体的钢瓶时，应当","o":["横放在地面上滚动","由两人肩扛通过楼梯","用专用小车或夹具固定后搬运","抓住瓶阀拖拽前行"],"a":"C","e":"钢瓶须用专用工具固定搬运，禁止滚动、肩扛和抓瓶阀拖拽。"},{"id":674,"ch":4,"t":"s","q":"开启盛有挥发性腐蚀性液体的试剂瓶时，正确的操作是","o":["在通风橱内缓慢旋开瓶塞，瓶口不朝向人","快速拧开瓶塞以缩短挥发时间","用明火烘烤瓶口使瓶塞松动","将瓶口对准水槽边冲水边开启"],"a":"A","e":"缓慢开启并避开人体，可防止瓶内压力喷溅伤人。"},{"id":675,"ch":4,"t":"s","q":"分装危险化学品时，对容器的要求是","o":["可用清洗干净的饮料瓶代替","用无任何标记的干净烧杯","使用专用容器并粘贴新标签","用敞口搪瓷盘临时盛放"],"a":"C","e":"分装必须用专用容器并重新标识，防止误用。"},{"id":676,"ch":4,"t":"s","q":"实验产生的危险废物，正确的处置方式是","o":["用大量水稀释后倒入下水道","混入生活垃圾由保洁清运","在通风橱内加热蒸干","分类收集后交有资质单位处置"],"a":"D","e":"危险废物须分类收集并由有资质单位统一处置。"},{"id":677,"ch":4,"t":"s","q":"危险废物收集容器的外表面应当","o":["保持空白以免泄露信息","粘贴标签，注明废物成分与日期","只写房间号即可","涂成红色即可识别"],"a":"B","e":"废物容器须有标签标明成分、日期等信息，便于识别与处置。"},{"id":678,"ch":4,"t":"s","q":"关于易制爆危险化学品的管理，正确的是","o":["与普通试剂混放即可","只在节假日登记","如实登记并向公安机关备案，专人管理","可私自转卖给他人"],"a":"C","e":"易制爆化学品须如实登记、备案并指定专人管理。"},{"id":679,"ch":4,"t":"s","q":"氧化剂与还原剂在储存和搬运时的正确做法是","o":["分开存放，严禁混存混运","同柜存放，只要标签清楚","同车搬运以节省时间","混合后统一处理"],"a":"A","e":"氧化剂与还原剂属禁配物，接触可能引发剧烈反应。"},{"id":680,"ch":4,"t":"s","q":"浓硫酸与氢氧化钠固体在实验室中应","o":["放在同一托盘内","相邻摆放便于取用","混合后保存","分开存放，避免相互接触"],"a":"D","e":"酸碱属禁配物，混放易发生中和放热甚至喷溅。"},{"id":681,"ch":4,"t":"s","q":"使用通风橱进行实验时，正确的做法是","o":["操作时视窗尽量放低，人体不伸入橱内","把视窗完全拉起便于操作","把头伸入橱内观察反应","关闭排风以节约能源"],"a":"A","e":"降低视窗、保持排风是通风橱有效防护的前提。"},{"id":682,"ch":4,"t":"s","q":"通风橱内不得","o":["放置正在反应的装置","摆放必要的仪器","进行有害气体操作","长期堆放试剂和杂物"],"a":"D","e":"通风橱不是储存柜，堆放杂物会扰乱气流、增加风险。"},{"id":683,"ch":4,"t":"s","q":"进入化学实验室时，个人防护的基本要求是","o":["只穿便装即可","戴棉纱手套进行所有操作","夏天可穿短裤和凉鞋","穿实验服、长发束起、不穿拖鞋凉鞋"],"a":"D","e":"实验服、束发和包脚鞋是实验室基本防护要求。"},{"id":684,"ch":4,"t":"s","q":"危险化学品入库前应","o":["核对品名、数量、包装和标签","直接放上货架","先开封试用","只登记数量不核对名称"],"a":"A","e":"验收登记须核对品名、数量、包装与标签，确保账物相符。"},{"id":685,"ch":4,"t":"s","q":"实验室存放危险化学品应当","o":["越多越省事","按颜色随意摆放","存放在走廊公共区域","按需领用，不超量、不超期存放"],"a":"D","e":"实验室只能限量存放，超量存放会显著增加事故后果。"},{"id":686,"ch":4,"t":"s","q":"盛装危险废液的容器必须","o":["用敞口烧杯","完好密封且不与废液发生反应","用金属桶盛装所有废液","装满至瓶口"],"a":"B","e":"容器材质须与废液相容并保持密封，防止泄漏和挥发。"},{"id":687,"ch":4,"t":"s","q":"废弃的剧毒化学品应当","o":["与普通废液一起处理","自行焚烧","倒入下水道","单独收集，按规定交专门机构处置"],"a":"D","e":"剧毒废物须单独收集、登记，交专门机构处置。"},{"id":688,"ch":4,"t":"s","q":"实验室产生的废酸、废碱应","o":["分别收集，中和处理须在指导后进行","直接倒入下水道","与有机废液混合","用纸吸附后丢入垃圾桶"],"a":"A","e":"酸碱废液应分开收集，中和须控制条件、防止放热喷溅。"},{"id":689,"ch":4,"t":"s","q":"取用液态试剂时，多取的试剂应当","o":["倒回原瓶以免浪费","按废弃物处理，不得倒回原瓶","放回原瓶但需过滤","留给下次使用"],"a":"B","e":"倒回原瓶会污染整瓶试剂，多取部分应按废物处理。"},{"id":690,"ch":4,"t":"s","q":"取用液体试剂时，瓶塞应当","o":["正放在台面上","握在手中","倒放在洁净台面上","放在水槽边"],"a":"C","e":"瓶塞倒放可避免污染，也防止瓶塞滚动摔碎。"},{"id":691,"ch":4,"t":"s","q":"开启低沸点、易挥发液体的试剂瓶前，宜","o":["先适当冷却，再在通风橱内缓慢开启","在阳光下暴晒","用力摇晃后立即开启","用热水加热瓶身"],"a":"A","e":"冷却可降低瓶内压力，避免开启时喷溅。"},{"id":692,"ch":4,"t":"s","q":"加热易燃液体时，正确的加热方式是","o":["用明火直接加热","用水浴或油浴等间接加热","用电炉丝裸露加热","用酒精灯直接加热烧杯底部"],"a":"B","e":"易燃液体应间接加热，明火和裸露电热丝均可能引燃蒸气。"},{"id":693,"ch":4,"t":"s","q":"危险化学品的领用原则是","o":["一次领足一学期用量","由学生随意领取","按实验需要领用，剩余及时退回","领用后自行存放于宿舍"],"a":"C","e":"按需领用、剩余退库可控制实验室存量。"},{"id":694,"ch":4,"t":"s","q":"遇湿易燃物品的储存要求是","o":["保持干燥，防止受潮，远离水源","放在水槽下方","与酸类同柜","敞口存放便于取用"],"a":"A","e":"遇湿易燃物遇水放出可燃气体，必须防潮隔绝水源。"},{"id":695,"ch":4,"t":"s","q":"高锰酸钾与甘油混合会发生","o":["无明显变化","缓慢溶解","生成无害气体","剧烈反应甚至燃烧"],"a":"D","e":"强氧化剂与有机物接触可自燃，二者属禁配物。"},{"id":696,"ch":4,"t":"s","q":"发现试剂标签脱落或模糊时，应当","o":["凭记忆继续使用","停止使用，补贴标签或按未知物处理","直接倒入废液桶","自行重新命名"],"a":"B","e":"无标签试剂不得继续使用，应按未知物登记处理。"},{"id":697,"ch":4,"t":"s","q":"搬运盛装液体的大玻璃瓶时，应当","o":["双手握住瓶颈","单人夹在腋下","使用提篮或推车","倒置搬运"],"a":"C","e":"大玻璃瓶易碎，须用提篮或推车分散受力。"},{"id":698,"ch":4,"t":"s","q":"分装易燃液体时，防止静电危害的措施是","o":["容器接地并控制流速","加快倾倒速度","用塑料漏斗","在化纤地毯上操作"],"a":"A","e":"接地和限速可减少静电积聚，避免放电引燃。"},{"id":699,"ch":4,"t":"s","q":"下列做法违反实验室危险化学品管理规定的是","o":["按需领用试剂","建立使用台账","剩余试剂及时退回","在实验台下方超量存放大量试剂"],"a":"D","e":"超量存放会使泄漏、火灾等事故后果明显放大。"},{"id":700,"ch":4,"t":"s","q":"危险废物在处置前应当","o":["直接混合以节省容器","查明性质并分类，不相容废物分开","加水稀释","密封后长期堆放于走廊"],"a":"B","e":"先查明性质再分类，可避免不相容废物混装反应。"},{"id":701,"ch":4,"t":"s","q":"易制爆化学品应存放在","o":["普通试剂架","学生实验台抽屉","专用场所或保险柜，双人双锁","走廊储物柜"],"a":"C","e":"易制爆化学品须专库专柜、双人双锁管理。"},{"id":702,"ch":4,"t":"s","q":"对成分不明的废弃试剂，应当","o":["单独收集并标明“未知”，交专门处理","与常见废液混合","倒入下水道冲走","自行燃烧"],"a":"A","e":"未知废物不得混装，须单独标识后交专门机构处理。"},{"id":703,"ch":4,"t":"s","q":"反应装置在通风橱内的放置位置应是","o":["紧贴视窗边缘","伸出橱外便于观察","放在橱内后部的安全位置","放在橱内门口"],"a":"C","e":"装置放在橱内后部可减少气流扰动和外部干扰。"},{"id":704,"ch":4,"t":"s","q":"某危险化学品安全标签上的象形图为黑色火焰位于圆圈上方、外围为红色菱形边框，该象形图对应的主要危险性类别是（ ）。","o":["氧化性物质","易燃液体","自燃物品","遇水放出易燃气体"],"a":"A","e":"GHS中“火焰在圆圈上”的象形图用于氧化性气体、氧化性液体和氧化性固体；单纯的火焰象形图才用于易燃物质。"},{"id":705,"ch":4,"t":"s","q":"按照GHS的要求，化学品安全技术说明书（SDS）中集中给出职业接触限值、工程控制措施和个体防护装备建议的是第（ ）部分。","o":["第6部分","第7部分","第8部分","第9部分"],"a":"C","e":"SDS第8部分为“接触控制/个体防护”；第6部分为泄漏应急处理，第7部分为操作处置与储存，第9部分为理化特性。"},{"id":706,"ch":4,"t":"s","q":"某易燃液体的闪点为18℃，初沸点为60℃。按GHS分类标准，该液体应归入易燃液体类别（ ）。","o":["类别1","类别2","类别3","类别4"],"a":"B","e":"GHS易燃液体类别1要求闪点小于23℃且初沸点不大于35℃；类别2要求闪点小于23℃且初沸点大于35℃。该液体闪点18℃、初沸点60℃，故属类别2。"},{"id":707,"ch":4,"t":"s","q":"实验室需要取用少量白磷，正确的操作是（ ）。","o":["在水下切割","在空气中快速称量","用滤纸包裹后称量","用手直接取用"],"a":"A","e":"白磷着火点约30℃，暴露在空气中易自燃，必须保存在水中，并在水下切割、取用。"},{"id":708,"ch":4,"t":"s","q":"氢氟酸灼伤皮肤后，在现场初步处理时，除立即用大量流水冲洗外，还应涂敷（ ）。","o":["稀醋酸","碳酸氢钠溶液","2.5%葡萄糖酸钙凝胶","酒精"],"a":"C","e":"氟离子可向深部组织渗透并与钙结合，冲洗后应涂敷2.5%葡萄糖酸钙凝胶，并尽快就医。"},{"id":709,"ch":4,"t":"s","q":"使用气体钢瓶时，乙炔瓶与氧气瓶之间的距离不得小于（ ）。","o":["1m","5m","10m","15m"],"a":"B","e":"通常要求乙炔瓶与氧气瓶间距不小于5m，二者与明火的距离不小于10m。"},{"id":710,"ch":4,"t":"s","q":"乙炔钢瓶在使用和储存过程中，瓶体表面温度不得超过（ ）。","o":["30℃","40℃","50℃","60℃"],"a":"B","e":"乙炔瓶表面温度不得超过40℃；温度过高会使丙酮挥发、乙炔分解，增加爆炸危险。"},{"id":711,"ch":4,"t":"s","q":"实验室少量汞洒落地面后，收集不起来的残留汞滴，最常用的处理方法是（ ）。","o":["用水冲入下水道","用抹布擦入垃圾桶","用稀盐酸冲洗","撒硫磺粉后收集"],"a":"D","e":"硫磺粉可与汞反应生成硫化汞，降低汞蒸气危害；汞不能冲入下水道，也不能随意丢弃。"},{"id":712,"ch":4,"t":"s","q":"高锰酸钾与下列哪种物质接触时，可能因剧烈氧化反应而自燃？","o":["水","氯化钠","甘油","氮气"],"a":"C","e":"高锰酸钾是强氧化剂，与甘油等有机物接触可剧烈反应甚至自燃，应避免与有机物、还原剂混放。"},{"id":713,"ch":4,"t":"s","q":"为防止静电积聚放电引发火灾爆炸，易燃液体储罐、输送管道及灌装设备的防静电接地电阻一般不应大于（　）。","o":["4 Ω","10 Ω","100 Ω","1000 Ω"],"a":"C","e":"按《防止静电事故通用导则》的要求，防静电接地电阻一般应在100 Ω以下。4 Ω是低压保护接地的限值，10 Ω是重复接地和防雷接地的常用限值，1000 Ω远达不到泄放静电电荷的要求，故只有100 Ω符合防静电接地的规定。"},{"id":714,"ch":4,"t":"m","q":"按危险货物分类，下列属于危险化学品大类的是","o":["爆炸品","易燃液体","放射性物品","腐蚀性物质"],"a":"ABCD","e":"九大类包括爆炸品、气体、易燃液体、易燃固体等、氧化性物质和有机过氧化物、毒性物质和感染性物质、放射性物品、腐蚀性物质、杂项。"},{"id":715,"ch":4,"t":"m","q":"GHS 标签通常应包含的要素有","o":["象形图","信号词","危险性说明","相对分子质量"],"a":"ABC","e":"标签要素为产品标识符、象形图、信号词、危险性说明、防范说明和供应商标识。"},{"id":716,"ch":4,"t":"m","q":"化学品安全技术说明书的内容包括","o":["急救措施","产品市场价格","消防措施","泄漏应急处理"],"a":"ACD","e":"SDS 的 16 部分中包含急救措施、消防措施和泄漏应急处理，不含价格信息。"},{"id":717,"ch":4,"t":"m","q":"爆炸品的主要特性有","o":["爆炸威力大、破坏性强","对撞击、摩擦和温度敏感","爆炸时可能引起邻近爆炸品殉爆","本身不可燃且无毒性"],"a":"ABC","e":"爆炸品感度高、爆炸反应速度快，并可能产生殉爆和有毒气体。"},{"id":718,"ch":4,"t":"m","q":"爆炸品储存过程中应做到","o":["可与起爆器材同库存放","专库储存、专人管理","与酸、碱、氧化剂严格隔离","库房通风、避光并远离火源"],"a":"BCD","e":"起爆器材与爆炸品必须分库储存，防止一处起爆引发连锁。"},{"id":719,"ch":4,"t":"m","q":"气瓶内气体的状态可分为","o":["压缩气体","液化气体","溶解气体","冷冻液化气体"],"a":"ABCD","e":"按充装状态分为压缩、液化、溶解和冷冻液化气体四类。"},{"id":720,"ch":4,"t":"m","q":"使用气体钢瓶时应注意","o":["直立放置并可靠固定","避免曝晒和靠近热源","按规定周期送检","用尽后随意丢弃"],"a":"ABC","e":"钢瓶须直立固定、避热并定期检验，报废钢瓶应按规定处理。"},{"id":721,"ch":4,"t":"m","q":"储存和使用易燃液体时的防火措施有","o":["用明火加热以提高效率","密闭操作、防止蒸气逸散","保持场所通风良好","设备接地以消除静电"],"a":"BCD","e":"易燃液体严禁明火加热，应密闭、通风并做好防静电措施。"},{"id":722,"ch":4,"t":"m","q":"剧毒化学品的“五双”管理包括","o":["双人保管","双人收发","双本账","单人使用"],"a":"ABC","e":"五双为双人保管、双人收发、双人使用、双把锁、双本账。"},{"id":723,"ch":4,"t":"m","q":"危险化学品储存应符合的要求有","o":["与禁忌物料同库储存","分类隔离、分区存放","严格控制储存数量","保持库房良好通风"],"a":"BCD","e":"禁忌物必须隔离，储存应分类分区、限量并保持通风。"},{"id":724,"ch":4,"t":"m","q":"操作腐蚀性物质时应","o":["用手直接取用","佩戴防护手套和护目镜","将酸缓慢加入水中","稀释过程持续搅拌"],"a":"BCD","e":"腐蚀品操作须做好个体防护，遵循酸入水、缓慢搅拌的原则。"},{"id":725,"ch":4,"t":"m","q":"下列属于禁配物组合的是","o":["氮气与氩气","氧化剂与还原剂","酸与碱","遇水反应物与水"],"a":"BCD","e":"禁配物接触会发生剧烈反应，氮气与氩气为惰性气体，可共存。"},{"id":726,"ch":4,"t":"m","q":"易制毒、易制爆化学品的日常管理要求有","o":["依法备案登记","专柜存放并双人双锁","建立购买和使用台账","可随意转借他人"],"a":"ABC","e":"此类化学品实行备案、专柜和台账管理，严禁私自转让。"},{"id":727,"ch":4,"t":"m","q":"安全技术说明书在日常工作中的用途有","o":["了解化学品的危害特性","指导泄漏和中毒的应急处置","指导选择合适的个体防护用品","替代实验室安全培训"],"a":"ABC","e":"SDS 是危害告知和应急的技术依据，但不能替代安全培训。"},{"id":728,"ch":4,"t":"m","q":"实验室废液的规范处置要求有","o":["稀释后直接排入下水道","分类收集、专桶存放","严禁倒入下水道","交有资质单位统一处理"],"a":"BCD","e":"废液须分类收集，禁止排入下水道，由有资质单位处置。"},{"id":729,"ch":4,"t":"m","q":"下列 GHS 象形图中，用于警示健康危害的有","o":["火焰","骷髅和交叉骨","感叹号","健康危害（人形上身）"],"a":"BCD","e":"火焰属物理危害象形图，其余三项均与健康危害相关。"},{"id":730,"ch":4,"t":"m","q":"气体按物理状态可分为（ ）","o":["压缩气体","液化气体","溶解气体","冷冻液化气体"],"a":"ABCD","e":"四类分别对应压缩、液化、溶解和冷冻液化气体。"},{"id":731,"ch":4,"t":"m","q":"气瓶安全使用的要求包括（ ）","o":["佩戴瓶帽和防震圈","直立放置并可靠固定","远离热源和明火","使用专用减压阀","不同气体可随意混装"],"a":"ABCD","e":"气瓶须专瓶专用，混装会引发化学反应和爆炸。"},{"id":732,"ch":4,"t":"m","q":"防止易燃液体静电危害的措施有（ ）","o":["储罐和管道接地","控制输送流速","增加环境湿度","穿防静电工作服","用塑料桶剧烈晃动"],"a":"ABCD","e":"接地、限速、增湿和防静电服均可减少静电积聚。"},{"id":733,"ch":4,"t":"m","q":"影响易燃液体火灾危险性的因素有（ ）","o":["闪点","自燃点","爆炸极限","液体颜色"],"a":"ABC","e":"颜色与火灾危险性无关，闪点、自燃点和爆炸极限是关键参数。"},{"id":734,"ch":4,"t":"m","q":"易燃液体储存要求包括（ ）","o":["阴凉通风","使用防爆电器","与氧化剂隔离","与强酸同库混放"],"a":"ABC","e":"易燃液体不得与氧化剂、强酸等禁配物混存。"},{"id":735,"ch":4,"t":"m","q":"下列物质中属于自燃物品的有（ ）","o":["黄磷","三乙基铝","硫磺","金属钠","白磷"],"a":"ABE","e":"硫磺为易燃固体，金属钠为遇湿易燃物品。"},{"id":736,"ch":4,"t":"m","q":"下列物质中属于遇湿易燃物品的有（ ）","o":["金属钠","碳化钙","金属钾","硫磺","氢化钠"],"a":"ABCE","e":"硫磺遇水不反应，其余均遇水放出可燃气体。"},{"id":737,"ch":4,"t":"m","q":"遇湿易燃物品火灾时，可使用的灭火剂有（ ）","o":["干砂","干粉","水","泡沫","二氧化碳"],"a":"AB","e":"水、泡沫含水分，二氧化碳可与活泼金属反应，均禁用。"},{"id":738,"ch":4,"t":"m","q":"氧化性物质的危险特性包括（ ）","o":["本身不一定可燃","能引起或促进可燃物燃烧","与还原剂混合有爆炸危险","受热分解放出氧气","自身闪点很低"],"a":"ABCD","e":"氧化性物质是助燃物，通常不以闪点衡量其危险性。"},{"id":739,"ch":4,"t":"m","q":"有机过氧化物的储存要求包括（ ）","o":["低温储存","避光","远离还原剂","与可燃物混放"],"a":"ABC","e":"有机过氧化物热不稳定，须低温、避光并远离还原剂和可燃物。"},{"id":740,"ch":4,"t":"m","q":"毒性物质侵入人体的途径有（ ）","o":["呼吸道吸入","皮肤吸收","消化道食入","光照辐射"],"a":"ABC","e":"毒物主要经呼吸道、皮肤和消化道进入人体。"},{"id":741,"ch":4,"t":"m","q":"下列气瓶颜色标记对应正确的有（ ）","o":["氧气瓶淡蓝色","氢气瓶淡绿色","氮气瓶黑色","乙炔瓶白色","二氧化碳瓶淡蓝色"],"a":"ABCD","e":"二氧化碳瓶为铝白色，不是淡蓝色。"},{"id":742,"ch":4,"t":"m","q":"气瓶搬运和储存的正确做法有（ ）","o":["轻装轻卸","戴瓶帽和防震圈","空瓶与实瓶分开存放","用电磁起重机吊运"],"a":"ABC","e":"电磁起重器吊运易脱落撞击，禁止用于气瓶搬运。"},{"id":743,"ch":4,"t":"m","q":"易燃固体的储存要求包括（ ）","o":["阴凉干燥","远离火种热源","与氧化剂分开","与自燃物品混放"],"a":"ABC","e":"易燃固体应与氧化剂、自燃物品等禁配物分开存放。"},{"id":744,"ch":4,"t":"m","q":"下列禁配物组合中，不能混合存放的有（ ）","o":["氧化剂与还原剂","酸与碱","遇水反应物与水","氮气与氩气"],"a":"ABC","e":"氮气与氩气均为惰性气体，可同处存放。"},{"id":745,"ch":4,"t":"m","q":"按《危险化学品安全管理条例》，危险化学品具有下列哪些性质？","o":["毒害","腐蚀","爆炸","燃烧","放射性"],"a":"ABCD","e":"危险化学品具有毒害、腐蚀、爆炸、燃烧、助燃等性质，放射性物品另按放射性物品管理。"},{"id":746,"ch":4,"t":"m","q":"危险化学品储存库房应当满足的要求包括（　）。","o":["与办公、生活区合并设置","良好的通风","明显的警示标识","分类分区存放","配备消防器材"],"a":"BCDE","e":"库房须专用、通风、分类分区并配备消防与警示设施。"},{"id":747,"ch":4,"t":"m","q":"稀释浓硫酸时的正确做法包括（　）。","o":["将水缓慢加入浓硫酸中","将酸沿器壁缓缓加入水中","边加边搅拌","使用耐热容器","佩戴护目镜和手套"],"a":"BCDE","e":"酸入水、勤搅拌、选耐热容器并做好个人防护。"},{"id":748,"ch":4,"t":"m","q":"操作感染性物质时，应当（　）。","o":["在生物安全柜内进行","用口吸移液","佩戴手套和口罩","实验结束后洗手消毒","废弃物先灭菌处理"],"a":"ACDE","e":"感染性操作须在生物安全柜内进行，禁止口吸，做好防护与灭菌。"},{"id":749,"ch":4,"t":"m","q":"危险化学品采购环节的要求包括（　）。","o":["由学生个人自行网购","编制采购计划并履行审批","从具有合法资质的单位购买","索取安全技术说明书","按规定办理备案手续"],"a":"BCDE","e":"采购须审批、从有资质单位购买、索取SDS并按规定备案。"},{"id":750,"ch":4,"t":"m","q":"危险化学品入库验收时应当检查（　）。","o":["供货方的广告宣传页","品名、规格与数量","包装是否完好","标签是否清晰","是否附有安全技术说明书"],"a":"BCDE","e":"验收核对品名规格数量、包装、标签及SDS等随附资料。"},{"id":751,"ch":4,"t":"m","q":"危险化学品台账应当记录的内容包括（　）。","o":["品名与数量","领用人的家庭住址","领用人和用途","领用与归还时间","结存数量"],"a":"ACDE","e":"台账记录品名数量、领用人用途、时间及结存，实现可追溯。"},{"id":752,"ch":4,"t":"m","q":"下列属于储存禁忌组合的有（　）。","o":["氧化剂与还原剂","酸与碱","玻璃瓶与塑料瓶","金属钠与水","易燃液体与明火"],"a":"ABDE","e":"氧化剂与还原剂、酸碱、遇水反应物与水、易燃物与火源均属禁忌。"},{"id":753,"ch":4,"t":"m","q":"剧毒化学品储存应当符合的要求有（　）。","o":["专库或专柜存放","与一般试剂混放","双人双锁","由一人独立保管","账物相符"],"a":"ACE","e":"剧毒品须专库专柜、双人双锁、账物相符，不得混放或单人保管。"},{"id":754,"ch":4,"t":"m","q":"腐蚀品灼伤后的处理原则包括（　）。","o":["用碱液中和酸灼伤创面","立即脱去被污染的衣物","用大量流动清水冲洗","眼睛受伤时提起眼睑冲洗","严重时尽快就医"],"a":"BCDE","e":"灼伤后先脱去污染衣物、大量清水冲洗并就医，不可自行中和。"},{"id":755,"ch":4,"t":"m","q":"危险化学品的使用规范包括（　）。","o":["用多少领多少","在通风橱内进行产生有害气体的操作","用饮料瓶分装试剂","佩戴必要的个人防护用品","实验室内禁止饮食"],"a":"ABDE","e":"使用须遵循最小量、通风、防护和禁止饮食等要求，不得用饮料瓶分装。"},{"id":756,"ch":4,"t":"m","q":"危险化学品搬运和分装时应当注意（　）。","o":["轻拿轻放，防止破损","用嘴吸移液管","分装容器贴好标签","专瓶专用，不得混装","大量分装时做好防护"],"a":"ACDE","e":"搬运分装须防破损、贴标签、专瓶专用并做好防护。"},{"id":757,"ch":4,"t":"m","q":"使用防爆柜储存易燃液体时，应当（　）。","o":["柜体可靠接地","将柜门长期敞开","存放量不超过规定限额","不存放相互禁忌的物质","远离热源和火源"],"a":"ACDE","e":"防爆柜须接地、限量、远离火源且不存放禁忌物，柜门应保持关闭。"},{"id":758,"ch":4,"t":"m","q":"易制毒、易制爆化学品的管理要求包括（　）。","o":["购买前按规定备案或审批","建立购买和使用台账","可自由转让给他人","专人保管","如实记录流向"],"a":"ABDE","e":"易制毒、易制爆化学品实行备案审批、台账和流向管理，不得自由转让。"},{"id":759,"ch":4,"t":"m","q":"危险化学品分类隔离存放的要求包括（　）。","o":["性质相容的品种可同区存放","禁忌物料分开存放","所有化学品按字母顺序混放","腐蚀品与氧化剂隔离","剧毒品与一般试剂同柜存放"],"a":"ABD","e":"按性质相容同区、禁忌隔离，不能按字母顺序混放或把剧毒品与一般试剂同柜。"},{"id":760,"ch":4,"t":"m","q":"腐蚀品的储存要求包括（　）。","o":["储存于阴凉通风处","与氧化剂、易燃物分开存放","酸性与碱性腐蚀品分区存放","使用耐腐蚀货架或托盘","可与食品同库存放"],"a":"ABCD","e":"腐蚀品须阴凉通风、分类隔离、耐腐蚀存放，严禁与食品同库。"},{"id":761,"ch":4,"t":"m","q":"使用危险化学品时，下列做法正确的有","o":["按实验需要取用最小量","挥发性物质在通风橱内操作","根据危害选择手套和护目镜","实验结束后将剩余试剂留在台面","操作前查阅安全技术说明书"],"a":"ABCE","e":"剩余试剂应及时归位或退回，不得留置台面。"},{"id":762,"ch":4,"t":"m","q":"搬运危险化学品时应注意","o":["轻拿轻放，防止容器破损","用专用推车并固定容器","氧化剂与还原剂同车混运","搬运前检查容器有无渗漏","大玻璃瓶用提篮或推车搬运"],"a":"ABDE","e":"禁配物不得混运，其余均属正确搬运要求。"},{"id":763,"ch":4,"t":"m","q":"分装危险化学品的作业要求包括","o":["使用专用洁净容器","分装后立即粘贴标签","将多余试剂倒回原瓶","易燃液体分装时注意防静电","分装剧毒品须双人进行"],"a":"ABDE","e":"倒回原瓶会污染原试剂，分装必须专器专标。"},{"id":764,"ch":4,"t":"m","q":"开启试剂瓶时，正确的做法有","o":["开封前核对标签与内容物","挥发性液体在通风橱内开启","夏季高温时先冷却再开启低沸点试剂","用明火烘烤瓶口使瓶塞松动","开启时瓶口朝向自己便于观察"],"a":"ABC","e":"不得明火烘烤，瓶口也不能朝向人体。"},{"id":765,"ch":4,"t":"m","q":"危险废物管理的要求包括","o":["按化学性质分类收集","容器外标明废物名称与日期","不相容废物混装以节省空间","废液容器保持密封","交由有资质单位处置"],"a":"ABDE","e":"不相容废物混装可能剧烈反应，必须分开。"},{"id":766,"ch":4,"t":"m","q":"下列属于禁配组合、不得混存的有","o":["氧化剂与还原剂","酸与碱","金属钠与水","高锰酸钾与甘油","氯化钠与硫酸钠"],"a":"ABCD","e":"前四组接触均可能发生剧烈反应，氯化钠与硫酸钠可共存。"},{"id":767,"ch":4,"t":"m","q":"下列属于遇水放出易燃气体的物质有","o":["金属钠","碳化钙","氢化钙","金属钾","氯化钠"],"a":"ABCD","e":"氯化钠溶于水不发生反应，其余遇水均放出可燃气体。"},{"id":768,"ch":4,"t":"m","q":"易制爆危险化学品的管理要求包括","o":["设置专用存放场所","向公安机关备案","专人管理并如实登记","可存放在普通试剂架上","不得私自转让"],"a":"ABCE","e":"易制爆化学品不得随意存放或私自转让。"},{"id":769,"ch":4,"t":"m","q":"化学实验中的个人防护装备包括","o":["实验服","护目镜","束起长发","戴手套后可直接触摸门把手","穿露趾凉鞋"],"a":"ABC","e":"戴手套不得接触公共设施，实验室内禁穿露趾鞋。"},{"id":770,"ch":4,"t":"m","q":"使用通风橱时应注意","o":["使用前检查排风是否正常","操作时视窗尽量放低","橱内长期存放挥发性试剂","出现异味或排风异常立即停用报修","实验结束后让风机继续运行一段时间"],"a":"ABDE","e":"通风橱不能兼作储存柜，橱内不应长期堆放试剂。"},{"id":771,"ch":4,"t":"m","q":"实验室废液处置的正确做法有","o":["按性质分类收集","容器保持密封","不相容废液分开存放","直接倒入下水道","标签注明主要成分"],"a":"ABCE","e":"废液严禁排入下水道，其余均为分类收集要求。"},{"id":772,"ch":4,"t":"m","q":"控制实验室危险化学品存量的措施有","o":["按需领用","实验室不超量存放","用剩试剂及时退回仓库","建立领用台账","为方便一次领足一学期用量"],"a":"ABCD","e":"一次大量领用会突破限量要求，增加事故风险。"},{"id":773,"ch":4,"t":"m","q":"取用化学试剂时，正确的做法有","o":["不得用手直接接触试剂","不得品尝试剂","用同一吸管连续取不同试剂","取多的试剂不倒回原瓶","取用后立即盖好瓶塞"],"a":"ABDE","e":"同一吸管交叉取用会造成试剂相互污染。"},{"id":774,"ch":4,"t":"m","q":"废弃剧毒化学品的处理要求包括","o":["单独收集存放","双人交接并登记","交专门机构处置","冲入下水道稀释","与普通废液混合后处理"],"a":"ABC","e":"剧毒废物严禁排入下水道或与普通废液混合。"},{"id":775,"ch":4,"t":"m","q":"下列物质中，必须与酸类隔离存放的有（ ）。","o":["氰化钠","硫化钠","次氯酸钠","氯化钠"],"a":"ABC","e":"氰化物遇酸生成剧毒氰化氢，硫化物遇酸生成硫化氢，次氯酸盐遇酸放出氯气；氯化钠与酸不产生此类危险反应。"},{"id":776,"ch":4,"t":"m","q":"储存有机过氧化物时，正确的做法有（ ）。","o":["储存于阴凉、避光、通风良好的场所","远离还原剂、促进剂和金属化合物","为保持稳定，可与促进剂混合储存","搬运时避免撞击、摩擦和剧烈震动"],"a":"ABD","e":"有机过氧化物热不稳定，受热、撞击、摩擦或与促进剂、还原剂接触易发生自加速分解甚至爆炸，必须低温避光、隔离储存、轻搬轻放。"},{"id":777,"ch":4,"t":"j","q":"GHS 采用统一的分类标准和标签要素，替代各国原有的化学品危险性分类与标签制度。","o":["对","错"],"a":"对","e":"GHS 的宗旨即统一分类和标签，减少国际贸易与使用的差异。"},{"id":778,"ch":4,"t":"j","q":"安全技术说明书可由企业印制的产品宣传彩页代替。","o":["对","错"],"a":"错","e":"SDS 须按标准格式编写，宣传彩页不能替代。"},{"id":779,"ch":4,"t":"j","q":"爆炸品可以与易燃液体存放在同一库房内。","o":["对","错"],"a":"错","e":"爆炸品须专库储存，不得与易燃液体等混存。"},{"id":780,"ch":4,"t":"j","q":"同种可燃液体，闪点越高，其火灾危险性越大。","o":["对","错"],"a":"错","e":"闪点越低才越易挥发形成可燃蒸气，火灾危险性越大。"},{"id":781,"ch":4,"t":"j","q":"氧气钢瓶可以卧放使用，只要固定牢靠即可。","o":["对","错"],"a":"错","e":"氧气钢瓶应直立使用并固定，卧放易造成瓶阀损坏和泄漏。"},{"id":782,"ch":4,"t":"j","q":"乙炔钢瓶必须直立使用，不得卧放。","o":["对","错"],"a":"对","e":"卧放会使瓶内丙酮流出，影响使用并带来危险。"},{"id":783,"ch":4,"t":"j","q":"稀释浓硫酸时，应将水缓慢倒入浓硫酸中并搅拌。","o":["对","错"],"a":"错","e":"应将浓硫酸缓慢加入水中，反之会因局部剧烈放热而飞溅。"},{"id":784,"ch":4,"t":"j","q":"遇湿易燃物品在储存中应避免与水、水蒸气接触。","o":["对","错"],"a":"对","e":"此类物品遇水放出可燃气体并放热，可能引起燃烧爆炸。"},{"id":785,"ch":4,"t":"j","q":"剧毒化学品应实行双人双锁管理并建立使用台账。","o":["对","错"],"a":"对","e":"剧毒化学品实行“五双”管理，双人双锁是其中要求。"},{"id":786,"ch":4,"t":"j","q":"危险化学品的包装上必须粘贴与内容物相符的安全标签。","o":["对","错"],"a":"对","e":"安全标签是危害告知的基本要求，须与包装内容物一致。"},{"id":787,"ch":4,"t":"j","q":"有机过氧化物与氧化性物质同属危险货物的第五类。","o":["对","错"],"a":"对","e":"第五类为氧化性物质和有机过氧化物，二者同属一类但分项。"},{"id":788,"ch":4,"t":"j","q":"所有危险化学品火灾都可以用水扑救。","o":["对","错"],"a":"错","e":"遇湿易燃物品、比水轻的易燃液体等禁用水扑救。"},{"id":789,"ch":4,"t":"j","q":"实验室危险化学品应随用随领，储存量越少越好。","o":["对","错"],"a":"对","e":"最小量原则可降低事故后果，减少库存风险。"},{"id":790,"ch":4,"t":"j","q":"使用危险化学品时只要在记录本上登记，不必佩戴防护用品。","o":["对","错"],"a":"错","e":"登记与个体防护是并列要求，不能相互替代。"},{"id":791,"ch":4,"t":"j","q":"危险化学品分装后应立即在分装容器上粘贴标签。","o":["对","错"],"a":"对","e":"未标识容器易被误用，是实验室常见事故原因。"},{"id":792,"ch":4,"t":"j","q":"少量危险废液可用大量水稀释后倒入下水道。","o":["对","错"],"a":"错","e":"危险废液严禁排入下水道，须分类收集交有资质单位处置。"},{"id":793,"ch":4,"t":"j","q":"GHS 的信号词只有“危险”和“警告”两个。","o":["对","错"],"a":"对","e":"GHS 以“危险”表示较严重，“警告”表示较轻。"},{"id":794,"ch":4,"t":"j","q":"安全技术说明书由使用单位自行编写，与供应商无关。","o":["对","错"],"a":"错","e":"SDS 由生产或供应商随化学品提供，使用单位负责索取和存档。"},{"id":795,"ch":4,"t":"j","q":"爆炸品仓库应远离火源、热源，并防止阳光直射。","o":["对","错"],"a":"对","e":"温度升高会降低爆炸品安定性，故须避热避光。"},{"id":796,"ch":4,"t":"j","q":"气瓶外表涂有规定的颜色和字样，以便识别气体种类。","o":["对","错"],"a":"对","e":"颜色标识和字样是辨别瓶内气体、防止误用混装的重要措施。"},{"id":797,"ch":4,"t":"j","q":"易制爆化学品购入后无需办理任何备案手续。","o":["对","错"],"a":"错","e":"易制爆化学品依法实行备案和流向登记管理。"},{"id":798,"ch":4,"t":"j","q":"氧气瓶、氧气管道和减压阀可以接触油脂。","o":["对","错"],"a":"错","e":"高压氧气与油脂接触会剧烈氧化甚至燃烧爆炸。"},{"id":799,"ch":4,"t":"j","q":"乙炔瓶必须直立使用，严禁卧放。","o":["对","错"],"a":"对","e":"卧放会使丙酮流出，导致乙炔压力异常和回火危险。"},{"id":800,"ch":4,"t":"j","q":"气瓶使用完毕后应留有一定余压。","o":["对","错"],"a":"对","e":"余压可防止空气或其他气体倒灌入瓶。"},{"id":801,"ch":4,"t":"j","q":"冷冻液化气体温度很低，泄漏接触可造成冻伤。","o":["对","错"],"a":"对","e":"液氮、液氧等沸点极低，接触皮肤会造成低温冻伤。"},{"id":802,"ch":4,"t":"j","q":"闪点越低的液体，火灾危险性越大。","o":["对","错"],"a":"对","e":"闪点低表示更易挥发起火，危险性更大。"},{"id":803,"ch":4,"t":"j","q":"易燃液体的蒸气密度都比空气小。","o":["对","错"],"a":"错","e":"多数易燃液体蒸气比空气重，易积聚在低洼处。"},{"id":804,"ch":4,"t":"j","q":"金属钠可以保存在水中。","o":["对","错"],"a":"错","e":"钠遇水剧烈反应生成氢气并放热，须保存在煤油中。"},{"id":805,"ch":4,"t":"j","q":"黄磷应保存在水中。","o":["对","错"],"a":"对","e":"水层隔绝空气，可防止黄磷自燃。"},{"id":806,"ch":4,"t":"j","q":"电石受潮会放出乙炔气体。","o":["对","错"],"a":"对","e":"碳化钙遇水生成乙炔，属遇湿易燃物品。"},{"id":807,"ch":4,"t":"j","q":"活泼金属引起的火灾可以用水直接扑救。","o":["对","错"],"a":"错","e":"水与活泼金属反应放出氢气，会加剧燃烧甚至爆炸。"},{"id":808,"ch":4,"t":"j","q":"有机过氧化物应低温、避光储存。","o":["对","错"],"a":"对","e":"低温和避光可减缓分解，防止热积累引发爆炸。"},{"id":809,"ch":4,"t":"j","q":"氧化性物质与还原性物质可以同库混存。","o":["对","错"],"a":"错","e":"两者混合可能剧烈反应，属典型禁配物。"},{"id":810,"ch":4,"t":"j","q":"毒性物质只能通过消化道进入人体。","o":["对","错"],"a":"错","e":"毒物还可经呼吸道和皮肤进入人体。"},{"id":811,"ch":4,"t":"j","q":"剧毒化学品应实行双人双锁管理。","o":["对","错"],"a":"对","e":"双人双锁是剧毒品“五双”管理的核心要求。"},{"id":812,"ch":4,"t":"j","q":"氧气瓶与乙炔瓶可以存放在同一库房内。","o":["对","错"],"a":"错","e":"两者应分室或隔离存放，防止泄漏后混合爆炸。"},{"id":813,"ch":4,"t":"j","q":"气瓶搬运时可以在地上滚动。","o":["对","错"],"a":"错","e":"滚动易损伤瓶体和瓶阀，应使用专用推车搬运。"},{"id":814,"ch":4,"t":"j","q":"易燃液体储罐应设防静电接地。","o":["对","错"],"a":"对","e":"接地可导走静电荷，防止放电引燃蒸气。"},{"id":815,"ch":4,"t":"j","q":"闪点是衡量液体火灾危险性的重要指标。","o":["对","错"],"a":"对","e":"闪点越低，液体越易起火，是分类的主要依据。"},{"id":816,"ch":4,"t":"j","q":"过氧化氢属于易燃液体。","o":["对","错"],"a":"错","e":"过氧化氢是氧化性物质，不是易燃液体。"},{"id":817,"ch":4,"t":"j","q":"自燃物品必须在明火作用下才能燃烧。","o":["对","错"],"a":"错","e":"自燃物品不需明火，靠自身氧化放热即可着火。"},{"id":818,"ch":4,"t":"j","q":"危险化学品可以与普通试剂混放在同一柜内。","o":["对","错"],"a":"错","e":"危险化学品应分类分区存放，不得与普通试剂随意混放。"},{"id":819,"ch":4,"t":"j","q":"感染性物质的操作应在生物安全柜内进行。","o":["对","错"],"a":"对","e":"生物安全柜可防止气溶胶扩散，保护人员和环境。"},{"id":820,"ch":4,"t":"j","q":"危险化学品入库后应及时登记，做到账物相符。","o":["对","错"],"a":"对","e":"及时登记、账物相符是流向管理的基础。"},{"id":821,"ch":4,"t":"j","q":"腐蚀品只包括酸性物质。","o":["对","错"],"a":"错","e":"腐蚀品还包括碱性腐蚀品和其他腐蚀品。"},{"id":822,"ch":4,"t":"j","q":"盛装危险化学品的容器可以不加标签，凭记忆识别。","o":["对","错"],"a":"错","e":"容器必须粘贴清晰标签，防止误用。"},{"id":823,"ch":4,"t":"j","q":"剧毒化学品领用后的剩余部分应及时退回专用库房。","o":["对","错"],"a":"对","e":"剩余剧毒品不得私自留存，须退库并登记。"},{"id":824,"ch":4,"t":"j","q":"氧化剂与还原剂只要瓶盖拧紧就可以相邻混放。","o":["对","错"],"a":"错","e":"瓶盖拧紧不能消除泄漏和反应风险，二者必须隔离存放。"},{"id":825,"ch":4,"t":"j","q":"安全技术说明书应随危险化学品一并提供。","o":["对","错"],"a":"对","e":"SDS是危险化学品的必备随附资料。"},{"id":826,"ch":4,"t":"j","q":"使用危险化学品时应遵循最小量原则。","o":["对","错"],"a":"对","e":"用多少领多少可减少暴露和事故后果。"},{"id":827,"ch":4,"t":"j","q":"危险化学品储存场所应设置明显的警示标识。","o":["对","错"],"a":"对","e":"警示标识便于识别危险并指导应急。"},{"id":828,"ch":4,"t":"j","q":"易制毒化学品的购买无需任何审批或备案。","o":["对","错"],"a":"错","e":"易制毒化学品实行备案或许可管理。"},{"id":829,"ch":4,"t":"j","q":"危险化学品分装后应立即更换新的标签。","o":["对","错"],"a":"对","e":"分装容器须标明名称等信息，防止误用。"},{"id":830,"ch":4,"t":"j","q":"酸液溅入眼睛后应先用稀碱液中和。","o":["对","错"],"a":"错","e":"应立即用大量流动清水冲洗，不能自行中和。"},{"id":831,"ch":4,"t":"j","q":"危险化学品库房可以使用普通非防爆电器。","o":["对","错"],"a":"错","e":"库房电气设备须符合防爆要求。"},{"id":832,"ch":4,"t":"j","q":"发生感染性物质溢洒时应先做好个人防护再处理。","o":["对","错"],"a":"对","e":"做好防护并隔离区域，可避免暴露和污染扩散。"},{"id":833,"ch":4,"t":"j","q":"危险化学品搬运时应轻拿轻放，防止包装破损。","o":["对","错"],"a":"对","e":"防止破损泄漏是搬运的基本要求。"},{"id":834,"ch":4,"t":"j","q":"危险化学品使用后的残液可以直接倒入下水道。","o":["对","错"],"a":"错","e":"残液须分类收集，交专业机构处置。"},{"id":835,"ch":4,"t":"j","q":"危险化学品的使用应遵循最小量原则，用多少领多少。","o":["对","错"],"a":"对","e":"减少现场存量是控制事故后果的基本措施。"},{"id":836,"ch":4,"t":"j","q":"通风橱可以兼作试剂柜，用于长期存放挥发性试剂。","o":["对","错"],"a":"错","e":"通风橱堆放试剂会扰乱气流，且不能替代专用储存柜。"},{"id":837,"ch":4,"t":"j","q":"分装危险化学品必须使用专用容器并粘贴标签。","o":["对","错"],"a":"对","e":"专用容器加标签是防止误用和污染的必要措施。"},{"id":838,"ch":4,"t":"j","q":"取用试剂时多取的部分可以倒回原瓶，以免造成浪费。","o":["对","错"],"a":"错","e":"倒回原瓶可能污染整瓶试剂，多取部分应按废物处理。"},{"id":839,"ch":4,"t":"j","q":"搬运盛装液体的大玻璃瓶时，双手握住瓶颈即可安全搬运。","o":["对","错"],"a":"错","e":"瓶颈受力集中易断裂，应使用提篮或推车搬运。"},{"id":840,"ch":4,"t":"j","q":"氧化剂与还原剂只要瓶盖拧紧就可以同柜存放。","o":["对","错"],"a":"错","e":"二者属禁配物，泄漏或破损时仍会接触反应，必须分开存放。"},{"id":841,"ch":4,"t":"j","q":"金属钠应浸没在煤油中保存，以防止接触水汽。","o":["对","错"],"a":"对","e":"煤油隔绝空气和水汽，可抑制钠的氧化和反应。"},{"id":842,"ch":4,"t":"j","q":"金属钠着火时可以用水扑灭。","o":["对","错"],"a":"错","e":"钠遇水放出氢气并放热，会使火势加剧，应用干燥砂土。"},{"id":843,"ch":4,"t":"j","q":"危险废物容器应粘贴标签，注明废物成分和日期。","o":["对","错"],"a":"对","e":"标识清楚便于分类存放和安全交接处置。"},{"id":844,"ch":4,"t":"j","q":"实验室少量的废酸可以直接倒入下水道冲走。","o":["对","错"],"a":"错","e":"废酸废碱应分别收集处理，不得排入下水道。"},{"id":845,"ch":4,"t":"j","q":"易制毒化学品的购买和使用须按规定备案并建立台账。","o":["对","错"],"a":"对","e":"备案与台账是易制毒化学品流向管理的基本要求。"},{"id":846,"ch":4,"t":"j","q":"易制爆化学品应实行双人双锁、专人管理。","o":["对","错"],"a":"对","e":"双人双锁可防止丢失、被盗和私自取用。"},{"id":847,"ch":4,"t":"j","q":"剧毒化学品可以由一人领取并保管，以提高工作效率。","o":["对","错"],"a":"错","e":"剧毒化学品实行“五双”管理，禁止单人保管和领取。"},{"id":848,"ch":4,"t":"j","q":"开启易挥发液体试剂瓶前应先适当冷却，并在通风橱内缓慢开启。","o":["对","错"],"a":"对","e":"冷却降压、缓慢开启可避免喷溅和蒸气扩散。"},{"id":849,"ch":4,"t":"j","q":"危险化学品包装破损时，只要操作小心仍可继续使用。","o":["对","错"],"a":"错","e":"包装破损应立即隔离并妥善处理，防止泄漏和污染。"},{"id":850,"ch":4,"t":"j","q":"使用通风橱时，不应将头伸入橱内观察或操作。","o":["对","错"],"a":"对","e":"伸入橱内会破坏气流屏障，使人员直接暴露于有害气体。"},{"id":851,"ch":4,"t":"j","q":"危险化学品应由学校统一采购，个人不得私自购买。","o":["对","错"],"a":"对","e":"统一采购便于资质审核、登记和全过程管理。"},{"id":852,"ch":4,"t":"j","q":"为方便实验，实验室可以大量存放危险化学品。","o":["对","错"],"a":"错","e":"实验室只能限量存放，超量存放会放大事故后果。"},{"id":853,"ch":4,"t":"j","q":"不相容的危险废物不得混装在同一容器中。","o":["对","错"],"a":"对","e":"混装可能发生放热、产气甚至燃烧爆炸。"},{"id":854,"ch":4,"t":"j","q":"标签脱落的试剂可以凭记忆判断后继续使用。","o":["对","错"],"a":"错","e":"无标签试剂应按未知物处理，不得凭记忆使用。"},{"id":855,"ch":4,"t":"j","q":"金属钠应浸没在煤油或液体石蜡中保存，以隔绝空气和水。","o":["对","错"],"a":"对","e":"钠遇水剧烈反应放出氢气，暴露在空气中易氧化，故须浸没在煤油或液体石蜡中密封保存。"},{"id":856,"ch":4,"t":"j","q":"氧气钢瓶瓶阀冻结时，可以用明火烘烤解冻。","o":["对","错"],"a":"错","e":"氧气助燃，瓶阀冻结只能用温水或蒸汽缓慢解冻，严禁明火烘烤，也不得用铁器敲击。"},{"id":857,"ch":4,"t":"j","q":"氢氟酸能腐蚀玻璃，但实验室仍可将其盛放在带玻璃塞的棕色细口瓶中密封保存。","o":["对","错"],"a":"错","e":"氢氟酸与玻璃中的二氧化硅反应（SiO2+4HF=SiF4↑+2H2O），会腐蚀瓶体内壁并使磨口玻璃塞与瓶口粘连、难以开启，故不能用玻璃容器（也不能用带玻璃塞的瓶）盛装。氢氟酸应保存在聚乙烯等塑料容器中，密封、阴凉处存放，并与其他试剂隔离。"},{"id":858,"ch":4,"t":"b","q":"危险货物按危险性质共分为____大类，第一类为爆炸品。","a":["9"]},{"id":859,"ch":4,"t":"b","q":"GHS 标签中用简短的词标示危险严重程度，这两个词称为____。","a":["信号词"]},{"id":860,"ch":4,"t":"b","q":"按国家标准编写的化学品安全技术说明书共包括____个部分。","a":["16"]},{"id":861,"ch":4,"t":"b","q":"衡量易燃液体发生闪燃的最低温度称为____，它是划分火灾危险性等级的依据。","a":["闪点"]},{"id":862,"ch":4,"t":"b","q":"一处爆炸品爆炸引起邻近爆炸品爆炸的现象称为____。","a":["殉爆"]},{"id":863,"ch":4,"t":"b","q":"剧毒化学品实行“五双”管理，即双人保管、双人收发、双人使用、____和双本账。","a":["双把锁"]},{"id":864,"ch":4,"t":"b","q":"稀释浓硫酸时，应将____沿器壁缓慢加入____中，并不断搅拌。","a":["浓硫酸","水"]},{"id":865,"ch":4,"t":"b","q":"遇湿易燃物品着火时，严禁使用____扑救。","a":["水"]},{"id":866,"ch":4,"t":"b","q":"按充装状态，气瓶内的气体分为压缩气体、液化气体、____和冷冻液化气体。","a":["溶解气体"]},{"id":867,"ch":4,"t":"b","q":"危险化学品的包装上必须附有____和安全标签，以告知危害信息。","a":["化学品安全技术说明书"]},{"id":868,"ch":4,"t":"b","q":"氧气钢瓶的瓶阀和减压器严禁沾染____，否则可能引起燃烧爆炸。","a":["油脂"]},{"id":869,"ch":4,"t":"b","q":"两种混合后会发生剧烈反应、必须隔离存放的物质互称为____。","a":["禁配物"]},{"id":870,"ch":4,"t":"b","q":"实验室危险废物应分类收集，并交由具有相应____的单位处置。","a":["资质"]},{"id":871,"ch":4,"t":"b","q":"气体按物理状态分为压缩气体、液化气体、____气体和冷冻液化气体。","a":["溶解"]},{"id":872,"ch":4,"t":"b","q":"易燃液体按闪点分为低闪点液体、中闪点液体和____闪点液体。","a":["高"]},{"id":873,"ch":4,"t":"b","q":"低闪点液体的闪点低于____℃。","a":["-18"]},{"id":874,"ch":4,"t":"b","q":"永久气体气瓶使用后，瓶内剩余压力一般不低于____MPa。","a":["0.05"]},{"id":875,"ch":4,"t":"b","q":"使用氧气瓶和乙炔瓶时，两瓶之间的距离不应小于____m。","a":["5"]},{"id":876,"ch":4,"t":"b","q":"气瓶与明火的距离一般不应小于____m。","a":["10"]},{"id":877,"ch":4,"t":"b","q":"溶解乙炔气瓶的多孔填料中浸有____，用于溶解乙炔。","a":["丙酮"]},{"id":878,"ch":4,"t":"b","q":"黄磷应保存在____中，以隔绝空气防止自燃。","a":["水"]},{"id":879,"ch":4,"t":"b","q":"金属钠、金属钾应保存在____中。","a":["煤油"]},{"id":880,"ch":4,"t":"b","q":"电石遇水会放出____气体。","a":["乙炔"]},{"id":881,"ch":4,"t":"b","q":"有机过氧化物热稳定性差，储存时应控制____并避光。","a":["温度"]},{"id":882,"ch":4,"t":"b","q":"在危险货物分类中，氧化性物质和有机过氧化物属于第____类。","a":["5"]},{"id":883,"ch":4,"t":"b","q":"感染性物质包装的外部应贴有____标识。","a":["生物危险"]},{"id":884,"ch":4,"t":"b","q":"危险化学品入库验收后应及时登记，做到____相符。","a":["账物"]},{"id":885,"ch":4,"t":"b","q":"危险化学品应储存在专用场所，并设置明显的____标识。","a":["警示"]},{"id":886,"ch":4,"t":"b","q":"领用危险化学品应遵循____原则，用多少领多少。","a":["最小量"]},{"id":887,"ch":4,"t":"b","q":"储存易燃液体的防爆柜，其柜体应可靠____。","a":["接地"]},{"id":888,"ch":4,"t":"b","q":"危险化学品的采购必须从具有合法____的单位购买。","a":["资质"]},{"id":889,"ch":4,"t":"b","q":"腐蚀品按化学性质分为酸性腐蚀品、碱性腐蚀品和____腐蚀品。","a":["其他"]},{"id":890,"ch":4,"t":"b","q":"危险化学品分装后应立即粘贴____。","a":["标签"]},{"id":891,"ch":4,"t":"b","q":"感染性物质实验废弃物通常先经____灭菌后再处置。","a":["高压蒸汽"]},{"id":892,"ch":4,"t":"b","q":"危险化学品台账应如实记录品名、数量、用途和____。","a":["流向"]},{"id":893,"ch":4,"t":"b","q":"易挥发、有毒物质的操作应在____中进行。","a":["通风橱"]},{"id":894,"ch":4,"t":"b","q":"分装后的容器必须粘贴____，注明品名和浓度。","a":["标签"]},{"id":895,"ch":4,"t":"b","q":"取用试剂时，多取的部分不得____原瓶。","a":["倒回"]},{"id":896,"ch":4,"t":"b","q":"金属钠、金属钾应浸没在____中保存。","a":["煤油"]},{"id":897,"ch":4,"t":"b","q":"金属钠着火时应使用____覆盖扑灭。","a":["干燥砂土"]},{"id":898,"ch":4,"t":"b","q":"遇水放出易燃气体的物质储存时应保持____，防止受潮。","a":["干燥"]},{"id":899,"ch":4,"t":"b","q":"危险废物应____收集，不得与不相容废物混装。","a":["分类"]},{"id":900,"ch":4,"t":"b","q":"剧毒化学品实行“五双”管理，即双人保管、双人领取、双人使用、双把锁和____。","a":["双本账"]},{"id":901,"ch":4,"t":"b","q":"易制毒化学品的购买须按规定办理____手续。","a":["备案"]},{"id":902,"ch":4,"t":"b","q":"搬运盛装腐蚀性液体的大玻璃瓶应使用____或推车。","a":["提篮"]},{"id":903,"ch":4,"t":"b","q":"强氧化剂与____接触可能发生剧烈反应甚至燃烧爆炸。","a":["还原剂"]},{"id":904,"ch":4,"t":"b","q":"危险化学品入库前应核对品名、数量、包装和____。","a":["标签"]},{"id":905,"ch":4,"t":"b","q":"按我国气瓶颜色标记，氢气瓶的瓶体为____色，字样为____色。","a":["淡绿色","红色"],"e":"氢气瓶为淡绿色瓶体、红色字样；氧气瓶为淡蓝色瓶体、黑色字样，乙炔瓶为白色瓶体、红色字样。"},{"id":906,"ch":4,"t":"b","q":"剧毒化学品实行“五双”管理，其中包括双人保管、双人领取、双人使用、____和____。","a":["双把锁","双本账"],"e":"“五双”即双人保管、双人领取、双人使用、双把锁、双本账，做到账物相符、双人监督。"},{"id":907,"ch":4,"t":"b","q":"硝酸铵储存时必须与____、____和金属粉末等分开，防止受热、撞击或混入杂质后发生爆炸。","a":["还原剂","酸类"],"e":"硝酸铵是强氧化剂，与还原剂、酸类、金属粉末、可燃物等混合后，在受热或撞击下可能发生剧烈分解爆炸。"},{"id":908,"ch":4,"t":"b","q":"GHS标签上的信号词只有“____”和“____”两个。","a":["危险","警告"],"e":"GHS信号词用“危险”表示较严重的危险性，用“警告”表示较轻的危险性，不能自造其他信号词。"},{"id":909,"ch":4,"t":"b","q":"在有毒气体浓度不明或可能缺氧的泄漏现场，救援人员必须佩戴____式空气呼吸器。","a":["正压"],"e":"正压式空气呼吸器可防止外界毒气渗入面罩；过滤式防毒面具不能用于缺氧或未知浓度有毒环境。"},{"id":910,"ch":4,"t":"x","q":"简述化学品安全技术说明书（SDS）的作用和主要内容。","a":"1.作用：向使用者传递化学品的危害信息，为安全操作、储存、运输和应急处置提供技术依据，也是作业场所危害告知的法定文件。2.主要内容：按标准共 16 部分，包括化学品及企业标识、危险性概述、成分/组成信息、急救措施、消防措施、泄漏应急处理、操作处置与储存、接触控制/个体防护、理化特性、稳定性和反应性、毒理学信息、生态学信息、废弃处置、运输信息、法规信息及其他信息。3.使用要求：使用前应查阅相应部分，重点掌握危害性、防护措施和急救方法。"},{"id":911,"ch":4,"t":"x","q":"说明爆炸品在储存和运输环节应采取的主要安全措施。","a":"1.储存：专库储存、专人管理，库房通风干燥、避光并远离火源热源；与酸、碱、氧化剂及起爆器材严格隔离；控制储存数量，堆垛留有通道，防止摩擦、撞击和倾倒。2.运输：使用专用车辆，专人押运，按危险货物规定悬挂标志；严禁与普通货物混装，禁止随身携带；装卸轻拿轻放，严禁抛掷、拖拉和碰撞。3.管理：建立出入库台账，定期检查包装和库房条件，发现渗漏、变质及时处理。"},{"id":912,"ch":4,"t":"x","q":"某实验室将高锰酸钾、过氧化氢与甘油、乙醇混放在同一试剂柜的下层，且柜内无隔离。请分析存在的危险并提出整改措施。","a":"1.危险分析：高锰酸钾为强氧化剂，过氧化氢为氧化性液体，甘油、乙醇为还原性有机物，属典型禁配物；一旦泄漏或瓶盖松动，氧化剂与有机物接触会发生剧烈氧化还原反应，放热并可能引燃或爆炸；混放于下层还便于液体渗漏积聚，风险更大。2.整改措施：将氧化剂与还原性有机物分柜、分层隔离存放，并设置明显标识；试剂分类上架、限量储存，瓶口密封，柜内放置防泄漏托盘；建立台账并定期检查；对相关人员开展禁配物和应急处置培训。"},{"id":913,"ch":4,"t":"x","q":"简述气瓶安全使用的主要要求。","a":"1.气瓶应专瓶专用，佩戴瓶帽和防震圈，轻装轻卸，禁止滚动、撞击和吊运瓶阀；2.直立放置并可靠固定，远离热源和明火，氧气瓶与乙炔瓶间距不小于5 m，与明火距离不小于10 m；3.使用专用减压阀，氧气瓶及附件严禁接触油脂，乙炔瓶严禁卧放；4.开阀应缓慢，人员站在侧面，不得用明火检漏；5.用后关阀并留有余压，空瓶与实瓶分开存放；6.按规定定期检验，超期或外观异常的气瓶不得使用。"},{"id":914,"ch":4,"t":"x","q":"简述易燃液体防火与防静电的主要措施。","a":"1.储存于阴凉通风库房，远离火种、热源，与氧化剂、强酸等禁配物隔离；2.采用防爆电气设备和防爆照明，严禁明火；3.储罐、管道和设备可靠接地，控制输送流速，防止喷溅和剧烈搅动；4.作业人员穿防静电工作服和防静电鞋，不用易产生静电的塑料容器；5.保持容器密闭，加强通风，防止蒸气积聚；6.配备干粉、泡沫等适用灭火器材，不用水直接扑救比水轻的液体火灾。"},{"id":915,"ch":4,"t":"x","q":"某实验室一名学生将少量金属钠残渣连同废液一起倒入水槽并用水冲洗，随即发生剧烈反应和燃烧。请分析事故原因，并说明金属钠的正确保存与废弃处置方法。","a":"1.原因：金属钠属遇湿易燃物品，与水剧烈反应放出氢气和大量热，氢气被引燃，钠渣飞溅造成燃烧甚至爆炸；将钠倒入水槽并用水冲洗，直接违反了遇湿易燃物品不得接触水的原则。2.保存：金属钠应浸没在煤油中密闭保存，置于阴凉干燥处，远离水、酸和氧化剂，容器上标注名称。3.取用：在干燥器皿中快速取用，用镊子夹取，剩余钠屑不得随意丢弃。4.废弃：少量残钠可用无水乙醇缓慢分解，确认无残余钠后按有机废液处理；量较大时应交学校危化品管理部门统一处置，严禁投入水槽或垃圾桶。"},{"id":916,"ch":4,"t":"x","q":"简述剧毒化学品“五双”管理制度的具体内容。","a":"1.双人保管：剧毒品由两名保管人员共同负责，互相监督；2.双人收发：收发时两人共同核对品名、数量并签字；3.双人使用：领用和使用时两人同时在场，共同监督并记录；4.双把锁：存放剧毒品的保险柜或库房门设两把锁，钥匙由两人分别保管，开启时两人同时到场；5.双本账：保管与使用各设一本账，分别记录购入、领用、退回和结存情况，定期核对，做到账物相符。通过上述措施实现全过程可追溯，防止丢失、被盗和误用。"},{"id":917,"ch":4,"t":"x","q":"简述浓硫酸稀释的正确操作，以及酸液灼伤皮肤后的应急处理。","a":"1.稀释操作：将浓硫酸沿容器壁缓缓加入水中，边加边用玻璃棒搅拌，使产生的热量及时扩散；严禁将水倒入浓硫酸中；宜使用耐热容器，操作者佩戴护目镜和防护手套。2.皮肤灼伤处理：立即脱去被污染的衣物，用大量流动清水持续冲洗灼伤部位，尽量稀释并去除残留酸液；不要用碱液自行中和，以免中和放热加重损伤；冲洗后可用洁净纱布覆盖创面，严重时尽快就医。3.眼睛受伤时提起眼睑用大量清水冲洗，并立即送医。"},{"id":918,"ch":4,"t":"x","q":"某实验室将浓硝酸与乙醇放在同一试剂柜内，并把感染性实验废弃物与生活垃圾混装。请指出其中的问题并提出整改措施。","a":"1.存在问题：浓硝酸是强氧化剂，乙醇是易燃物，二者属禁忌组合，同柜存放一旦泄漏接触可能起火爆炸；感染性废弃物与生活垃圾混装，会造成病原微生物扩散和环境污染；同时反映该实验室危险化学品分类隔离和废弃物管理不到位。2.整改措施：将氧化剂与易燃物分柜分区存放，张贴禁忌物提示；试剂柜保持通风，配备泄漏应急用品；感染性废弃物经高压蒸汽灭菌后装入专用包装，交有资质单位处置；建立危险化学品台账和废弃物交接记录，开展分类储存与应急处置培训，并定期检查落实情况。"},{"id":919,"ch":4,"t":"x","q":"简述实验室使用危险化学品时应遵守的基本规范（至少答出五点）。","a":"1.按最小量原则领用，用多少领多少，剩余试剂及时退回，不在实验台面大量存放；2.易挥发、有毒、有腐蚀性的操作在通风橱内进行，视窗放低，人体不伸入橱内；3.按要求穿戴实验服、护目镜和合适手套，长发束起，不穿拖鞋凉鞋；4.取用试剂核对标签，瓶塞倒放，多取部分不倒回原瓶，用后立即盖好；5.分装使用专用容器并粘贴新标签，易燃液体分装注意接地防静电；6.操作前查阅安全技术说明书，了解危害、禁配物和应急处置方法；7.废液废物分类收集、贴标签，交有资质单位处置，不排入下水道。"},{"id":920,"ch":4,"t":"x","q":"某实验结束后，有人将剩余浓硝酸、乙醇废液和高锰酸钾废液一并倒入同一废液桶，次日发现桶内发热并产生刺激性气体。请分析原因，并说明危险废物分类收集的基本要求。","a":"1.原因分析：浓硝酸是强氧化剂，乙醇是可燃的还原性有机物，高锰酸钾也是强氧化剂。三者混装后，硝酸与乙醇发生强烈氧化还原反应，放出大量热和氮氧化物等刺激性气体；高锰酸钾与乙醇等有机物接触也会剧烈反应，甚至可能燃烧爆炸，故桶内发热并冒刺激性气体。2.分类收集要求：按化学性质分类收集，氧化剂与还原剂、酸与碱、有机物与强氧化剂等禁配物严禁混装；废液容器须材质相容、完好密封，不得装满至瓶口；容器外粘贴标签，注明废物名称、主要成分、日期和危险特性；剧毒废物单独收集并双人交接登记；存放于阴凉通风的专用暂存点，不超量、不超期；最终交有资质单位处置，严禁排入下水道或混入生活垃圾。"},{"id":921,"ch":5,"t":"s","q":"电流通过人体时，对人体危害最大的电流途径是","o":["手至脚","脚至脚","手至手","臀部至脚"],"a":"A","e":"手至脚的电流路径经过心脏，危险性最大。"},{"id":922,"ch":5,"t":"s","q":"工频电流刚能引起人体感觉的电流称为感知电流，其数值约为","o":["0.1 mA","1 mA","10 mA","50 mA"],"a":"B","e":"工频感知电流约为1 mA，此时人体开始有麻刺感。"},{"id":923,"ch":5,"t":"s","q":"成年男性能够自主摆脱带电体的最大工频电流约为","o":["1 mA","5 mA","10 mA","50 mA"],"a":"C","e":"成年男性摆脱电流约为10 mA，女性略低。"},{"id":924,"ch":5,"t":"s","q":"工频电流通过人体时，通常认为可能引起心室颤动的危险电流约为","o":["1 mA","10 mA","50 mA","500 mA"],"a":"C","e":"工频50 mA左右即可引起心室颤动，危及生命。"},{"id":925,"ch":5,"t":"s","q":"电流对人体造成的电灼伤，属于","o":["电击","电磁场伤害","静电感应伤害","电伤"],"a":"D","e":"电灼伤是电流的热效应造成的局部伤害，属于电伤。"},{"id":926,"ch":5,"t":"s","q":"在中性点直接接地的低压系统中，人体触及一根相线造成的单相触电，人体承受的电压是","o":["线电压","相电压","两倍相电压","零电压"],"a":"B","e":"中性点接地系统中单相触电时，人体承受的是相电压。"},{"id":927,"ch":5,"t":"s","q":"人体同时触及两根相线造成的两相触电，人体承受的电压是","o":["线电压","相电压","相电压的一半","零电压"],"a":"A","e":"两相触电时人体承受线电压，是最危险的触电方式之一。"},{"id":928,"ch":5,"t":"s","q":"高压导线断落地面后，人距接地点多远以外可认为跨步电压接近于零","o":["5 m","10 m","20 m","50 m"],"a":"C","e":"一般距接地点20 m以外，跨步电压可视为零。"},{"id":929,"ch":5,"t":"s","q":"下列情形中最容易发生跨步电压触电的是","o":["家用电器外壳漏电","高压导线断落地面","用湿手插拔插头","雷雨天使用手机"],"a":"B","e":"导线落地后电流向四周扩散，地面形成电位差，行人两脚间产生跨步电压。"},{"id":930,"ch":5,"t":"s","q":"我国安全电压额定值系列中，下列数值不属于该系列的是","o":["42 V","36 V","24 V","18 V"],"a":"D","e":"我国安全电压额定值为42 V、36 V、24 V、12 V、6 V，不含18 V。"},{"id":931,"ch":5,"t":"s","q":"在特别潮湿的场所或金属容器内作业时，行灯使用的安全电压不应超过","o":["42 V","36 V","12 V","24 V"],"a":"C","e":"特别潮湿或金属容器内人体电阻显著降低，应采用12 V及以下安全电压。"},{"id":932,"ch":5,"t":"s","q":"保护接地适用于","o":["中性点直接接地的三相四线制系统","所有高压系统","单相两线制系统","中性点不接地的低压系统"],"a":"D","e":"保护接地用于中性点不接地的低压系统，把设备外壳与大地连接。"},{"id":933,"ch":5,"t":"s","q":"保护接零适用于","o":["中性点直接接地的三相四线制系统","中性点不接地的低压系统","直流供电系统","仅有相线的系统"],"a":"A","e":"保护接零把设备外壳与零线连接，适用于中性点直接接地的系统。"},{"id":934,"ch":5,"t":"s","q":"保护接地的接地电阻一般不应大于","o":["0.5 Ω","4 Ω","10 Ω","30 Ω"],"a":"B","e":"保护接地电阻一般要求不大于4 Ω。"},{"id":935,"ch":5,"t":"s","q":"重复接地的主要作用是","o":["提高线路的供电电压","增大接地电阻","减少线路的有功损耗","降低零线断开时设备外壳的对地电压"],"a":"D","e":"重复接地可降低零线断线后外壳对地电压，减轻触电危险。"},{"id":936,"ch":5,"t":"s","q":"一般场所使用的漏电保护器，其额定漏电动作电流多为","o":["30 mA","100 mA","300 mA","500 mA"],"a":"A","e":"用于人身保护的漏电保护器动作电流一般为30 mA。"},{"id":937,"ch":5,"t":"s","q":"用于人身触电保护的漏电保护器，其动作时间一般不应超过","o":["0.01 s","0.1 s","1 s","10 s"],"a":"B","e":"漏电保护器动作时间一般不大于0.1 s，以尽快切断电源。"},{"id":938,"ch":5,"t":"s","q":"实验室用电要求做到“一机一闸一漏一箱”，其含义是","o":["多台设备共用一个开关","一个开关控制整个实验室","每台用电设备有专用开关和漏电保护装置","只要总闸有漏电保护即可"],"a":"C","e":"每台设备应设专用开关和漏电保护，避免一闸多机带来误操作和过载。"},{"id":939,"ch":5,"t":"s","q":"低压电气线路和设备的绝缘电阻一般不应低于","o":["0.05 MΩ","0.1 MΩ","0.5 MΩ","5 MΩ"],"a":"C","e":"低压线路绝缘电阻一般要求不低于0.5 MΩ。"},{"id":940,"ch":5,"t":"s","q":"发现有人触电，救护人员首先应当","o":["立即切断电源","立即用手拉开触电者","立即送医院","立即做人工呼吸"],"a":"A","e":"先使触电者脱离电源，才能安全施救，否则救护人员也会触电。"},{"id":941,"ch":5,"t":"s","q":"触电急救中，下列做法错误的是","o":["迅速切断电源","用干燥木棒挑开导线","直接用手拉拽触电者","拨打急救电话"],"a":"C","e":"直接用手拉拽会使救护人员一同触电，必须使用绝缘物。"},{"id":942,"ch":5,"t":"s","q":"扑救电气火灾时，首先应当","o":["用水浇灭火焰","打开门窗通风","用泡沫灭火器灭火","切断电源"],"a":"D","e":"带电灭火有触电危险，应首先切断电源再组织扑救。"},{"id":943,"ch":5,"t":"s","q":"下列灭火器材中，不能用于带电灭火的是","o":["干粉灭火器","二氧化碳灭火器","水","惰性气体灭火器"],"a":"C","e":"水导电，带电灭火时严禁使用水和泡沫灭火器。"},{"id":944,"ch":5,"t":"s","q":"在潮湿场所使用手持电动工具时，应优先采用","o":["220 V 市电直接供电","降低线路截面","取消漏电保护","安全电压供电"],"a":"D","e":"潮湿场所人体电阻低，应优先采用安全电压供电。"},{"id":945,"ch":5,"t":"s","q":"实验室中私拉乱接电线的首要危害是","o":["增加线路过载和触电、火灾风险","影响实验室美观","增加电费支出","缩短灯具寿命"],"a":"A","e":"私拉乱接易造成线路过载、绝缘破损和接触不良，引发触电和火灾。"},{"id":946,"ch":5,"t":"s","q":"防爆电器主要用于","o":["普通办公场所","高温干燥场所","计算机机房","易燃易爆场所"],"a":"D","e":"易燃易爆场所存在可燃气体或粉尘，必须选用防爆型电气设备。"},{"id":947,"ch":5,"t":"s","q":"用湿手插拔电源插头的主要危险是","o":["损坏插座外观","使插头变松","降低线路电压","增加触电风险"],"a":"D","e":"湿手使人体电阻降低，插拔时接触带电部位极易触电。"},{"id":948,"ch":5,"t":"s","q":"在保护接零系统中，零线上不得装设","o":["熔断器和开关","接地线","绝缘套管","接线端子"],"a":"A","e":"零线装有熔断器或开关时，一旦断开会使设备外壳带电。"},{"id":949,"ch":5,"t":"s","q":"保护接地的作用是降低设备漏电时外壳的对地电压，一般要求其接地电阻不大于（　）。","o":["0.5Ω","1Ω","4Ω","10Ω"],"a":"C","e":"保护接地电阻一般不大于4Ω，以保证漏电时外壳电压处于较低水平。"},{"id":950,"ch":5,"t":"s","q":"在保护接零系统中，重复接地的接地电阻一般要求不大于（　）。","o":["4Ω","10Ω","30Ω","100Ω"],"a":"B","e":"重复接地电阻一般不大于10Ω，可降低零线断线后外壳的对地电压。"},{"id":951,"ch":5,"t":"s","q":"用于防止人身触电的漏电保护器，其额定动作电流一般不大于（　）。","o":["30mA","100mA","300mA","500mA"],"a":"A","e":"人身保护用漏电保护器的额定动作电流一般不大于30mA。"},{"id":952,"ch":5,"t":"s","q":"漏电保护器检测到规定剩余电流后，其动作时间一般不应超过（　）。","o":["1s","0.5s","2s","0.1s"],"a":"D","e":"漏电保护器动作时间一般不超过0.1s，以尽快切断电源。"},{"id":953,"ch":5,"t":"s","q":"装设保护接地的主要目的是（　）。","o":["提高设备的输出功率","降低漏电设备外壳的对地电压","增大线路中的工作电流","延长电气设备的使用寿命"],"a":"B","e":"保护接地通过接地体分流，使漏电时外壳对地电压降低到安全范围。"},{"id":954,"ch":5,"t":"s","q":"在保护接零系统中，电气设备的金属外壳应与（　）可靠连接。","o":["保护零线（PE线）","相线","任意一根导线","独立接地极而不接零线"],"a":"A","e":"保护接零要求外壳与保护零线连接，漏电时形成单相短路使保护装置动作。"},{"id":955,"ch":5,"t":"s","q":"关于同一供电系统中保护接地与保护接零的关系，正确的说法是（　）。","o":["可以任意混合使用","必须同时采用","不得混合使用","由使用人员临时决定"],"a":"C","e":"同一供电系统中两种保护方式混用会造成部分设备外壳带电，故不得混用。"},{"id":956,"ch":5,"t":"s","q":"电气设备外壳防护等级IP代码中，第一位数字表示（　）的能力。","o":["防水","防腐蚀","防爆","防固体异物进入"],"a":"D","e":"IP代码第一位表示防固体异物进入，第二位表示防水。"},{"id":957,"ch":5,"t":"s","q":"检查电气设备绝缘好坏、测量绝缘电阻时，应使用（　）。","o":["万用表","兆欧表","钳形电流表","电桥"],"a":"B","e":"绝缘电阻数值大，需用兆欧表测量。"},{"id":958,"ch":5,"t":"s","q":"实验室用电管理中的一机一闸是指（　）。","o":["一台设备配多个开关","多台设备共用一个开关","每台设备由专用的开关控制","一个开关控制整个实验室"],"a":"C","e":"一机一闸便于单台设备检修和故障时迅速断电。"},{"id":959,"ch":5,"t":"s","q":"三孔插座中与设备外壳相连的那个孔应接（　）。","o":["相线","中性线","任意一孔均可","保护接地线"],"a":"D","e":"该孔为保护接地孔，接保护接地线后才能起保护作用。"},{"id":960,"ch":5,"t":"s","q":"不能用湿手插拔插头，主要原因是（　）。","o":["水使人体电阻明显降低，触电危险增大","水会使电源电压升高","水会使插头重量增加","水会改变电流的方向"],"a":"A","e":"潮湿使皮肤电阻下降，同样电压下通过人体的电流增大。"},{"id":961,"ch":5,"t":"s","q":"造成电气线路过载的常见原因是（　）。","o":["电源频率偏低","导线截面偏小或接入负荷过大","接地电阻偏大","线路走向不整齐"],"a":"B","e":"导线截面与负荷不匹配时电流超过允许值，即形成过载。"},{"id":962,"ch":5,"t":"s","q":"电气线路发生短路时，线路中的电流将（　）。","o":["明显减小","保持恒定","急剧增大","变为零"],"a":"C","e":"短路时阻抗很小，电流急剧增大并伴随强烈发热。"},{"id":963,"ch":5,"t":"s","q":"下列因素中，会加速导线绝缘老化的是（　）。","o":["环境通风良好","线路负荷较轻","环境保持干燥","长期过热和化学腐蚀"],"a":"D","e":"过热、腐蚀、光照等都会加速绝缘材料老化。"},{"id":964,"ch":5,"t":"s","q":"私拉乱接电线的主要危害是（　）。","o":["接头接触不良、绝缘易破损，引发火灾和触电","可以提高供电质量","能够节约电能","便于日后检修"],"a":"A","e":"私拉乱接缺乏规范连接和保护，是常见的电气火灾与触电隐患。"},{"id":965,"ch":5,"t":"s","q":"发现电气火灾后，首先应当（　）。","o":["用水浇灭火焰","切断电源","打开门窗通风","用泡沫灭火器喷射"],"a":"B","e":"先断电可避免触电并使灭火更安全，之后再选用合适灭火器。"},{"id":966,"ch":5,"t":"s","q":"因情况紧急需要带电灭火时，宜选用（　）。","o":["水","泡沫灭火器","二氧化碳或干粉灭火器","湿棉被"],"a":"C","e":"二氧化碳和干粉不导电，可用于带电灭火，禁用水和泡沫。"},{"id":967,"ch":5,"t":"s","q":"对触电者实施急救时，第一步应当（　）。","o":["立即注射强心药物","先做人工呼吸","直接送往医院","迅速使触电者脱离电源"],"a":"D","e":"只有先脱离电源，后续急救才有意义且救护者才安全。"},{"id":968,"ch":5,"t":"s","q":"救护人员使触电者脱离带电体时，应当（　）。","o":["使用干燥的木棒等绝缘物","直接用手拉拽其衣服","用金属杆挑开导线","用湿布包裹后拖拉"],"a":"A","e":"使用绝缘物可防止救护人员一同触电。"},{"id":969,"ch":5,"t":"s","q":"触电急救中禁止直接用手拉拽触电者，是因为（　）。","o":["会损坏用电设备","救护者可能一同触电","会影响事故记录","会中断正常生产"],"a":"B","e":"触电者身上可能带电，直接接触会使救护者触电。"},{"id":970,"ch":5,"t":"s","q":"下列数值中，属于我国常用安全电压额定值系列的是（　）。","o":["12V、24V、36V、48V","24V、36V、48V、60V","6V、12V、24V、36V、42V","36V、42V、48V、60V"],"a":"C","e":"我国安全电压额定值系列为42V、36V、24V、12V、6V。"},{"id":971,"ch":5,"t":"s","q":"在特别潮湿场所或金属容器内使用行灯时，其电压不应超过（　）。","o":["220V","110V","36V","12V"],"a":"D","e":"特别潮湿或金属容器内触电危险大，行灯电压不应超过12V。"},{"id":972,"ch":5,"t":"s","q":"人体触及一相带电体而发生的触电属于（　）。","o":["单相触电","两相触电","跨步电压触电","感应电压触电"],"a":"A","e":"单相触电是人体一部分接触一相带电体、另一部分接地的触电方式。"},{"id":973,"ch":5,"t":"s","q":"跨步电压触电通常发生在（　）。","o":["室内干燥的绝缘地面上","高压导线落地处周围的地面","低压插座附近","铺有绝缘垫的操作台上"],"a":"B","e":"高压线落地后电流向四周扩散，地面两点间存在电位差形成跨步电压。"},{"id":974,"ch":5,"t":"s","q":"防爆型电气设备主要适用于（　）。","o":["潮湿的浴室","高温的锅炉房","有易燃易爆气体的场所","有腐蚀性液体的场所"],"a":"C","e":"易燃易爆场所必须选用防爆电器，防止电火花引燃爆炸性混合物。"},{"id":975,"ch":5,"t":"s","q":"漏电保护器不能有效起保护作用的触电方式是（　）。","o":["单相触电","设备漏电引起的触电","触及漏电设备外壳","两相触电"],"a":"D","e":"两相触电时电流不流经剩余电流检测回路，漏电保护器不动作。"},{"id":976,"ch":5,"t":"s","q":"在特别潮湿的实验室场所使用行灯照明时，其供电电压不应超过","o":["12V","36V","110V","220V"],"a":"A","e":"特别潮湿场所人体电阻显著降低，行灯应采用12V及以下安全电压。"},{"id":977,"ch":5,"t":"s","q":"存在酸碱腐蚀性气体的实验室，电气线路的敷设方式宜优先采用","o":["明敷塑料线槽","穿金属管暗敷并做防腐处理","沿地面直接拖设","用普通绝缘导线悬挂"],"a":"B","e":"穿管暗敷可隔绝腐蚀性介质，金属管件还应做防腐处理。"},{"id":978,"ch":5,"t":"s","q":"靠近高温电炉的配电导线应当","o":["选用普通聚氯乙烯绝缘线","改用裸铝线","选用耐热绝缘导线并远离热源","用绝缘胶布缠绕旧线后使用"],"a":"C","e":"高温会加速绝缘老化，应选耐热导线并保持足够距离。"},{"id":979,"ch":5,"t":"s","q":"在可能积聚可燃气体、蒸气的实验室中，电气设备应选用","o":["普通开启式电器","普通电器加塑料罩","仅加装漏电保护器的普通电器","防爆型电器"],"a":"D","e":"易燃易爆场所必须采用防爆电器，普通电器电火花即可引燃。"},{"id":980,"ch":5,"t":"s","q":"防爆电气设备标志中的“Ex”表示该设备具有","o":["防爆性能","防水性能","防腐性能","防尘性能"],"a":"A","e":"Ex是防爆电气设备的统一标志，其后字母表示防爆型式与类别。"},{"id":981,"ch":5,"t":"s","q":"一个电源插座上同时接入多台大功率仪器，最主要的危害是","o":["插孔容易松动","线路过载发热，可能引发电气火灾","仪器测量精度下降","供电电压升高"],"a":"B","e":"多台大功率设备共用插座会使线路过载，发热后可能起火。"},{"id":982,"ch":5,"t":"s","q":"手潮湿时插拔电源插头，主要危险在于","o":["插头容易磨损","插座容易发热","人体电阻下降，触电危险增大","电网电压波动"],"a":"C","e":"潮湿皮肤电阻大幅降低，同样电压下通过人体的电流更大。"},{"id":983,"ch":5,"t":"s","q":"发现有人触电时，首先应当","o":["直接用手把触电者拉开","先打120电话等待救援","向触电者泼水使其清醒","立即切断电源或用绝缘物使触电者脱离带电体"],"a":"D","e":"使触电者尽快脱离电源是急救的第一步，且救护者必须保证自身安全。"},{"id":984,"ch":5,"t":"s","q":"救护人员未采取绝缘措施就直接用手拉拽触电者，可能造成的后果是","o":["救护人员同时触电","只是救不了人，没有其他危险","触电者会更快苏醒","对双方都没有影响"],"a":"A","e":"人体是导体，直接接触触电者会使电流经救护者形成回路。"},{"id":985,"ch":5,"t":"s","q":"下列物品中，可用于挑开触电者身上带电导线的是","o":["湿毛巾","铁管","干燥的木棒","潮湿的绳索"],"a":"C","e":"干燥木棒是绝缘物，湿毛巾、铁管、湿绳均导电。"},{"id":986,"ch":5,"t":"s","q":"触电者心跳、呼吸均已停止时，应当","o":["送往医院途中再作处理","掐人中等其自行苏醒","先给触电者喂水","就地进行心肺复苏，同时呼救"],"a":"D","e":"心跳呼吸停止应立即就地实施心肺复苏，等待会丧失抢救时机。"},{"id":987,"ch":5,"t":"s","q":"电气设备着火时，首要的处置措施是","o":["先切断电源，再用干粉或二氧化碳灭火器扑救","立即用水扑救","用泡沫灭火器扑救","打开门窗通风后观察"],"a":"A","e":"先断电可消除触电和复燃风险，再选用不导电灭火剂扑救。"},{"id":988,"ch":5,"t":"s","q":"带电的电气设备着火时不能用水扑救，主要原因是","o":["水会损坏设备外观","水导电，可能造成触电并扩大事故","水的灭火效率太低","水会很快蒸发"],"a":"B","e":"普通水导电，射流接触带电体时会把电流引向灭火人员。"},{"id":989,"ch":5,"t":"s","q":"扑救精密电子仪器火灾时，宜选用的灭火器是","o":["水基灭火器","泡沫灭火器","二氧化碳灭火器","酸碱灭火器"],"a":"C","e":"二氧化碳灭火后不留残渣，不损坏精密仪器，且不导电。"},{"id":990,"ch":5,"t":"s","q":"潮湿实验室内的电源插座宜采用","o":["普通插座","无盖插座","平放在地面的插座","防水防溅型插座并可靠接地"],"a":"D","e":"防水防溅结构可阻止潮气进入，可靠接地可降低触电后果。"},{"id":991,"ch":5,"t":"s","q":"长期处于高温环境的电气线路，最主要的风险是","o":["导线截面积增大","绝缘材料加速老化，易发生短路","线路电阻减小","供电电压升高"],"a":"B","e":"高温使绝缘变脆、失去绝缘能力，容易短路起火。"},{"id":992,"ch":5,"t":"s","q":"在易燃易爆场所作业时，下列做法正确的是","o":["使用普通电烙铁焊接","使用防爆工具和防爆电器","用手机照明检查设备内部","带电更换照明灯泡"],"a":"B","e":"防爆工具和防爆电器不会产生足以引燃爆炸性混合物的火花。"},{"id":993,"ch":5,"t":"s","q":"发现实验室内导线绝缘层破损、铜芯外露，正确的处理是","o":["用透明胶带缠绕后继续使用","用手触摸确认是否带电","停止使用并报修更换","降低负载后继续使用"],"a":"C","e":"绝缘破损的导线必须停用更换，胶带缠绕不能恢复绝缘性能。"},{"id":994,"ch":5,"t":"s","q":"用湿抹布擦拭通电设备外壳的做法","o":["可以，只要动作快就行","可以，设备外壳有保护作用","只擦拭有接地标志的部位即可","禁止，可能造成触电和短路"],"a":"D","e":"湿抹布导电且会使水分渗入设备，既易触电又易引起短路。"},{"id":995,"ch":5,"t":"s","q":"实验台之间随意拖地的电源线，主要隐患是","o":["易被踩踏、碾压致绝缘破损而漏电","只影响实验室整洁","使线路电阻明显增大","使供电电压下降"],"a":"A","e":"拖地电线受踩踏和碾压后绝缘易破损，导致漏电和触电。"},{"id":996,"ch":5,"t":"s","q":"触电者脱离电源后神志清醒但自觉心悸，应当","o":["让其来回走动以缓解症状","让其自行回家休息","就地平卧休息、注意观察并及时送医","立即进行胸外心脏按压"],"a":"C","e":"触电后可能出现迟发性心律失常，应静卧观察并送医检查。"},{"id":997,"ch":5,"t":"s","q":"成人心肺复苏时，胸外按压与人工呼吸的次数比例为","o":["15:2","5:1","10:1","30:2"],"a":"D","e":"成人单人或双人施救均采用30次按压配合2次人工呼吸。"},{"id":998,"ch":5,"t":"s","q":"电源尚未切断时扑救电气火灾，应使用","o":["干粉或二氧化碳灭火器","水","泡沫灭火器","湿棉被覆盖"],"a":"A","e":"干粉和二氧化碳不导电，可在断电前安全使用。"},{"id":999,"ch":5,"t":"s","q":"为潮湿实验室选用电气设备时，应优先考虑","o":["价格最低","体积最小","良好的防潮绝缘性能和可靠接地","外观美观"],"a":"C","e":"潮湿环境首先要求防潮绝缘和接地保护，以限制漏电电流。"},{"id":1000,"ch":5,"t":"s","q":"易燃易爆场所内的电气线路应当","o":["架空明敷、随意布置","用临时插线板连接","沿地面随意铺设","穿管敷设并采取防爆措施"],"a":"D","e":"穿管敷设可防止机械损伤和火花外泄，是防爆场所的基本要求。"},{"id":1001,"ch":5,"t":"s","q":"触电者心跳存在、呼吸停止时，应采取的措施是","o":["口对口人工呼吸","胸外心脏按压","立即喂水","等待其自行恢复呼吸"],"a":"A","e":"心跳尚存而呼吸停止时应以人工呼吸为主，帮助恢复通气。"},{"id":1002,"ch":5,"t":"s","q":"下班离开实验室时，对不使用的仪器设备应当","o":["保持待机状态","切断电源","只拔掉网线","只关闭显示屏"],"a":"B","e":"切断电源可避免无人值守时设备故障引发火灾。"},{"id":1003,"ch":5,"t":"s","q":"在有腐蚀性介质的场所，接地装置应采取的措施是","o":["加大接地电阻","取消接地装置","采取防腐处理并定期检查","改用塑料接地体"],"a":"C","e":"腐蚀会增大接地电阻甚至腐蚀断接地体，须防腐并定期检测。"},{"id":1004,"ch":5,"t":"s","q":"高压导线断落在地面时，会以落地点为中心形成跨步电压。人若停留在距落地点多远以外，通常可认为不再有跨步电压危险？","o":["20 m 以外","10 m 以外","5 m 以外","1 m 以内"],"a":"A","e":"高压导线落地后电流由落地点向四周扩散，地面各点之间形成电位差，距落地点越近跨步电压越高。通常距落地点 20 m 以外电位差已很小，可视为安全区；发现断线应远离，不得大步跑开。"},{"id":1005,"ch":5,"t":"s","q":"按我国电气线路的导线颜色标记规定，保护接地线（PE线）应采用的绝缘层颜色是（　）。","o":["淡蓝色","黄绿双色","黑色","红色"],"a":"B","e":"我国规定保护接地线（PE线）必须采用黄绿双色绝缘导线，中性线（N线）用淡蓝色，相线用黄、绿、红三色区分。施工和检修时不得把黄绿双色线挪作相线或中性线使用，否则会使外壳接地失效并造成误判。"},{"id":1006,"ch":5,"t":"m","q":"电流对人体的伤害程度与下列哪些因素有关","o":["电流大小","通电时间","电流途径","人体健康状况","天气晴雨"],"a":"ABCD","e":"电流大小、持续时间、途径和人体状况都直接影响伤害程度。"},{"id":1007,"ch":5,"t":"m","q":"按照人体触及带电体的方式，触电可分为","o":["单相触电","两相触电","跨步电压触电","接触电压触电","静电感应"],"a":"ABCD","e":"触电方式主要包括单相、两相、跨步电压和接触电压触电。"},{"id":1008,"ch":5,"t":"m","q":"下列数值中，属于我国安全电压额定值系列的有","o":["42 V","36 V","24 V","12 V","48 V"],"a":"ABCD","e":"我国安全电压额定值系列为42、36、24、12、6 V，不含48 V。"},{"id":1009,"ch":5,"t":"m","q":"关于保护接地，下列说法正确的有","o":["适用于中性点不接地的低压系统","设备金属外壳应与接地体可靠连接","接地电阻一般不大于4 Ω","可以代替漏电保护器"],"a":"ABC","e":"保护接地降低外壳对地电压，但不能代替漏电保护器。"},{"id":1010,"ch":5,"t":"m","q":"重复接地的作用包括","o":["降低零线断线时设备外壳的对地电压","提高线路的供电电压","减轻零线断线的危险","增大接地电阻"],"a":"AC","e":"重复接地可降低零线断线后的外壳电压，提高系统安全性。"},{"id":1011,"ch":5,"t":"m","q":"关于漏电保护器，下列说法正确的有","o":["可防止漏电引起的触电事故","动作电流一般不大于30 mA","动作时间一般不超过0.1 s","可替代保护接零或保护接地"],"a":"ABC","e":"漏电保护器是附加保护，不能替代保护接地或保护接零。"},{"id":1012,"ch":5,"t":"m","q":"扑救电气火灾时，正确的做法有","o":["先切断电源","使用干粉灭火器","使用二氧化碳灭火器","用水直接浇灭"],"a":"ABC","e":"断电后宜用干粉或二氧化碳灭火器，水会导电扩大事故。"},{"id":1013,"ch":5,"t":"m","q":"触电急救的正确做法有","o":["迅速切断电源","用干燥木棒挑开导线","直接用手拉拽触电者","心跳呼吸停止时立即进行心肺复苏"],"a":"ABD","e":"救护人员必须借助绝缘物脱离电源，直接拉拽会造成连锁触电。"},{"id":1014,"ch":5,"t":"m","q":"实验室常见的电气隐患有","o":["私拉乱接电线","插座超负荷使用","设备外壳带电","电线绝缘层破损","定期检测漏电保护器"],"a":"ABCD","e":"私拉乱接、超负荷、外壳带电和绝缘破损都是常见隐患。"},{"id":1015,"ch":5,"t":"m","q":"造成电气线路过载的常见原因有","o":["导线截面偏小","接入设备过多","线路长期超负荷运行","导线绝缘层受潮"],"a":"ABC","e":"导线截面偏小、设备过多和长期超负荷都会使线路过载发热。"},{"id":1016,"ch":5,"t":"m","q":"在易燃易爆场所使用电气设备，应当","o":["选用防爆型电气设备","随意增设临时插座","保持设备良好接地","在场所内使用普通插座"],"a":"AC","e":"易燃易爆场所必须选用防爆电器并做好接地，严禁临时增设普通插座。"},{"id":1017,"ch":5,"t":"m","q":"漏电保护器能够起保护作用的触电形式有（　）。","o":["人体触及一相带电体","设备绝缘损坏引起的漏电","人体同时触及两相带电体","人体触及漏电设备的外壳"],"a":"ABD","e":"漏电保护器检测剩余电流，对不流经检测回路的两相触电不起作用。"},{"id":1018,"ch":5,"t":"m","q":"电气设备安全使用的要求包括（　）。","o":["绝缘完好并定期检测","金属外壳可靠接地或接零","外壳防护等级与环境相适应","插头插座完好、接触可靠","为散热方便可拆除防护罩"],"a":"ABCD","e":"防护罩不得随意拆除，其余各项均为设备安全使用的基本要求。"},{"id":1019,"ch":5,"t":"m","q":"关于插头插座的使用，做法正确的有（　）。","o":["不用湿手插拔插头","不超负荷使用插座","插头应插紧到位","可用导线线头直接插入插座取电","破损的插座应及时更换"],"a":"ABCE","e":"导线线头直接插入插座易接触不良、触电，属违章用电。"},{"id":1020,"ch":5,"t":"m","q":"电气线路发生短路的原因可能有（　）。","o":["绝缘损坏致使导线相碰","接线错误造成相线与零线短接","过载发热烧坏绝缘后相碰","导线截面选择过大"],"a":"ABC","e":"导线截面过大不会引起短路，前三项是短路的常见原因。"},{"id":1021,"ch":5,"t":"m","q":"防止电气线路过载的措施有（　）。","o":["按负荷大小选择足够截面的导线","不用铜丝代替熔丝","把多台大功率设备接在同一插座上","定期检查线路和接头温度"],"a":"ABD","e":"多台大功率设备共用一个插座会加剧过载，应避免。"},{"id":1022,"ch":5,"t":"m","q":"电气线路日常检查的主要内容有（　）。","o":["导线绝缘有无破损、老化","接头有无发热变色","插座、开关有无烧焦痕迹","随手用湿布擦拭带电线路"],"a":"ABC","e":"湿布擦拭带电线路易导致触电，不属检查内容。"},{"id":1023,"ch":5,"t":"m","q":"实验室中禁止的用电行为有（　）。","o":["擅自改动配电线路","多个大功率设备共用一个插座","用铜丝代替保险丝","离开时切断非必要电源"],"a":"ABC","e":"离开时切断非必要电源是良好习惯，前三项均属违章行为。"},{"id":1024,"ch":5,"t":"m","q":"在潮湿、腐蚀等特殊场所用电，应注意（　）。","o":["选用防护等级相适应的电气设备","行灯采用安全电压","加强绝缘并做好接地","普通设备可直接安装使用"],"a":"ABC","e":"特殊场所必须选用防护等级相符的设备，不能使用普通设备。"},{"id":1025,"ch":5,"t":"m","q":"在易燃易爆场所使用电气设备，正确的有（　）。","o":["选用防爆型电气设备","线路连接可靠，避免产生电火花","临时使用普通插座供电","设备外壳可靠接地"],"a":"ABD","e":"易燃易爆场所严禁使用非防爆的普通插座和电器。"},{"id":1026,"ch":5,"t":"m","q":"关于外壳防护等级IP代码，说法正确的有（　）。","o":["第一位数字表示防固体异物进入的能力","第二位数字表示防水能力","数字越大防护能力越强","IP00表示防护能力最强"],"a":"ABC","e":"IP00表示无防护，数字越大防护能力越强。"},{"id":1027,"ch":5,"t":"m","q":"潮湿场所用电应采取的安全措施包括","o":["采用防水防溅型插座","设备金属外壳可靠接地","用湿手操作电源开关","定期检查线路绝缘状况"],"a":"ABD","e":"湿手操作开关会显著增加触电风险，其余三项均为防潮措施。"},{"id":1028,"ch":5,"t":"m","q":"易燃易爆场所的用电要求包括","o":["选用防爆型电气设备","电气线路穿管敷设","临时使用普通插线板供电","禁止带电作业和使用非防爆工具"],"a":"ABD","e":"普通插线板不具防爆性能，在爆炸性环境中严禁使用。"},{"id":1029,"ch":5,"t":"m","q":"下列属于实验室常见电气隐患的有","o":["私拉乱接临时电线","多台大功率设备共用一个插座","导线绝缘破损后继续使用","安装合格的漏电保护器","电源线拖地并受踩踏"],"a":"ABCE","e":"合格漏电保护器是安全措施，其余各项均属常见隐患。"},{"id":1030,"ch":5,"t":"m","q":"触电急救的正确做法包括","o":["立即切断电源","用干燥木棒等绝缘物使触电者脱离带电体","直接用手拉拽触电者","心跳呼吸停止时立即实施心肺复苏"],"a":"ABD","e":"直接用手拉拽会使救护者一同触电，必须使用绝缘物。"},{"id":1031,"ch":5,"t":"m","q":"电气火灾的处置方法正确的有","o":["先切断电源","用干粉灭火器扑救","用水直接扑救带电设备","用二氧化碳灭火器扑救精密仪器"],"a":"ABD","e":"水导电，带电扑救会造成触电并扩大事故。"},{"id":1032,"ch":5,"t":"m","q":"触电者脱离电源后，正确的处理包括","o":["神志清醒者就地平卧休息、注意观察","立即给触电者喂水","呼吸心跳停止者立即进行心肺复苏","及时拨打急救电话"],"a":"ACD","e":"触电后意识不清或可能呕吐，喂水易造成误吸，应禁止。"},{"id":1033,"ch":5,"t":"m","q":"潮湿、腐蚀环境对电气设备的主要影响有","o":["降低绝缘性能","加速金属部件腐蚀","提高设备绝缘水平","增加漏电和短路风险"],"a":"ABD","e":"潮湿与腐蚀均使绝缘劣化、金属锈蚀，从而提高漏电风险。"},{"id":1034,"ch":5,"t":"m","q":"高温环境用电应注意的事项有","o":["将电源线搭在电炉外壳上","导线远离热源","选用耐热绝缘导线","防止绝缘受热老化"],"a":"BCD","e":"把电源线搭在电炉外壳上会因受热而迅速损坏绝缘。"},{"id":1035,"ch":5,"t":"m","q":"关于防爆电器的使用，下列说法正确的有","o":["易燃易爆场所应选用防爆型电器","防爆外壳可以随意拆开检修","防爆电器应定期检查维护","防爆场所禁止使用明火和非防爆工具"],"a":"ACD","e":"防爆外壳一旦破坏即失去防爆能力，不得随意拆开。"},{"id":1036,"ch":5,"t":"m","q":"预防实验室电气火灾的措施包括","o":["不超负荷用电","用铜丝代替熔断丝","及时更换老化线路","离开实验室时切断不必要的电源"],"a":"ACD","e":"铜丝不能按额定电流熔断，会失去过载保护作用。"},{"id":1037,"ch":5,"t":"m","q":"对实验室已发现的电气隐患进行整改，正确的做法有","o":["绝缘破损的导线立即停用更换","插座长期过载时增设专用供电回路","让未经培训的学生自行改装配电箱","请持证电工检修配电线路"],"a":"ABD","e":"配电设施改造必须由持证电工完成，学生不得擅自拆改。"},{"id":1038,"ch":5,"t":"m","q":"电气设备或线路发生火灾时，下列处置措施中正确的是（ ）","o":["先切断电源，再组织扑救","用二氧化碳灭火器扑救","用泡沫灭火器扑救","用干粉灭火器扑救","用水直接浇灭"],"a":"ABD","e":"电气火灾应先切断电源；二氧化碳和干粉灭火剂不导电，可用于带电扑救。泡沫灭火剂和水都导电，带电扑救会造成触电，且水还会损坏设备，故不能使用。"},{"id":1039,"ch":5,"t":"m","q":"使用马弗炉时，下列做法正确的是（ ）","o":["使用前检查炉膛内是否有杂物","用长柄坩埚钳取放坩埚","炉温很高时直接用手取出炉内物品","不得将潮湿或含易燃物的样品放入炉内","使用完毕切断电源并待炉温下降后再清理"],"a":"ABDE","e":"马弗炉炉膛温度很高，使用前应检查炉膛，取放物品必须用长柄坩埚钳，严禁用手直接取放；潮湿样品入炉会爆裂飞溅，含易燃物样品可能燃烧爆炸；使用后应断电并待炉温下降后再清理。"},{"id":1040,"ch":5,"t":"m","q":"为防止静电危害，可采取的措施有（ ）","o":["设备接地","增加环境湿度","加入抗静电添加剂","操作人员穿化纤工作服","控制易燃液体流速"],"a":"ABCE","e":"防静电的常用措施包括接地导走电荷、增湿提高表面导电性、加入抗静电添加剂、限制易燃液体流速以减少电荷产生等。化纤衣物容易摩擦起电且不易导走电荷，应穿防静电工作服，故 D 错误。"},{"id":1041,"ch":5,"t":"j","q":"电流通过人体的时间越长，对人体的伤害越严重。","o":["对","错"],"a":"对","e":"通电时间延长会增加热效应和电化学损伤，降低人体耐受能力。"},{"id":1042,"ch":5,"t":"j","q":"两相触电时人体承受的是相电压。","o":["对","错"],"a":"错","e":"两相触电时人体承受的是线电压，比相电压更危险。"},{"id":1043,"ch":5,"t":"j","q":"跨步电压触电多发生在高压导线断落地面时。","o":["对","错"],"a":"对","e":"导线落地后电流扩散形成电位差，行人两脚间产生跨步电压。"},{"id":1044,"ch":5,"t":"j","q":"我国安全电压额定值系列包括42 V、36 V、24 V、12 V和6 V。","o":["对","错"],"a":"对","e":"这是我国安全电压的五个额定值等级。"},{"id":1045,"ch":5,"t":"j","q":"保护接地适用于中性点直接接地的三相四线制系统。","o":["对","错"],"a":"错","e":"中性点直接接地的系统应采用保护接零，保护接地适用于中性点不接地系统。"},{"id":1046,"ch":5,"t":"j","q":"重复接地的接地电阻一般不应大于10 Ω。","o":["对","错"],"a":"对","e":"重复接地电阻一般要求不大于10 Ω。"},{"id":1047,"ch":5,"t":"j","q":"漏电保护器动作后，可以强行反复合闸继续使用。","o":["对","错"],"a":"错","e":"应查明漏电原因并排除故障后方可送电，强行合闸会扩大事故。"},{"id":1048,"ch":5,"t":"j","q":"发现有人触电，应立即用手把触电者拉开。","o":["对","错"],"a":"错","e":"直接用手拉拽会使救护人员触电，应先切断电源或用绝缘物使其脱离。"},{"id":1049,"ch":5,"t":"j","q":"电气火灾在切断电源后，可用干粉或二氧化碳灭火器扑救。","o":["对","错"],"a":"对","e":"干粉和二氧化碳不导电，适用于电气火灾。"},{"id":1050,"ch":5,"t":"j","q":"在特别潮湿场所，行灯电压不应超过36 V。","o":["对","错"],"a":"错","e":"特别潮湿或金属容器内行灯电压不应超过12 V。"},{"id":1051,"ch":5,"t":"j","q":"保护接零系统中，零线上可以装设熔断器。","o":["对","错"],"a":"错","e":"零线装设熔断器后一旦断开，设备外壳会带电，十分危险。"},{"id":1052,"ch":5,"t":"j","q":"设备金属外壳可靠接地或接零，是防止触电的重要措施。","o":["对","错"],"a":"对","e":"外壳接地或接零可降低故障时外壳对地电压。"},{"id":1053,"ch":5,"t":"j","q":"用湿手插拔电源插头容易发生触电事故。","o":["对","错"],"a":"对","e":"湿手使人体电阻降低，接触带电部位时电流增大。"},{"id":1054,"ch":5,"t":"j","q":"导线绝缘老化只会影响美观，不会带来安全隐患。","o":["对","错"],"a":"错","e":"绝缘老化易造成漏电、短路和火灾，必须及时更换。"},{"id":1055,"ch":5,"t":"j","q":"心跳呼吸停止的触电者，应立即进行心肺复苏并坚持抢救。","o":["对","错"],"a":"对","e":"及时、持续的心肺复苏是挽救触电者的关键措施。"},{"id":1056,"ch":5,"t":"j","q":"保护接地的接地电阻一般不应大于4Ω。","o":["对","错"],"a":"对","e":"保护接地电阻通常要求不大于4Ω。"},{"id":1057,"ch":5,"t":"j","q":"重复接地可以降低零线断线后设备外壳的对地电压。","o":["对","错"],"a":"对","e":"重复接地减小零线断线时的中性点偏移，从而降低外壳电压。"},{"id":1058,"ch":5,"t":"j","q":"漏电保护器动作后，可直接重新合闸继续使用，不必查找动作原因。","o":["对","错"],"a":"错","e":"动作说明存在漏电或触电，应先查明原因、排除故障后再送电。"},{"id":1059,"ch":5,"t":"j","q":"在保证正常泄漏电流不引起误动作的前提下，漏电保护器的动作电流越小，对人身保护越灵敏。","o":["对","错"],"a":"对","e":"动作电流越小，越小的剩余电流即可触发断电，保护更灵敏。"},{"id":1060,"ch":5,"t":"j","q":"保护接地与保护接零可以在同一供电系统中混合使用。","o":["对","错"],"a":"错","e":"混用会使部分设备外壳带危险电压，规范禁止混用。"},{"id":1061,"ch":5,"t":"j","q":"IP防护等级的数字越大，其防护能力越强。","o":["对","错"],"a":"对","e":"IP代码数字递增表示防护等级提高。"},{"id":1062,"ch":5,"t":"j","q":"三孔插座中的保护接地孔可以空着不接线。","o":["对","错"],"a":"错","e":"接地孔不接线则设备外壳失去保护，漏电时会带电。"},{"id":1063,"ch":5,"t":"j","q":"熔断器的熔丝烧断后，可以用铜丝临时代替使用。","o":["对","错"],"a":"错","e":"铜丝熔点高、不易熔断，会失去过载和短路保护作用。"},{"id":1064,"ch":5,"t":"j","q":"电气线路短路时电流急剧增大，容易引起绝缘燃烧和火灾。","o":["对","错"],"a":"对","e":"短路电流产生大量热量，是电气火灾的常见起因。"},{"id":1065,"ch":5,"t":"j","q":"导线绝缘老化只与使用时间有关，与环境和负荷无关。","o":["对","错"],"a":"错","e":"过热、潮湿、腐蚀和机械损伤都会加速绝缘老化。"},{"id":1066,"ch":5,"t":"j","q":"为了取电方便，可以在实验室私拉乱接临时电线。","o":["对","错"],"a":"错","e":"私拉乱接缺乏规范连接和保护，极易引发触电和火灾。"},{"id":1067,"ch":5,"t":"j","q":"发生电气火灾时，应先切断电源再组织灭火。","o":["对","错"],"a":"对","e":"先断电可防止灭火人员触电并提高灭火效果。"},{"id":1068,"ch":5,"t":"j","q":"触电急救时，救护人员可以直接用手拉拽触电者使其脱离电源。","o":["对","错"],"a":"错","e":"直接拉拽会使救护人员一同触电，应使用绝缘物。"},{"id":1069,"ch":5,"t":"j","q":"潮湿场所应选用防护等级较高的电气设备。","o":["对","错"],"a":"对","e":"提高防水防潮等级可减小绝缘下降和漏电风险。"},{"id":1070,"ch":5,"t":"j","q":"一机一闸是指每台电气设备都应由专用的开关控制。","o":["对","错"],"a":"对","e":"一机一闸便于单台设备停送电和故障隔离。"},{"id":1071,"ch":5,"t":"j","q":"在特别潮湿的场所，应使用安全电压或采取可靠的防潮措施。","o":["对","错"],"a":"对","e":"潮湿使人体电阻下降，降低电压和加强防潮是基本要求。"},{"id":1072,"ch":5,"t":"j","q":"在易燃易爆场所，只要安装了漏电保护器，就可以使用普通非防爆电器。","o":["对","错"],"a":"错","e":"漏电保护器不能防止电火花，防爆场所必须使用防爆电器。"},{"id":1073,"ch":5,"t":"j","q":"发现有人触电时，应立即用手将其拉离带电体。","o":["对","错"],"a":"错","e":"徒手拉拽会使救护者触电，应先断电或用绝缘物操作。"},{"id":1074,"ch":5,"t":"j","q":"扑救电气火灾时，应先切断电源，再使用干粉或二氧化碳灭火器。","o":["对","错"],"a":"对","e":"先断电可避免触电，干粉和二氧化碳均不导电。"},{"id":1075,"ch":5,"t":"j","q":"带电的电气设备着火时，可以用水直接扑救。","o":["对","错"],"a":"错","e":"水导电，带电用水扑救极易造成触电事故。"},{"id":1076,"ch":5,"t":"j","q":"触电者心跳、呼吸停止时，应立即就地进行心肺复苏。","o":["对","错"],"a":"对","e":"就地抢救能争取时间，等待送医会错过最佳抢救时机。"},{"id":1077,"ch":5,"t":"j","q":"用湿抹布擦拭通电的电气设备外壳是安全的。","o":["对","错"],"a":"错","e":"湿抹布导电且水分可能渗入设备，易造成触电和短路。"},{"id":1078,"ch":5,"t":"j","q":"高温环境会加速电气线路绝缘材料的老化。","o":["对","错"],"a":"对","e":"绝缘材料长期受热会变脆、开裂，失去绝缘能力。"},{"id":1079,"ch":5,"t":"j","q":"实验室的电源线可以随意拖在地面上，只要不绊倒人就没有危险。","o":["对","错"],"a":"错","e":"拖地电线易被踩踏碾压而破损，导致漏电和触电。"},{"id":1080,"ch":5,"t":"j","q":"使触电者脱离电源时，应使用干燥的木棒等绝缘物，而不能直接用手拉拽。","o":["对","错"],"a":"对","e":"绝缘物可隔断电流通路，保护救护者免于触电。"},{"id":1081,"ch":5,"t":"j","q":"在腐蚀性气体环境中，电气设备应选用防腐型并定期检查。","o":["对","错"],"a":"对","e":"腐蚀会破坏绝缘和金属构件，防腐选型与检查缺一不可。"},{"id":1082,"ch":5,"t":"j","q":"防爆电器的外壳可以随意拆开，不会影响其防爆性能。","o":["对","错"],"a":"错","e":"外壳是防爆结构的一部分，擅自拆开会丧失防爆能力。"},{"id":1083,"ch":5,"t":"j","q":"电气火灾扑灭后，应确认电源已切断、设备冷却后再进行检查处理。","o":["对","错"],"a":"对","e":"余热和残余电荷仍可能造成复燃或触电，须确认后处理。"},{"id":1084,"ch":5,"t":"j","q":"一个插座上同时接入多台大功率仪器，容易造成线路过载。","o":["对","错"],"a":"对","e":"总电流超过线路和插座额定值即形成过载，发热后可能起火。"},{"id":1085,"ch":5,"t":"j","q":"触电者脱离电源后神志清醒，就可以让其立即走动回家。","o":["对","错"],"a":"错","e":"触电后可能发生迟发性心律失常，应静卧观察并送医。"},{"id":1086,"ch":5,"t":"b","q":"工频电流刚能引起人体感觉的电流称为感知电流，约为____mA。","a":["1"]},{"id":1087,"ch":5,"t":"b","q":"人体触及一根相线所造成的触电称为____触电。","a":["单相"]},{"id":1088,"ch":5,"t":"b","q":"保护接地的接地电阻一般不应大于____Ω。","a":["4"]},{"id":1089,"ch":5,"t":"b","q":"一般场所漏电保护器的额定漏电动作电流多为____mA。","a":["30"]},{"id":1090,"ch":5,"t":"b","q":"用于人身保护的漏电保护器，其动作时间一般不应超过____s。","a":["0.1"]},{"id":1091,"ch":5,"t":"b","q":"我国安全电压额定值系列为42 V、36 V、24 V、12 V和____V。","a":["6"]},{"id":1092,"ch":5,"t":"b","q":"发生电气火灾时，应首先____，然后再组织灭火。","a":["切断电源"]},{"id":1093,"ch":5,"t":"b","q":"触电急救时，严禁救护人员直接用手____触电者。","a":["拉拽","拖拉"]},{"id":1094,"ch":5,"t":"b","q":"保护接零系统中重复接地的接地电阻一般不应大于____Ω。","a":["10"],"e":"重复接地电阻一般不大于10Ω。"},{"id":1095,"ch":5,"t":"b","q":"用于人身触电保护的漏电保护器，额定动作电流一般不大于____mA。","a":["30"],"e":"人身保护取30mA及以下。"},{"id":1096,"ch":5,"t":"b","q":"漏电保护器的动作时间一般不应超过____s。","a":["0.1"],"e":"快速动作，通常不超过0.1s。"},{"id":1097,"ch":5,"t":"b","q":"测量电气设备绝缘电阻应使用____。","a":["兆欧表"],"e":"绝缘电阻值大，用兆欧表测量。"},{"id":1098,"ch":5,"t":"b","q":"IP防护等级中，第一位数字表示____能力，第二位数字表示____能力。","a":["防固体异物","防水"],"e":"IP代码第一位防固体异物，第二位防水。"},{"id":1099,"ch":5,"t":"b","q":"电气线路长期过载会使导线____升高，加速绝缘老化。","a":["温度"],"e":"过载发热导致温升超标，绝缘加速老化。"},{"id":1100,"ch":5,"t":"b","q":"发生电气火灾时，应首先____，然后再选用合适的灭火器材。","a":["切断电源"],"e":"先断电是电气火灾处置的首要步骤。"},{"id":1101,"ch":5,"t":"b","q":"在特别潮湿场所或金属容器内使用行灯，其电压不应超过____V。","a":["12"],"e":"特别潮湿或金属容器内行灯电压不超过12V。"},{"id":1102,"ch":5,"t":"b","q":"发现有人触电，救护人员应先迅速____，再设法使触电者脱离电源。","a":["切断电源"]},{"id":1103,"ch":5,"t":"b","q":"扑救带电电气火灾时，应使用____灭火器或二氧化碳灭火器，严禁用水扑救。","a":["干粉"]},{"id":1104,"ch":5,"t":"b","q":"在易燃易爆场所，应选用具有____性能的电气设备。","a":["防爆"]},{"id":1105,"ch":5,"t":"b","q":"成人心肺复苏时，胸外按压与人工呼吸的比例为____。","a":["30:2"]},{"id":1106,"ch":5,"t":"b","q":"潮湿场所应选用____型插座，并做好可靠接地。","a":["防水防溅"]},{"id":1107,"ch":5,"t":"b","q":"触电者脱离电源后，如心跳、呼吸停止，应立即进行____，并同时拨打____急救电话。","a":["心肺复苏","120"]},{"id":1108,"ch":5,"t":"b","q":"电气线路长期过载会加速____老化，甚至引起短路和火灾。","a":["绝缘"]},{"id":1109,"ch":5,"t":"b","q":"在有腐蚀性介质的场所，接地装置应采取____措施并定期检查。","a":["防腐"]},{"id":1110,"ch":5,"t":"b","q":"长期处于高温环境的电气设备，应选用____绝缘导线并远离热源。","a":["耐热"]},{"id":1111,"ch":5,"t":"b","q":"一般场所使用的行灯电压不得超过____V；在特别潮湿场所或金属容器内作业时，行灯电压不得超过____V。","a":["36","12"],"e":"行灯采用安全电压供电，一般场所不超过 36 V；特别潮湿场所、金属容器内等触电危险性大的环境，人体电阻显著降低，行灯电压不得超过 12 V。"},{"id":1112,"ch":5,"t":"b","q":"保护接地的作用是把设备外壳的对地电压限制在安全范围内，一般要求保护接地电阻不大于____Ω；而防静电接地电阻一般要求不大于____Ω。","a":["4","100"],"e":"保护接地电阻一般要求不大于 4 Ω，以保证故障时外壳对地电压足够低；防静电接地电阻一般要求不大于 100 Ω，用于把静电荷及时导入大地。"},{"id":1113,"ch":5,"t":"b","q":"工频电流通过人体时，一般人能自主摆脱的电流约为____mA；足以引起心室颤动、危及生命的电流约为____mA。","a":["10","50"],"e":"工频电流通过人体时，感知电流约为 1 mA，摆脱电流约为 10 mA，超过后肌肉痉挛、无法自主摆脱；50 mA 左右即可引起心室颤动，是危及生命的致命电流。"},{"id":1114,"ch":5,"t":"b","q":"对触电后呼吸心跳停止的成人实施心肺复苏时，胸外按压频率应为每分钟____次，按压深度应为____cm。","a":["100~120","5~6"],"e":"成人心肺复苏时胸外按压频率为 100~120 次/min，按压深度为 5~6 cm，按压与人工呼吸比例为 30∶2；按压应快速有力、每次按压后让胸廓充分回弹。"},{"id":1115,"ch":5,"t":"x","q":"简述触电急救的基本步骤。","a":"1.迅速切断电源，或使用干燥木棒、绝缘钳等绝缘物使触电者脱离带电体，严禁救护人员直接用手拉拽触电者；2.脱离电源后立即判断触电者的意识、呼吸和心跳，同时呼救并拨打急救电话；3.心跳呼吸停止者应立即进行心肺复苏，包括胸外按压和人工呼吸，并坚持抢救直到专业医护人员到达；4.对电灼伤等外伤作简单包扎处理后，尽快送医院救治。"},{"id":1116,"ch":5,"t":"x","q":"某实验室插座超负荷使用，导线发热冒烟并引燃附近纸张。请说明正确的处置方法及理由。","a":"1.立即切断电源，如拉下总闸或拔掉插头，未切断电源前不得用水扑救；2.断电后使用干粉或二氧化碳灭火器扑救，严禁使用水和泡沫灭火器，因为水导电，会造成触电并使火势扩大；3.火势较大或无法控制时，应迅速撤离并拨打火警电话，同时报告实验室负责人；4.灭火后检查线路和设备，查明过载原因，更换老化导线、合理分配用电负荷，消除隐患后方可恢复用电。"},{"id":1117,"ch":5,"t":"x","q":"简述漏电保护器的作用及其主要技术参数要求。","a":"1.作用：当线路或设备发生漏电、人身触电时迅速切断电源，防止触电伤亡和电气火灾。2.额定动作电流：用于人身保护时一般不大于30mA。3.动作时间：一般不超过0.1s，以保证快速断电。4.使用要求：应装设在被保护线路的电源侧，保护范围内的工作零线不得重复接地，并定期试跳检查；动作后应查明原因、排除故障再合闸送电。"},{"id":1118,"ch":5,"t":"x","q":"某实验室用一只接线板从走廊插座引出电源，同时接入烘箱、离心机等多台大功率仪器，使用中导线发热、绝缘出现焦糊味。请分析存在的隐患并提出正确做法。","a":"1.存在隐患：多台大功率仪器共用一个插座和接线板，线路严重过载，导线发热使绝缘老化甚至短路起火；私拉乱接的接线板接头接触不良，易产生电火花；线路无独立开关控制，故障时不能迅速断电。2.正确做法：按设备总功率配置足够截面的专用线路，做到一机一闸、一漏一箱；不私拉乱接，不使用劣质接线板；发现导线发热、绝缘焦糊应立即停用并更换；设备外壳可靠接地，加装漏电保护器并定期检查。"},{"id":1119,"ch":5,"t":"x","q":"简述实验室用电环境安全在潮湿、腐蚀、高温和易燃易爆四类场所的主要要求。","a":"1.潮湿场所：采用安全电压供电，选用防水防溅型插座和防潮型设备，金属外壳可靠接地，保持环境干燥通风。2.腐蚀性场所：选用防腐型电气设备和导线，线路穿管暗敷，接地装置做防腐处理并定期检查。3.高温场所：导线远离热源，选用耐热绝缘导线，加强通风散热，防止绝缘受热老化。4.易燃易爆场所：选用防爆电器并保持防爆外壳完整，线路穿管敷设，禁止明火、非防爆工具和带电作业。5.各类场所均应定期检查维护，发现隐患及时整改。"},{"id":1120,"ch":5,"t":"x","q":"某实验室一名学生发现同学触电倒地，情急之下直接用手去拉，结果两人均触电。请指出其错误，并说明正确的急救步骤。","a":"错误：救护人员徒手拉拽触电者，自身未采取绝缘措施，使电流经其身体形成回路而一同触电。正确步骤：1.立即切断电源，如拉闸、拔插头；无法断电时，用干燥木棒等绝缘物挑开带电体，严禁直接用手接触。2.将触电者移至通风安全处，检查意识、呼吸和心跳。3.呼吸心跳停止者立即就地进行心肺复苏，按压与通气按30:2进行，持续至专业救援到达。4.同时拨打120急救电话并报告实验室负责人。5.神志清醒者也要就地平卧休息、注意观察并及时送医。6.事后保护现场，排查并消除电气隐患。"},{"id":1121,"ch":6,"t":"s","q":"按我国特种设备安全监察的有关规定，压力容器最高工作压力（表压）的下限值为（ ）。","o":["0.05 MPa","0.1 MPa","0.5 MPa","1.0 MPa"],"a":"B","e":"最高工作压力大于或等于0.1 MPa（表压）是判定压力容器的压力下限。"},{"id":1122,"ch":6,"t":"s","q":"下列压力容器中，属于高压容器的是（ ）。","o":["设计压力 0.5 MPa","设计压力 1.6 MPa","设计压力 12 MPa","设计压力 120 MPa"],"a":"C","e":"高压容器的压力范围为10 MPa≤p<100 MPa，12 MPa在此范围内。"},{"id":1123,"ch":6,"t":"s","q":"按用途分类，用于完成介质间热量交换的压力容器是（ ）。","o":["反应压力容器","换热压力容器","分离压力容器","储存压力容器"],"a":"B","e":"换热压力容器主要用于完成介质的热量交换。"},{"id":1124,"ch":6,"t":"s","q":"关于爆破片装置，下列说法正确的是（ ）。","o":["爆破后能自动复位","可反复多次使用","爆破后必须更换","只能与安全阀并联安装"],"a":"C","e":"爆破片靠膜片破裂泄压，属一次性泄压装置，动作后必须更换。"},{"id":1125,"ch":6,"t":"s","q":"压力表表盘刻度极限值一般应选用容器最高工作压力的（ ）。","o":["1.0~1.5倍","1.5~3倍","3~5倍","5~10倍"],"a":"B","e":"压力表刻度极限值通常取最高工作压力的1.5~3倍，以保证指示清晰又不超量程。"},{"id":1126,"ch":6,"t":"s","q":"蒸汽管道上的压力表前应装设（ ）。","o":["存水弯管","止回阀","过滤器","疏水阀"],"a":"A","e":"存水弯管内积水可隔离高温蒸汽，防止压力表受热损坏。"},{"id":1127,"ch":6,"t":"s","q":"安全阀的主要作用是（ ）。","o":["超压时自动开启排气，压力降低后自动关闭","显示容器内的压力","测量容器内介质的温度","防止介质倒流"],"a":"A","e":"安全阀是自动泄压装置，超压开启、降压回座，可重复使用。"},{"id":1128,"ch":6,"t":"s","q":"液位计的主要功能是（ ）。","o":["显示容器内液面位置","测量容器内压力","调节介质流量","降低介质温度"],"a":"A","e":"液位计用于监视液面高度，防止容器超装或抽空。"},{"id":1129,"ch":6,"t":"s","q":"温度计在压力容器上的主要作用是（ ）。","o":["显示液面高度","测量容器内压力","测量和控制介质温度","降低介质温度"],"a":"C","e":"温度计用于测量和控制容器内介质温度，保证工艺与安全。"},{"id":1130,"ch":6,"t":"s","q":"减压阀在气瓶供气系统中的作用是（ ）。","o":["显示瓶内压力","过滤气体杂质","防止气体倒流","将高压气体降至稳定的低压"],"a":"D","e":"减压阀把瓶内高压气体减压并稳定在所需的工作压力。"},{"id":1131,"ch":6,"t":"s","q":"氧气瓶及其减压阀、管路严禁接触（ ）。","o":["油脂","氮气","干燥空气","蒸馏水"],"a":"A","e":"油脂在纯氧中极易燃烧，氧气系统接触油脂会引发着火事故。"},{"id":1132,"ch":6,"t":"s","q":"使用乙炔瓶时，正确的放置方式是（ ）。","o":["卧放使用","倒立使用","直立使用并固定","倾斜45度使用"],"a":"C","e":"乙炔瓶必须直立使用并可靠固定，卧放会使丙酮流出、增加危险。"},{"id":1133,"ch":6,"t":"s","q":"氧气瓶瓶体的颜色是（ ）。","o":["白色","淡蓝色","黑色","淡绿色"],"a":"B","e":"按气瓶颜色标记规定，氧气瓶为淡蓝色瓶体、黑色字样。"},{"id":1134,"ch":6,"t":"s","q":"乙炔瓶瓶体的颜色是（ ）。","o":["淡绿色","淡蓝色","白色","黑色"],"a":"C","e":"乙炔瓶为白色瓶体、红色字样。"},{"id":1135,"ch":6,"t":"s","q":"氧气瓶上的字样颜色是（ ）。","o":["红色","黑色","白色","黄色"],"a":"B","e":"氧气瓶为淡蓝色瓶体，瓶体上标注黑色“氧”字。"},{"id":1136,"ch":6,"t":"s","q":"气瓶瓶帽的主要作用是（ ）。","o":["防止瓶体腐蚀","便于搬运","标示气体种类","保护瓶阀免受损伤"],"a":"D","e":"瓶帽罩在瓶阀外部，防止搬运、储存时碰坏瓶阀。"},{"id":1137,"ch":6,"t":"s","q":"气瓶防震圈的作用是（ ）。","o":["减轻搬运碰撞对瓶体的损伤","防止气体泄漏","固定瓶阀","标示气体种类"],"a":"A","e":"防震圈套装在瓶体外部，缓冲碰撞、保护瓶体。"},{"id":1138,"ch":6,"t":"s","q":"压力容器的外部检查一般应（ ）。","o":["每三年至少一次","每两年至少一次","每半年至少一次","每年至少一次"],"a":"D","e":"外部检查主要检查外观、附件和运行状况，一般每年至少进行一次。"},{"id":1139,"ch":6,"t":"s","q":"压力容器使用单位办理使用登记的时限是投入使用前或者投入使用后（ ）。","o":["10日内","30日内","60日内","90日内"],"a":"B","e":"按规定应在投入使用前或者投入使用后30日内办理使用登记。"},{"id":1140,"ch":6,"t":"s","q":"安全阀一般应（ ）至少校验一次。","o":["每三年","每两年","每半年","每年"],"a":"D","e":"安全阀应定期校验，一般每年至少校验一次，确保动作可靠。"},{"id":1141,"ch":6,"t":"s","q":"按压力等级分类，低压容器的压力范围是（ ）。","o":["0.1 MPa≤p<1.6 MPa","1.6 MPa≤p<10 MPa","10 MPa≤p<100 MPa","p≥100 MPa"],"a":"A","e":"低压容器的压力范围为0.1 MPa≤p<1.6 MPa。"},{"id":1142,"ch":6,"t":"s","q":"超高压容器的压力范围是（ ）。","o":["0.1 MPa≤p<1.6 MPa","1.6 MPa≤p<10 MPa","p≥100 MPa","10 MPa≤p<100 MPa"],"a":"C","e":"超高压容器的压力范围为p≥100 MPa。"},{"id":1143,"ch":6,"t":"s","q":"储存压力容器主要用于（ ）。","o":["完成介质化学反应","储存或盛装气体、液体等介质","完成介质热量交换","分离介质组分"],"a":"B","e":"储存压力容器用于盛装气体、液体等介质，不进行化学反应。"},{"id":1144,"ch":6,"t":"s","q":"介质容易结晶、聚合或含有颗粒，安全阀容易失灵时，宜选用（ ）。","o":["安全阀","压力表","液位计","爆破片"],"a":"D","e":"爆破片通道简单、不易堵塞，适用于安全阀难以可靠工作的场合。"},{"id":1145,"ch":6,"t":"s","q":"检查压力表时，若指针在无压状态下不能回到零位，说明（ ）。","o":["压力表已失准，应停止使用","压力表精度过高","容器内仍有压力","压力表量程过大"],"a":"A","e":"指针不回零表明弹簧管等部件已失效，压力表必须更换或校验。"},{"id":1146,"ch":6,"t":"s","q":"液位计出现假液位时，正确的处理是（ ）。","o":["继续使用并加强观察","关闭液位计即可","及时清洗、检修或更换","提高容器压力"],"a":"C","e":"假液位会误导操作，必须清洗、检修或更换液位计后再使用。"},{"id":1147,"ch":6,"t":"s","q":"气瓶瓶体上喷涂的颜色和字样主要用于（ ）。","o":["美观装饰","识别瓶内气体种类","表示气瓶容积","表示气瓶生产日期"],"a":"B","e":"颜色和字样是气瓶的识别标记，用于快速判断瓶内气体种类。"},{"id":1148,"ch":6,"t":"s","q":"安装减压阀前，正确的做法是","o":["用油脂润滑接口螺纹","将调节螺杆旋到最大","检查接口清洁并确认减压阀关闭","用明火检查接口密封"],"a":"C","e":"安装前应检查接口清洁、无油脂，并确认减压阀处于关闭状态。"},{"id":1149,"ch":6,"t":"s","q":"氧气瓶减压阀严禁接触油脂，主要是因为","o":["油脂会腐蚀阀体","油脂会堵塞气路","油脂会使压力表失准","油脂遇高压氧易燃烧爆炸"],"a":"D","e":"油脂在高压氧环境中会剧烈氧化，可能引发燃烧甚至爆炸。"},{"id":1150,"ch":6,"t":"s","q":"关于减压阀的使用，说法正确的是","o":["每种气体应使用专用减压阀","氧气和乙炔可共用同一减压阀","减压阀可随意互换使用","减压阀不需要定期检查"],"a":"A","e":"不同气体的性质不同，减压阀应专用，不能随意互换。"},{"id":1151,"ch":6,"t":"s","q":"开启钢瓶阀门时，正确的操作是","o":["迅速全开","反复快速开关","缓慢开启","先开减压阀再开瓶阀"],"a":"C","e":"缓慢开启瓶阀可避免高压气流冲击和产生静电，保护减压阀。"},{"id":1152,"ch":6,"t":"s","q":"钢瓶使用过程中，操作人员","o":["可以短时间离开","不得离开现场","可委托他人代管","关小流量后即可离开"],"a":"B","e":"钢瓶使用期间操作人员不得离岗，以便及时发现和处理异常。"},{"id":1153,"ch":6,"t":"s","q":"乙炔瓶上必须安装的防止回火装置是","o":["安全阀","爆破片","液位计","回火防止器"],"a":"D","e":"回火防止器能阻止火焰沿管路回窜入乙炔瓶内。"},{"id":1154,"ch":6,"t":"s","q":"检查钢瓶阀门或管路是否漏气，应采用的方法是","o":["肥皂水检漏","明火试漏","闻气味判断","用手触摸接口"],"a":"A","e":"用肥皂水涂抹接口，观察是否产生气泡，是安全可靠的检漏方法。"},{"id":1155,"ch":6,"t":"s","q":"搬运钢瓶时，必须佩戴的附件是","o":["减压阀","压力表","瓶帽和防震圈","回火防止器"],"a":"C","e":"瓶帽保护瓶阀，防震圈减轻碰撞，二者是搬运钢瓶的基本附件。"},{"id":1156,"ch":6,"t":"s","q":"钢瓶搬运过程中，下列做法禁止的是","o":["轻装轻卸","抛掷或滚动钢瓶","用专用小车搬运","两人配合抬运"],"a":"B","e":"抛掷、滚动钢瓶容易损坏瓶阀和瓶体，严禁采用。"},{"id":1157,"ch":6,"t":"s","q":"钢瓶在库房内储存时，应","o":["卧放并堆叠","倒立存放","随意靠墙放置","直立存放并固定"],"a":"D","e":"钢瓶应直立存放并采取固定措施，防止倾倒造成事故。"},{"id":1158,"ch":6,"t":"s","q":"空钢瓶与实钢瓶应","o":["分开存放","混合存放","将实瓶放在通道上","将空瓶露天堆放"],"a":"A","e":"空瓶与实瓶应分区存放并设置明显标识，防止误用。"},{"id":1159,"ch":6,"t":"s","q":"可燃气体钢瓶与助燃气体钢瓶应","o":["同室混放","紧靠在一起","分室存放","放在同一气瓶柜内"],"a":"C","e":"可燃气体与助燃气体混放会增大火灾爆炸风险，应分开存放。"},{"id":1160,"ch":6,"t":"s","q":"钢瓶储存场所应保持","o":["密闭","通风良好","潮湿","高温"],"a":"B","e":"良好通风可防止泄漏气体聚集，降低火灾和中毒风险。"},{"id":1161,"ch":6,"t":"s","q":"钢瓶与明火的距离一般不应小于","o":["2 m","5 m","8 m","10 m"],"a":"D","e":"钢瓶与明火应保持10 m以上的安全距离。"},{"id":1162,"ch":6,"t":"s","q":"钢瓶与暖气设备的距离一般不应小于","o":["1 m","3 m","5 m","10 m"],"a":"A","e":"钢瓶与暖气等热源应保持1 m以上距离，防止受热升压。"},{"id":1163,"ch":6,"t":"s","q":"氧气瓶与乙炔瓶同时使用时的间距不应小于","o":["2 m","5 m","8 m","10 m"],"a":"B","e":"氧气瓶与乙炔瓶使用时间距不应小于5 m，防止泄漏后相互引燃。"},{"id":1164,"ch":6,"t":"s","q":"氧气瓶阀与乙炔瓶阀的正确使用方式是","o":["两种瓶阀可以互换","螺纹相同即可代用","瓶阀按气体种类专用，不得混用","只要不漏气即可混用"],"a":"C","e":"气瓶瓶阀按气体性质设计，连接螺纹也不同，不能混用。"},{"id":1165,"ch":6,"t":"s","q":"钢瓶存放时应避免","o":["阳光曝晒","直立放置","可靠固定","通风换气"],"a":"A","e":"阳光曝晒会使瓶内温度、压力升高，应避免。"},{"id":1166,"ch":6,"t":"s","q":"钢瓶上套设防震圈的主要作用是","o":["密封瓶口","减轻碰撞对瓶体的损伤","过滤气体","调节气体压力"],"a":"B","e":"防震圈具有缓冲作用，可减轻钢瓶碰撞时受到的损伤。"},{"id":1167,"ch":6,"t":"s","q":"使用钢瓶时发现瓶阀漏气，应首先","o":["关闭瓶阀并加强通风","继续使用","用明火照明检查","用水冲洗钢瓶"],"a":"A","e":"发现漏气应立即关闭瓶阀、加强通风，并杜绝一切火源。"},{"id":1168,"ch":6,"t":"s","q":"钢瓶使用完毕后，正确的做法是","o":["只关减压阀","不关瓶阀","关闭瓶阀并释放减压阀内余气","将钢瓶放倒"],"a":"C","e":"使用后应关闭瓶阀，释放减压阀内余气，再松开调节螺杆。"},{"id":1169,"ch":6,"t":"s","q":"乙炔瓶在使用时禁止","o":["直立放置","安装回火防止器","缓慢开启瓶阀","卧放使用"],"a":"D","e":"乙炔瓶卧放使用可能使丙酮流出，增加爆炸和火灾风险。"},{"id":1170,"ch":6,"t":"s","q":"氧气瓶阀冻结时，正确的处理方法是","o":["用温水或热布解冻","用明火烘烤","用沸水浇淋","用铁器敲击"],"a":"A","e":"可用温水或热布缓慢解冻，严禁明火烘烤和铁器敲击。"},{"id":1171,"ch":6,"t":"s","q":"钢瓶表面涂色的主要作用是","o":["美观装饰","识别瓶内气体种类","增加瓶体强度","防止瓶体锈蚀"],"a":"B","e":"钢瓶颜色和字样是识别气体种类的重要标记，不能随意更改。"},{"id":1172,"ch":6,"t":"s","q":"钢瓶内气体使用到最后应","o":["全部用完","用尽后加热排空","留有余压","倒置排空"],"a":"C","e":"瓶内应留有余压，防止空气或其他气体倒灌污染钢瓶。"},{"id":1173,"ch":6,"t":"s","q":"钢瓶开启前，减压阀的调节螺杆应","o":["拧到最大","拆下保管","涂上油脂","处于关闭或松开状态"],"a":"D","e":"开启瓶阀前减压阀应处于关闭或松开状态，防止出口压力骤升。"},{"id":1174,"ch":6,"t":"s","q":"氧气瓶瓶阀、减压阀及连接管路严禁沾染油脂，其根本原因是","o":["油脂会堵塞瓶阀内的细小通道","油脂会降低瓶内氧气的纯度","油脂与高压氧接触会剧烈氧化放热，可能引起燃烧爆炸","油脂会使钢瓶内壁加速锈蚀"],"a":"C","e":"高压氧与油脂接触会剧烈氧化，是氧气瓶禁油的根本原因。"},{"id":1175,"ch":6,"t":"s","q":"乙炔瓶在使用过程中必须留有一定余压，这样要求的主要目的是","o":["便于按质量计量实际用气量","防止空气或其他气体倒灌入瓶内","便于充装时快速接头对接","减少瓶内丙酮的装填量"],"a":"B","e":"留余压可防止空气等倒灌，避免瓶内形成爆炸性混合气体。"},{"id":1176,"ch":6,"t":"s","q":"乙炔瓶在使用和存放时必须保持直立，严禁卧放，主要是因为卧放时","o":["瓶阀容易被碰坏而漏气","瓶内有效容积会明显减小","不便观察瓶上的压力表读数","丙酮易随乙炔流出，且回火风险增大"],"a":"D","e":"卧放会使丙酮随气流带出，既改变气体组成又增加回火危险。"},{"id":1177,"ch":6,"t":"s","q":"开启钢瓶瓶阀时的正确做法是","o":["缓慢开启，操作者站在阀门侧面","迅速全开，以节省操作时间","站在阀门正对面用力快速拧开","用锤子敲击手轮帮助开启"],"a":"A","e":"缓慢开启并侧身站立，可避免高压气流伤人。"},{"id":1178,"ch":6,"t":"s","q":"搬运气体钢瓶时，下列做法正确的是","o":["把钢瓶放倒在地上滚动前进","抓住瓶阀将钢瓶提吊起来","装好瓶帽和防震圈，用专用小车搬运","由一人肩扛钢瓶穿过走廊"],"a":"C","e":"钢瓶禁止抛、滚、撞击，应戴瓶帽和防震圈并用专用小车搬运。"},{"id":1179,"ch":6,"t":"s","q":"可燃气体钢瓶与助燃气体钢瓶在库房中的存放要求是","o":["可以放在同一个储存柜内","分开存放，并保持规定的安全距离","只要室内无人，就可以混放","助燃气瓶可放在可燃气瓶的正上方"],"a":"B","e":"可燃气与助燃气必须分开存放并保持安全距离，防止泄漏后相遇。"},{"id":1180,"ch":6,"t":"s","q":"按国家标准，氧气瓶的漆色和字样标记应为","o":["白色瓶身、红色“氧”字","深绿色瓶身、白色“氧”字","银灰色瓶身、红色“氧”字","淡（天）蓝色瓶身、黑色“氧”字"],"a":"D","e":"氧气瓶为淡（天）蓝色瓶身、黑色“氧”字，属于专用颜色标记。"},{"id":1181,"ch":6,"t":"s","q":"乙炔瓶的漆色和字样标记应为","o":["白色瓶身、红色“乙炔”字样","淡蓝色瓶身、黑色“乙炔”字样","深绿色瓶身、白色“乙炔”字样","银灰色瓶身、黑色“乙炔”字样"],"a":"A","e":"乙炔瓶为白色瓶身、红色“乙炔”字样，便于与其他气体钢瓶区分。"},{"id":1182,"ch":6,"t":"s","q":"检查钢瓶瓶阀或管路接口是否漏气，正确的方法是","o":["用点燃的纸条靠近接口试探","用手掌贴近接口感受气流","用肥皂水涂抹接口并观察气泡","仅靠嗅闻气味判断有无泄漏"],"a":"C","e":"肥皂水检漏简便可靠，严禁用明火试漏。"},{"id":1183,"ch":6,"t":"s","q":"钢瓶使用中强调“人不离岗”，主要是为了","o":["防止他人随意借用气瓶","及时发现泄漏、回火等异常并立即处置","便于统计当次实验的用气量","避免瓶体长时间受到阳光照射"],"a":"B","e":"使用中人员在场才能及时关闭瓶阀、处置泄漏或回火。"},{"id":1184,"ch":6,"t":"s","q":"钢瓶上安装的减压阀的主要作用是","o":["把瓶内高压气体降低并稳定到所需输出压力","增大气体的输出流量以提高效率","过滤气体中夹带的机械杂质","防止火焰沿管路向瓶内回窜"],"a":"A","e":"减压阀起减压和稳压作用，防回火由回火防止器承担。"},{"id":1185,"ch":6,"t":"s","q":"安装减压阀之前，正确的操作是","o":["在接口螺纹处涂抹润滑油脂","用扳手敲击瓶阀使其松动","把减压阀整体浸入水中检查","稍开瓶阀吹除瓶口灰尘后再连接"],"a":"D","e":"先吹除瓶口灰尘可防止杂质进入减压阀，连接前须确认接口洁净。"},{"id":1186,"ch":6,"t":"s","q":"关于钢瓶内气体的使用限度，正确的做法是","o":["必须用尽瓶内气体以免浪费","用尽后更便于下次充装","应留有余压，防止其他气体倒灌","有无余压对安全没有影响"],"a":"C","e":"气瓶不得用尽，须留余压以防止倒灌和便于检验。"},{"id":1187,"ch":6,"t":"s","q":"发现钢瓶漏气且瓶阀无法关闭时，首先应当","o":["把钢瓶推倒在室内地面上","迅速移至室外通风处，远离火源并设置警戒","用水持续浇淋瓶体降温","继续使用直到瓶内气体放完"],"a":"B","e":"无法关阀时应尽快把漏气瓶转移到室外安全处并警戒。"},{"id":1188,"ch":6,"t":"s","q":"钢瓶着火时，正确的处置顺序是","o":["迅速关闭瓶阀切断气源，同时冷却瓶体并报警","先用水浇灭火焰，再考虑关闭瓶阀","把钢瓶推倒后立即撤离现场","打开瓶阀放空余气以减小压力"],"a":"A","e":"切断气源是扑救气体火灾的关键，同时冷却瓶体防止爆炸。"},{"id":1189,"ch":6,"t":"s","q":"使用油封机械真空泵时，下列做法正确的是","o":["可长时间抽含大量水汽的气体而不作处理","泵油加得越满，密封效果越好","抽腐蚀性气体时无需任何防护措施","定期检查油位和油质，并及时更换泵油"],"a":"D","e":"泵油变质会显著降低真空度，应定期检查并更换。"},{"id":1190,"ch":6,"t":"s","q":"玻璃真空系统防止内爆的适当措施是","o":["选用普通厚壁玻璃即可，不必额外防护","抽真空时操作人员贴近观察管内情况","系统外加防护罩或防爆网，操作时戴护目镜","全部用橡胶管代替玻璃管路"],"a":"C","e":"玻璃真空系统存在内爆风险，应加防护并佩戴护目镜。"},{"id":1191,"ch":6,"t":"s","q":"真空系统中设置冷阱（冷冻捕集）的主要作用是","o":["加热被抽气体以提高流速","捕集可凝性蒸气，提高真空度并保护真空泵","过滤气流中夹带的粉尘颗粒","直接测量系统的真空度"],"a":"B","e":"冷阱捕集水汽、有机溶剂等可凝蒸气，保护泵油免受污染。"},{"id":1192,"ch":6,"t":"s","q":"冷阱与被抽真空系统之间应当","o":["设置安全瓶等缓冲装置，防止倒吸","直接连通，不设任何中间装置","保持系统处于正压状态","不需要设置任何阀门或缓冲件"],"a":"A","e":"设置安全瓶可防止冷阱中的冷凝物倒吸入被抽系统。"},{"id":1193,"ch":6,"t":"s","q":"液氮在常压下的沸点约为","o":["-78℃","-100℃","-183℃","-196℃"],"a":"D","e":"液氮常压沸点约为-196℃，属于深低温介质。"},{"id":1194,"ch":6,"t":"s","q":"使用杜瓦瓶盛装液氮时，正确的做法是","o":["盖紧密封以延长保存时间","盛装量应超过瓶口便于取用","留出通气口，严禁密闭","可用普通玻璃保温瓶代替杜瓦瓶"],"a":"C","e":"杜瓦瓶必须留通气口，密闭会因液氮汽化造成超压。"},{"id":1195,"ch":6,"t":"s","q":"皮肤接触液氮造成冻伤后，正确的处理是","o":["立即用热水浸泡患处","用温水复温，避免揉搓，并及时就医","用力揉搓患处促进血液循环","用冰块冷敷以减轻疼痛"],"a":"B","e":"冻伤应用温水缓慢复温，揉搓会加重组织损伤。"},{"id":1196,"ch":6,"t":"s","q":"进行液氮等低温操作时，个人防护的正确做法是","o":["佩戴防寒手套和护目镜，避免皮肤裸露","戴普通薄线手套即可操作","徒手操作更为灵活安全","穿短袖工作服以便于活动"],"a":"A","e":"低温操作须防冻伤，应佩戴防寒手套、护目镜并避免皮肤裸露。"},{"id":1197,"ch":6,"t":"s","q":"在密闭房间内大量使用液氮，最主要的危险是","o":["引发可燃物火灾","造成人员急性中毒","引起粉尘爆炸","氮气置换空气导致缺氧窒息"],"a":"D","e":"液氮汽化使氧含量下降，密闭空间内有窒息风险。"},{"id":1198,"ch":6,"t":"s","q":"按用途分类，压力容器可分为","o":["低压、中压、高压和超高压容器","常温、中温和高温容器","反应、换热、分离和储存容器","球形、圆筒形和矩形容器"],"a":"C","e":"按用途分为反应、换热、分离、储存等压力容器。"},{"id":1199,"ch":6,"t":"s","q":"下列安全附件中，属于一次性泄压装置的是","o":["安全阀","爆破片","压力表","液位计"],"a":"B","e":"爆破片破裂后不能复位，属一次性泄压装置。"},{"id":1200,"ch":6,"t":"s","q":"压力容器上压力表的基本作用是","o":["显示容器内的压力","自动泄放超压气体","控制容器内的温度","指示容器内的液位"],"a":"A","e":"压力表用于监视容器压力，是重要的安全附件。"},{"id":1201,"ch":6,"t":"s","q":"气体钢瓶储存场所应当满足的条件是","o":["阴凉、通风、干燥，远离热源和阳光直射","露天堆放以节省库房面积","紧靠暖气片存放以防冻","存放在密闭不通风的地下室"],"a":"A","e":"钢瓶库房应阴凉通风干燥，避免暴晒和热源。"},{"id":1202,"ch":6,"t":"s","q":"按 GB 7144《气瓶颜色标志》的规定，乙炔气瓶的瓶体颜色和字样颜色分别是（ ）。","o":["淡蓝色瓶体、黑色字样","白色瓶体、红色字样","淡绿色瓶体、红色字样","黑色瓶体、淡黄色字样"],"a":"B","e":"乙炔瓶为白色瓶体、红色“乙炔”字样；淡蓝色瓶体黑字是氧气瓶，淡绿色瓶体红字是氢气瓶，黑色瓶体淡黄字是氮气瓶。颜色标志是防止误充装、误使用的第一道识别手段，漆色脱落或标识不清的气瓶不得充装使用。"},{"id":1203,"ch":6,"t":"s","q":"按《气瓶安全监察规程》的规定，盛装一般性气体的气瓶，其定期检验周期为（ ）。","o":["每1年检验一次","每2年检验一次","每3年检验一次","每5年检验一次"],"a":"C","e":"一般性气体气瓶每3年检验一次；盛装腐蚀性气体的气瓶（以及潜水气瓶、常与海水接触的气瓶）每2年检验一次；盛装惰性气体的气瓶每5年检验一次。乙炔气瓶属于特殊规定，每3年检验一次。超期未检的气瓶不得继续使用。"},{"id":1204,"ch":6,"t":"s","q":"实验室使用气瓶时，气瓶距明火的距离不得小于（ ）。","o":["3 m","5 m","8 m","10 m"],"a":"D","e":"使用气瓶时，氧气瓶与乙炔瓶之间的间距不得小于5 m，二者距明火的距离均不得小于10 m；储存气瓶应直立放置、远离明火10 m以上、距暖气1 m以上，并有防倾倒措施。注意5 m是两瓶之间的间距，10 m是气瓶与明火的距离，两者不可混淆。"},{"id":1205,"ch":6,"t":"s","q":"按压力容器定期检验的要求，钢制压力容器水压（液压）试验的试验压力一般取设计压力的（ ）。","o":["1.25倍","1.5倍","1.0倍","2.0倍"],"a":"A","e":"液压试验压力一般取设计压力的1.25倍（当材料许用应力比不同时按相应系数修正），且不小于设计压力加0.1 MPa；气密性试验压力一般取设计压力。试验时应先充满水并排净空气，缓慢升压，达到规定压力后保压检查，严禁带压紧固螺栓。"},{"id":1206,"ch":6,"t":"m","q":"压力容器的安全附件包括（ ）。","o":["安全阀","爆破片","压力表","搅拌器","减速机"],"a":"ABC","e":"安全阀、爆破片、压力表属于安全附件，搅拌器和减速机是工艺部件。"},{"id":1207,"ch":6,"t":"m","q":"压力容器按用途可分为（ ）。","o":["反应压力容器","换热压力容器","分离压力容器","储存压力容器","输送压力容器"],"a":"ABCD","e":"按用途分为反应、换热、分离、储存四类，输送不属于该分类。"},{"id":1208,"ch":6,"t":"m","q":"与安全阀相比，爆破片的特点有（ ）。","o":["结构简单、动作灵敏","泄放能力大","爆破后不能自动关闭","可重复使用","密封性好，适用于黏稠或腐蚀性介质"],"a":"ABCE","e":"爆破片动作后即破裂，不能重复使用，故D错误。"},{"id":1209,"ch":6,"t":"m","q":"压力表日常检查的内容包括（ ）。","o":["是否在检定有效期内","指针是否回零","表盘是否清晰、有无破损","容器内介质颜色","环境温度是否适宜"],"a":"ABC","e":"压力表检查重点是检定有效期、指针回零和表盘完好，介质颜色与环境温度不是压力表检查内容。"},{"id":1210,"ch":6,"t":"m","q":"下列气瓶颜色与所装气体对应正确的有（ ）。","o":["氧气瓶—淡蓝色","氢气瓶—淡绿色","氮气瓶—黑色","乙炔瓶—白色","二氧化碳瓶—红色"],"a":"ABCD","e":"二氧化碳瓶一般为黑色瓶体、黄色字样，不是红色。"},{"id":1211,"ch":6,"t":"m","q":"气瓶的安全附件主要包括（ ）。","o":["瓶阀","瓶帽","防震圈","易熔合金塞","减压阀"],"a":"ABCD","e":"减压阀装在气瓶外部管路上，不属于气瓶本体附件。"},{"id":1212,"ch":6,"t":"m","q":"使用减压阀时应注意（ ）。","o":["不同气体的减压阀不得混用","氧气减压阀严禁沾油","安装前应吹除接口内的灰尘","开启时应缓慢","可将可燃气体减压阀用于氧气瓶"],"a":"ABCD","e":"减压阀应专气专用，可燃气体减压阀用于氧气瓶会造成污染和燃爆危险。"},{"id":1213,"ch":6,"t":"m","q":"压力容器使用单位应建立的安全管理制度包括（ ）。","o":["岗位安全责任制","安全操作规程","定期检验制度","事故应急预案","产品广告宣传制度"],"a":"ABCD","e":"使用单位应建立责任制、操作规程、检验制度和应急预案，广告宣传与安全管理无关。"},{"id":1214,"ch":6,"t":"m","q":"按检验范围，压力容器的定期检验可分为（ ）。","o":["外部检查","内外部检验","全面检验","日常巡检"],"a":"ABC","e":"定期检验按范围分为外部检查、内外部检验和全面检验，日常巡检不属于定期检验。"},{"id":1215,"ch":6,"t":"m","q":"搬运气瓶时，正确的做法有（ ）。","o":["佩戴瓶帽和防震圈","轻装轻卸，禁止抛、滚、撞击","用电磁起重机吊运","使用专用小车搬运","把气瓶放在地上滚动前进"],"a":"ABD","e":"气瓶禁止抛滚和用电磁起重机吊运，应戴好附件并用专用小车搬运。"},{"id":1216,"ch":6,"t":"m","q":"下列装置中属于压力容器泄压装置的有（ ）。","o":["安全阀","爆破片","压力表","液位计"],"a":"AB","e":"安全阀和爆破片能泄放压力，压力表、液位计只起显示作用。"},{"id":1217,"ch":6,"t":"m","q":"使用气瓶时，正确的做法有（ ）。","o":["缓慢开启瓶阀","使用专用减压阀","用肥皂水检查接口是否漏气","人员离开时不必关闭瓶阀","用明火检查是否漏气"],"a":"ABC","e":"开阀应缓慢、减压阀应专用、检漏应用肥皂水；离开应关阀，严禁明火检漏。"},{"id":1218,"ch":6,"t":"m","q":"使用减压阀时，正确的做法有","o":["每种气体使用专用减压阀","安装前检查接口清洁、无油脂","开启时缓慢升压","用明火检查是否漏气"],"a":"ABC","e":"减压阀应专用、洁净并缓慢升压，严禁用明火检漏。"},{"id":1219,"ch":6,"t":"m","q":"搬运钢瓶时应做到","o":["戴好瓶帽","套好防震圈","轻装轻卸","抛掷或滚动","使用专用小车"],"a":"ABCE","e":"搬运钢瓶要戴瓶帽、套防震圈、轻装轻卸，并使用专用小车。"},{"id":1220,"ch":6,"t":"m","q":"钢瓶储存应符合的要求有","o":["直立放置并固定","空瓶与实瓶分开","分类存放","放在暖气设备旁"],"a":"ABC","e":"钢瓶应直立固定、分类存放，空实瓶分开，并远离暖气。"},{"id":1221,"ch":6,"t":"m","q":"可燃气体钢瓶与助燃气体钢瓶的存放要求包括","o":["分室存放","与明火保持10 m以上距离","与暖气保持1 m以上距离","紧靠在一起","储存场所通风良好"],"a":"ABCE","e":"可燃气体与助燃气体应分室存放，远离明火和热源，并保持通风。"},{"id":1222,"ch":6,"t":"m","q":"使用钢瓶时应遵守的操作规范有","o":["缓慢开启瓶阀","操作人员不得离岗","乙炔瓶安装回火防止器","用肥皂水检漏","用明火检漏"],"a":"ABCD","e":"钢瓶使用应缓慢开阀、人不离岗，乙炔瓶装回火防止器，并用肥皂水检漏。"},{"id":1223,"ch":6,"t":"m","q":"使用氧气瓶时，下列行为禁止的有","o":["瓶阀或减压阀接触油脂","靠近明火","剧烈碰撞","与乙炔瓶混放","直立固定"],"a":"ABCD","e":"氧气瓶严禁接触油脂、靠近明火、剧烈碰撞，并应与乙炔瓶分开。"},{"id":1224,"ch":6,"t":"m","q":"乙炔瓶的使用要求包括","o":["必须直立使用","安装回火防止器","卧放使用","将瓶内气体用尽","与氧气瓶保持5 m以上间距"],"a":"ABE","e":"乙炔瓶应直立使用、装回火防止器，并与氧气瓶保持5 m以上间距。"},{"id":1225,"ch":6,"t":"m","q":"气体钢瓶的附件通常包括","o":["瓶帽","防震圈","瓶阀","液位计","温度计"],"a":"ABC","e":"瓶帽、防震圈和瓶阀是气体钢瓶的常见附件，液位计和温度计一般不属此类。"},{"id":1226,"ch":6,"t":"m","q":"发现钢瓶漏气时，应采取的措施有","o":["立即关闭瓶阀","加强通风","严禁烟火","报告有关人员","用明火查找漏点"],"a":"ABCD","e":"漏气时应关阀、通风、禁火并报告，严禁用明火查找漏点。"},{"id":1227,"ch":6,"t":"m","q":"钢瓶储存场所应具备的条件有","o":["通风良好","避免阳光曝晒","远离热源","保持密闭"],"a":"ABC","e":"储存场所应通风、防晒、远离热源，不能保持密闭。"},{"id":1228,"ch":6,"t":"m","q":"下列气瓶不得同室存放的有","o":["氢气瓶与氧气瓶","乙炔瓶与氧气瓶","氮气瓶与氩气瓶","二氧化碳瓶与氩气瓶"],"a":"AB","e":"氢气、乙炔等可燃气体瓶不得与氧气等助燃气体瓶同室存放。"},{"id":1229,"ch":6,"t":"m","q":"钢瓶使用前应检查的内容有","o":["瓶体颜色和字样标识","检验期限","瓶阀是否完好","减压阀是否匹配","钢瓶是否便于搬运"],"a":"ABCD","e":"使用前应核对标识、检验期限、瓶阀和减压阀，搬运是否方便不属于安全检查内容。"},{"id":1230,"ch":6,"t":"m","q":"关于氧气瓶禁油，下列说法正确的有","o":["氧气瓶瓶阀不得沾染油脂","安装氧气减压阀前不得用油润滑接口","手上沾有油脂时擦一擦即可直接操作阀门","氧气瓶可与油脂类物品同车运输","与氧气接触的管路和工具均应禁油"],"a":"ABE","e":"凡与高压氧接触的部位和工具都必须严格禁油。"},{"id":1231,"ch":6,"t":"m","q":"下列做法中，属于乙炔瓶使用禁忌的有","o":["卧放使用","把瓶内气体用尽","与氧气瓶混放且不保持间距","在瓶体上引弧焊接","用专用乙炔减压阀减压"],"a":"ABCD","e":"乙炔瓶须直立、留余压、与氧气瓶分开存放，禁止在瓶体上引弧。"},{"id":1232,"ch":6,"t":"m","q":"气体钢瓶入库储存时，应符合的要求有","o":["直立放置并可靠固定","空瓶与实瓶分开存放","库房通风良好","与明火和热源保持安全距离","可临时存放在楼梯间和疏散通道内"],"a":"ABCD","e":"钢瓶储存应直立固定、分类分开、通风并远离火源，不得占用疏散通道。"},{"id":1233,"ch":6,"t":"m","q":"发现钢瓶泄漏时，正确的处置措施包括","o":["迅速关闭瓶阀，切断气源","打开门窗加强通风，严禁烟火","将漏气钢瓶移至室外安全处","用明火在接口处寻找漏点","疏散无关人员并报警"],"a":"ABCE","e":"泄漏处置以关阀、通风、转移、警戒为主，严禁明火试漏。"},{"id":1234,"ch":6,"t":"m","q":"油封机械真空泵的正确使用要求包括","o":["启动前检查油位和油质","抽可凝性蒸气时在泵前设置冷阱","定期更换泵油","不同牌号的泵油可随意混合使用"],"a":"ABC","e":"泵油应保持清洁并定期更换，不同牌号不宜混用。"},{"id":1235,"ch":6,"t":"m","q":"使用玻璃真空系统时，应注意的安全事项有","o":["选用合格玻璃件，避免使用有划痕的器件","系统外加装防护网罩","用手直接扳动粘接的玻璃磨口","操作时佩戴护目镜","抽真空前检查各接口连接是否牢固"],"a":"ABDE","e":"玻璃真空系统应防内爆、防划伤，磨口处不得用蛮力扳动。"},{"id":1236,"ch":6,"t":"m","q":"使用冷阱进行冷冻捕集时，正确的做法有","o":["使用前检查冷阱有无裂纹","冷阱与被抽系统之间设置安全瓶","缓慢加入液氮，避免玻璃骤冷炸裂","用自来水代替液氮作冷冻剂","冷阱用后待其回温再打开"],"a":"ABCE","e":"冷阱属低温玻璃器件，须防骤冷骤热并防止倒吸。"},{"id":1237,"ch":6,"t":"m","q":"进行液氮低温操作时，个人防护和操作要求包括","o":["佩戴防寒手套","用液氮冷却饮料后饮用","佩戴护目镜","穿长袖工作服，避免皮肤裸露","盛装液氮的容器不得密闭"],"a":"ACDE","e":"低温操作以防冻伤和防超压为原则，液氮不得用于冷却饮品。"},{"id":1238,"ch":6,"t":"m","q":"关于杜瓦瓶的使用，下列做法正确的有","o":["瓶口应留有通气口","搬运时轻拿轻放，防止碰撞","可完全密封以延长液氮保存时间","发现真空度下降、外壁结霜应停止使用","液氮应存放在通风良好的场所"],"a":"ABDE","e":"杜瓦瓶不得密闭，夹层失效结霜即为报废信号。"},{"id":1239,"ch":6,"t":"m","q":"压力容器安全附件的管理要求包括","o":["安全阀应定期校验","爆破片破裂后应及时更换","压力表应定期检定","液位计应保持清晰可见","安全附件损坏时可临时拆除继续使用"],"a":"ABCD","e":"安全附件必须完好并定期校验，不得随意拆除。"},{"id":1240,"ch":6,"t":"m","q":"关于压力容器的使用登记与定期检验，说法正确的有","o":["投用前应办理使用登记","应按规定周期进行定期检验","检验中发现的问题应及时处理","是否检验由使用单位自行决定"],"a":"ABC","e":"压力容器须登记建档并按规定定期检验，属强制要求。"},{"id":1241,"ch":6,"t":"j","q":"压力容器的设计压力可以低于其最高工作压力。","o":["对","错"],"a":"错","e":"设计压力是设计时设定的压力基准，不得低于最高工作压力。"},{"id":1242,"ch":6,"t":"j","q":"安全阀的排放口应朝向安全区域，不得正对人员或通道。","o":["对","错"],"a":"对","e":"排放口朝向人员或通道会在泄压时造成伤害，必须引至安全处。"},{"id":1243,"ch":6,"t":"j","q":"爆破片动作泄压后，经修复可以继续使用。","o":["对","错"],"a":"错","e":"爆破片破裂后结构已破坏，不能修复使用，必须更换。"},{"id":1244,"ch":6,"t":"j","q":"压力表应定期校验，并在表盘上标注校验日期。","o":["对","错"],"a":"对","e":"标注校验日期便于确认压力表是否在有效期内。"},{"id":1245,"ch":6,"t":"j","q":"氧气瓶、氧气减压阀及输氧管路允许接触少量油脂。","o":["对","错"],"a":"错","e":"纯氧与油脂接触会剧烈燃烧，氧气系统必须严格禁油。"},{"id":1246,"ch":6,"t":"j","q":"乙炔瓶可以卧放使用，以便于搬运。","o":["对","错"],"a":"错","e":"乙炔瓶卧放会使丙酮随气体流出，必须直立使用并固定。"},{"id":1247,"ch":6,"t":"j","q":"气瓶在运输和储存过程中应戴上瓶帽。","o":["对","错"],"a":"对","e":"瓶帽可保护瓶阀，避免碰撞损坏导致漏气或飞瓶。"},{"id":1248,"ch":6,"t":"j","q":"气瓶的颜色和字样标记可由使用单位根据方便自行确定。","o":["对","错"],"a":"错","e":"气瓶颜色和字样执行统一规定，使用单位不得自行更改。"},{"id":1249,"ch":6,"t":"j","q":"压力容器在投入使用前应办理使用登记。","o":["对","错"],"a":"对","e":"使用登记是压力容器合法投用的前提，也可在投用后30日内办理。"},{"id":1250,"ch":6,"t":"j","q":"安全阀一般应铅直安装。","o":["对","错"],"a":"对","e":"铅直安装可保证阀瓣动作灵活、回座可靠。"},{"id":1251,"ch":6,"t":"j","q":"液位计出现假液位时，只要容器压力正常就可以继续使用。","o":["对","错"],"a":"错","e":"假液位会导致误操作，可能造成超装或抽空，必须处理。"},{"id":1252,"ch":6,"t":"j","q":"压力容器的外部检查一般每年至少进行一次。","o":["对","错"],"a":"对","e":"外部检查属于经常性检查，一般每年至少一次。"},{"id":1253,"ch":6,"t":"j","q":"不同气体的减压阀可以互相借用。","o":["对","错"],"a":"错","e":"减压阀应专气专用，混用会造成气体污染甚至燃爆事故。"},{"id":1254,"ch":6,"t":"j","q":"储存气瓶时，空瓶和实瓶应分开存放。","o":["对","错"],"a":"对","e":"空实瓶分开存放可避免误用，便于管理和应急处置。"},{"id":1255,"ch":6,"t":"j","q":"搬运气瓶时，可以在平整地面上滚动气瓶以节省人力。","o":["对","错"],"a":"错","e":"气瓶禁止滚动搬运，应使用专用小车并轻装轻卸。"},{"id":1256,"ch":6,"t":"j","q":"氧气瓶减压阀可以涂少量油脂防锈。","o":["对","错"],"a":"错","e":"氧气瓶及减压阀严禁接触油脂，油脂遇高压氧可能燃烧爆炸。"},{"id":1257,"ch":6,"t":"j","q":"搬运钢瓶时，可以用滚动的方式短距离移动。","o":["对","错"],"a":"错","e":"搬运钢瓶严禁抛掷、滚动，应使用专用小车并轻装轻卸。"},{"id":1258,"ch":6,"t":"j","q":"钢瓶储存时应直立放置，并采取固定措施。","o":["对","错"],"a":"对","e":"直立并固定可防止钢瓶倾倒、碰撞和瓶阀损坏。"},{"id":1259,"ch":6,"t":"j","q":"空钢瓶与实钢瓶可以混放在同一区域。","o":["对","错"],"a":"错","e":"空瓶与实瓶应分开存放并设置明显标识，防止误用。"},{"id":1260,"ch":6,"t":"j","q":"可燃气体钢瓶与助燃气体钢瓶应分开存放。","o":["对","错"],"a":"对","e":"两类气瓶混放会增大火灾爆炸风险，必须分开存放。"},{"id":1261,"ch":6,"t":"j","q":"钢瓶储存场所应保持通风良好。","o":["对","错"],"a":"对","e":"通风良好可防止泄漏气体聚集，降低事故风险。"},{"id":1262,"ch":6,"t":"j","q":"钢瓶库房与明火的距离不得小于3 m。","o":["对","错"],"a":"错","e":"钢瓶与明火的距离一般不应小于10 m。"},{"id":1263,"ch":6,"t":"j","q":"钢瓶与暖气设备的距离一般不应小于1 m。","o":["对","错"],"a":"对","e":"钢瓶应远离热源，与暖气保持1 m以上距离。"},{"id":1264,"ch":6,"t":"j","q":"开启钢瓶阀门时应缓慢，防止高压气流冲击。","o":["对","错"],"a":"对","e":"缓慢开启可避免气流冲击损坏减压阀，并可减少静电产生。"},{"id":1265,"ch":6,"t":"j","q":"使用钢瓶时，操作人员可以短时间离开现场。","o":["对","错"],"a":"错","e":"使用钢瓶时操作人员不得离岗，以便及时处置异常情况。"},{"id":1266,"ch":6,"t":"j","q":"乙炔瓶必须安装回火防止器。","o":["对","错"],"a":"对","e":"回火防止器可阻止火焰回窜入乙炔瓶，是必要的安全装置。"},{"id":1267,"ch":6,"t":"j","q":"可以用肥皂水检查钢瓶阀门是否漏气。","o":["对","错"],"a":"对","e":"肥皂水检漏安全可靠，观察接口是否产生气泡即可判断。"},{"id":1268,"ch":6,"t":"j","q":"氧气瓶与乙炔瓶使用时的间距只要大于2 m即可。","o":["对","错"],"a":"错","e":"氧气瓶与乙炔瓶使用时的间距不应小于5 m。"},{"id":1269,"ch":6,"t":"j","q":"氧气减压阀和乙炔减压阀可以互换使用。","o":["对","错"],"a":"错","e":"不同气体的减压阀应专用，不能互换使用。"},{"id":1270,"ch":6,"t":"j","q":"搬运钢瓶时必须戴好瓶帽。","o":["对","错"],"a":"对","e":"瓶帽可保护瓶阀，防止搬运过程中碰坏瓶阀造成泄漏。"},{"id":1271,"ch":6,"t":"j","q":"氧气瓶及其减压阀、连接管路严禁沾染油脂。","o":["对","错"],"a":"对","e":"高压氧遇油脂会剧烈氧化，故必须严格禁油。"},{"id":1272,"ch":6,"t":"j","q":"乙炔瓶可以卧放使用，只要用支架固定牢靠即可。","o":["对","错"],"a":"错","e":"乙炔瓶必须直立使用，卧放会使丙酮流出并增大回火风险。"},{"id":1273,"ch":6,"t":"j","q":"搬运钢瓶时可以把钢瓶放倒在地上滚动，以节省人力。","o":["对","错"],"a":"错","e":"钢瓶禁止滚动、抛掷和撞击，应使用专用小车搬运。"},{"id":1274,"ch":6,"t":"j","q":"开启钢瓶瓶阀应缓慢进行，操作者宜站在阀门侧面。","o":["对","错"],"a":"对","e":"缓慢开启并侧身站立可避免高压气流冲击伤人。"},{"id":1275,"ch":6,"t":"j","q":"检查钢瓶接口是否漏气时，可以用点燃的纸条靠近试探。","o":["对","错"],"a":"错","e":"严禁明火试漏，应使用肥皂水检漏。"},{"id":1276,"ch":6,"t":"j","q":"钢瓶内的气体应尽量用完，以免余气造成浪费。","o":["对","错"],"a":"错","e":"气瓶不得用尽，必须留有余压以防倒灌。"},{"id":1277,"ch":6,"t":"j","q":"可燃气体钢瓶与助燃气体钢瓶应分开存放并保持安全距离。","o":["对","错"],"a":"对","e":"分开存放可避免泄漏后两种气体相遇引发燃烧爆炸。"},{"id":1278,"ch":6,"t":"j","q":"气体钢瓶应直立放置并采取可靠的固定措施，防止倾倒。","o":["对","错"],"a":"对","e":"钢瓶倾倒可能撞坏瓶阀造成高压气体喷出。"},{"id":1279,"ch":6,"t":"j","q":"真空系统抽气结束准备停泵时，应先使系统与大气相通再停泵。","o":["对","错"],"a":"对","e":"先放气可防止泵油倒吸入被抽系统。"},{"id":1280,"ch":6,"t":"j","q":"玻璃真空系统只要玻璃壁足够厚，就不必再采取防内爆措施。","o":["对","错"],"a":"错","e":"厚壁玻璃同样会内爆，仍需加防护罩并佩戴护目镜。"},{"id":1281,"ch":6,"t":"j","q":"在真空系统中设置冷阱捕集可凝性蒸气，有助于提高系统真空度。","o":["对","错"],"a":"对","e":"冷阱可捕集水汽和有机蒸气，减少其对真空度和泵油的影响。"},{"id":1282,"ch":6,"t":"j","q":"液氮温度约为-196℃，皮肤直接接触会造成严重冻伤。","o":["对","错"],"a":"对","e":"深低温介质接触皮肤可迅速造成冻伤。"},{"id":1283,"ch":6,"t":"j","q":"盛装液氮的杜瓦瓶必须严密加盖密封，否则液氮会不断挥发损失。","o":["对","错"],"a":"错","e":"杜瓦瓶密闭会因液氮汽化而超压，必须留有通气口。"},{"id":1284,"ch":6,"t":"j","q":"发生冻伤后应立即用热水浸泡或用力揉搓患处以恢复知觉。","o":["对","错"],"a":"错","e":"冻伤应用温水复温，热水和揉搓都会加重组织损伤。"},{"id":1285,"ch":6,"t":"j","q":"钢瓶着火时，应首先设法关闭瓶阀以切断气源。","o":["对","错"],"a":"对","e":"切断气源是扑救气体钢瓶火灾的首要措施。"},{"id":1286,"ch":6,"t":"b","q":"压力容器按压力等级分为低压容器、中压容器、高压容器和____容器。","a":["超高压"]},{"id":1287,"ch":6,"t":"b","q":"压力容器按用途分为反应压力容器、换热压力容器、分离压力容器和____压力容器。","a":["储存"]},{"id":1288,"ch":6,"t":"b","q":"爆破片属于____使用的泄压装置，动作后必须更换。","a":["一次性"]},{"id":1289,"ch":6,"t":"b","q":"蒸汽管道上的压力表前应装设____，以防止高温蒸汽直接进入压力表。","a":["存水弯管"]},{"id":1290,"ch":6,"t":"b","q":"气瓶瓶帽的作用是保护____免受损伤。","a":["瓶阀"]},{"id":1291,"ch":6,"t":"b","q":"气瓶防震圈可以减轻气瓶在搬运过程中因____造成的瓶体损伤。","a":["碰撞"]},{"id":1292,"ch":6,"t":"b","q":"氧气瓶瓶体为淡蓝色，字样为____字“氧”。","a":["黑"]},{"id":1293,"ch":6,"t":"b","q":"乙炔瓶瓶体为白色，字样为____字“乙炔”。","a":["红"]},{"id":1294,"ch":6,"t":"b","q":"压力容器使用单位应当在投入使用前或者投入使用后____日内办理使用登记。","a":["30"]},{"id":1295,"ch":6,"t":"b","q":"安全阀一般每____至少校验一次。","a":["年"]},{"id":1296,"ch":6,"t":"b","q":"减压阀可将钢瓶内的高压气体____到实验所需压力，并保持压力稳定。","a":["减压"]},{"id":1297,"ch":6,"t":"b","q":"搬运钢瓶时必须戴好____，以保护瓶阀。","a":["瓶帽"]},{"id":1298,"ch":6,"t":"b","q":"钢瓶瓶体上套设的____可以减轻碰撞造成的损伤。","a":["防震圈"]},{"id":1299,"ch":6,"t":"b","q":"钢瓶在储存时应____放置，并采取固定措施。","a":["直立"]},{"id":1300,"ch":6,"t":"b","q":"空瓶与实瓶应____存放，不得混放，并设置明显标识。","a":["分开"]},{"id":1301,"ch":6,"t":"b","q":"可燃气体钢瓶与助燃气体钢瓶应分室存放，不得____存放。","a":["同室"]},{"id":1302,"ch":6,"t":"b","q":"钢瓶储存场所应保持____良好，防止气体积聚。","a":["通风"]},{"id":1303,"ch":6,"t":"b","q":"开启钢瓶阀门时应____，以免高压气流损坏减压阀。","a":["缓慢"]},{"id":1304,"ch":6,"t":"b","q":"使用乙炔瓶时必须安装____，防止火焰回窜入瓶内。","a":["回火防止器"]},{"id":1305,"ch":6,"t":"b","q":"检查钢瓶接口是否漏气时，可用____涂抹并观察是否产生气泡。","a":["肥皂水"]},{"id":1306,"ch":6,"t":"b","q":"氧气瓶及与其连接的减压阀、管路严禁沾染____。","a":["油脂"]},{"id":1307,"ch":6,"t":"b","q":"乙炔瓶在使用和存放时必须____放置，严禁卧放。","a":["直立"]},{"id":1308,"ch":6,"t":"b","q":"搬运钢瓶时应装好____和防震圈，防止瓶阀被撞坏。","a":["瓶帽"]},{"id":1309,"ch":6,"t":"b","q":"检查钢瓶瓶阀和管路接口是否漏气，应使用____涂抹后观察。","a":["肥皂水"]},{"id":1310,"ch":6,"t":"b","q":"氧气瓶瓶身漆成淡（天）蓝色，并用____色标注“氧”字。","a":["黑"]},{"id":1311,"ch":6,"t":"b","q":"油封机械真空泵中起密封和润滑作用的介质是____。","a":["真空泵油"]},{"id":1312,"ch":6,"t":"b","q":"液氮在常压下的沸点约为____℃。","a":["-196"]},{"id":1313,"ch":6,"t":"b","q":"低温操作时应佩戴____和护目镜，避免皮肤直接裸露。","a":["防寒手套"]},{"id":1314,"ch":6,"t":"b","q":"压力容器上用于自动泄放超压介质的附件主要有安全阀和____。","a":["爆破片"]},{"id":1315,"ch":6,"t":"x","q":"简述安全阀与爆破片的主要区别，并说明各自的适用场合。","a":"1.工作原理不同：安全阀依靠阀瓣在压力作用下的开启与回座自动泄压，压力降低后能自动关闭；爆破片依靠膜片受压破裂泄压，动作后不能复位。2.使用特性不同：安全阀可重复使用，但密封性和响应速度相对较差；爆破片结构简单、动作迅速、泄放量大、密封性好，但属一次性使用。3.适用场合不同：安全阀适用于一般气体、蒸汽和清洁液体介质；爆破片适用于介质黏稠、易结晶、腐蚀性强或反应迅速、安全阀难以可靠工作的场合，也可与安全阀组合使用。"},{"id":1316,"ch":6,"t":"x","q":"某实验室用氧气瓶供气，操作人员发现减压阀接口处有油污但未处理便开启瓶阀，随即接口处起火。请分析事故原因，并说明氧气瓶使用中的主要安全要求。","a":"1.原因分析：氧气是强氧化剂，油脂在纯氧中燃点降低、燃烧剧烈；减压阀接口沾有油脂，开启瓶阀时氧气高速喷出，摩擦热或静电即可引燃油脂，导致起火。2.安全要求：①氧气瓶、减压阀、管路及工具严禁接触油脂，操作人员手套、工具应洁净；②安装减压阀前吹除接口灰尘，检查螺纹和密封面；③缓慢开启瓶阀，人站在侧面，不得正对接口；④用肥皂水检漏，严禁明火检漏；⑤氧气瓶应直立固定，远离明火和热源，与可燃气体瓶保持规定间距；⑥专瓶专用，减压阀不得混用；⑦用后关紧瓶阀，保留余压。"},{"id":1317,"ch":6,"t":"x","q":"简述钢瓶搬运和储存的主要安全要求。","a":"1.搬运前检查瓶帽、瓶阀是否完好，搬运时戴好瓶帽和防震圈，轻装轻卸，严禁抛掷、滚动，使用专用小车；2.储存时直立放置并可靠固定，分类存放，空瓶与实瓶分开；3.可燃气体与助燃气体分室存放，库房通风良好，避免阳光曝晒，远离热源并保持通道畅通；4.钢瓶与明火保持10 m以上距离，与暖气保持1 m以上距离。"},{"id":1318,"ch":6,"t":"x","q":"某学生使用氧气瓶时，发现减压阀接口沾有油污，仍继续安装并开启，随后接口处起火。请分析事故原因，并写出氧气瓶使用的安全措施。","a":"1.原因：减压阀接口沾有油脂，开启后油脂在高压氧环境中迅速氧化放热，引起燃烧甚至爆炸。2.措施：氧气瓶必须使用专用减压阀，瓶阀、减压阀及管路严禁接触油脂；安装前检查接口清洁；开启瓶阀应缓慢，操作人员不得离岗；用肥皂水检漏，严禁明火；氧气瓶与乙炔瓶保持5 m以上间距，与明火保持10 m以上距离；使用完毕关闭瓶阀并释放减压阀内余气。"},{"id":1319,"ch":6,"t":"x","q":"简述使用乙炔瓶的主要安全禁忌以及余压要求。","a":"1.乙炔瓶必须直立使用并可靠固定，严禁卧放，防止丙酮随气流流出和回火；2.应远离热源、明火，与氧气瓶分开存放并保持安全距离，避免阳光暴晒；3.开阀应缓慢，严禁用敲击、摔打等方式强行开启，不得在瓶体上引弧或敲击；4.必须使用专用的乙炔减压阀，不得与氧气减压阀混用，管路应装回火防止器；5.瓶内气体不得用尽，须留有余压，以防空气等倒灌形成爆炸性混合气体；6.检漏用肥皂水，发现泄漏应立即关闭瓶阀并通风，严禁明火试漏。"},{"id":1320,"ch":6,"t":"x","q":"某实验室用油封机械真空泵抽含大量水汽的玻璃真空系统，未设冷阱。抽气过程中玻璃管路突然内爆，操作者因未戴护目镜被碎玻璃划伤。请分析其中的错误并说明正确做法。","a":"1.错误之一：抽含大量水汽的气体未在泵前设置冷阱，水汽进入泵体使泵油乳化、真空度下降，还可能在管路中凝积；2.错误之二：玻璃真空系统未加防护罩或防爆网，也未能事先检查玻璃件有无划痕、裂纹；3.错误之三：操作者未佩戴护目镜等防护用品；4.正确做法：泵前加装冷阱捕集可凝性蒸气，定期检查并更换泵油；选用合格无损伤的玻璃件，系统外加装防护网罩；操作时佩戴护目镜，缓慢抽气，不得贴近观察；停泵前先使系统与大气相通，冷阱用后待回温再打开。"},{"id":1321,"ch":7,"t":"s","q":"α粒子的本质是（ ）","o":["高速电子流","氦原子核","高频电磁波","中子流"],"a":"B","e":"α粒子是带两个单位正电荷的氦原子核。"},{"id":1322,"ch":7,"t":"s","q":"下列电离辐射中，穿透能力最弱的是（ ）","o":["α射线","β射线","γ射线","X射线"],"a":"A","e":"α粒子质量大、电荷多，容易被物质阻挡，穿透能力最弱。"},{"id":1323,"ch":7,"t":"s","q":"β射线的穿透特点是（ ）","o":["只能穿透一张纸","可穿透几毫米铝板，但可被有机玻璃阻挡","可穿透厚铅板","与γ射线完全相同"],"a":"B","e":"β射线穿透能力中等，低原子序数材料即可有效阻挡。"},{"id":1324,"ch":7,"t":"s","q":"γ射线的本质是（ ）","o":["氦核流","电子流","波长很短的电磁波","中子流"],"a":"C","e":"γ射线是原子核衰变时释放的高能光子，属于电磁辐射。"},{"id":1325,"ch":7,"t":"s","q":"X射线与γ射线的主要区别在于（ ）","o":["是否带电","传播速度","能否被屏蔽","产生机制"],"a":"D","e":"X射线主要来自核外电子过程，γ射线来自原子核衰变，二者本质相同。"},{"id":1326,"ch":7,"t":"s","q":"屏蔽中子射线效果较好的材料是（ ）","o":["含氢丰富的水和石蜡","薄铝板","有机玻璃","铜片"],"a":"A","e":"中子与氢核碰撞时能量损失显著，含氢材料屏蔽效果较好。"},{"id":1327,"ch":7,"t":"s","q":"外照射防护的三原则是（ ）","o":["通风、过滤、排放","包容、去污、监测","时间、距离、屏蔽","隔离、消毒、封闭"],"a":"C","e":"缩短时间、增大距离和设置屏蔽是外照射防护的基本手段。"},{"id":1328,"ch":7,"t":"s","q":"点状放射源外某点的剂量率与距离的关系是（ ）","o":["与距离成正比","与距离平方成反比","与距离无关","与距离立方成反比"],"a":"B","e":"点源辐射遵循平方反比规律，距离增大剂量率迅速下降。"},{"id":1329,"ch":7,"t":"s","q":"内照射防护最关键的措施是（ ）","o":["防止放射性物质进入体内","缩短受照时间","增大与源的距离","增加屏蔽厚度"],"a":"A","e":"内照射源于放射性物质进入体内，阻断摄入途径是防护核心。"},{"id":1330,"ch":7,"t":"s","q":"半衰期是指（ ）","o":["核素完全衰变所需的时间","射线能量减少一半所需的时间","活度增加到两倍所需的时间","核素原子核数目减少到原来一半所需的时间"],"a":"D","e":"半衰期是放射性核素原子核数目衰减到初始值一半所需的时间。"},{"id":1331,"ch":7,"t":"s","q":"某放射性核素经过3个半衰期后，剩余的原子核数目约为原来的（ ）","o":["1/2","1/4","1/8","1/16"],"a":"C","e":"每经过一个半衰期剩余一半，三个半衰期后剩余八分之一。"},{"id":1332,"ch":7,"t":"s","q":"放射性活度的国际单位是（ ）","o":["贝可勒尔（Bq）","戈瑞（Gy）","希沃特（Sv）","居里（Ci）"],"a":"A","e":"贝可勒尔是放射性活度的国际单位，表示每秒一次衰变。"},{"id":1333,"ch":7,"t":"s","q":"吸收剂量的国际单位是（ ）","o":["贝可（Bq）","戈瑞（Gy）","希沃特（Sv）","伦琴（R）"],"a":"B","e":"戈瑞表示单位质量物质吸收的辐射能量，是吸收剂量单位。"},{"id":1334,"ch":7,"t":"s","q":"当量剂量的国际单位是（ ）","o":["贝可（Bq）","戈瑞（Gy）","库仑每千克（C/kg）","希沃特（Sv）"],"a":"D","e":"希沃特用于表示当量剂量和有效剂量，反映辐射危害程度。"},{"id":1335,"ch":7,"t":"s","q":"计算有效剂量时，除了吸收剂量和辐射权重因子外，还需要考虑（ ）","o":["源活度","照射时间","组织权重因子","源与人的距离"],"a":"C","e":"有效剂量需按不同组织的辐射敏感性进行加权求和。"},{"id":1336,"ch":7,"t":"s","q":"确定性效应的特点是（ ）","o":["有阈值，严重程度随剂量增加","无阈值，发生概率随剂量增加","仅发生在胚胎期","与剂量率无关"],"a":"A","e":"确定性效应有明确阈值，超过阈值后严重程度随剂量上升。"},{"id":1337,"ch":7,"t":"s","q":"随机性效应的特点是（ ）","o":["有明确阈值","无阈值，发生概率随剂量增加","严重程度随剂量增加","仅由外照射引起"],"a":"B","e":"随机性效应无阈值，发生概率随剂量增加而严重程度与剂量无关。"},{"id":1338,"ch":7,"t":"s","q":"按GB 18871的规定，职业照射连续5年平均的年有效剂量不应超过（ ）","o":["1 mSv","5 mSv","15 mSv","20 mSv"],"a":"D","e":"职业照射年有效剂量按连续5年平均不超过20 mSv控制。"},{"id":1339,"ch":7,"t":"s","q":"公众照射的年有效剂量限值为（ ）","o":["1 mSv","5 mSv","20 mSv","50 mSv"],"a":"A","e":"公众照射的年有效剂量限值通常为1 mSv。"},{"id":1340,"ch":7,"t":"s","q":"个人剂量计的主要作用是（ ）","o":["测量表面污染","测量空气放射性浓度","监测个人累积受照剂量","测量放射源的活度"],"a":"C","e":"个人剂量计用于记录佩戴者一定时期内累积的个人受照剂量。"},{"id":1341,"ch":7,"t":"s","q":"监测工作台面和人员体表的放射性污染，应使用（ ）","o":["个人剂量计","表面污染监测仪","剂量率仪","辐射报警仪"],"a":"B","e":"表面污染监测仪可检测物体和人体表面的放射性沾污。"},{"id":1342,"ch":7,"t":"s","q":"放射性工作场所通常划分为（ ）","o":["办公区和实验区","高活度区和低活度区","内区和外区","控制区和监督区"],"a":"D","e":"辐射工作场所按辐射风险分为控制区和监督区实施管理。"},{"id":1343,"ch":7,"t":"s","q":"放射性废物管理应遵循的原则是（ ）","o":["分类收集、减容固化、合规处置","直接排入下水道","与生活垃圾一起填埋","露天焚烧"],"a":"A","e":"放射性废物必须分类收集、减容固化并按规定安全处置。"},{"id":1344,"ch":7,"t":"s","q":"紫外线对人体的主要危害是（ ）","o":["电离损伤","热烧伤","电光性眼炎和皮肤红斑","神经系统损伤"],"a":"C","e":"过量紫外线可引起皮肤红斑和角膜结膜的急性损伤。"},{"id":1345,"ch":7,"t":"s","q":"防止紫外线伤害的有效措施是（ ）","o":["佩戴普通太阳镜","使用不透紫外的屏蔽和防护镜","缩短与光源的距离","延长照射时间"],"a":"B","e":"屏蔽和专用防护镜可减少紫外线对皮肤和眼睛的照射。"},{"id":1346,"ch":7,"t":"s","q":"激光对人眼最严重的危害是（ ）","o":["近视","色盲","干眼症","视网膜灼伤"],"a":"D","e":"激光能量集中，聚焦后可在视网膜造成严重灼伤。"},{"id":1347,"ch":7,"t":"s","q":"激光防护的核心措施是（ ）","o":["佩戴与波长匹配的防护镜并避免直视光束","戴普通墨镜","用手遮挡光束","靠近光束观察光路"],"a":"A","e":"激光防护镜需与激光波长匹配，同时应避免直视光束。"},{"id":1348,"ch":7,"t":"s","q":"微波和射频辐射的主要生物效应是（ ）","o":["电离效应","遗传效应","热效应","化学腐蚀"],"a":"C","e":"微波和射频属于非电离辐射，过量暴露以热效应为主。"},{"id":1349,"ch":7,"t":"s","q":"红外线长期照射眼睛可能引起（ ）","o":["电光性眼炎","晶状体混浊","视网膜脱离","青光眼"],"a":"B","e":"长期红外线照射可导致晶状体蛋白变性，形成白内障。"},{"id":1350,"ch":7,"t":"s","q":"发现放射源丢失、被盗，应当（ ）","o":["只报告本单位负责人","自行组织人员寻找","等待失主认领","立即报告公安和生态环境部门"],"a":"D","e":"放射源丢失或被盗属于辐射事故，应立即报告监管部门。"},{"id":1351,"ch":7,"t":"s","q":"发生辐射事故时，首要的处置措施是（ ）","o":["撤离人员、封锁现场并立即报告","继续实验并观察变化","先清理现场再报告","先查明事故原因再处理"],"a":"A","e":"辐射事故应急应优先保护人员安全并控制事故影响范围。"},{"id":1352,"ch":7,"t":"s","q":"电离辐射警告标志的图案是（ ）","o":["骷髅","火焰","三叶形","三角形感叹号"],"a":"C","e":"电离辐射警告标志采用三叶形图案，提示存在电离辐射危害。"},{"id":1353,"ch":7,"t":"s","q":"同一核素中，半衰期越短，其比活度（ ）","o":["越小","越大","不变","先增后减"],"a":"B","e":"半衰期越短，单位质量核素在单位时间内的衰变数越多。"},{"id":1354,"ch":7,"t":"s","q":"发生β衰变后，原子核的原子序数（ ）","o":["减少2","减少1","不变","增加1"],"a":"D","e":"β衰变中中子转变为质子，原子序数增加1而质量数不变。"},{"id":1355,"ch":7,"t":"s","q":"α粒子穿透能力弱，在空气中通常只能行进数厘米，能有效阻挡其外照射的常用材料是：","o":["一张纸或皮肤角质层","几毫米厚的铅板","含硼石蜡","厚混凝土墙"],"a":"A","e":"α粒子射程很短，纸张或皮肤表层即可将其阻挡。"},{"id":1356,"ch":7,"t":"s","q":"屏蔽β射线时优先选用低原子序数材料，其主要原因是：","o":["低原子序数材料价格更低","低原子序数材料密度更大","可减少轫致辐射的产生","可完全吸收γ射线"],"a":"C","e":"低原子序数材料可减少β射线与物质作用产生的轫致辐射。"},{"id":1357,"ch":7,"t":"s","q":"对点状γ放射源，将人员与源的距离增大到原来的2倍，剂量率约变为原来的：","o":["1/2","1/4","1/3","1/8"],"a":"B","e":"点状源剂量率与距离的平方成反比。"},{"id":1358,"ch":7,"t":"s","q":"下列材料中，屏蔽中子射线效果较好的是：","o":["铅","铝","玻璃","含氢材料（如水、石蜡）"],"a":"D","e":"中子与氢核作用可有效慢化，含氢材料常用于中子屏蔽。"},{"id":1359,"ch":7,"t":"s","q":"外照射防护中“时间防护”的含义是：","o":["尽量缩短受照射时间","尽量延长操作时间","只在夜间进行操作","把操作推迟到以后"],"a":"A","e":"受照剂量与受照时间近似成正比，缩短时间可降低剂量。"},{"id":1360,"ch":7,"t":"s","q":"外照射防护中“距离防护”的主要依据是：","o":["剂量率随距离增大而线性下降","剂量率随距离平方反比下降","距离越近屏蔽效果越好","距离不改变剂量率"],"a":"B","e":"点状源的剂量率随距离增加按平方反比规律减弱。"},{"id":1361,"ch":7,"t":"s","q":"内照射防护的首要措施是：","o":["增加操作时间","靠近放射源操作","把放射性物质包容在密闭系统内","去掉屏蔽层"],"a":"C","e":"密闭包容可从源头阻止放射性物质进入环境。"},{"id":1362,"ch":7,"t":"s","q":"操作易挥发的放射性物质时，为防止吸入，应在下列哪种设施中进行：","o":["普通实验台","办公桌","离心机旁","通风柜或手套箱"],"a":"D","e":"通风柜或手套箱可控制气流并包容放射性气溶胶。"},{"id":1363,"ch":7,"t":"s","q":"放射性表面污染去污的主要目的是：","o":["增加放射性活度","降低表面污染水平，防止扩散和摄入","改变核素半衰期","提高剂量率"],"a":"B","e":"去污可减少污染转移和人员摄入的危险。"},{"id":1364,"ch":7,"t":"s","q":"确定性效应（组织反应）的典型特征是：","o":["无剂量阈值，发生概率随剂量增加","与受照剂量无关","有剂量阈值，严重程度随剂量增加","只发生于公众成员"],"a":"C","e":"确定性效应存在阈值，超过阈值后严重程度随剂量增加。"},{"id":1365,"ch":7,"t":"s","q":"随机性效应的典型特征是：","o":["有明确阈值，严重程度随剂量增加","只由内照射引起","剂量越大，病情必然越重","无阈值，发生概率随剂量增加"],"a":"D","e":"随机性效应无阈值，发生概率随剂量增加而严重程度与剂量无关。"},{"id":1366,"ch":7,"t":"s","q":"职业照射中，眼晶状体的年当量剂量限值为：","o":["150 mSv","15 mSv","50 mSv","500 mSv"],"a":"A","e":"职业照射眼晶状体年当量剂量限值为150 mSv。"},{"id":1367,"ch":7,"t":"s","q":"在特殊情况下，公众照射单一年份有效剂量不得超过：","o":["0.1 mSv","1 mSv","5 mSv","20 mSv"],"a":"C","e":"特殊情况下公众单一年份有效剂量不得超过5 mSv，且5年平均不超过1 mSv。"},{"id":1368,"ch":7,"t":"s","q":"有效剂量的国际单位是：","o":["贝可（Bq）","戈瑞（Gy）","居里（Ci）","希沃特（Sv）"],"a":"D","e":"有效剂量用于综合表征辐射危害，单位为希沃特。"},{"id":1369,"ch":7,"t":"s","q":"个人剂量计一般应佩戴在：","o":["脚踝","后背","口袋中","胸前"],"a":"D","e":"胸前佩戴可较好地代表躯干和全身受照情况。"},{"id":1370,"ch":7,"t":"s","q":"热释光剂量计（TLD）记录累积剂量的基本原理是：","o":["晶体受照后加热发光","胶片感光变黑","气体电离产生电流","液体闪烁计数"],"a":"A","e":"热释光材料受照后加热释放光信号，其强度与剂量相关。"},{"id":1371,"ch":7,"t":"s","q":"对放射性工作场所进行表面污染监测的主要目的是：","o":["测定空气中放射性浓度","判断表面污染是否超过控制水平","测量个人累积剂量","确定放射性核素的半衰期"],"a":"B","e":"表面污染监测用于发现污染并判断是否超过规定控制水平。"},{"id":1372,"ch":7,"t":"s","q":"测量环境γ剂量率常用的仪器是：","o":["表面污染仪","离心机","剂量率仪（如电离室或GM计数管）","分光光度计"],"a":"C","e":"电离室、GM计数管等可指示环境剂量率水平。"},{"id":1373,"ch":7,"t":"s","q":"看到电离辐射警告标志后，正确的做法是：","o":["可以随意进入该区域","可以自行拆除标志","可在标志旁长时间休息","未经许可不得进入该区域"],"a":"D","e":"警告标志提示存在辐射风险，未经许可不得擅自进入。"},{"id":1374,"ch":7,"t":"s","q":"放射性废物分类收集的主要依据是：","o":["核素种类、活度水平和半衰期","废物的颜色和气味","废物的包装大小","废物的酸碱度"],"a":"A","e":"放射性废物应按核素种类、活度水平和半衰期等分类收集。"},{"id":1375,"ch":7,"t":"s","q":"使用紫外线灯进行消毒时，为防止人员受到照射，应：","o":["打开门窗增加湿度","用普通玻璃随意遮挡","设置遮光罩并避免人员在场","延长照射时间"],"a":"C","e":"紫外线灯应加遮光罩，使用时人员离开现场，避免直接暴露。"},{"id":1376,"ch":7,"t":"s","q":"激光实验中控制光路的主要安全目的是：","o":["提高激光输出功率","避免镜面反射造成意外照射","改变激光的波长","使激光转变为电离辐射"],"a":"B","e":"控制光路可减少镜面反射和杂散光造成的意外照射。"},{"id":1377,"ch":7,"t":"s","q":"放射性核素的半衰期是指：","o":["放射性活度减少到原来一半所需时间","核素质量减少一半所需时间","射线能量减少一半所需时间","剂量率增加一倍所需时间"],"a":"A","e":"半衰期是放射性活度衰减到初始值一半所需的时间。"},{"id":1378,"ch":7,"t":"s","q":"α放射性物质进入体内后危害较大的原因是：","o":["α粒子穿透力强","α粒子半衰期长","α粒子带负电","α粒子电离密度大，能量集中沉积在局部组织"],"a":"D","e":"α粒子传能线密度高，内照射时局部组织损伤明显。"},{"id":1379,"ch":7,"t":"s","q":"职业照射中，四肢和皮肤的年当量剂量限值为：","o":["50 mSv","500 mSv","150 mSv","15 mSv"],"a":"B","e":"职业照射四肢和皮肤的年当量剂量限值为500 mSv。"},{"id":1380,"ch":7,"t":"s","q":"发生放射性污染事故时，现场设置警戒区的主要目的是：","o":["方便群众围观","加快放射性核素衰变","限制人员进入，防止污染扩散","替代个人防护用品"],"a":"C","e":"警戒区可限制无关人员进入，减少污染扩散和人员受照。"},{"id":1381,"ch":7,"t":"s","q":"放射性工作场所中，不需要专门防护手段但需进行经常性监测的区域称为：","o":["监督区","控制区","非限制区","生活区"],"a":"A","e":"监督区通常不需要专门防护手段，但需定期监测和必要的管理。"},{"id":1382,"ch":7,"t":"s","q":"转让放射性同位素时，使用单位应当：","o":["双方自行协商即可","只登记数量即可","口头报告即可","依法办理转让审批或备案手续"],"a":"D","e":"放射性同位素转让应依法办理审批或备案，接受监管部门管理。"},{"id":1383,"ch":7,"t":"s","q":"在放射性碘污染事故中，服用稳定性碘的主要作用是：","o":["加速碘的排出","减少甲状腺对放射性碘的吸收","中和放射性","屏蔽γ射线"],"a":"B","e":"稳定性碘可占据甲状腺摄取位点，减少放射性碘蓄积。"},{"id":1384,"ch":7,"t":"s","q":"皮肤受到放射性污染后，正确的处理方法是：","o":["用热水和硬毛刷用力刷洗","用有机溶剂反复擦洗","用温水和中性肥皂轻柔清洗","不予处理，等待自行衰减"],"a":"C","e":"轻柔清洗可去除污染，避免损伤皮肤而促进放射性物质吸收。"},{"id":1385,"ch":7,"t":"s","q":"非电离辐射中，微波的主要防护措施是：","o":["屏蔽和距离防护","戴铅眼镜","服用碘片","增加照射时间"],"a":"A","e":"微波可通过屏蔽和增大距离降低暴露水平。"},{"id":1386,"ch":7,"t":"s","q":"在辐射防护中，“屏蔽”的主要作用是：","o":["降低放射源的活度","缩短放射性核素半衰期","减少到达人员的射线强度","改变射线种类"],"a":"C","e":"屏蔽材料通过吸收或散射降低到达人员处的射线强度。"},{"id":1387,"ch":7,"t":"s","q":"使用放射性同位素的单位，依法应当取得","o":["排污许可证","辐射安全许可证","安全生产许可证","医疗器械经营许可证"],"a":"B","e":"使用放射性同位素必须依法取得辐射安全许可证。"},{"id":1388,"ch":7,"t":"s","q":"我国对放射源实行分类管理，其主要依据是","o":["放射源的外观尺寸","放射源的生产厂家","活度与潜在危害程度","使用人员的数量"],"a":"C","e":"放射源按活度及潜在危害程度分为不同类别实施管理。"},{"id":1389,"ch":7,"t":"s","q":"放射源台账管理最基本的要求是","o":["账物相符并动态更新","只登记新购入的放射源","每年清点一次即可","由使用人个人保存"],"a":"A","e":"台账应真实反映放射源数量和状态，做到账物相符、动态更新。"},{"id":1390,"ch":7,"t":"s","q":"转让放射性同位素，使用单位应当依法办理","o":["工商变更登记","税务登记","房屋租赁手续","审批或备案手续"],"a":"D","e":"放射性同位素转让须经审批或备案，不得擅自转让。"},{"id":1391,"ch":7,"t":"s","q":"放射源容器外表面的标识一般应标明","o":["使用人姓名和住址","核素名称、活度和编号","生产日期和保质期","运输车辆牌号"],"a":"B","e":"放射源容器标识应包含核素、活度和唯一编号等关键信息。"},{"id":1392,"ch":7,"t":"s","q":"放射源暂存场所应当","o":["与易燃品混合存放","设在人员密集区域","专用防盗并设警示","平时不上锁管理"],"a":"C","e":"放射源应存放在专用、防盗并设有警示标志的场所。"},{"id":1393,"ch":7,"t":"s","q":"不再使用的放射源，正确的处置方式是","o":["送贮或返回生产厂家","长期存放在使用场所","卖给废品收购站","自行拆解后掩埋"],"a":"A","e":"废弃放射源应送贮或返回生产厂家，不得自行处置。"},{"id":1394,"ch":7,"t":"s","q":"与放射源相比，X射线装置断电停止工作后","o":["仍持续发射X射线","变成开放型放射源","辐射剂量反而增大","不再产生X射线"],"a":"D","e":"X射线由装置通电产生，断电后即停止产生X射线。"},{"id":1395,"ch":7,"t":"s","q":"半衰期较短的放射性废液，常用的处理方法是","o":["直接排入下水道","露天晾晒蒸发","贮存一段时间使其衰变","与酸碱废液中和"],"a":"C","e":"短半衰期废液可贮存衰变，待活度降低后处理。"},{"id":1396,"ch":7,"t":"s","q":"放射性废液处理中，下列做法禁止的是","o":["直接排入下水道","贮存衰变处理","离子交换处理","蒸发浓缩处理"],"a":"A","e":"放射性废液直接排入下水道会造成环境污染，必须禁止。"},{"id":1397,"ch":7,"t":"s","q":"放射性废气排放前应当","o":["直接排入走廊","用风扇吹散","压缩后装袋","净化达标后排放"],"a":"D","e":"放射性废气须净化达标后经规定途径排放。"},{"id":1398,"ch":7,"t":"s","q":"放射性废物暂存时间较长时，最应当防止","o":["颜色发生变化","标签脱落或容器破损","重量明显减轻","气味逐渐散失"],"a":"B","e":"废物暂存期间应防止容器破损和标签脱落造成污染扩散。"},{"id":1399,"ch":7,"t":"s","q":"放射性废物暂存场所应当","o":["露天堆放废物","与食品同库储存","专用防渗防盗并设警示","设在地下室通道"],"a":"C","e":"废物暂存场所应专用、防渗、防盗并设置警示标志。"},{"id":1400,"ch":7,"t":"s","q":"经监测达到清洁解控水平的放射性废物，可以","o":["按普通废物处理","直接就地掩埋","直接露天焚烧","与生活垃圾混放"],"a":"A","e":"达到清洁解控水平并经批准后，可按普通废物处理。"},{"id":1401,"ch":7,"t":"s","q":"辐射工作场所中，需要采取专门防护手段和安全措施的区域是","o":["生活区","办公区","绿化区","控制区"],"a":"D","e":"控制区是可能受到显著照射、需要专门防护的区域。"},{"id":1402,"ch":7,"t":"s","q":"关于监督区，下列说法正确的是","o":["需要专门防护手段","不需专门防护但需监督","可以随意进入","不需要任何监测"],"a":"B","e":"监督区通常不需要专门防护手段，但需经常监督。"},{"id":1403,"ch":7,"t":"s","q":"控制区入口处应当设置","o":["普通办公告示","清洁卫生提示","警告标志和门禁","安全出口标志"],"a":"C","e":"控制区入口应设警告标志和门禁，限制无关人员进入。"},{"id":1404,"ch":7,"t":"s","q":"放射性实验室的地面和台面应","o":["光滑、无缝、易于去污","铺设普通地毯","留有缝隙便于排水","使用粗糙多孔材料"],"a":"A","e":"光滑无缝的表面便于去污，可减少放射性物质残留。"},{"id":1405,"ch":7,"t":"s","q":"操作开放型放射性物质时，应在","o":["普通实验台面上","实验室走廊内","普通办公室内","通风柜或手套箱"],"a":"D","e":"通风柜或手套箱可包容放射性气溶胶，防止内照射。"},{"id":1406,"ch":7,"t":"s","q":"放射性工作场所内，下列做法正确的是","o":["可以饮食","禁止饮食、饮水和化妆","可以存放食品","可以吸烟"],"a":"B","e":"放射性工作场所禁止饮食、饮水和化妆，防止放射性物质摄入。"},{"id":1407,"ch":7,"t":"s","q":"使用紫外线杀菌灯进行空气消毒时，正确的做法是","o":["人员留在室内观察","用眼睛直视灯管","人员离开房间并关闭门窗","缩短距离以提高效果"],"a":"C","e":"紫外线照射时人员必须离开，避免皮肤和眼睛受损。"},{"id":1408,"ch":7,"t":"s","q":"紫外线杀菌灯长时间工作时，室内可能积聚的有害气体是","o":["臭氧","氮气","二氧化碳","氦气"],"a":"A","e":"紫外线杀菌灯工作时会产生臭氧，应加强通风。"},{"id":1409,"ch":7,"t":"s","q":"过量紫外线照射眼睛可能引起","o":["近视","色盲","干眼症","电光性眼炎"],"a":"D","e":"紫外线过量照射可引起电光性眼炎。"},{"id":1410,"ch":7,"t":"s","q":"接触紫外线作业时，眼睛的防护应使用","o":["普通太阳镜","专用防紫外护目镜","无色玻璃片","不需要防护"],"a":"B","e":"普通太阳镜不能有效阻挡紫外线，应使用专用防护镜。"},{"id":1411,"ch":7,"t":"s","q":"选择激光防护眼镜的主要依据是","o":["眼镜颜色","镜架材质","激光波长和等级","眼镜价格"],"a":"C","e":"激光防护镜必须与激光波长和防护等级匹配。"},{"id":1412,"ch":7,"t":"s","q":"调整激光光路时，正确的做法是","o":["在尽可能低的功率下进行","在最大功率下进行","戴普通太阳镜即可","拆除所有防护罩"],"a":"A","e":"低功率调试可降低意外照射和灼伤风险。"},{"id":1413,"ch":7,"t":"s","q":"激光实验室的门联锁装置应在人员进入时","o":["提高激光功率","关闭通风系统","解除所有警示","切断或遮挡激光光路"],"a":"D","e":"门联锁可在人员进入时自动切断或遮挡激光光路。"},{"id":1414,"ch":7,"t":"s","q":"激光设备除光束外，还可能存在的重要伴生危害是","o":["只有光辐射","高压电击、火灾等","只有噪声","没有任何其他危害"],"a":"B","e":"激光设备的高压电源、冷却系统和光束均可造成伴生危害。"},{"id":1415,"ch":7,"t":"s","q":"发现放射源丢失、被盗，应当立即报告","o":["只报告本单位负责人","等待失主认领","公安和生态环境部门","当地物业公司"],"a":"C","e":"放射源丢失、被盗应立即报告公安和生态环境部门。"},{"id":1416,"ch":7,"t":"s","q":"发现来历不明、可能有放射性的物体时，应当","o":["远离并报告有关部门","用手触摸判断","装入口袋带走","用水冲洗后丢弃"],"a":"A","e":"不明物体可能为放射源，应远离并报告，不得徒手接触。"},{"id":1417,"ch":7,"t":"s","q":"人员怀疑自己受到放射性污染时，首先应当","o":["立即回家洗澡","继续完成实验","用手拍打衣服","离开污染区接受检测"],"a":"D","e":"人员可能受污染时应先离开污染区，接受检测和去污。"},{"id":1418,"ch":7,"t":"s","q":"放射性表面污染去污后，解除控制前必须","o":["喷洒香水掩盖气味","监测并确认合格","用清水冲一遍即可","等待一周自然衰减"],"a":"B","e":"去污后必须监测合格，才能解除控制。"},{"id":1419,"ch":7,"t":"s","q":"辐射事故现场设置警戒区的主要目的是","o":["方便媒体采访","保护设备财产","划分卫生责任","防止无关人员进入"],"a":"D","e":"警戒区用于防止无关人员进入，降低污染扩散风险。"},{"id":1420,"ch":7,"t":"s","q":"某放射源活度为3.7×10^4 Bq，下列关于该活度含义的表述，正确的是","o":["该源每千克受照物质每秒吸收3.7×10^4 J的辐射能量","该源每秒发生3.7×10^4次核衰变","该源在距其1 m处的剂量率为3.7×10^4 Gy/h","该源活度相当于3.7×10^4 Ci"],"a":"B","e":"Bq（贝可勒尔）是放射性活度单位，1 Bq=1次核衰变/秒，因此3.7×10^4 Bq表示该源每秒发生3.7×10^4次核衰变。Gy是吸收剂量单位（J/kg），Gy/h是剂量率单位；Ci是旧活度单位，3.7×10^4 Bq仅相当于1 μCi，远不是3.7×10^4 Ci。"},{"id":1421,"ch":7,"t":"s","q":"某点状γ放射源在0.5 m处产生的剂量率为D。若忽略空气和介质吸收，将探测器移至1.5 m处，该处剂量率约为","o":["D/3","D/6","D/9","D/12"],"a":"C","e":"点状源的外照射剂量率与距离的平方成反比。距离由0.5 m增至1.5 m，变为原来的3倍，剂量率变为原来的1/3^2=1/9，即约为D/9。这也是外照射防护中“距离防护”的定量依据。"},{"id":1422,"ch":7,"t":"s","q":"实验室使用32P（纯β发射体，β最大能量约1.71 MeV）进行标记实验，操作后对β射线及伴随的轫致辐射进行屏蔽，正确的做法是","o":["直接用厚铅罐屏蔽β射线，无需再加其他材料","用一张普通薄纸即可完全挡住β射线，无需屏蔽","先用石蜡屏蔽β射线，再用水层屏蔽轫致辐射","先用几毫米厚有机玻璃屏蔽β射线，再用铅屏蔽轫致辐射"],"a":"D","e":"32P的β射线能量较高，普通薄纸不能完全阻挡。β射线在铅等高原子序数材料中会大量产生轫致辐射，因此应先用几毫米厚有机玻璃等低原子序数材料挡住β射线，再用铅等屏蔽外层产生的轫致辐射。石蜡主要用于屏蔽中子，水层也不是屏蔽轫致辐射的规范选择。"},{"id":1423,"ch":7,"t":"m","q":"电离辐射包括（ ）","o":["α射线","紫外线","β射线","γ射线","中子流"],"a":"ACDE","e":"α、β、γ射线和中子流均能引起电离，紫外线属于非电离辐射。"},{"id":1424,"ch":7,"t":"m","q":"屏蔽γ射线可选用的材料有（ ）","o":["铅","有机玻璃","混凝土","铁"],"a":"ACD","e":"γ射线需要高密度或高原子序数材料屏蔽，有机玻璃主要用于β射线。"},{"id":1425,"ch":7,"t":"m","q":"内照射防护措施包括（ ）","o":["包容放射性物质","增大与源的距离","加强通风","防止经口摄入","及时表面去污"],"a":"ACDE","e":"内照射防护围绕阻断摄入途径，增大距离属于外照射防护。"},{"id":1426,"ch":7,"t":"m","q":"确定性效应可表现为（ ）","o":["恶性肿瘤","皮肤红斑","白内障","造血功能损伤"],"a":"BCD","e":"皮肤红斑、白内障和造血损伤有剂量阈值，恶性肿瘤属于随机性效应。"},{"id":1427,"ch":7,"t":"m","q":"常用于个人剂量监测的器件有（ ）","o":["热释光剂量计","表面污染仪","胶片剂量计","电子个人剂量计"],"a":"ACD","e":"热释光、胶片和电子剂量计均可用于个人累积剂量监测。"},{"id":1428,"ch":7,"t":"m","q":"放射性废物分类通常考虑的因素有（ ）","o":["活度浓度","核素半衰期","物理形态","化学毒性"],"a":"ABCD","e":"放射性废物按活度浓度、半衰期、形态和毒性等分类管理。"},{"id":1429,"ch":7,"t":"m","q":"放射源使用管理的要求包括（ ）","o":["取得许可","建立台账","设置警示标识","可自行转借"],"a":"ABC","e":"放射源实行许可和台账管理，严禁擅自转借或转让。"},{"id":1430,"ch":7,"t":"m","q":"紫外线防护措施包括（ ）","o":["设置遮光屏","涂抹普通润肤霜","佩戴防紫外护目镜","缩短暴露时间"],"a":"ACD","e":"遮光屏、专用护目镜和缩短暴露时间可有效减少紫外线伤害。"},{"id":1431,"ch":7,"t":"m","q":"激光安全操作要求包括（ ）","o":["佩戴匹配波长的防护镜","用眼睛直接观察光路","封闭光路","设置警示标识"],"a":"ACD","e":"激光操作应封闭光路、设置警示并佩戴与波长匹配的防护镜。"},{"id":1432,"ch":7,"t":"m","q":"微波与射频辐射的防护措施包括（ ）","o":["屏蔽","增大距离","缩短接触时间","加强场强监测"],"a":"ABCD","e":"屏蔽、距离、时间和监测是微波与射频防护的基本措施。"},{"id":1433,"ch":7,"t":"m","q":"辐射监测的内容包括（ ）","o":["个人剂量监测","工作场所剂量率监测","表面污染监测","凭嗅觉判断污染","环境介质监测"],"a":"ABCE","e":"辐射监测依靠仪器测量，不能凭感官判断放射性污染。"},{"id":1434,"ch":7,"t":"m","q":"辐射事故应急措施包括（ ）","o":["撤离无关人员","封锁现场","及时报告","开展监测与去污"],"a":"ABCD","e":"事故应急应优先撤离人员、控制现场并及时报告和处置。"},{"id":1435,"ch":7,"t":"m","q":"表面污染监测的对象包括（ ）","o":["工作台面","地面","设备表面","人员体表和衣物","空气中氡浓度"],"a":"ABCD","e":"表面污染监测针对物体和人体表面，空气氡浓度属于空气监测。"},{"id":1436,"ch":7,"t":"m","q":"下列措施中，属于外照射防护的有：","o":["缩短操作时间","增大与源的距离","设置屏蔽","加强通风","表面去污"],"a":"ABC","e":"外照射防护主要依靠时间、距离和屏蔽，通风与去污主要用于内照射防护。"},{"id":1437,"ch":7,"t":"m","q":"操作非密封放射性物质时，下列做法正确的有：","o":["在通风柜中进行","佩戴手套和口罩","在工作台面饮食","操作后检测表面污染","将废物丢入普通垃圾"],"a":"ABD","e":"非密封操作应在通风柜中进行，做好个人防护并监测污染，禁止饮食和随意丢弃废物。"},{"id":1438,"ch":7,"t":"m","q":"下列属于确定性效应表现的有：","o":["皮肤红斑","白内障","癌症发生概率增加","急性放射病"],"a":"ABD","e":"皮肤红斑、白内障和急性放射病均有阈值，属于确定性效应。"},{"id":1439,"ch":7,"t":"m","q":"关于辐射防护的基本原则，下列说法正确的有：","o":["实践的正当性要求权衡利弊","防护最优化要求将剂量保持在可合理达到的尽量低水平","个人剂量限值用于限制个人受照","剂量限值可以根据需要随意突破"],"a":"ABC","e":"辐射防护遵循实践正当性、防护最优化和个人剂量限值原则。"},{"id":1440,"ch":7,"t":"m","q":"常用的个人剂量计有：","o":["胶片剂量计","表面污染仪","热释光剂量计","光释光剂量计","电子个人剂量计"],"a":"ACDE","e":"胶片、热释光、光释光和电子剂量计均可用于个人累积剂量监测。"},{"id":1441,"ch":7,"t":"m","q":"表面放射性污染监测可采用的方法有：","o":["擦拭法取样","用剂量率仪直接测个人剂量","使用表面污染监测仪","对擦拭样品进行计数测量"],"a":"ACD","e":"表面污染监测通常先擦拭取样，再用污染仪或计数装置测量。"},{"id":1442,"ch":7,"t":"m","q":"关于剂量限值，下列说法正确的有：","o":["职业照射连续5年平均每年不超过20 mSv","公众照射每年不超过20 mSv","职业照射任何一年不超过50 mSv","公众照射每年不超过1 mSv","怀孕工作人员应保证胎儿剂量不超过1 mSv"],"a":"ACDE","e":"职业照射为5年均值20 mSv、单年50 mSv，公众为1 mSv，胎儿为1 mSv。"},{"id":1443,"ch":7,"t":"m","q":"放射性废物常用的处理方式有：","o":["随意排入下水道","衰变暂存","焚烧或压缩减容","固化后安全处置"],"a":"BCD","e":"放射性废物应按规定暂存、减容和固化处置，不得随意排放。"},{"id":1444,"ch":7,"t":"m","q":"辐射实验室的安全措施包括：","o":["划分控制区和监督区","设置电离辐射警告标志","配备个人防护用品","建立放射源台账","在实验室内饮食"],"a":"ABCD","e":"分区、标识、防护用品和台账管理均为辐射实验室的基本要求。"},{"id":1445,"ch":7,"t":"m","q":"紫外线的危害及防护措施包括：","o":["可引起皮肤红斑","可引起电光性眼炎","应佩戴防紫外线护目镜","可被普通玻璃完全阻挡，因此无需防护"],"a":"ABC","e":"紫外线可损伤皮肤和眼睛，应使用专用防护镜并减少暴露。"},{"id":1446,"ch":7,"t":"m","q":"激光的安全防护要求包括：","o":["激光属于电离辐射","可损伤视网膜","应避免直视激光束","应使用与波长匹配的防护镜"],"a":"BCD","e":"激光是非电离辐射，可损伤视网膜，需避免直视并使用匹配的防护镜。"},{"id":1447,"ch":7,"t":"m","q":"放射性物质泄漏事故的应急处理措施包括：","o":["立即撤离无关人员","向上风向转移","隐瞒事故自行处理","对污染人员进行去污","及时报告并封锁现场"],"a":"ABDE","e":"撤离、向上风向转移、去污和报告封锁均是正确处置措施。"},{"id":1448,"ch":7,"t":"m","q":"放射源管理的基本要求包括：","o":["办理辐射安全许可证","建立放射源台账","设置警示标识","可随意转借给外单位使用"],"a":"ABC","e":"放射源使用需许可、台账和标识管理，不得随意转借。"},{"id":1449,"ch":7,"t":"m","q":"关于β射线与物质的相互作用，下列说法正确的有：","o":["β射线是高速电子流","与高原子序数物质作用可产生轫致辐射","在空气中的射程比α射线长","β射线不需要任何屏蔽"],"a":"ABC","e":"β射线是高速电子流，与高原子序数物质作用易产生轫致辐射，其射程比α射线长但仍需屏蔽。"},{"id":1450,"ch":7,"t":"m","q":"放射源与射线装置许可管理的主要环节包括","o":["申领许可证","办理变更登记","有效期届满办理延续","将许可证转借他人"],"a":"ABC","e":"许可管理包括申领、变更和延续，许可证不得转借。"},{"id":1451,"ch":7,"t":"m","q":"放射性废物分类收集应当","o":["按核素种类分开","按半衰期分开","按活度水平分开","将不同废物混合收集"],"a":"ABC","e":"分类收集要求按核素、半衰期和活度分开，不得混合。"},{"id":1452,"ch":7,"t":"m","q":"下列场所中，通常应划为控制区的有","o":["放射源贮存库","射线装置照射室","普通办公室","职工食堂"],"a":"AB","e":"放射源库和照射室属于控制区，办公室和食堂不属于。"},{"id":1453,"ch":7,"t":"m","q":"紫外线消毒的安全管理措施包括","o":["照射时人员离开","设置警示或门联锁","加强通风","用眼睛观察灯管"],"a":"ABC","e":"人员离开、警示联锁和通风是紫外线消毒的基本安全措施。"},{"id":1454,"ch":7,"t":"m","q":"激光调试和操作的安全要求包括","o":["在低功率下调试","封闭光路","佩戴匹配的护目镜","用眼睛直视光束"],"a":"ABC","e":"低功率调试、封闭光路和匹配护目镜可有效降低激光风险。"},{"id":1455,"ch":7,"t":"m","q":"放射源丢失、被盗后，正确的处置措施有","o":["向公安和生态环境部门报告","保护现场","用仪器搜寻","徒手捡拾源"],"a":"ABC","e":"放射源丢失后应立即报告、保护现场并用仪器搜寻，不能徒手接触。"},{"id":1456,"ch":7,"t":"m","q":"放射源台账应当记录的内容包括","o":["核素名称","活度","源编号","存放位置"],"a":"ABCD","e":"台账应完整记录核素、活度、编号和存放位置等信息。"},{"id":1457,"ch":7,"t":"m","q":"开放型放射性实验室防止污染扩散的措施有","o":["在通风柜或手套箱内操作","采用湿式操作","及时去污","用干扫方式清理台面"],"a":"ABC","e":"通风柜、湿式操作和及时去污可防止污染扩散，干扫会扬尘。"},{"id":1458,"ch":7,"t":"m","q":"放射性废液常用的处理方法包括","o":["贮存衰变","离子交换","蒸发浓缩","直接排入下水道"],"a":"ABC","e":"废液可采用衰变、离子交换、蒸发等方法处理，禁止直排。"},{"id":1459,"ch":7,"t":"m","q":"电离辐射警告标志应设置在","o":["放射源存放处","射线装置机房入口","放射性废物暂存处","控制区入口"],"a":"ABCD","e":"放射源库、机房、废物暂存处和控制区入口均应设警告标志。"},{"id":1460,"ch":7,"t":"m","q":"进入放射性工作场所时，可使用的个人防护用品有","o":["铅围裙","铅玻璃眼镜","防护手套","凉鞋"],"a":"ABC","e":"铅围裙、铅玻璃眼镜和防护手套可提供防护，凉鞋不能。"},{"id":1461,"ch":7,"t":"m","q":"人员体表受到放射性污染后，正确的处理措施有","o":["脱去污染衣物","用温水清洗","进行污染监测","用力擦洗皮肤"],"a":"ABC","e":"人员污染后应脱去污染衣物、温水清洗并监测，不可用力擦洗。"},{"id":1462,"ch":7,"t":"m","q":"激光可能造成的危害包括","o":["眼损伤","皮肤灼伤","火灾","电击"],"a":"ABCD","e":"激光可损伤眼和皮肤，并可引发火灾及高压电击。"},{"id":1463,"ch":7,"t":"m","q":"关于实验室放射性废物的分类、暂存和处置，下列做法正确的是","o":["按核素种类和半衰期分别收集，容器外标明核素、活度、日期","短半衰期废液在专用衰变设施中放置足够长时间（一般不少于10个半衰期），经监测达到解控水平后再按普通废物处理","放射性废液可经大量自来水稀释后直接排入实验室下水道","废旧放射源应退回生产厂家或送有资质单位收贮，不得自行丢弃或转卖","放射性废物可与普通化学废物混装，以节省暂存空间"],"a":"ABD","e":"放射性废物必须按核素和半衰期分类收集，容器外标注核素、活度、日期等信息；短半衰期废物可放置衰变，一般经过不少于10个半衰期并监测达到解控水平后按普通废物处理；废旧放射源应交回生产厂家或送有资质单位收贮。稀释排放和与普通化学废物混装都是禁止的。"},{"id":1464,"ch":7,"t":"m","q":"在化学实验室使用激光光谱仪时，下列防护措施正确的是","o":["根据激光波长选用相应光密度（OD）的激光防护镜","调整光路时取下激光警示牌，以便观察光路是否畅通","尽可能封闭光路，减少杂散光和镜面反射","进入光路区前摘下手表、戒指等反光物品","用眼睛贴近光路观察激光是否出光"],"a":"ACD","e":"激光防护镜必须与所用激光波长匹配，并具有足够的光密度；光路应尽量封闭，减少杂散光和镜面反射；手表、戒指等反光物品可能把激光反射入眼，进入光路区前应摘下。激光警示牌在设备运行和调试期间都应保留，绝不能取下；用眼睛贴近光路观察激光是否出光属于严重违规操作。"},{"id":1465,"ch":7,"t":"j","q":"γ射线穿透能力强，通常需要用铅、混凝土等高密度材料屏蔽。","o":["对","错"],"a":"对","e":"γ射线为高能光子，需用高密度或高原子序数材料有效衰减。"},{"id":1466,"ch":7,"t":"j","q":"α粒子外照射对人体危害很大，因此α放射源必须用厚铅屏蔽。","o":["对","错"],"a":"错","e":"α射线穿透能力弱，纸张或皮肤即可阻挡，其主要危害来自内照射。"},{"id":1467,"ch":7,"t":"j","q":"对同一种核素，半衰期越长，放射性活度衰减越快。","o":["对","错"],"a":"错","e":"半衰期越长，核素衰变越慢，活度衰减也越慢。"},{"id":1468,"ch":7,"t":"j","q":"放射性活度1 Bq表示核素每秒发生一次衰变。","o":["对","错"],"a":"对","e":"贝可勒尔定义为每秒一次放射性衰变。"},{"id":1469,"ch":7,"t":"j","q":"吸收剂量和当量剂量的单位都是戈瑞。","o":["对","错"],"a":"错","e":"吸收剂量单位为戈瑞，当量剂量单位为希沃特。"},{"id":1470,"ch":7,"t":"j","q":"随机性效应存在剂量阈值。","o":["对","错"],"a":"错","e":"随机性效应无阈值，其发生概率随剂量增加而增大。"},{"id":1471,"ch":7,"t":"j","q":"确定性效应存在剂量阈值。","o":["对","错"],"a":"对","e":"确定性效应只有超过一定剂量阈值后才发生。"},{"id":1472,"ch":7,"t":"j","q":"公众照射的年有效剂量限值为1 mSv。","o":["对","错"],"a":"对","e":"公众照射年有效剂量限值通常按1 mSv控制。"},{"id":1473,"ch":7,"t":"j","q":"个人剂量计佩戴后可以随意取下或转借他人。","o":["对","错"],"a":"错","e":"个人剂量计应专人专用并按规定佩戴，不得随意取下或转借。"},{"id":1474,"ch":7,"t":"j","q":"电焊弧光中的紫外线可引起电光性眼炎。","o":["对","错"],"a":"对","e":"电焊弧光含较强紫外线，可损伤角膜和结膜。"},{"id":1475,"ch":7,"t":"j","q":"激光束亮度高，但短暂直视不会造成伤害。","o":["对","错"],"a":"错","e":"激光能量集中，短暂直视也可能造成视网膜不可逆损伤。"},{"id":1476,"ch":7,"t":"j","q":"微波和射频辐射的主要危害是电离作用。","o":["对","错"],"a":"错","e":"微波和射频属于非电离辐射，过量暴露以热效应为主。"},{"id":1477,"ch":7,"t":"j","q":"电离辐射警告标志为三叶形图案。","o":["对","错"],"a":"对","e":"三叶形是国际通用的电离辐射警告标志。"},{"id":1478,"ch":7,"t":"j","q":"放射性废物可以与普通实验垃圾一起丢弃。","o":["对","错"],"a":"错","e":"放射性废物必须分类收集并按规定处置，不得混入普通垃圾。"},{"id":1479,"ch":7,"t":"j","q":"对于点状放射源，距离增加一倍，剂量率约降为原来的四分之一。","o":["对","错"],"a":"对","e":"点源剂量率与距离平方成反比，距离加倍剂量率降为四分之一。"},{"id":1480,"ch":7,"t":"j","q":"只要通风良好，就可以在放射性工作场所内饮食。","o":["对","错"],"a":"错","e":"放射性工作场所禁止饮食，通风不能替代防止摄入的基本要求。"},{"id":1481,"ch":7,"t":"j","q":"放射性工作场所应设置明显的警示标识和中文警示说明。","o":["对","错"],"a":"对","e":"警示标识和中文说明是放射性工作场所的基本管理要求。"},{"id":1482,"ch":7,"t":"j","q":"放射性核素的衰变速度通常不受温度、压力等外界条件的显著影响。","o":["对","错"],"a":"对","e":"核衰变由原子核内部性质决定，通常不随温度、压力明显改变。"},{"id":1483,"ch":7,"t":"j","q":"α粒子穿透能力弱，一张纸即可将其阻挡。","o":["对","错"],"a":"对","e":"α粒子射程很短，纸张或皮肤表层即可有效阻挡。"},{"id":1484,"ch":7,"t":"j","q":"X射线和γ射线都是波长很短的电磁波，穿透能力较强。","o":["对","错"],"a":"对","e":"X射线和γ射线均不带电、波长短，可穿透较厚物质。"},{"id":1485,"ch":7,"t":"j","q":"对点状放射源，距离增大到原来的2倍，剂量率降为原来的1/4。","o":["对","错"],"a":"对","e":"点状源剂量率与距离平方成反比。"},{"id":1486,"ch":7,"t":"j","q":"屏蔽β射线时，应优先选用厚铅板。","o":["对","错"],"a":"错","e":"厚铅板会产生较强的轫致辐射，β射线宜先用低原子序数材料屏蔽。"},{"id":1487,"ch":7,"t":"j","q":"确定性效应具有剂量阈值，剂量越高后果越严重。","o":["对","错"],"a":"对","e":"确定性效应的严重程度随剂量增加而增加。"},{"id":1488,"ch":7,"t":"j","q":"随机性效应的严重程度与受照剂量成正比。","o":["对","错"],"a":"错","e":"随机性效应的严重程度与剂量无关，只有发生概率随剂量增加。"},{"id":1489,"ch":7,"t":"j","q":"职业照射连续5年平均有效剂量不应超过20 mSv。","o":["对","错"],"a":"对","e":"这是职业照射有效剂量的基本限值要求。"},{"id":1490,"ch":7,"t":"j","q":"公众照射有效剂量限值为每年20 mSv。","o":["对","错"],"a":"错","e":"公众照射有效剂量限值一般为每年1 mSv。"},{"id":1491,"ch":7,"t":"j","q":"个人剂量计通常佩戴在胸前，以代表全身受照剂量。","o":["对","错"],"a":"对","e":"胸前佩戴位置可较好反映躯干和全身的受照水平。"},{"id":1492,"ch":7,"t":"j","q":"胶片剂量计可以无限期佩戴，无需定期更换。","o":["对","错"],"a":"错","e":"胶片剂量计应按规定的监测周期更换和读数。"},{"id":1493,"ch":7,"t":"j","q":"表面放射性污染不能通过擦拭取样检测，只能凭肉眼判断。","o":["对","错"],"a":"错","e":"表面污染通常用擦拭法取样并结合仪器测量，肉眼无法判断。"},{"id":1494,"ch":7,"t":"j","q":"戴着手套就可以在放射性实验室内饮食。","o":["对","错"],"a":"错","e":"放射性实验室内禁止饮食，手套不能防止污染入口。"},{"id":1495,"ch":7,"t":"j","q":"通风柜可以长期存放放射性废物。","o":["对","错"],"a":"错","e":"通风柜是操作设施，不能兼作放射性废物长期存放场所。"},{"id":1496,"ch":7,"t":"j","q":"紫外线照射眼睛可引起电光性眼炎。","o":["对","错"],"a":"对","e":"紫外线可损伤角膜和结膜，引起电光性眼炎。"},{"id":1497,"ch":7,"t":"j","q":"激光防护镜只要颜色够深，就能防护所有波长的激光。","o":["对","错"],"a":"错","e":"激光防护镜必须与激光波长和功率匹配，颜色深浅不能作为依据。"},{"id":1498,"ch":7,"t":"j","q":"放射性废物可采用衰变暂存、固化等方式处理。","o":["对","错"],"a":"对","e":"衰变暂存和固化是放射性废物常用的处理处置方式。"},{"id":1499,"ch":7,"t":"j","q":"从事辐射工作的人员应接受辐射安全培训并取得相应资格。","o":["对","错"],"a":"对","e":"辐射工作人员需经培训考核，具备相应的安全防护知识。"},{"id":1500,"ch":7,"t":"j","q":"发现放射性污染后，应先离开现场，不必告知他人。","o":["对","错"],"a":"错","e":"发现污染应立即报告并采取警戒、去污等措施，不能隐瞒。"},{"id":1501,"ch":7,"t":"j","q":"辐射安全许可证可以转借给其他单位使用。","o":["对","错"],"a":"错","e":"许可证不得转借、转让，单位必须按许可范围开展活动。"},{"id":1502,"ch":7,"t":"j","q":"放射源使用单位应当做到台账与实物相符，并记录源的使用和转移情况。","o":["对","错"],"a":"对","e":"台账应账物相符，并记录使用、转移和处置情况。"},{"id":1503,"ch":7,"t":"j","q":"放射性废物暂存场所应当防渗、防盗并设置警示标志。","o":["对","错"],"a":"对","e":"暂存场所应防渗、防盗并设置警示标志，防止污染扩散。"},{"id":1504,"ch":7,"t":"j","q":"半衰期很短的放射性废物可先贮存衰变，监测达标后按普通废物处理。","o":["对","错"],"a":"对","e":"短半衰期废物可贮存衰变，监测达标后按规定解控。"},{"id":1505,"ch":7,"t":"j","q":"控制区是需要采取专门防护手段和安全措施的区域。","o":["对","错"],"a":"对","e":"控制区需要专门防护手段和安全措施。"},{"id":1506,"ch":7,"t":"j","q":"监督区通常不需要专门防护手段，但仍需经常监督。","o":["对","错"],"a":"对","e":"监督区通常不需要专门防护手段，但需经常监督。"},{"id":1507,"ch":7,"t":"j","q":"使用紫外线杀菌灯消毒时，人员可以在房间内短时间停留。","o":["对","错"],"a":"错","e":"紫外线照射时人员不得留在室内。"},{"id":1508,"ch":7,"t":"j","q":"紫外线杀菌灯产生的臭氧无害，因此不需要加强通风。","o":["对","错"],"a":"错","e":"臭氧有害，紫外线消毒时应加强通风。"},{"id":1509,"ch":7,"t":"j","q":"激光防护眼镜可以通用，不必根据激光波长选择。","o":["对","错"],"a":"错","e":"激光防护镜必须与波长匹配，不能通用。"},{"id":1510,"ch":7,"t":"j","q":"调整激光光路时，应把激光功率调到最大以便看清光路。","o":["对","错"],"a":"错","e":"激光调试应在尽可能低的功率下进行。"},{"id":1511,"ch":7,"t":"j","q":"发现放射源丢失后，应先自行寻找，找不到再报告有关部门。","o":["对","错"],"a":"错","e":"放射源丢失应立即报告，不得先自行寻找或隐瞒。"},{"id":1512,"ch":7,"t":"j","q":"发现来历不明的放射源，应立即远离并报告有关部门。","o":["对","错"],"a":"对","e":"不明放射源应远离并报告，不能徒手接触。"},{"id":1513,"ch":7,"t":"j","q":"放射性废液可以直接排入实验室下水道。","o":["对","错"],"a":"错","e":"放射性废液禁止直接排入下水道。"},{"id":1514,"ch":7,"t":"j","q":"放射性废物包装容器外表面应标明核素名称、活度和日期。","o":["对","错"],"a":"对","e":"废物容器应标明核素、活度和日期等信息。"},{"id":1515,"ch":7,"t":"j","q":"放射性表面污染去污应遵循由外向内、防止污染扩散的原则。","o":["对","错"],"a":"对","e":"去污应由外向内，防止污染范围扩大。"},{"id":1516,"ch":7,"t":"j","q":"放射性表面污染去污后，不经过监测就可以解除控制。","o":["对","错"],"a":"错","e":"去污后必须监测合格才能解除控制。"},{"id":1517,"ch":7,"t":"j","q":"辐射事故应急处理应优先撤离人员、封锁现场并及时报告。","o":["对","错"],"a":"对","e":"事故应急应优先撤离人员、封锁现场并报告。"},{"id":1518,"ch":7,"t":"j","q":"X射线装置断电停止工作后，仍会像放射源一样持续产生辐射。","o":["对","错"],"a":"错","e":"射线装置断电后不再产生X射线，不会像放射源持续辐射。"},{"id":1519,"ch":7,"t":"b","q":"α衰变后，原子核的质量数减少____，原子序数减少____。","a":["4","2"]},{"id":1520,"ch":7,"t":"b","q":"放射性活度随时间按____规律衰减。","a":["指数"]},{"id":1521,"ch":7,"t":"b","q":"每千克物质吸收1焦耳辐射能量时，吸收剂量为____Gy。","a":["1"]},{"id":1522,"ch":7,"t":"b","q":"希沃特与毫希沃特的换算关系为1 Sv＝____mSv。","a":["1000"]},{"id":1523,"ch":7,"t":"b","q":"β射线通常用____或铝板等低原子序数材料屏蔽。","a":["有机玻璃"]},{"id":1524,"ch":7,"t":"b","q":"放射性工作场所的台面和地面应光滑无缝，便于____。","a":["去污"]},{"id":1525,"ch":7,"t":"b","q":"个人剂量计通常佩戴在____部。","a":["胸"]},{"id":1526,"ch":7,"t":"b","q":"电离辐射警告标志的背景色为____。","a":["黄色"]},{"id":1527,"ch":7,"t":"b","q":"激光产品按危害程度分为____个等级。","a":["4"]},{"id":1528,"ch":7,"t":"b","q":"放射性工作场所分为控制区和____区。","a":["监督"]},{"id":1529,"ch":7,"t":"b","q":"操作开放型放射性物质应在____中进行。","a":["通风柜"]},{"id":1530,"ch":7,"t":"b","q":"放射性废物处理应遵循分类收集、____、固化、处置的原则。","a":["减容"]},{"id":1531,"ch":7,"t":"b","q":"外照射防护的三项基本原则是____、____和____。","a":["时间防护","距离防护","屏蔽防护"]},{"id":1532,"ch":7,"t":"b","q":"内照射防护中，应尽量将放射性物质限制在____系统内，并通过____降低空气中放射性浓度。","a":["密闭","通风"]},{"id":1533,"ch":7,"t":"b","q":"确定性效应具有剂量____，只有受照剂量超过该值时才可能发生。","a":["阈值"]},{"id":1534,"ch":7,"t":"b","q":"随机性效应的主要表现是____和____。","a":["癌症","遗传效应"]},{"id":1535,"ch":7,"t":"b","q":"职业照射连续5年的年平均有效剂量不超过____mSv。","a":["20"]},{"id":1536,"ch":7,"t":"b","q":"公众照射的年有效剂量限值为____mSv。","a":["1"]},{"id":1537,"ch":7,"t":"b","q":"有效剂量的单位符号是____，放射性活度的单位符号是____。","a":["Sv","Bq"]},{"id":1538,"ch":7,"t":"b","q":"个人剂量计一般佩戴在____部，用于估算全身有效剂量。","a":["胸"]},{"id":1539,"ch":7,"t":"b","q":"检查表面放射性污染常用的取样方法是____法。","a":["擦拭"]},{"id":1540,"ch":7,"t":"b","q":"放射性核素的活度减少到原来一半所需的时间称为____。","a":["半衰期"]},{"id":1541,"ch":7,"t":"b","q":"对放射性表面污染去污时，应按照从____污染区向____污染区逐步进行的原则，避免污染扩散。","a":["低","高"]},{"id":1542,"ch":7,"t":"b","q":"发生放射性物质泄漏时，人员应向____风向撤离。","a":["上"]},{"id":1543,"ch":7,"t":"b","q":"使用放射性同位素和射线装置的单位，应当依法取得辐射安全____。","a":["许可证"]},{"id":1544,"ch":7,"t":"b","q":"放射源台账管理应做到____相符，并动态更新。","a":["账物"]},{"id":1545,"ch":7,"t":"b","q":"转让放射性同位素，应当依法办理____或备案手续。","a":["审批"]},{"id":1546,"ch":7,"t":"b","q":"放射性废物应当____收集，不得随意混合。","a":["分类"]},{"id":1547,"ch":7,"t":"b","q":"半衰期较短的放射性废液可先贮存____。","a":["衰变"]},{"id":1548,"ch":7,"t":"b","q":"控制区入口应设置电离辐射____标志。","a":["警告"]},{"id":1549,"ch":7,"t":"b","q":"紫外线杀菌灯工作时会产生____，应加强通风。","a":["臭氧"]},{"id":1550,"ch":7,"t":"b","q":"过量紫外线照射眼睛可引起____眼炎。","a":["电光性"]},{"id":1551,"ch":7,"t":"b","q":"选择激光防护眼镜时，必须考虑激光的____。","a":["波长"]},{"id":1552,"ch":7,"t":"b","q":"调整激光光路应在尽可能____的功率下进行。","a":["低"]},{"id":1553,"ch":7,"t":"b","q":"放射性表面污染去污一般应遵循由____向内的原则。","a":["外"]},{"id":1554,"ch":7,"t":"x","q":"简述外照射防护的三原则及主要措施。","a":"1.时间防护：操作前做好准备和演练，尽量缩短在放射源附近的停留时间，多人轮流操作。2.距离防护：使用长柄夹具等工具，增大人员与放射源的距离；点源剂量率与距离平方成反比，增大距离可显著降低剂量。3.屏蔽防护：根据射线种类选择材料，α射线用纸张或手套即可阻挡，β射线用有机玻璃或铝板，γ射线和X射线用铅、混凝土等，中子用含氢丰富的水、石蜡等。4.综合运用三原则，并配合个人剂量监测。"},{"id":1555,"ch":7,"t":"x","q":"说明确定性效应与随机性效应的区别，并各举一例。","a":"1.确定性效应有剂量阈值，剂量超过阈值后效应发生率明显升高，严重程度随剂量增加而加重，例如皮肤红斑、白内障、造血功能损伤等。2.随机性效应没有剂量阈值，发生概率随剂量增加而增大，但严重程度与剂量无关，例如恶性肿瘤和遗传效应。3.防护上应通过剂量限值防止确定性效应发生，并遵循ALARA原则使随机性效应的发生概率尽量低。"},{"id":1556,"ch":7,"t":"x","q":"某实验室少量放射性溶液洒在工作台面，请说明应急处理步骤。","a":"1.立即停止操作，疏散无关人员，设置警戒区域，并报告实验室负责人和辐射安全管理部门。2.操作人员做好个人防护，佩戴手套、口罩和防护服。3.用吸水纸或吸附材料从污染区外缘向中心覆盖吸附，防止液体扩散，禁止干扫或用大量水冲洗。4.用表面污染监测仪确定污染范围并标记边界。5.用专用去污剂由外向内擦拭，直至污染水平符合要求，所用材料放入放射性废物容器。6.人员体表沾染时及时清洗并监测，最后填写事故记录并分析原因。"},{"id":1557,"ch":7,"t":"x","q":"简述外照射防护的三项基本原则，并说明各自的主要措施。","a":"1.时间防护：在满足工作需要的前提下尽量缩短操作时间，可通过预先演练、使用长柄工具和轮换作业减少受照时间。2.距离防护：尽量增大人员与放射源的距离，点状源剂量率随距离平方反比下降，可使用长柄夹具、机械手或远距离操作。3.屏蔽防护：在人与源之间设置合适屏蔽材料，α射线用纸张或薄层材料即可阻挡，β射线宜用有机玻璃等低原子序数材料，γ射线用铅、混凝土等高密度材料，中子用含氢材料。三者应综合应用。"},{"id":1558,"ch":7,"t":"x","q":"某实验室发生少量放射性溶液洒漏，污染了台面和操作人员手部。请写出应急处置和去污的主要步骤。","a":"1.立即停止操作，疏散无关人员，设置警戒并报告实验室负责人。2.开启通风，佩戴手套、口罩等防护用品，避免扬尘和污染扩大。3.用吸水纸或吸附材料从外围向中心覆盖吸附洒漏液，防止其流入下水道。4.对台面用温水和中性洗涤剂由外向内擦拭，反复更换擦拭材料，直至污染水平降至可接受范围。5.手部用温水和中性肥皂轻柔清洗，避免擦伤皮肤，必要时进行污染检测。6.将污染物、擦拭物放入放射性废物容器，标注核素和日期，按规定暂存处理。7.对现场进行表面污染监测，确认合格后方可恢复使用。"},{"id":1559,"ch":7,"t":"x","q":"简述放射性废物从产生到处置全过程的管理要求。","a":"1.分类收集：按核素种类、半衰期、活度水平和物态分别收集，容器外贴标签，注明核素、活度和日期。2.减量化：采取压实、去污等措施减少体积，但含放射性核素的废物不得随意焚烧。3.短半衰期废物可在专用设施中贮存衰变，监测达到清洁解控水平后按普通废物处理。4.长半衰期和高活度废物应送有资质的放射性废物处置单位，不得自行掩埋、丢弃或混入生活垃圾。5.废液可采用贮存衰变、离子交换、蒸发、过滤等方法处理，达标后排放。6.建立废物台账，交接转移有记录，防止丢失和污染扩散。"},{"id":1560,"ch":7,"t":"x","q":"简述放射源丢失、被盗事故的应急处置流程。","a":"1.立即报告：发现放射源丢失、被盗，现场人员应保护现场并向单位负责人、公安部门和生态环境部门报告。2.控制现场：设置警戒区，禁止无关人员进入，防止源被移动或破坏。3.调查搜寻：在专业人员指导下使用辐射监测仪器搜寻，不得徒手接触可疑物体。4.剂量评估：对可能受照人员进行个人剂量监测和医学观察。5.后续处理：找回源后检查其完整性并妥善存放；确认丢失的，按规定办理备案和补办手续。6.记录总结：如实记录事故经过、处置措施和监测结果，配合监管部门调查。"},{"id":1561,"ch":8,"t":"s","q":"关于破裂玻璃器皿的处理，正确做法是（ ）","o":["直接丢入普通垃圾桶","用手捡起较大碎片后丢弃","用镊子或扫帚簸箕收集后放入专用容器","用水冲入下水道"],"a":"C","e":"破碎玻璃应机械化收集并置于专用容器，避免割伤。"},{"id":1562,"ch":8,"t":"s","q":"判断玻璃器皿是否洗净，最可靠的观察指标是（ ）","o":["外壁光亮无水痕","内壁形成均匀水膜而不挂水珠","器皿完全干燥无水","洗后有洗涤剂泡沫"],"a":"B","e":"内壁不挂水珠是洗净的常用判据。"},{"id":1563,"ch":8,"t":"s","q":"下列玻璃器皿中，可直接置于火焰上加热的是（ ）","o":["量筒","容量瓶","试管","试剂瓶"],"a":"C","e":"试管可直接加热，量器类器皿不可加热。"},{"id":1564,"ch":8,"t":"s","q":"水浴加热所能达到的温度上限约为（ ）","o":["室温","80℃","150℃","100℃"],"a":"D","e":"常压水浴温度不超过水的沸点。"},{"id":1565,"ch":8,"t":"s","q":"油浴加热通常适用的温度范围是（ ）","o":["室温至100℃","100～250℃","300～400℃","400℃以上"],"a":"B","e":"油浴用于高于水浴而低于高温浴的场合，上限取决于油品。"},{"id":1566,"ch":8,"t":"s","q":"沙浴加热相对于水浴的突出特点是（ ）","o":["可获得较高温度且受热较均匀","升温速度最快","无需任何控温措施","只适用于低温操作"],"a":"A","e":"沙浴传热均匀且温度范围较宽。"},{"id":1567,"ch":8,"t":"s","q":"电热套最适合用于下列哪类加热场合（ ）","o":["精确控制低温","快速冷却反应体系","加热强腐蚀性固体","加热易燃液体"],"a":"D","e":"电热套无明火，适合易燃液体的加热。"},{"id":1568,"ch":8,"t":"s","q":"关于实验室明火使用的限制，正确的说法是（ ）","o":["任何实验均可使用明火","蒸馏易燃液体时可用明火直接加热","存在易燃蒸气的区域禁止使用明火","通风橱内可以随意使用明火"],"a":"C","e":"易燃蒸气与明火接触有着火爆炸风险。"},{"id":1569,"ch":8,"t":"s","q":"蒸馏装置中，温度计的水银球应放置在（ ）","o":["插入液面以下","置于冷凝管中部","置于接受瓶内部","位于蒸馏烧瓶支管口处"],"a":"D","e":"支管口处测得的是蒸出蒸气的温度。"},{"id":1570,"ch":8,"t":"s","q":"回流操作的主要目的是（ ）","o":["显著提高反应速率","使挥发物冷凝返回体系以减少损失","直接分离目标产物","降低反应体系温度"],"a":"B","e":"回流可避免溶剂和反应物挥发损失。"},{"id":1571,"ch":8,"t":"s","q":"蒸馏前向液体中加入沸石，其作用是（ ）","o":["提高液体沸点","防止暴沸","催化反应进行","增加产物产量"],"a":"B","e":"沸石提供气化中心，使沸腾平稳。"},{"id":1572,"ch":8,"t":"s","q":"下列关于蒸馏操作的叙述，错误的是（ ）","o":["装液量一般不超过烧瓶容积的三分之二","冷凝水应下进上出","结束时先停止加热再停冷凝水","沸腾过程中可随时补加沸石"],"a":"D","e":"沸腾时补加沸石会引发剧烈暴沸。"},{"id":1573,"ch":8,"t":"s","q":"用分液漏斗萃取振荡时，正确的放气时机是（ ）","o":["振荡几次后立即倒置旋开活塞放气","全部振荡结束后一次放气","静置分层后再放气","整个过程无需放气"],"a":"A","e":"少量多次放气可避免内压积聚。"},{"id":1574,"ch":8,"t":"s","q":"分液操作中，下层液体的正确取出方式是（ ）","o":["从上口直接倒出","用滴管逐滴吸出","从下口活塞放出","将漏斗整体倾斜倾出"],"a":"C","e":"下层液体由下口活塞放出，上层液体从上口倒出。"},{"id":1575,"ch":8,"t":"s","q":"选择萃取溶剂时，最关键的条件是（ ）","o":["与原溶剂互溶","与原溶剂不互溶且对溶质溶解度大","密度必须大于水","颜色浅且无毒"],"a":"B","e":"互不相溶与选择性溶解是萃取的基础。"},{"id":1576,"ch":8,"t":"s","q":"减压蒸馏相对于常压蒸馏的主要优势是（ ）","o":["显著加快蒸馏速度","提高产品产率","降低沸点避免高温分解","减少溶剂使用量"],"a":"C","e":"压力降低使沸点下降，适合热敏物质。"},{"id":1577,"ch":8,"t":"s","q":"减压蒸馏结束时的正确操作顺序是（ ）","o":["先关真空泵再移去热源","先移去热源，缓慢恢复常压后再停泵","同时关闭热源与真空泵","先拆下接受瓶再停真空泵"],"a":"B","e":"先撤热再缓慢破真空，最后停泵。"},{"id":1578,"ch":8,"t":"s","q":"使用真空泵时，为防止系统中的液体倒吸应设置（ ）","o":["分液漏斗","冷凝管","干燥塔","安全瓶（缓冲瓶）"],"a":"D","e":"安全瓶可截留倒吸液体，保护泵体。"},{"id":1579,"ch":8,"t":"s","q":"加压反应最关键的安全措施是（ ）","o":["选用厚壁玻璃器皿","装设压力表并设置防爆屏障","提高反应温度","大幅减少投料量"],"a":"B","e":"压力监测与物理防护是加压反应的基本要求。"},{"id":1580,"ch":8,"t":"s","q":"高压反应釜投料前必须完成的操作是（ ）","o":["先升温再检查","加入过量试剂以保证反应完全","检查密封与压力表并确认无泄漏","拆除安全阀以免误动作"],"a":"C","e":"投料前须确认密封可靠、仪表正常。"},{"id":1581,"ch":8,"t":"s","q":"向反应体系中导入气体时，防止倒吸的有效办法是（ ）","o":["尽可能加快通气速度","在导气管末端安装防倒吸装置","把反应液预先加热","把气体流量调至零"],"a":"B","e":"防倒吸装置可阻断液体回流。"},{"id":1582,"ch":8,"t":"s","q":"处理有毒尾气的规范做法是（ ）","o":["用合适的吸收液吸收后再排放","直接排入通风橱即可","点火燃烧后排放","收集在气球中存放"],"a":"A","e":"依据气体性质选择吸收液进行无害化处理。"},{"id":1583,"ch":8,"t":"s","q":"关于尾气吸收装置，下列说法错误的是（ ）","o":["氯化氢可用水或碱液吸收","可用倒扣漏斗防止倒吸","所有尾气都可用水有效吸收","吸收液应定期更换"],"a":"C","e":"不同气体溶解性差异大，不能一概用水吸收。"},{"id":1584,"ch":8,"t":"s","q":"使用分析天平称量时，正确的操作是（ ）","o":["直接用手取放砝码","把称量物直接放在秤盘上","使用称量纸或容器并避免手触砝码","在强通风处快速称量"],"a":"C","e":"砝码需专用工具夹取，样品不直接接触秤盘。"},{"id":1585,"ch":8,"t":"s","q":"取用固体试剂时，规范的做法是（ ）","o":["用药匙或镊子取用，剩余一般不放回原瓶","用手直接抓取","剩余试剂一律倒回原瓶以节约","用嘴吹去多余粉末"],"a":"A","e":"取用工具专用且剩余试剂不回瓶以防污染。"},{"id":1586,"ch":8,"t":"s","q":"实验室移取液体时，严厉禁止的操作是（ ）","o":["使用移液管","用口直接吸取","配合洗耳球操作","使用注射器转移"],"a":"B","e":"口吸可能误吸有毒或腐蚀性液体。"},{"id":1587,"ch":8,"t":"s","q":"使用移液管放液后，管尖残留的少量液体应（ ）","o":["用力吹出","甩出","加热赶出","按刻度要求使其自然流尽"],"a":"D","e":"普通移液管按自然流尽设计，不应随意吹出。"},{"id":1588,"ch":8,"t":"s","q":"磁力搅拌子在实验中的主要作用是（ ）","o":["对体系加热","使反应混合均匀","测量体系温度","代替沸石防止暴沸"],"a":"B","e":"搅拌子通过旋转带动液体混匀。"},{"id":1589,"ch":8,"t":"s","q":"控温实验中，温度计的正确放置方式是（ ）","o":["浸入液面以下且不接触容器壁","悬挂在容器外部","紧贴容器底部","悬停在液面上方"],"a":"A","e":"测得的应是反应液真实温度且避开器壁干扰。"},{"id":1590,"ch":8,"t":"s","q":"常压冰浴所能维持的温度约为（ ）","o":["-5℃","10℃","0℃","20℃"],"a":"C","e":"冰水混合物在常压下约为零摄氏度。"},{"id":1591,"ch":8,"t":"s","q":"实验室干冰浴通常可维持的温度约为（ ）","o":["0℃","-20℃","-78℃","-196℃"],"a":"C","e":"干冰在常压下升华温度约为负七十八摄氏度。"},{"id":1592,"ch":8,"t":"s","q":"关于液氮的使用，正确的说法是（ ）","o":["可以直接用手接触液氮","可与有机溶剂随意混合","可密封在玻璃容器中长期保存","应在通风良好处使用以防窒息"],"a":"D","e":"液氮汽化会置换氧气，须通风并防冻伤。"},{"id":1593,"ch":8,"t":"s","q":"重结晶后固体的常规干燥方法是（ ）","o":["真空干燥或自然晾干","用火焰直接烘烤","微波高温加热","加水煮沸"],"a":"A","e":"温和干燥可避免产品分解或熔化。"},{"id":1594,"ch":8,"t":"s","q":"抽滤（减压过滤）相对适合的应用场景是（ ）","o":["快速分离较多固体沉淀","需要保温的热过滤","分离胶体溶液","任何过滤场合"],"a":"A","e":"抽滤速度快，适合固体与母液的快速分离。"},{"id":1595,"ch":8,"t":"s","q":"离心操作中最重要的安全要求是（ ）","o":["尽量把离心管装满","启动即设为最高转速","配平并对称放置离心管","不必盖离心机盖"],"a":"C","e":"不平衡会造成剧烈振动甚至损坏转子。"},{"id":1596,"ch":8,"t":"s","q":"投料顺序的一般原则是（ ）","o":["先固后液，放热反应缓慢滴加","所有试剂一次快速加入","先加热再补加试剂","任意顺序均可"],"a":"A","e":"缓慢加料可控制放热速率。"},{"id":1597,"ch":8,"t":"s","q":"下列反应类型中，最需防范失控风险的是（ ）","o":["常温下的中和反应","食盐溶解","常压过滤","强放热且伴随产气的反应"],"a":"D","e":"放热与产气叠加易导致冲料或爆炸。"},{"id":1598,"ch":8,"t":"s","q":"在通风橱内进行实验时，柜门应保持（ ）","o":["完全打开","降至安全标线以下","完全密闭","随意放置"],"a":"B","e":"降低柜门可维持稳定面风速并保证捕集效率。"},{"id":1599,"ch":8,"t":"s","q":"用电热干燥箱烘干玻璃仪器时，合理的做法是","o":["设定越高温度越好，以缩短烘干时间","将带刻度的量器一同高温烘烤","依据仪器材质设定适宜温度，避免过热损坏","烘干结束后立即徒手取出热仪器"],"a":"C","e":"烘干温度应据材质合理设定，量器不宜高温烘烤，取热仪器需防烫伤。"},{"id":1600,"ch":8,"t":"s","q":"干燥氨气等碱性气体时，不宜选用的干燥剂是","o":["碱石灰","生石灰","固体氢氧化钠","浓硫酸"],"a":"D","e":"浓硫酸会与碱性气体氨反应，不能用于干燥氨气。"},{"id":1601,"ch":8,"t":"s","q":"常压过滤时，引流玻璃棒的下端应轻靠在","o":["三层滤纸的一侧","漏斗颈的内壁上","滤纸的上边缘","漏斗的外壁上"],"a":"A","e":"玻璃棒下端靠在三层滤纸一侧，可避免戳破滤纸。"},{"id":1602,"ch":8,"t":"s","q":"减压过滤结束时，正确的操作顺序是","o":["先关闭抽气泵，再拔下抽气连接管","先拔下抽气连接管使体系通大气，再关闭抽气泵","先取下布氏漏斗，再关闭抽气泵","无需先后顺序，任意操作即可"],"a":"B","e":"先通大气再关泵，可防止滤液倒吸。"},{"id":1603,"ch":8,"t":"s","q":"变色硅胶干燥剂吸湿失效后，其颜色变化为","o":["由白色变为蓝色","由粉红色变为蓝色","由蓝色变为绿色","由蓝色变为粉红色"],"a":"D","e":"变色硅胶吸湿后由蓝变粉红，提示需再生更换。"},{"id":1604,"ch":8,"t":"s","q":"重结晶中进行热过滤，其主要目的是","o":["使产品充分结晶析出","除去不溶性杂质并防止产品提前结晶","降低溶液温度便于过滤","增加溶剂的挥发损失"],"a":"B","e":"热过滤可在除去不溶物的同时避免产品过早析出堵塞滤纸。"},{"id":1605,"ch":8,"t":"s","q":"使用离心机时，对称位置上放置的离心管应当","o":["只要体积相同即可","质量大致平衡、相互对称","随意放置不影响结果","只在单侧放置样品管"],"a":"B","e":"离心管须对称平衡放置，否则转子失衡会损坏机器。"},{"id":1606,"ch":8,"t":"s","q":"离心分离样品时，盛装样品应选用","o":["与机型匹配并能承受相应转速的专用离心管","普通玻璃试管","实验室常用烧杯","量筒或量杯"],"a":"A","e":"普通玻璃器皿难以承受离心力，须用专用离心管。"},{"id":1607,"ch":8,"t":"s","q":"离心结束后，取放样品的正确时机是","o":["断电后立即开盖","运行途中随时可开盖","转子完全停止转动后再开盖","转子尚在转动时用手扶住取出"],"a":"C","e":"须待转子停稳再开盖，防止发生机械伤害。"},{"id":1608,"ch":8,"t":"s","q":"离心机启动前，必须确认","o":["机盖已盖好并锁紧","转子可自由晃动","盖板处于完全打开状态","样品管单侧放置"],"a":"A","e":"机盖盖好锁紧是离心机安全运行的基本前提。"},{"id":1609,"ch":8,"t":"s","q":"稀释浓硫酸时，正确的操作是","o":["将水沿器壁倒入浓硫酸中","将浓硫酸沿器壁缓慢加入水中并不断搅拌","将两者同时快速倒入同一容器","在密闭容器中混合后静置"],"a":"B","e":"应把浓硫酸加入水中并搅拌散热，切勿将水倒入酸中。"},{"id":1610,"ch":8,"t":"s","q":"对强放热反应进行投料时，合理的方式是","o":["将反应物一次性全部投入","关闭冷却以加快反应","缓慢分批加入并监测温度","尽量提高投料速度以缩短时间"],"a":"C","e":"缓慢分批加料并配合温度监测是控制放热的关键。"},{"id":1611,"ch":8,"t":"s","q":"使用球形冷凝管回流时，冷却水的流向应为","o":["上进下出","从冷凝管中部进入","进出水方向没有要求","下进上出，保证套管充满冷却水"],"a":"D","e":"冷却水下进上出才能使冷凝套管充满水、充分换热。"},{"id":1612,"ch":8,"t":"s","q":"进行强放热反应前，为控制温度应预先准备","o":["更高的加热功率","密闭的反应装置","大量的干燥剂","合适的冷却浴（如冰浴）和温度监测手段"],"a":"D","e":"预先备好冷却浴和测温手段才能及时抑制温升。"},{"id":1613,"ch":8,"t":"s","q":"明确会产生气体的反应，装置设计上必须避免","o":["使用冷凝管","缓慢滴加","持续搅拌","形成完全密闭的体系"],"a":"D","e":"密闭体系会因产气而超压，必须留有泄压或吸收通路。"},{"id":1614,"ch":8,"t":"s","q":"易发生剧烈聚合的单体在储存或反应时应特别注意","o":["避光、低温并按需添加阻聚剂","高温以促进聚合","密闭加压储存","与引发剂共同存放"],"a":"A","e":"避光、低温、加阻聚剂可抑制失控聚合。"},{"id":1615,"ch":8,"t":"s","q":"乙醚等醚类溶剂久置后可能生成具有爆炸性的","o":["醇类","酯类","过氧化物","醛类"],"a":"C","e":"醚类久置易生成过氧化物，受热或摩擦有爆炸风险。"},{"id":1616,"ch":8,"t":"s","q":"使用久置的醚类溶剂前，为安全起见应","o":["直接使用无需处理","先检验是否含过氧化物","加热蒸馏除去杂质","加入金属钠干燥"],"a":"B","e":"先检验过氧化物可避免蒸馏等操作引发爆炸。"},{"id":1617,"ch":8,"t":"s","q":"遇水会剧烈放热甚至燃烧的物质，储存和使用时应","o":["存放在潮湿环境","用水作为灭火剂","可与含水试剂混放","严格防潮、远离水源"],"a":"D","e":"遇水反应物质必须防潮避水，并选用合适灭火剂。"},{"id":1618,"ch":8,"t":"s","q":"手套箱用于无水无氧操作，其核心环境指标是","o":["箱内保持高氧高湿","箱内为真空状态","箱内温度保持恒定高温","水、氧含量维持在极低水平"],"a":"D","e":"手套箱通过维持极低的水氧含量保护敏感物质。"},{"id":1619,"ch":8,"t":"s","q":"Schlenk 操作中常用的保护气体是","o":["氧气","空气","氮气或氩气等惰性气体","二氧化碳"],"a":"C","e":"常用氮气或氩气等惰性气体排除空气与水分。"},{"id":1620,"ch":8,"t":"s","q":"Schlenk 技术的核心操作是","o":["反复抽真空并充入惰性气体","持续加热反应体系","用明火烘干仪器","敞口进行操作"],"a":"A","e":"抽真空—充惰性气体循环是 Schlenk 除氧除水的核心。"},{"id":1621,"ch":8,"t":"s","q":"对空气和水汽敏感的试剂，取用后应","o":["敞口放置在通风处","在惰性气体保护下密封保存","加水液封","与普通试剂一同存放"],"a":"B","e":"须在惰性气体保护下密封，隔绝空气和水汽。"},{"id":1622,"ch":8,"t":"s","q":"在通风橱内操作时，柜门（视窗）应","o":["尽量提升到最高以便观察","降至较低位置，仅留操作所需开口","完全取下","随意放置，与气流无关"],"a":"B","e":"柜门保持较低可维持面风速与捕集效果。"},{"id":1623,"ch":8,"t":"s","q":"通风橱的面风速若过低，直接后果是","o":["能耗增加","柜内温度降低","噪音增大","有害气体不能被有效捕集而外逸"],"a":"D","e":"面风速过低会使有害气体逸散到室内。"},{"id":1624,"ch":8,"t":"s","q":"关于通风橱的使用，下列做法正确的是","o":["长期把试剂瓶存放在柜内","把通风橱当作储物柜","保持柜内整洁，不存放无关物品","堆放杂物以节省空间"],"a":"C","e":"通风橱不得作长期储物之用，应保持整洁。"},{"id":1625,"ch":8,"t":"s","q":"在通风橱内操作，双手和器材应尽量","o":["贴近柜门开口处","位于距前缘一定距离的柜内深处","伸到柜外操作","先放在桌面再推入"],"a":"B","e":"在柜内一定深度操作有利于气流捕集有害气体。"},{"id":1626,"ch":8,"t":"s","q":"开始使用通风橱前，应先","o":["确认排风正常、气流指示有效","先堆放好所有试剂","关闭总电源","把柜门完全打开"],"a":"A","e":"使用前确认排风与气流状态是基本安全要求。"},{"id":1627,"ch":8,"t":"s","q":"实验区内正确的行为是","o":["在实验台旁进餐","用烧杯饮水","不在实验室存放和食用食品","边实验边吃零食"],"a":"C","e":"实验室内禁止饮食及存放食品。"},{"id":1628,"ch":8,"t":"s","q":"进入化学实验室，着装符合要求的是","o":["穿实验服和能覆盖脚面的鞋","穿拖鞋、凉鞋","穿露脚趾的鞋","赤脚"],"a":"A","e":"应穿实验服和不露趾的鞋，严禁拖鞋。"},{"id":1629,"ch":8,"t":"s","q":"进行危险性较高的实验时，正确做法是","o":["独自一人完成","至少两人在场或有人在旁监护","锁门独自操作以免打扰","安排在夜间独自进行"],"a":"B","e":"高危实验应有他人监护，禁止独自操作。"},{"id":1630,"ch":8,"t":"s","q":"反应需要过夜连续进行时，恰当的处理是","o":["无人值守直接离开","关闭所有安全设施","不记录、不告知他人","提前审批并做好安排、明确交接与监控"],"a":"D","e":"过夜反应须审批、交接并安排监控，不得无人值守。"},{"id":1631,"ch":8,"t":"s","q":"开展新实验前，了解试剂危害最直接的资料是","o":["安全技术说明书（SDS/MSDS）","小说的描述","网络传言","同事的口头经验"],"a":"A","e":"SDS/MSDS 是获取化学品危害信息的权威资料。"},{"id":1632,"ch":8,"t":"s","q":"取用后剩余的试剂，正确的处理方式是","o":["倒回原试剂瓶以免浪费","混入其他试剂瓶","按性质分类回收或按规定处理，不倒回原瓶","随意丢弃"],"a":"C","e":"剩余试剂不得倒回原瓶，应分类回收或按规定处理。"},{"id":1633,"ch":8,"t":"s","q":"关于实验记录，符合规范的是","o":["实验结束后凭记忆补写","只记录成功的实验数据","随意撕页重抄","及时、如实记录，修改处签名并保留原样"],"a":"D","e":"记录应及时真实，修改留痕，不得撕页或事后补记。"},{"id":1634,"ch":8,"t":"s","q":"移取液体时，绝对禁止的操作是","o":["使用移液管架","用洗耳球辅助","用嘴直接吸吮移液管","使用移液器"],"a":"C","e":"严禁用口吸吮移液管，须用洗耳球或移液器。"},{"id":1635,"ch":8,"t":"s","q":"用分液漏斗萃取振荡后，正确的操作是","o":["及时旋开活塞放气，释放内部压力","直接静置，无需处理","加热漏斗赶出气体","打开上盖持续振荡而不放气"],"a":"A","e":"振荡后须及时放气，防止内压骤增发生危险。"},{"id":1636,"ch":8,"t":"s","q":"检出含过氧化物的醚类溶剂，正确的处理是","o":["直接蒸馏至干","加热蒸发除去过氧化物","继续长期存放","按规定用还原剂处理或交由专业机构处置，切勿蒸干"],"a":"D","e":"含过氧化物严禁蒸干，应还原处理或专业处置。"},{"id":1637,"ch":8,"t":"s","q":"取用氢氟酸时，应选用的防护手套是","o":["一次性乳胶手套","普通棉纱手套","厚丁腈橡胶手套或氟橡胶手套","薄型PVC薄膜手套"],"a":"C","e":"氢氟酸能穿透普通乳胶手套并造成深层组织损伤，操作时须戴厚丁腈或氟橡胶手套。"},{"id":1638,"ch":8,"t":"m","q":"下列玻璃器皿中，不能用火焰直接加热的有（ ）","o":["量筒","容量瓶","蒸发皿","试剂瓶","试管"],"a":"ABD","e":"量器与试剂瓶受热易变形或破裂。"},{"id":1639,"ch":8,"t":"m","q":"关于玻璃器皿的洗涤，正确的做法有（ ）","o":["根据污物性质选择洗涤剂","以内壁不挂水珠作为洗净标准","必要时用待装液润洗","用毕及时清洗","将强酸与强碱混合后使用"],"a":"ABCD","e":"强酸强碱混合剧烈放热，十分危险。"},{"id":1640,"ch":8,"t":"m","q":"下列加热方式中，属于间接加热且无明火的有（ ）","o":["水浴","油浴","沙浴","电热套","酒精喷灯"],"a":"ABCD","e":"前四种均不产生明火，酒精喷灯属于明火加热。"},{"id":1641,"ch":8,"t":"m","q":"关于实验室明火的限制，正确的说法有（ ）","o":["蒸馏易燃液体时禁用明火","通风橱内可随意使用明火","可燃气体泄漏时禁用明火","实验结束须确认无残留火源","任何时候都可使用明火"],"a":"ACD","e":"通风橱内同样禁止无谓的明火操作。"},{"id":1642,"ch":8,"t":"m","q":"下列蒸馏操作要点中，正确的有（ ）","o":["冷凝水下进上出","加入沸石防止暴沸","装液量不超过烧瓶容积的三分之二","沸腾后可随时补加沸石","先通冷凝水再开始加热"],"a":"ABCE","e":"沸腾时补加沸石会诱发暴沸。"},{"id":1643,"ch":8,"t":"m","q":"回流操作的注意事项包括（ ）","o":["冷凝水下进上出","控制适宜的回流速度","装置需固定稳妥","体系必须完全密闭","保持冷却水管连接牢固"],"a":"ABCE","e":"回流体系必须与大气相通，严禁密闭。"},{"id":1644,"ch":8,"t":"m","q":"分液漏斗使用前应检查的项目有（ ）","o":["活塞是否漏液","上口塞子是否密合","玻璃有无破损裂纹","液体颜色是否透明","刻度是否清晰"],"a":"ABC","e":"密封性与完整性是分液漏斗检查重点。"},{"id":1645,"ch":8,"t":"m","q":"萃取振荡时放气的正确做法包括（ ）","o":["将漏斗倒置","旋开活塞进行放气","振荡几次即放气一次","放气口朝向无人处","用导管把气体排入室内"],"a":"ABCD","e":"放出的气体应排向安全区域而非室内。"},{"id":1646,"ch":8,"t":"m","q":"典型的减压蒸馏系统通常包括（ ）","o":["真空泵","缓冲瓶","冷凝管","真空表","分液漏斗"],"a":"ABCD","e":"分液漏斗不属于减压蒸馏的必配装置。"},{"id":1647,"ch":8,"t":"m","q":"真空操作的安全要点包括（ ）","o":["设置安全瓶防止倒吸","缓慢调节真空度","玻璃器皿应能承受压差","突然破坏真空以加快操作","结束时先通大气再停泵"],"a":"ABCE","e":"骤然破真空易引起冲料和器皿损坏。"},{"id":1648,"ch":8,"t":"m","q":"加压反应应采取的安全措施有（ ）","o":["安装压力表","设置防爆挡板","事先检查密封性","超压运行以提高效率","使用合格的反应釜"],"a":"ABCE","e":"严禁超压运行。"},{"id":1649,"ch":8,"t":"m","q":"关于尾气处理，正确的做法有（ ）","o":["有毒气体用吸收液吸收","按气体性质选择吸收剂","装置应设置防倒吸措施","直接排入实验室室内","定期更换吸收液"],"a":"ABCE","e":"尾气不得直接排入室内。"},{"id":1650,"ch":8,"t":"m","q":"关于移液操作，正确的有（ ）","o":["严禁用口吸取","配合洗耳球操作","移液管可随意平放在桌面","读数时视线与液面平齐","使用完毕后及时清洗"],"a":"ABDE","e":"移液管应架空放置，避免污染和滚动。"},{"id":1651,"ch":8,"t":"m","q":"关于冷却介质，正确的说法有（ ）","o":["冰浴约为0℃","干冰浴约为-78℃","液氮约为-196℃","液氮可密封在玻璃瓶中保存","使用低温介质需防冻伤"],"a":"ABCE","e":"液氮严禁密封，否则汽化会导致爆炸。"},{"id":1652,"ch":8,"t":"m","q":"搅拌与控温的正确做法有（ ）","o":["搅拌子尺寸与容器匹配","温度计浸入液面以下","温度计紧贴容器底部","剧烈放热时控速滴加","搅拌速度越快越好"],"a":"ABD","e":"温度计不应接触器壁或器底，搅拌速度按需选择。"},{"id":1653,"ch":8,"t":"m","q":"通风橱的正确使用方式包括（ ）","o":["柜门降至安全线以下","不在柜内长期存放试剂","保持合格的面风速","离开时不必关小柜门","所有操作尽量在柜内进行"],"a":"ABCE","e":"实验结束应将柜门关小以维持实验室气流稳定。"},{"id":1654,"ch":8,"t":"m","q":"关于干燥操作，下列说法正确的有","o":["干燥剂应与被干燥物质不发生反应","所有物质都适合高温烘干","变色硅胶失效后可通过烘干再生","浓硫酸可安全干燥碱性气体氨气"],"a":"AC","e":"干燥剂须不与物料反应；变色硅胶可再生，但并非所有物质都耐高温，浓硫酸不能干燥氨。"},{"id":1655,"ch":8,"t":"m","q":"减压过滤（抽滤）操作中，正确的做法包括","o":["抽滤结束先关泵再拔管","布氏漏斗内滤纸应润湿并贴紧","可用普通玻璃漏斗代替布氏漏斗进行抽滤","结束时先通大气再关闭抽气泵"],"a":"BD","e":"滤纸润湿贴紧、结束先通大气再关泵；反过来易倒吸，普通漏斗不能用于抽滤。"},{"id":1656,"ch":8,"t":"m","q":"使用离心机的安全要点包括","o":["离心管对称平衡放置","盖好机盖后再启动","运行中可开盖观察分离情况","转子未停可用手制动","转子停稳后再开盖取管"],"a":"ABE","e":"对称平衡、盖好盖、停稳再开盖；运行中开盖或用手制动都十分危险。"},{"id":1657,"ch":8,"t":"m","q":"控制强放热反应的措施有","o":["一次性快速投料以缩短时间","缓慢滴加反应物","保持有效搅拌","配置冷却浴并监测温度"],"a":"BCD","e":"缓慢滴加、搅拌与冷却测温可控制放热，快速投料会导致失控。"},{"id":1658,"ch":8,"t":"m","q":"下列属于危险反应异常信号或特征的有","o":["温度异常快速上升","大量气体或泡沫产生","反应平稳、温度恒定","体系冒烟或颜色剧烈变化"],"a":"ABD","e":"温升失控、产气冒烟和剧烈变色都是危险信号，平稳状态不是。"},{"id":1659,"ch":8,"t":"m","q":"关于醚类过氧化物，说法正确的有","o":["久置醚类可能生成过氧化物","蒸馏至干可安全去除过氧化物","使用前应检验并去除","过氧化物性质稳定、毫无危险"],"a":"AC","e":"醚类久置生成过氧化物，使用前须检验去除，蒸干有爆炸风险。"},{"id":1660,"ch":8,"t":"m","q":"无水无氧操作要点包括","o":["手套箱内水氧含量维持极低","Schlenk 线通过抽真空—充气循环除氧除水","可用空气直接置换体系","常用氮气或氩气作保护气","保护气中氧气含量越高越好"],"a":"ABD","e":"水氧含量极低、抽真空充气循环、惰性气体保护是关键，空气与富氧均不适用。"},{"id":1661,"ch":8,"t":"m","q":"关于实验室行为规范，说法正确的有","o":["实验室内禁止饮食","可穿拖鞋进入实验室","可独自进行高危实验","过夜反应需审批并安排值守"],"a":"AD","e":"禁止饮食、禁止拖鞋、禁止独自高危实验，过夜反应须审批值守。"},{"id":1662,"ch":8,"t":"m","q":"实验前的充分准备包括","o":["查阅试剂安全技术说明书","熟悉反应可能的危害","检查并确认应急设施可用","制定异常情况的处置预案"],"a":"ABCD","e":"查 SDS、辨识危害、确认应急设施并制定预案，都是实验前应做的准备。"},{"id":1663,"ch":8,"t":"m","q":"关于试剂取用，说法正确的有","o":["取用后剩余试剂应倒回原瓶","取用工具应专用、洁净","试剂瓶标签应清晰完整","不同试剂可共用同一支滴管"],"a":"BC","e":"工具专用洁净、标签清晰；剩余试剂不得倒回原瓶，滴管不可混用。"},{"id":1664,"ch":8,"t":"m","q":"关于实验记录与交接，符合规范的有","o":["实验记录应及时、真实","数据可随意涂改或撕页重抄","过夜反应无需交接","交接时应说明反应状态与注意事项"],"a":"AD","e":"记录及时真实、交接清楚；涂改撕页和不交接都不符合规范。"},{"id":1665,"ch":8,"t":"m","q":"关于实验废液与剩余试剂的处理，正确的有","o":["废液应分类收集","剩余试剂可随意倒入下水道","剧毒废液按规定专门处理","不同废液可混合存放以节省空间","废液容器应贴好标签"],"a":"ACE","e":"废液分类收集、贴标签，剧毒废液专门处理；不得随意倾倒或混放。"},{"id":1666,"ch":8,"t":"m","q":"关于玻璃器皿的安全使用，说法正确的有","o":["破损玻璃器皿可继续使用","玻璃仪器破裂应及时清理并妥善处置","可用嘴直接吹扫玻璃碎屑","发生玻璃割伤应及时处理并报告"],"a":"BD","e":"破损器皿应清理处置，割伤须及时处理报告，不可用嘴吹碎屑。"},{"id":1667,"ch":8,"t":"m","q":"关于实验室加热方式，说法正确的有","o":["易燃溶剂避免明火，宜用水浴或电热套","油浴使用需注意温度与油品闪点","加热套应匹配容器大小","加热过程中可长时间无人值守看管"],"a":"ABC","e":"易燃物忌明火、油浴注意闪点、加热套匹配容器；加热时不能无人值守。"},{"id":1668,"ch":8,"t":"m","q":"关于化学实验室通风橱的使用，下列说法正确的有：","o":["普通通风橱正常工作时的面风速一般应维持在约0.5 m/s","柜内应尽量少堆放试剂瓶和仪器，以免阻碍气流、形成涡流","操作时玻璃视窗应尽量放低，人的头部不要伸入柜内","通风橱可以代替试剂柜，长期存放挥发性有机溶剂","柜内发生少量有毒气体泄漏时，应立即关掉风机以阻止气体外逸"],"a":"ABC","e":"通风橱面风速一般控制在0.4～0.6 m/s，约0.5 m/s，风速过高会形成涡流、过低则捕集能力不足；柜内堆放物品会扰乱气流并在柜内形成污染死角，故应保持整洁、少堆物；操作时视窗越低、人员头部越靠外，暴露风险越小。通风橱是操作设备而非储存设备，不得长期存放挥发性试剂；一旦柜内泄漏有毒气体，应保持风机继续运行把气体排出，人员撤离并报告，贸然关机会使有毒气体在柜内积聚甚至外溢。"},{"id":1669,"ch":8,"t":"j","q":"试管可以直接在酒精灯火焰上加热。","o":["对","错"],"a":"对","e":"试管属于可直接加热的玻璃器皿。"},{"id":1670,"ch":8,"t":"j","q":"量筒可用于准确配制一定物质的量浓度的溶液。","o":["对","错"],"a":"错","e":"量筒精度不足，配制溶液应使用容量瓶。"},{"id":1671,"ch":8,"t":"j","q":"玻璃器皿洗净后，内壁应形成均匀水膜而不聚成水珠。","o":["对","错"],"a":"对","e":"这是判断洗净的常用标准。"},{"id":1672,"ch":8,"t":"j","q":"破碎的玻璃器皿可直接丢入普通垃圾袋。","o":["对","错"],"a":"错","e":"应收集于专用容器并标识，防止扎伤清理人员。"},{"id":1673,"ch":8,"t":"j","q":"蒸馏低沸点易燃溶剂时，可用酒精灯直接加热烧瓶。","o":["对","错"],"a":"错","e":"易燃蒸气遇明火可能燃烧爆炸。"},{"id":1674,"ch":8,"t":"j","q":"冷凝水采取下进上出的方式，有利于冷凝管夹层充满冷却水。","o":["对","错"],"a":"对","e":"下进上出可避免夹层内出现气袋。"},{"id":1675,"ch":8,"t":"j","q":"蒸馏途中发现忘记加沸石，可立即打开瓶塞补加。","o":["对","错"],"a":"错","e":"热液中补加沸石会引发剧烈暴沸，须冷却后再加。"},{"id":1676,"ch":8,"t":"j","q":"回流装置中冷凝管上端应与大气相通，不得密闭。","o":["对","错"],"a":"对","e":"密闭加热会导致压力升高发生危险。"},{"id":1677,"ch":8,"t":"j","q":"用分液漏斗振荡萃取时，无需进行放气操作。","o":["对","错"],"a":"错","e":"振荡会使内压升高，必须及时放气。"},{"id":1678,"ch":8,"t":"j","q":"分液时，静置分层后应先打开上口塞子再放出下层液体。","o":["对","错"],"a":"对","e":"打开上口塞可使内外气压平衡，便于液体流出。"},{"id":1679,"ch":8,"t":"j","q":"减压蒸馏通过降低体系压力使沸点下降，适合热不稳定物质。","o":["对","错"],"a":"对","e":"降低沸点可减少高温分解。"},{"id":1680,"ch":8,"t":"j","q":"真空系统中设置缓冲瓶有助于防止液体倒吸入泵。","o":["对","错"],"a":"对","e":"缓冲瓶能截留倒吸液体。"},{"id":1681,"ch":8,"t":"j","q":"加压反应可在普通锥形瓶中密闭进行。","o":["对","错"],"a":"错","e":"须使用耐压反应釜并设防护。"},{"id":1682,"ch":8,"t":"j","q":"吸收有毒尾气的装置应考虑防倒吸措施。","o":["对","错"],"a":"对","e":"停气或冷却时易发生倒吸。"},{"id":1683,"ch":8,"t":"j","q":"移液时可用口吸来调整液面至刻度线。","o":["对","错"],"a":"错","e":"严禁用口吸取任何化学液体。"},{"id":1684,"ch":8,"t":"j","q":"称量易吸湿的样品时，应尽量缩短其暴露在空气中的时间。","o":["对","错"],"a":"对","e":"可减少吸水对称量结果的影响。"},{"id":1685,"ch":8,"t":"j","q":"操作液氮时应佩戴低温防护手套和护目镜。","o":["对","错"],"a":"对","e":"液氮可造成严重冻伤。"},{"id":1686,"ch":8,"t":"j","q":"干冰温度很低，可用手直接抓取以方便取用。","o":["对","错"],"a":"错","e":"干冰会造成冻伤，应使用工具并戴手套。"},{"id":1687,"ch":8,"t":"j","q":"离心时只要离心管对称放置，就不必严格配平。","o":["对","错"],"a":"错","e":"质量不平衡会引起剧烈振动甚至损坏设备。"},{"id":1688,"ch":8,"t":"j","q":"搅拌有助于传热，可缓解反应体系局部过热。","o":["对","错"],"a":"对","e":"搅拌使温度分布更均匀。"},{"id":1689,"ch":8,"t":"j","q":"通风橱内可长期存放大量试剂以便取用。","o":["对","错"],"a":"错","e":"柜内长期堆放会扰乱气流并增加风险。"},{"id":1690,"ch":8,"t":"j","q":"通风橱的柜门开得越高，对有害气体的捕集效果越好。","o":["对","错"],"a":"错","e":"柜门应尽量降低以维持面风速和捕集效果。"},{"id":1691,"ch":8,"t":"j","q":"离心机转子尚未完全停止即可开盖取放样品管。","o":["对","错"],"a":"错","e":"须待转子完全停稳后再开盖。"},{"id":1692,"ch":8,"t":"j","q":"稀释浓硫酸时，应把浓硫酸沿器壁缓慢加入水中并不断搅拌。","o":["对","错"],"a":"对","e":"酸入水并搅拌可及时散热，防止飞溅。"},{"id":1693,"ch":8,"t":"j","q":"久置的乙醚可不经检验直接蒸馏至干。","o":["对","错"],"a":"错","e":"久置醚类须先检验过氧化物，严禁蒸干。"},{"id":1694,"ch":8,"t":"j","q":"手套箱内水和氧的含量越低，越有利于保护空气敏感物质。","o":["对","错"],"a":"对","e":"低水低氧环境是无水无氧操作的核心要求。"},{"id":1695,"ch":8,"t":"j","q":"实验室内可以在不妨碍他人的前提下进食或饮水。","o":["对","错"],"a":"错","e":"实验室内一律禁止饮食和存放食品。"},{"id":1696,"ch":8,"t":"j","q":"减压过滤结束时先使体系与大气相通再关泵，可防止滤液倒吸。","o":["对","错"],"a":"对","e":"先通大气再关泵是防止倒吸的正确顺序。"},{"id":1697,"ch":8,"t":"j","q":"取用后剩余的试剂，为节约起见应倒回原试剂瓶。","o":["对","错"],"a":"错","e":"剩余试剂不得倒回原瓶，以免污染整瓶试剂。"},{"id":1698,"ch":8,"t":"j","q":"强放热反应可通过缓慢滴加并配合冷却来控制温升。","o":["对","错"],"a":"对","e":"控制加料速度与冷却是抑制温升的有效手段。"},{"id":1699,"ch":8,"t":"j","q":"产生大量气体的反应可以在完全密闭的装置中进行。","o":["对","错"],"a":"错","e":"密闭体系会因产气超压，必须留有泄压通路。"},{"id":1700,"ch":8,"t":"j","q":"实验记录应及时如实书写，修改处签名并保留原记录。","o":["对","错"],"a":"对","e":"记录修改留痕、保留原样是基本规范。"},{"id":1701,"ch":8,"t":"j","q":"穿拖鞋进入化学实验室是允许的。","o":["对","错"],"a":"错","e":"实验室禁止穿拖鞋等露趾鞋。"},{"id":1702,"ch":8,"t":"j","q":"Schlenk 技术通过反复抽真空与充惰性气体来排除空气和水分。","o":["对","错"],"a":"对","e":"抽真空—充惰性气体循环是其核心操作。"},{"id":1703,"ch":8,"t":"j","q":"通风橱内可以长期存放试剂和杂物。","o":["对","错"],"a":"错","e":"通风橱不得作储物用，应保持整洁。"},{"id":1704,"ch":8,"t":"j","q":"进行高危实验时，应有他人在场或监护，不宜独自操作。","o":["对","错"],"a":"对","e":"高危实验须有人监护，禁止单人操作。"},{"id":1705,"ch":8,"t":"j","q":"分液漏斗振荡萃取后无需放气，直接静置分层即可。","o":["对","错"],"a":"错","e":"振荡后须及时放气释放内压。"},{"id":1706,"ch":8,"t":"j","q":"遇水剧烈反应的物质应远离水源并防潮保存。","o":["对","错"],"a":"对","e":"防潮避水是此类物质储存使用的基本要求。"},{"id":1707,"ch":8,"t":"j","q":"需要过夜的连续反应可以无人值守，只要反应顺利启动即可。","o":["对","错"],"a":"错","e":"过夜反应须审批并安排人员值守监控。"},{"id":1708,"ch":8,"t":"j","q":"变色硅胶由蓝色变为粉红色，表明其已吸湿失效。","o":["对","错"],"a":"对","e":"蓝变粉红说明硅胶吸湿，需要再生或更换。"},{"id":1709,"ch":8,"t":"j","q":"易聚合单体应避光、低温保存，必要时加入阻聚剂。","o":["对","错"],"a":"对","e":"避光、低温、阻聚剂可抑制失控聚合。"},{"id":1710,"ch":8,"t":"b","q":"玻璃器皿洗净的标准是内壁形成均匀的____而不聚成水珠。","a":["水膜"]},{"id":1711,"ch":8,"t":"b","q":"常压水浴加热的温度上限一般不超过____℃。","a":["100"]},{"id":1712,"ch":8,"t":"b","q":"冷凝水应从冷凝管的____口进入、从____口流出。","a":["下","上"]},{"id":1713,"ch":8,"t":"b","q":"蒸馏前向液体中加入沸石，目的是防止____。","a":["暴沸"]},{"id":1714,"ch":8,"t":"b","q":"用分液漏斗振荡萃取后，必须及时____，以免内压升高。","a":["放气"]},{"id":1715,"ch":8,"t":"b","q":"减压蒸馏是通过降低体系压力使液体的____下降。","a":["沸点"]},{"id":1716,"ch":8,"t":"b","q":"真空泵前设置的、兼具缓冲与防倒吸作用的容器称为安全瓶，也称____。","a":["缓冲瓶"]},{"id":1717,"ch":8,"t":"b","q":"实验室移取液体时严禁用____吸取。","a":["口"]},{"id":1718,"ch":8,"t":"b","q":"常压冰浴所能维持的温度约为____℃。","a":["0"]},{"id":1719,"ch":8,"t":"b","q":"干冰在常压下的升华温度约为____℃。","a":["-78"]},{"id":1720,"ch":8,"t":"b","q":"实验中取用后剩余的试剂一般____放回原试剂瓶。","a":["不得"]},{"id":1721,"ch":8,"t":"b","q":"使用通风橱时，柜门应降至____以下。","a":["安全标线"]},{"id":1722,"ch":8,"t":"b","q":"变色硅胶吸水后由____色变为____色，表明其已失效。","a":["蓝","粉红"],"e":"蓝变粉红提示吸湿失效。"},{"id":1723,"ch":8,"t":"b","q":"使用离心机时，对称位置的离心管必须____，以防止转子失衡。","a":["配平"],"e":"离心前须对称配平。"},{"id":1724,"ch":8,"t":"b","q":"减压过滤结束时，应先把体系____，再关闭抽气泵，以防倒吸。","a":["通大气"],"e":"先通大气再关泵。"},{"id":1725,"ch":8,"t":"b","q":"实验室中禁止用____直接吸取液体试剂。","a":["嘴"],"e":"严禁用口吸，须用洗耳球或移液器。"},{"id":1726,"ch":8,"t":"b","q":"乙醚等醚类溶剂久置后可能产生爆炸性的____，使用前应检验。","a":["过氧化物"],"e":"醚类久置易生过氧化物。"},{"id":1727,"ch":8,"t":"b","q":"典型手套箱中，水和氧的含量需维持在____水平。","a":["极低"],"e":"定性描述，具体数值依设备而定。"},{"id":1728,"ch":8,"t":"b","q":"Schlenk 操作通过反复____和充入惰性气体来除去空气与水分。","a":["抽真空"],"e":"抽真空—充气循环。"},{"id":1729,"ch":8,"t":"b","q":"在通风橱内操作时，柜门（视窗）应尽量保持____高度。","a":["较低"],"e":"低柜门保证面风速。"},{"id":1730,"ch":8,"t":"b","q":"处理强放热反应，常通过____的方式加入反应物并配合冷却。","a":["缓慢滴加"],"e":"缓慢滴加控制放热。"},{"id":1731,"ch":8,"t":"b","q":"分液漏斗振荡萃取后，应及时____以释放内部压力。","a":["放气"],"e":"振荡后须放气。"},{"id":1732,"ch":8,"t":"b","q":"过夜连续反应须提前审批，明确____事项，并安排人员____。","a":["交接","值守"],"e":"强调交接与值守。"},{"id":1733,"ch":8,"t":"b","q":"稀释浓硫酸时，应将____沿器壁缓缓倒入____中，并用玻璃棒不断搅拌；若将顺序颠倒，局部产生的大量热会使液体____，容易造成灼伤事故。","a":["浓硫酸","水","沸腾飞溅"],"e":"浓硫酸溶于水放出大量热，且密度比水大。正确操作是“酸入水”：把浓硫酸沿器壁缓缓注入水中并不断搅拌，使热量及时扩散。若把水倒入浓硫酸，水浮在酸面上、局部剧烈放热，会使液体沸腾飞溅伤人，因此顺序绝不能颠倒。"},{"id":1734,"ch":8,"t":"b","q":"进行减压蒸馏时，应先____再加热；蒸馏结束时应先____，再解除真空。","a":["抽真空（减压）","停止加热（撤去热源）"],"e":"先减压可降低沸点、避免暴沸；结束时先停热可防止倒吸和残留物过热。"},{"id":1735,"ch":8,"t":"b","q":"进行无水无氧操作时，玻璃仪器须先____，并在____保护下完成组装和加料。","a":["烘干（充分干燥）","氮气（惰性气体）"],"e":"水分和空气中的氧会破坏对水氧敏感的试剂，故须干燥并在惰性气氛下操作。"},{"id":1736,"ch":8,"t":"x","q":"某同学在蒸馏低沸点易燃有机溶剂时，用酒精灯直接加热烧瓶，且未接通冷凝水。请指出其中的错误，并说明正确的操作要点。","a":"1.错误一：明火直接加热易燃溶剂，蒸气遇火可能燃烧爆炸，应改用水浴或电热套加热；2.错误二：未通冷凝水，蒸气无法冷凝会大量挥发，应确保冷凝水下进上出后再加热；3.还应加入沸石防暴沸，装液量不超过烧瓶容积的三分之二，温度计水银球置于支管口；4.装置固定稳妥，在通风橱内进行，结束时先停加热、继续通水冷却后再关水。"},{"id":1737,"ch":8,"t":"x","q":"学生在分液漏斗中用乙醚萃取水相，振荡后未放气即静置分层，放液时也未打开上口塞子。请分析可能的风险并给出规范操作。","a":"1.未放气的风险：乙醚挥发使漏斗内压升高，可能冲开塞子导致液体喷溅伤人；应倒置漏斗并旋开活塞放气，反复几次，放气口朝向无人处；2.未开上口塞的风险：漏斗内形成负压，下层液体难以流出；静置分层后应先打开上口塞子再放液；3.规范操作：下层液体从下口活塞放出，上层液体从上口倒出；使用前检查活塞是否漏液；乙醚易燃，操作应远离火源并在通风橱中进行。"},{"id":1738,"ch":8,"t":"x","q":"请简述减压蒸馏的操作顺序及主要安全注意事项。","a":"1.准备：检查玻璃器皿无裂纹、能承受压差，系统连接严密，配备安全瓶与真空表；2.加料：加入沸石或采用磁力搅拌，装液量适当；3.操作顺序：先通冷凝水，再缓慢抽真空至所需压力，然后加热，调节真空度应平缓以防突沸；4.结束顺序：先移去热源，缓慢放入空气恢复常压，再停真空泵，最后关闭冷凝水；5.防护：佩戴护目镜并设置防爆挡板，防止玻璃内爆伤人，该方法适用于高沸点及热不稳定物质。"},{"id":1739,"ch":8,"t":"x","q":"案例：某同学在通风橱内进行一个强放热反应，把全部试剂一次性倒入烧杯，未开启冷却，柜门开到最高，并把若干试剂瓶长期堆放在橱内，反应迅速升温、冒烟。请指出其中的违规之处，并给出正确做法。","a":"1. 投料方式错误：强放热反应应借助滴液漏斗缓慢滴加，持续搅拌并监测温度，严禁一次性全部投入；2. 未控温：应预先备好冰浴等冷却手段并开启冷凝水，温度过高时暂停加料；3. 柜门开度过大：应把视窗降至较低位置，仅留操作所需开口，以保证面风速与捕集效果；4. 柜内存放试剂：通风橱不得当储物柜，试剂应存入专用柜，保持橱内整洁；5. 应急处置：出现冒烟、温升失控应立即停止加料、切断热源，按预案处置并报告，必要时撤离疏散。"},{"id":1740,"ch":8,"t":"x","q":"案例：某课题组需过夜进行一个对水氧敏感的反应。实验员甲把反应瓶敞口放在桌面就离校，乙检查时发现体系已接触空气。请指出问题，并说明正确的操作与交接要求。","a":"1. 无水无氧被破坏：对水氧敏感的反应须在手套箱或 Schlenk 装置中进行，用氮气或氩气保护并保持体系密闭，隔绝空气与水分；2. 严禁无人值守：过夜反应须提前审批，安排人员定时巡查监控，不得无人过夜；3. 记录与交接：应如实记录反应状态、温度、时间等，做好书面交接，写明注意事项与应急措施；4. 风险准备：开始前查阅安全技术说明书，确认应急设施，备好异常处置预案；5. 体系一旦接触空气，应评估反应物是否变质，决定终止或重做。"},{"id":1741,"ch":9,"t":"s","q":"进入化学实验室前，对个人着装的基本要求是：","o":["可穿凉鞋，便于冲洗","穿化纤衣物更耐酸碱腐蚀","穿好实验服并扣好衣扣，长发束起","戴棉纱手套即可不戴护目镜"],"a":"C","e":"实验室须穿合体实验服并扣好衣扣，长发束起，不得穿凉鞋或拖鞋。"},{"id":1742,"ch":9,"t":"s","q":"关于实验服的使用，说法正确的是：","o":["应合体、扣好衣扣、袖口收紧，不得穿出实验室","敞开穿着以利于散热","可以穿到食堂就餐","棉质实验服能完全阻挡所有化学品"],"a":"A","e":"实验服应合体并扣好，防止试剂渗入衣物，且不得穿出实验室。"},{"id":1743,"ch":9,"t":"s","q":"进行有飞溅风险的酸碱操作时，眼部防护应选择：","o":["普通近视眼镜","太阳镜","隐形眼镜","密封式化学护目镜"],"a":"D","e":"普通眼镜和隐形眼镜不能替代护目镜，飞溅操作应戴密封式化学护目镜。"},{"id":1744,"ch":9,"t":"s","q":"关于隐形眼镜与实验室眼部防护，说法正确的是：","o":["隐形眼镜可以代替护目镜使用","化学蒸气可在镜片下积聚，应尽量避免佩戴并加戴护目镜","戴隐形眼镜者无需任何眼部防护","隐形眼镜遇酸碱不会受损"],"a":"B","e":"隐形眼镜易积聚化学蒸气且不便冲洗，应尽量避免佩戴，并加戴护目镜。"},{"id":1745,"ch":9,"t":"s","q":"涉及丙酮、甲苯等有机溶剂的操作，手套宜选用：","o":["丁腈橡胶手套","天然乳胶手套","棉纱手套","皮革手套"],"a":"A","e":"丁腈橡胶对多数有机溶剂耐受性较好，乳胶和棉纱手套防护不足。"},{"id":1746,"ch":9,"t":"s","q":"接触浓硫酸、浓硝酸等强腐蚀性酸时，宜选用的手套材质是：","o":["一次性PE薄膜手套","棉布手套","丁基橡胶手套","皮革手套"],"a":"C","e":"丁基橡胶耐强酸腐蚀，薄膜手套和棉布手套防护能力差。"},{"id":1747,"ch":9,"t":"s","q":"关于防护手套的使用，正确的是：","o":["一副手套可反复使用直到明显破损","出现破损、溶胀、变色应立即更换","戴手套后可随意触摸门把手、电话","摘下手套后不必洗手"],"a":"B","e":"手套一旦破损、溶胀或变色即失去防护能力，应立即更换并洗手。"},{"id":1748,"ch":9,"t":"s","q":"选择防毒面具滤毒罐的主要依据是：","o":["使用者的身高体重","面具的价格高低","滤毒罐的颜色外观","现场毒物的种类和浓度"],"a":"D","e":"滤毒罐须与现场毒物种类、浓度匹配，并按有效期更换。"},{"id":1749,"ch":9,"t":"s","q":"关于过滤式防毒面具的适用范围，正确的是：","o":["可用于缺氧的密闭空间","可代替自给式呼吸器进入储罐","适用于毒物种类已知、浓度不高且氧气充足的场所","对任何毒物均有可靠防护"],"a":"C","e":"过滤式面具只在氧气充足、毒物种类已知且浓度不高时适用。"},{"id":1750,"ch":9,"t":"s","q":"在噪声较强的实验室佩戴耳塞、耳罩，主要目的是：","o":["防止噪声性听力损伤","提高对声音的敏感度","防止化学灼伤","代替护目镜"],"a":"A","e":"听力防护器具用于降低噪声暴露，预防噪声性听力损伤。"},{"id":1751,"ch":9,"t":"s","q":"洗眼器和紧急喷淋装置的设置要求是：","o":["可随意挪动位置","周围可堆放杂物","平时上锁以免误用","设在危险操作区附近，通道畅通并定期试水"],"a":"D","e":"应急冲洗设施应就近设置、通道畅通、标识明显并定期试水。"},{"id":1752,"ch":9,"t":"s","q":"化学试剂溅入眼内，正确的现场处理是：","o":["用手揉搓眼睛","立即用洗眼器大量清水冲洗，翻开眼睑并持续足够时间","先滴眼药水观察","等待校医到场再处理"],"a":"B","e":"眼内溅入化学品应立即用洗眼器大量清水冲洗并翻开眼睑，再就医。"},{"id":1753,"ch":9,"t":"s","q":"使用紧急喷淋装置的正确方式是：","o":["迅速脱去污染衣物，站在喷淋下持续冲洗","只冲洗头部即可","用干毛巾擦拭污染处","冲洗数秒后立即停止"],"a":"A","e":"应脱去污染衣物并持续冲洗足够时间，减少化学品与皮肤接触。"},{"id":1754,"ch":9,"t":"s","q":"实验室急救箱中不应存放的是：","o":["无菌纱布和绷带","创可贴与烫伤膏","过期药品和来历不明的药物","医用剪刀和镊子"],"a":"C","e":"急救箱应定期清查，过期或来历不明的药品须及时清除。"},{"id":1755,"ch":9,"t":"s","q":"实验室发生少量化学品泄漏时，首先应：","o":["立即用水冲入下水道","用手直接捧起泄漏物","用抹布擦净后继续实验","疏散无关人员、消除火源并做好个人防护"],"a":"D","e":"先控制现场与火源、做好防护，再实施围堵和吸附处置。"},{"id":1756,"ch":9,"t":"s","q":"扑救化学实验室初期火灾，首先应：","o":["一律用水浇灭","判断起火物质性质，选用合适灭火器材并报警","打开所有门窗通风","先拍照留存证据"],"a":"B","e":"须按燃烧物性质选择灭火剂，同时报警并组织疏散。"},{"id":1757,"ch":9,"t":"s","q":"金属钠着火时，正确的灭火方法是：","o":["用二氧化碳灭火器扑救","用泡沫灭火器扑救","用干砂或专用金属灭火剂覆盖","用大量水浇灭"],"a":"C","e":"金属钠遇水剧烈反应，只能用干砂或专用金属灭火剂覆盖。"},{"id":1758,"ch":9,"t":"s","q":"浓硫酸溅到皮肤上，正确的处理是：","o":["先用干布轻轻拭去，再用大量清水冲洗，然后涂碳酸氢钠溶液","立即用大量水冲洗后不必再处理","直接涂抹油膏包扎","先用碱液中和再冲洗"],"a":"A","e":"浓硫酸先用干布拭去可避免稀释放热扩大损伤，再大量水冲并中和。"},{"id":1759,"ch":9,"t":"s","q":"氢氟酸灼伤皮肤后，除大量清水冲洗外还应：","o":["用浓碱液中和","涂敷葡萄糖酸钙凝胶并尽快就医","用酒精反复擦洗","包扎后观察，不必就医"],"a":"B","e":"氢氟酸可深达骨骼，冲洗后须涂葡萄糖酸钙并立即就医。"},{"id":1760,"ch":9,"t":"s","q":"液溴溅到皮肤上，正确的处理是：","o":["用浓氢氧化钠溶液中和","用干布擦去后不予处理","用石油醚反复擦洗","立即用大量水冲洗，再用乙醇擦洗并就医"],"a":"D","e":"溴腐蚀性强，应大量水冲洗后乙醇擦洗，并送医处理。"},{"id":1761,"ch":9,"t":"s","q":"白磷灼伤皮肤后，正确的处理是：","o":["用湿布覆盖隔绝空气，大量水冲洗并尽快送医","用酒精清洗创面","将创面暴露在空气中晾干","涂抹油膏后包扎"],"a":"A","e":"白磷在空气中可自燃，须用湿布隔绝空气并大量水冲洗。"},{"id":1762,"ch":9,"t":"s","q":"碱液溅入眼内，用清水冲洗的时间一般不应少于：","o":["30秒","1分钟","15分钟","3分钟"],"a":"C","e":"碱液对眼组织损伤持续，冲洗时间应充分，一般不少于15分钟。"},{"id":1763,"ch":9,"t":"s","q":"轻度烫伤后，正确的现场处理是：","o":["涂抹酱油或牙膏","立即刺破水泡","用毛巾用力擦拭","用流动冷水持续冲洗降温"],"a":"D","e":"冷水冲洗可带走余热、减轻损伤，不可涂酱油或挑破水泡。"},{"id":1764,"ch":9,"t":"s","q":"被液氮等低温介质冻伤时，正确的处理是：","o":["用热水浸泡","用温水复温，不可揉搓患处","用力揉搓促进血液循环","用火烘烤"],"a":"B","e":"冻伤应温水复温，揉搓、热水或火烤会加重组织损伤。"},{"id":1765,"ch":9,"t":"s","q":"被玻璃割伤且伤口较深、出血较多时，应：","o":["用止血带长时间扎紧不放","用嘴吸吮伤口","清除伤口内玻璃碎片，加压包扎止血并就医","涂抹药膏后继续实验"],"a":"C","e":"先清除可见碎片，再加压包扎止血并及时就医。"},{"id":1766,"ch":9,"t":"s","q":"不慎吸入有毒气体后，急救的首要措施是：","o":["迅速将中毒者转移至空气新鲜处，保持呼吸道通畅","让中毒者在室内静坐观察","给中毒者大量饮水","让中毒者剧烈活动以加快代谢"],"a":"A","e":"脱离毒源、保持呼吸道通畅是吸入中毒急救的第一步。"},{"id":1767,"ch":9,"t":"s","q":"误食有毒化学品后，下列做法不正确的是：","o":["立即用清水漱口","饮用适量牛奶或蛋清保护胃黏膜","携带药品标签尽快就医","无论误食何种物质都立即催吐"],"a":"D","e":"腐蚀性物质中毒催吐会造成二次损伤，不能一律催吐。"},{"id":1768,"ch":9,"t":"s","q":"误食强酸、强碱等腐蚀性物质后，错误的处理是：","o":["服用少量牛奶或蛋清","立即催吐","立即就医","保留残余物及包装供医生参考"],"a":"B","e":"催吐会使腐蚀性物质再次灼伤食管和口腔，应禁止。"},{"id":1769,"ch":9,"t":"s","q":"身上衣物着火时，正确的做法是：","o":["就地卧倒打滚或用衣物覆盖灭火","奔跑呼救以引起注意","用手直接拍打火焰","躲进通风柜内"],"a":"A","e":"奔跑会助燃，应就地打滚或用衣物覆盖隔绝空气灭火。"},{"id":1770,"ch":9,"t":"s","q":"实验室发生火灾需要疏散时，正确做法是：","o":["乘电梯快速下楼","返回取个人贵重物品","沿安全通道低姿撤离，不乘电梯","躲到实验台下面等待"],"a":"C","e":"火灾时电梯可能断电困人，应沿安全通道低姿撤离。"},{"id":1771,"ch":9,"t":"s","q":"实施心肺复苏时，胸外按压的部位是：","o":["心前区左侧","胸骨下半部（两乳头连线中点）","上腹部","剑突处"],"a":"B","e":"按压部位为胸骨下半部，即两乳头连线中点。"},{"id":1772,"ch":9,"t":"s","q":"泄漏液体围堵与吸附常用的材料是：","o":["普通报纸","家用抹布","塑料薄膜","砂土、蛭石或专用吸附棉"],"a":"D","e":"砂土、蛭石和专用吸附棉吸附能力强，便于收集处理。"},{"id":1773,"ch":9,"t":"s","q":"事故调查处理“四不放过”原则不包括：","o":["事故原因未查清不放过","责任人未处理不放过","事故未公开报道不放过","整改措施未落实不放过"],"a":"C","e":"“四不放过”不含公开报道要求，重在查因、追责、整改和教育。"},{"id":1774,"ch":9,"t":"s","q":"实验室应急预案的核心要素一般不包括：","o":["实验课程的教学进度安排","组织机构与职责分工","报警与通讯联络方式","应急处置程序与疏散路线"],"a":"A","e":"应急预案应包含组织、报警、处置程序和疏散路线等要素。"},{"id":1775,"ch":9,"t":"s","q":"少量浓硫酸洒落在实验台面上，最先应进行的处理是","o":["立即用大量水冲洗台面","用干布或干燥砂土吸附酸液","用湿抹布擦入下水道","撒氢氧化钠固体中和"],"a":"B","e":"浓硫酸遇水放热易飞溅，应先吸附再中和清理。"},{"id":1776,"ch":9,"t":"s","q":"化学实验室发生化学品泄漏后，处置工作的正确顺序是","o":["围堵泄漏→吸附或中和→清理现场→向上报告","清理现场→围堵泄漏→吸附中和→向上报告","向上报告→清理现场→围堵泄漏→吸附中和","吸附中和→向上报告→围堵泄漏→清理现场"],"a":"A","e":"先控制扩散，再消除危险，最后清理并报告。"},{"id":1777,"ch":9,"t":"s","q":"水银温度计打碎后，在散落汞滴上撒硫磺粉的主要作用是","o":["吸附汞滴防止滚动","中和汞的酸性","使汞生成难挥发的硫化汞","加快汞挥发便于排出"],"a":"C","e":"硫与汞生成硫化汞，降低汞蒸气危害。"},{"id":1778,"ch":9,"t":"s","q":"发现有人触电，首要的救护措施是","o":["用手把触电者拉离电源","先电话报告实验室负责人","立即对触电者做胸外按压","迅速切断电源或用绝缘物挑开电线"],"a":"D","e":"先脱离电源，避免救护者自身触电。"},{"id":1779,"ch":9,"t":"s","q":"成人胸外心脏按压的正确部位是","o":["胸骨下半部、约两乳头连线中点","胸骨上端靠近锁骨处","左侧乳头下方心尖处","剑突与脐之间"],"a":"A","e":"按压胸骨下半部才能有效挤压心脏。"},{"id":1780,"ch":9,"t":"s","q":"成人胸外心脏按压的深度约为","o":["2~3 cm","3~4 cm","5~6 cm","8~10 cm"],"a":"C","e":"过浅无效，过深易造成胸廓损伤。"},{"id":1781,"ch":9,"t":"s","q":"四肢大出血使用止血带时，正确的做法是","o":["扎得越紧止血效果越好","记录扎带时间并定时放松","直接把止血带扎在伤口上","扎上后可长时间不放松"],"a":"B","e":"定时放松可防止肢体缺血坏死。"},{"id":1782,"ch":9,"t":"s","q":"放射性物质洒漏后，现场人员首先应","o":["用抹布擦净后继续实验","开窗通风后自行处理","用水冲入下水道","撤离人员、封锁现场并报告"],"a":"D","e":"先控制污染范围，再由专业人员处理。"},{"id":1783,"ch":9,"t":"s","q":"关于应急演练，下列说法错误的是","o":["可检验应急预案的可操作性","演练前应制定方案、明确分工","演练结束即可归档，不必总结","可使人熟悉疏散路线和处置程序"],"a":"C","e":"演练后应总结评估，改进预案。"},{"id":1784,"ch":9,"t":"s","q":"实验室事故报告应遵循的原则是","o":["及时、准确、完整，不得隐瞒","先内部处理，严重时才上报","只报人员伤亡，不报泄漏","由当事人自行决定是否上报"],"a":"A","e":"如实及时报告是事故处置的基本要求。"},{"id":1785,"ch":9,"t":"s","q":"事故调查期间对事故现场的正确做法是","o":["立即彻底清扫恢复实验","随意搬动设备查找原因","用水冲洗消除气味","保护现场并拍照、标记"],"a":"D","e":"现场是查明原因的重要依据，应妥善保护。"},{"id":1786,"ch":9,"t":"s","q":"单人对成人施救时，胸外按压与人工呼吸的比例为","o":["30:2","15:2","5:1","10:1"],"a":"A","e":"成人单人或双人施救均按三十比二操作。"},{"id":1787,"ch":9,"t":"s","q":"向负责人报告化学品泄漏时，一般不必说明的是","o":["泄漏物质名称和数量","泄漏地点和人员情况","泄漏物质的价格","已采取的处置措施"],"a":"C","e":"报告应突出危害与处置信息，价格与应急无关。"},{"id":1788,"ch":9,"t":"s","q":"少量浓硝酸洒落后，宜先用于吸附的材料是","o":["湿抹布","滤纸","铝箔","干燥砂土或专用吸附剂"],"a":"D","e":"先用惰性吸附材料吸收，再中和清理。"},{"id":1789,"ch":9,"t":"s","q":"氢氟酸溅到皮肤上，用水冲洗后还应","o":["涂碳酸氢钠溶液","涂葡萄糖酸钙凝胶并就医","用酒精反复擦洗","包扎后继续实验"],"a":"B","e":"钙剂可结合氟离子，减轻深层组织损伤。"},{"id":1790,"ch":9,"t":"s","q":"液溴溅到皮肤上，急救时应","o":["用浓碱液中和","用干布擦干后包扎","大量水冲洗后再用乙醇擦洗","涂油脂密封创面"],"a":"C","e":"溴腐蚀性强，冲洗后用乙醇擦洗可减少残留。"},{"id":1791,"ch":9,"t":"s","q":"化学药品溅入眼内，用洗眼器冲洗的时间一般不少于","o":["30 秒","1 分钟","5 分钟","15 分钟"],"a":"D","e":"充分冲洗才能稀释并清除残留化学品。"},{"id":1792,"ch":9,"t":"s","q":"有人吸入有毒气体昏迷，首先应","o":["原地等待救护车","迅速转移到空气新鲜处","立即喂水","给其服用解毒药"],"a":"B","e":"脱离毒源、保持呼吸道通畅是急救第一步。"},{"id":1793,"ch":9,"t":"s","q":"误食强酸后的急救措施是","o":["服少量清水或牛奶稀释，禁催吐，立即就医","立即催吐","服碳酸氢钠粉末中和","服泻药加速排出"],"a":"A","e":"催吐和中和产气会加重食管损伤。"},{"id":1794,"ch":9,"t":"s","q":"实验室内少量有机溶剂着火，应优先选用","o":["直流水","湿抹布扑打","沙土掩埋","干粉或二氧化碳灭火器"],"a":"D","e":"有机溶剂密度小、比水轻，用水易使火势蔓延。"},{"id":1795,"ch":9,"t":"s","q":"操作浓硝酸时宜选用的手套是","o":["棉纱手套","一次性 PE 手套","丁腈橡胶手套","皮革手套"],"a":"C","e":"丁腈橡胶耐酸碱腐蚀，适合操作强腐蚀性试剂。"},{"id":1796,"ch":9,"t":"s","q":"选用过滤式防毒面具时最关键的是","o":["面具颜色与实验服相配","滤毒罐型号与所接触毒物相匹配","面具越重防护越好","同一滤毒罐可长期反复使用"],"a":"B","e":"滤毒罐有选择性，型号不符则起不到防护作用。"},{"id":1797,"ch":9,"t":"s","q":"进入噪声较强的实验区域应选用的防护用品是","o":["防尘口罩","防护眼镜","安全帽","耳塞或耳罩"],"a":"D","e":"耳塞、耳罩可降低噪声对听力的损伤。"},{"id":1798,"ch":9,"t":"s","q":"化学品泄漏处置中，“围堵”的主要目的是","o":["防止泄漏物扩散流散","使泄漏物尽快挥发","把泄漏物冲入下水道","中和泄漏物的腐蚀性"],"a":"A","e":"围堵用于控制污染范围，为后续处理创造条件。"},{"id":1799,"ch":9,"t":"s","q":"实验室急救箱中，用于皮肤小面积擦伤消毒的常用物品是","o":["浓盐酸","碘伏","乙醚","苯酚"],"a":"B","e":"碘伏刺激性小，适用于皮肤消毒。"},{"id":1800,"ch":9,"t":"s","q":"触电者脱离电源后呼吸心跳停止，应立即","o":["喂水并保暖","掐人中观察","进行心肺复苏并呼叫急救","送医院途中不做处理"],"a":"C","e":"呼吸心跳骤停须立即心肺复苏，争取抢救时间。"},{"id":1801,"ch":9,"t":"s","q":"发现放射源丢失、被盗时，正确的做法是","o":["立即报告并封锁现场，不得自行寻找","自行寻找后放回原处","当作普通物品处理","隐瞒不报以免影响考评"],"a":"A","e":"放射源失控危害大，须由专业部门处置。"},{"id":1802,"ch":9,"t":"s","q":"应急预案中不可缺少的内容是","o":["实验室装修方案","实验课程安排","试剂采购清单","应急组织、处置程序和联络方式"],"a":"D","e":"预案须明确谁来做、怎么做、如何联系。"},{"id":1803,"ch":9,"t":"s","q":"实验室事故案例表明，多数事故的直接诱因是","o":["仪器价格低廉","实验课时不足","违章操作和麻痹大意","实验室面积狭小"],"a":"C","e":"人的不安全行为是实验室事故的主要致因。"},{"id":1804,"ch":9,"t":"s","q":"皮肤被热玻璃烫伤后，正确的处理是","o":["立即涂抹牙膏","用冷水冲洗降温后就医","挑破水泡","用酒精擦拭"],"a":"B","e":"冷水冲洗可减轻热损伤，牙膏等偏方易致感染。"},{"id":1805,"ch":9,"t":"s","q":"紧急喷淋装置的使用场合是","o":["试剂配制时降温","玻璃仪器清洗","实验台面消毒","化学物质大面积污染身体时"],"a":"D","e":"喷淋用于人员身体被化学品大面积污染时的快速冲洗。"},{"id":1806,"ch":9,"t":"s","q":"皮肤被氢氟酸（HF）灼伤后，除立即脱去污染衣物并用大量清水冲洗外，首选的特效处理措施是（　）。","o":["涂敷葡萄糖酸钙凝胶或在灼伤处周围注射葡萄糖酸钙","涂敷稀醋酸溶液以中和残余酸","涂敷饱和碳酸氢钠溶液以中和残余酸","用高锰酸钾溶液反复冲洗创面"],"a":"A","e":"氢氟酸中的氟离子极易与体内的钙、镁结合，可穿透皮肤造成深层组织坏死。急救时应在大量清水冲洗后，使用葡萄糖酸钙凝胶外涂或在灼伤处周围注射葡萄糖酸钙，使氟离子与钙结合生成难溶的氟化钙，阻止其继续向深部渗透。用醋酸或碳酸氢钠中和、用高锰酸钾冲洗均非氢氟酸灼伤的特效处理。"},{"id":1807,"ch":9,"t":"s","q":"眼睛被酸、碱等化学试剂溅入后，应立即用洗眼器或大量清水持续冲洗，冲洗时间一般不应少于（　）。","o":["3分钟","8分钟","15分钟","45分钟"],"a":"C","e":"眼睛接触化学试剂后应争分夺秒就地冲洗，用洗眼器或流动清水持续冲洗至少15分钟，并翻开眼睑、转动眼球，使结膜囊内的化学品被充分冲净；冲洗时间过短难以彻底清除腐蚀性物质，冲洗后应尽快就医。"},{"id":1808,"ch":9,"t":"s","q":"发生氰化物（如氰化钾、氰化钠）中毒时，下列现场急救措施正确的是（　）。","o":["立即对中毒者进行口对口人工呼吸","让中毒者吸入亚硝酸异戊酯并尽快使用特效解毒剂","让中毒者大量饮水并自行催吐","将中毒者移至密闭房间内保暖观察"],"a":"B","e":"氰化物中毒抢救的关键是尽快使用解毒剂：可先让中毒者吸入亚硝酸异戊酯（掰碎安瓿置于口鼻处），并尽快送医使用亚硝酸钠—硫代硫酸钠等特效解毒剂。口对口人工呼吸易使施救者吸入氰化物而二次中毒，催吐对已吸收的毒物无效，密闭房间会加重缺氧，均不可取。"},{"id":1809,"ch":9,"t":"m","q":"进入化学实验室时，个人防护装备通常包括：","o":["实验服","护目镜","合适的防护手套","拖鞋"],"a":"ABC","e":"实验服、护目镜和合适手套是基本防护，拖鞋禁止穿入实验室。"},{"id":1810,"ch":9,"t":"m","q":"选用防护手套时应考虑的因素有：","o":["化学品的种类与浓度","接触时间的长短","手套的颜色是否美观","手套材质的渗透性"],"a":"ABD","e":"手套选型取决于化学品种类、浓度、接触时间及材质渗透性。"},{"id":1811,"ch":9,"t":"m","q":"关于防毒面具的使用，正确的有：","o":["使用前检查面罩气密性","在缺氧环境中可以放心使用","根据毒物种类选配滤毒罐","定期更换滤毒罐"],"a":"ACD","e":"面具使用前须查气密性、按毒物选罐并定期更换，缺氧环境禁用。"},{"id":1812,"ch":9,"t":"m","q":"实验室应急设施包括：","o":["洗眼器","紧急喷淋装置","急救箱","泄漏处理包"],"a":"ABCD","e":"四者均属实验室应急设施，应配备齐全并定期检查。"},{"id":1813,"ch":9,"t":"m","q":"洗眼器和紧急喷淋装置的维护要求包括：","o":["定期试水检查","保持周围通道畅通","设置明显标识","平时上锁防止学生使用"],"a":"ABC","e":"应急冲洗设施须随时可用，上锁会延误急救。"},{"id":1814,"ch":9,"t":"m","q":"化学灼伤现场处理的一般原则有：","o":["迅速脱离污染源","先中和再冲洗","立即用大量清水冲洗","尽快就医"],"a":"ACD","e":"灼伤处理以脱离、冲洗、就医为主，盲目中和可能放热加重损伤。"},{"id":1815,"ch":9,"t":"m","q":"氢氟酸灼伤的特点与处理包括：","o":["初期疼痛可能不明显，容易被忽视","可深达骨骼造成组织坏死","只需冲洗不必就医","冲洗后涂敷葡萄糖酸钙凝胶"],"a":"ABD","e":"氢氟酸渗透深、症状隐匿，必须冲洗、涂钙剂并就医。"},{"id":1816,"ch":9,"t":"m","q":"白磷灼伤的处理要点有：","o":["将创面暴露在空气中","迅速用大量水冲洗","用湿布覆盖创面隔绝空气","清除可见的磷颗粒"],"a":"BCD","e":"白磷在空气中自燃，须隔绝空气、冲洗并清除磷颗粒。"},{"id":1817,"ch":9,"t":"m","q":"烫伤与冻伤的现场处理，正确的有：","o":["烫伤后用流动冷水持续冲洗降温","冻伤后用温水复温","立即刺破水泡","不可强行撕脱与创面粘连的衣物"],"a":"ABD","e":"冷水降温、温水复温、保护创面是原则，水泡不可自行刺破。"},{"id":1818,"ch":9,"t":"m","q":"吸入有毒气体后的急救措施包括：","o":["迅速转移至空气新鲜处","让中毒者继续留在现场观察","保持呼吸道通畅","必要时给氧或进行心肺复苏"],"a":"ACD","e":"吸入中毒须立即脱离毒源、通畅气道并视情况给氧或复苏。"},{"id":1819,"ch":9,"t":"m","q":"误食化学品后的处理原则包括：","o":["立即漱口","腐蚀性物质中毒不宜催吐","可饮用牛奶或蛋清保护胃黏膜","携带毒物标签就医"],"a":"ABCD","e":"漱口、慎催吐、保护胃黏膜并携带标签就医均为正确原则。"},{"id":1820,"ch":9,"t":"m","q":"实验室火灾与爆炸的应急措施包括：","o":["立即报警并切断电源、气源","按物质性质选择灭火器材","组织人员沿安全通道疏散","乘电梯迅速撤离"],"a":"ABC","e":"报警、断源、科学灭火和疏散是正确措施，火场严禁乘电梯。"},{"id":1821,"ch":9,"t":"m","q":"化学品泄漏的处置要点包括：","o":["划定警戒区并疏散无关人员","做好个人防护","用水直接冲入下水道","围堵、吸附或中和泄漏物","及时向有关部门报告"],"a":"ABDE","e":"泄漏处置包括警戒、防护、围堵吸附中和及报告等环节。"},{"id":1822,"ch":9,"t":"m","q":"事故报告与调查应遵循的要求有：","o":["及时如实报告，不得隐瞒","保护事故现场","事故原因查清前可先行复工","坚持“四不放过”原则"],"a":"ABD","e":"应如实报告、保护现场并按“四不放过”调查，不得草率复工。"},{"id":1823,"ch":9,"t":"m","q":"化学品泄漏处置的正确做法包括","o":["立即围堵，防止泄漏物扩散","根据物质性质选择吸附或中和","处理完毕按规定报告并记录","用大量水直接冲入下水道"],"a":"ABC","e":"冲入下水道会扩大污染，须收集后按危废处置。"},{"id":1824,"ch":9,"t":"m","q":"触电急救过程中应注意","o":["先使触电者脱离电源","救护者做好绝缘防护","呼吸心跳停止者立即心肺复苏","直接用手拉扯触电者"],"a":"ABC","e":"徒手拉扯会使救护者一同触电。"},{"id":1825,"ch":9,"t":"m","q":"辐射事故的应急措施包括","o":["撤离无关人员并封锁现场","对可能受污染人员进行去污和检测","按规定报告辐射安全管理部门","自行掩埋放射性废物"],"a":"ABC","e":"放射性废物须交专业机构处置，不得自行掩埋。"},{"id":1826,"ch":9,"t":"m","q":"应急演练的作用有","o":["检验应急预案的可行性","提高人员应急处置能力","发现应急设施和物资的不足","替代日常安全管理"],"a":"ABC","e":"演练是检验和提升手段，不能代替日常管理。"},{"id":1827,"ch":9,"t":"m","q":"事故报告与调查的要求包括","o":["及时如实报告，不得隐瞒","保护事故现场","按“四不放过”原则处理","原因未查清即先行复工"],"a":"ABC","e":"原因未查清、措施未落实不得复工。"},{"id":1828,"ch":9,"t":"m","q":"心肺复苏的有效指征包括","o":["可触及大动脉搏动","面色由紫绀转为红润","瞳孔由大变小","出现自主呼吸"],"a":"ABCD","e":"四项均为复苏有效的常见表现。"},{"id":1829,"ch":9,"t":"m","q":"止血包扎的要点有","o":["包扎松紧适度","先用无菌敷料覆盖伤口","四肢大出血可用止血带并记录时间","伤口内异物应强行拔出后再包扎"],"a":"ABC","e":"深部异物强行拔出易造成二次损伤。"},{"id":1830,"ch":9,"t":"m","q":"应急预案应包括的要素有","o":["应急组织机构与职责","报警与联络方式","现场处置措施与疏散路线","事后恢复与演练要求"],"a":"ABCD","e":"预案须覆盖事前、事中、事后各环节。"},{"id":1831,"ch":9,"t":"m","q":"化学品泄漏后需要报告的内容通常包括","o":["泄漏物质及大致数量","泄漏地点与时间","人员受伤情况","已采取的措施"],"a":"ABCD","e":"这些信息决定后续处置和救援方案。"},{"id":1832,"ch":9,"t":"m","q":"实验室常备的泄漏处理用品有","o":["吸附棉或吸附砂","中和剂","收集容器和废弃物袋","敞口垃圾桶"],"a":"ABC","e":"泄漏物须密闭收集，不能投入敞口垃圾桶。"},{"id":1833,"ch":9,"t":"m","q":"化学灼伤急救的一般原则包括","o":["迅速脱去被污染的衣物","用大量流动清水冲洗","冲洗后按伤情就医","立即用碱液中和酸灼伤"],"a":"ABC","e":"自行中和会放热加重损伤。"},{"id":1834,"ch":9,"t":"m","q":"从事故案例中应吸取的教训有","o":["事故多由违章操作引起","小事故也应及时报告分析","侥幸心理是重要隐患","事故只与运气有关，无法预防"],"a":"ABC","e":"事故可防可控，侥幸心理要不得。"},{"id":1835,"ch":9,"t":"m","q":"使用紧急喷淋和洗眼器时应注意","o":["安装位置便于就近到达","定期检查出水是否正常","冲洗时间要足够","平时可堆放物品遮挡"],"a":"ABC","e":"应急设施须保持通道畅通、随时可用。"},{"id":1836,"ch":9,"t":"m","q":"实验室常用的个人防护用品包括","o":["实验服","护目镜","材质合适的手套","拖鞋"],"a":"ABC","e":"拖鞋不能保护足部，禁止在实验室穿用。"},{"id":1837,"ch":9,"t":"j","q":"实验服可以穿出实验室，到食堂或会议室继续穿着。","o":["对","错"],"a":"错","e":"实验服可能沾染化学品，严禁穿出实验室。"},{"id":1838,"ch":9,"t":"j","q":"佩戴普通近视眼镜可以替代化学护目镜。","o":["对","错"],"a":"错","e":"普通眼镜侧面不密封，不能替代防飞溅的化学护目镜。"},{"id":1839,"ch":9,"t":"j","q":"防护手套出现破损或溶胀时应立即更换。","o":["对","错"],"a":"对","e":"破损溶胀的手套已失去防护能力，须及时更换。"},{"id":1840,"ch":9,"t":"j","q":"过滤式防毒面具可以在缺氧环境中使用。","o":["对","错"],"a":"错","e":"缺氧环境须使用自给式呼吸器，过滤式面具无法供氧。"},{"id":1841,"ch":9,"t":"j","q":"洗眼器和紧急喷淋装置应设在危险操作区附近，并保持通道畅通。","o":["对","错"],"a":"对","e":"就近设置且通道畅通才能保证事故时迅速冲洗。"},{"id":1842,"ch":9,"t":"j","q":"化学试剂溅入眼内，应立即用洗眼器大量清水冲洗并翻开眼睑。","o":["对","错"],"a":"对","e":"充分冲洗并翻开眼睑可减少化学品在结膜囊内滞留。"},{"id":1843,"ch":9,"t":"j","q":"浓硫酸溅到皮肤上，应立即用大量水冲洗，再涂碳酸氢钠溶液。","o":["对","错"],"a":"错","e":"浓硫酸应先用于布拭去再冲洗，直接冲水可能因稀释放热加重损伤。"},{"id":1844,"ch":9,"t":"j","q":"氢氟酸灼伤初期疼痛不明显，容易被忽视，但仍须立即冲洗并就医。","o":["对","错"],"a":"对","e":"氢氟酸渗透深、症状隐匿，延误处理会造成严重组织坏死。"},{"id":1845,"ch":9,"t":"j","q":"白磷灼伤后应将创面暴露在空气中，以便观察伤情。","o":["对","错"],"a":"错","e":"白磷遇空气可自燃，创面须用湿布覆盖隔绝空气。"},{"id":1846,"ch":9,"t":"j","q":"液溴溅到皮肤上，应立即用大量水冲洗，再用乙醇擦洗。","o":["对","错"],"a":"对","e":"大量水冲去溴液后用乙醇擦洗，可减轻灼伤并便于送医。"},{"id":1847,"ch":9,"t":"j","q":"轻度烫伤后应立即用流动冷水持续冲洗降温。","o":["对","错"],"a":"对","e":"冷水冲洗带走余热，能减轻组织损伤和疼痛。"},{"id":1848,"ch":9,"t":"j","q":"冻伤后可用热水浸泡或用力揉搓患处。","o":["对","错"],"a":"错","e":"热水和揉搓会加重组织损伤，应用温水缓慢复温。"},{"id":1849,"ch":9,"t":"j","q":"被玻璃割伤后，若伤口内有玻璃碎片，应先清除碎片再包扎止血。","o":["对","错"],"a":"对","e":"残留碎片会加重损伤，应先清除再加压包扎。"},{"id":1850,"ch":9,"t":"j","q":"吸入有毒气体中毒者，应立即转移到空气新鲜处并保持呼吸道通畅。","o":["对","错"],"a":"对","e":"脱离毒源和通畅气道是吸入中毒急救的首要措施。"},{"id":1851,"ch":9,"t":"j","q":"误食强酸、强碱后应立即催吐，把毒物排出。","o":["对","错"],"a":"错","e":"腐蚀性物质催吐会二次灼伤食管和口腔，应禁止。"},{"id":1852,"ch":9,"t":"j","q":"金属钠着火可用水或泡沫灭火器扑救。","o":["对","错"],"a":"错","e":"金属钠遇水剧烈反应放出氢气，只能用干砂或专用灭火剂。"},{"id":1853,"ch":9,"t":"j","q":"发生火灾疏散时应乘电梯尽快下楼。","o":["对","错"],"a":"错","e":"火场电梯可能断电或成为烟囱，应走安全通道。"},{"id":1854,"ch":9,"t":"j","q":"事故发生后应及时如实报告，保护现场，不得隐瞒。","o":["对","错"],"a":"对","e":"如实报告并保护现场是事故调查处理的基本要求。"},{"id":1855,"ch":9,"t":"j","q":"化学品泄漏后应先围堵，再进行吸附或中和。","o":["对","错"],"a":"对","e":"先控制扩散范围，后续处理才有效。"},{"id":1856,"ch":9,"t":"j","q":"发生事故后，为尽快恢复实验可以立即清扫现场。","o":["对","错"],"a":"错","e":"现场应保护，待调查取证后再清理。"},{"id":1857,"ch":9,"t":"j","q":"触电急救时，救护者可以直接用手把触电者拉开。","o":["对","错"],"a":"错","e":"徒手施救会使救护者触电。"},{"id":1858,"ch":9,"t":"j","q":"胸外心脏按压时应让患者仰卧在坚硬平面上。","o":["对","错"],"a":"对","e":"软床会削弱按压效果。"},{"id":1859,"ch":9,"t":"j","q":"使用止血带止血时，应记录开始时间并定时放松。","o":["对","错"],"a":"对","e":"防止肢体长时间缺血坏死。"},{"id":1860,"ch":9,"t":"j","q":"放射性废物可以与普通实验垃圾一起处理。","o":["对","错"],"a":"错","e":"放射性废物须单独收集、专业处置。"},{"id":1861,"ch":9,"t":"j","q":"应急演练结束后应进行总结评估。","o":["对","错"],"a":"对","e":"总结评估可发现预案和处置中的问题。"},{"id":1862,"ch":9,"t":"j","q":"只要未造成人员伤亡，实验室事故就可以隐瞒不报。","o":["对","错"],"a":"错","e":"事故报告必须及时、准确、完整。"},{"id":1863,"ch":9,"t":"j","q":"事故处理应坚持“四不放过”原则。","o":["对","错"],"a":"对","e":"该原则强调原因、责任、教育、整改四方面。"},{"id":1864,"ch":9,"t":"j","q":"少量浓硫酸洒落时可直接用大量水冲洗。","o":["对","错"],"a":"错","e":"遇水放热会使酸液飞溅，应先吸附。"},{"id":1865,"ch":9,"t":"j","q":"氢氟酸灼伤后可用葡萄糖酸钙处理并及时就医。","o":["对","错"],"a":"对","e":"钙离子可结合氟离子，减轻组织损伤。"},{"id":1866,"ch":9,"t":"j","q":"化学药品溅入眼内应立即用洗眼器大量冲洗。","o":["对","错"],"a":"对","e":"及时充分冲洗是减轻眼损伤的关键。"},{"id":1867,"ch":9,"t":"j","q":"误食腐蚀性物质后应立即催吐。","o":["对","错"],"a":"错","e":"催吐会使腐蚀性物质再次灼伤食管。"},{"id":1868,"ch":9,"t":"j","q":"保护事故现场有助于查明事故原因。","o":["对","错"],"a":"对","e":"现场痕迹和物证是分析原因的重要依据。"},{"id":1869,"ch":9,"t":"j","q":"实验室内可以用敞口容器存放大量有机溶剂。","o":["对","错"],"a":"错","e":"敞口存放易挥发积聚，增加火灾爆炸风险。"},{"id":1870,"ch":9,"t":"j","q":"应急预案制定后无需演练即可长期有效。","o":["对","错"],"a":"错","e":"预案须通过演练检验并定期修订。"},{"id":1871,"ch":9,"t":"j","q":"事故发生后应先抢救伤员、控制事故扩大，再进行调查。","o":["对","错"],"a":"对","e":"救人控险优先，调查在险情控制后开展。"},{"id":1872,"ch":9,"t":"j","q":"实验室发生小面积可燃液体（如乙醇、丙酮）泄漏时，应立即用大量水冲洗，将其冲入下水道。","o":["对","错"],"a":"错","e":"可燃液体泄漏不可用水直接冲入下水道，既可能使液体和蒸气扩散、扩大火险，又会污染环境并引发下水道安全隐患。正确做法是立即切断火源和电源、加强通风，用砂土、吸附棉等吸附材料覆盖围堵吸收，再收集装入密闭容器按危险废物处置。"},{"id":1873,"ch":9,"t":"b","q":"化学实验时必须穿好____，并扣好衣扣，长发应束起。","a":["实验服"]},{"id":1874,"ch":9,"t":"b","q":"化学试剂溅入眼内，应立即使用____进行大量清水冲洗。","a":["洗眼器"]},{"id":1875,"ch":9,"t":"b","q":"身上衣物着火时，应就地____或用衣物覆盖灭火。","a":["卧倒打滚"]},{"id":1876,"ch":9,"t":"b","q":"浓硫酸溅到皮肤上，应先用____轻轻拭去，再用大量水冲洗。","a":["干布"]},{"id":1877,"ch":9,"t":"b","q":"氢氟酸灼伤后，除大量冲洗外还应涂敷____凝胶并尽快就医。","a":["葡萄糖酸钙"]},{"id":1878,"ch":9,"t":"b","q":"白磷灼伤后应用____覆盖创面，使其与空气隔绝。","a":["湿布"]},{"id":1879,"ch":9,"t":"b","q":"金属钠着火时，应用____或专用金属灭火剂覆盖扑救。","a":["干砂"]},{"id":1880,"ch":9,"t":"b","q":"误食强酸、强碱等腐蚀性物质后不宜____，以免造成二次损伤。","a":["催吐"]},{"id":1881,"ch":9,"t":"b","q":"吸入有毒气体后，应首先保持中毒者____通畅，并尽快脱离毒源。","a":["呼吸道"]},{"id":1882,"ch":9,"t":"b","q":"事故调查处理坚持“四不放过”，即原因未查清、责任人未处理、整改措施未落实和____不放过。","a":["有关人员未受到教育"]},{"id":1883,"ch":9,"t":"b","q":"使用过滤式防毒面具前，应检查面罩的____，确保佩戴严密。","a":["气密性"]},{"id":1884,"ch":9,"t":"b","q":"被玻璃割伤出血较多时，应立即____包扎止血并尽快就医。","a":["加压"]},{"id":1885,"ch":9,"t":"b","q":"化学品泄漏处置的基本步骤是围堵、____、清理和报告。","a":["吸附或中和"],"e":"吸附或中和用于消除泄漏物的危险性。"},{"id":1886,"ch":9,"t":"b","q":"“四不放过”原则中，除事故原因未查清、责任人员未处理、整改措施未落实外，还有____不放过。","a":["有关人员未受到教育"],"e":"教育相关人员是“四不放过”的内容之一。"},{"id":1887,"ch":9,"t":"b","q":"成人胸外心脏按压的频率为每分钟____次。","a":["100~120"],"e":"频率过慢或过快都会影响复苏效果。"},{"id":1888,"ch":9,"t":"b","q":"单人对成人施救时，胸外按压与人工呼吸的次数比为____。","a":["30:2"],"e":"每按压三十次给予两次人工呼吸。"},{"id":1889,"ch":9,"t":"b","q":"使用止血带时，应记录____，并定时放松。","a":["扎带时间"],"e":"记录时间便于掌握放松间隔，防止肢体坏死。"},{"id":1890,"ch":9,"t":"b","q":"实验室事故报告应做到及时、____、完整，不得隐瞒。","a":["准确"],"e":"报告内容须真实准确，便于正确处置。"},{"id":1891,"ch":9,"t":"b","q":"放射性物质洒漏后，应首先____现场人员并封锁现场。","a":["撤离"],"e":"先减少人员受照，再控制污染扩散。"},{"id":1892,"ch":9,"t":"b","q":"眼睛被化学品溅入后，应用洗眼器连续冲洗不少于____分钟。","a":["15"],"e":"充分冲洗可有效降低眼组织损伤程度。"},{"id":1893,"ch":9,"t":"b","q":"皮肤被浓硫酸灼伤后，应立即用大量____冲洗。","a":["流动清水"],"e":"大量流动清水可迅速带走热量和残留酸液。"},{"id":1894,"ch":9,"t":"b","q":"应急预案应包括应急组织、____、处置措施和疏散路线等内容。","a":["联络方式"],"e":"联络方式是报警与求援得以实现的前提。"},{"id":1895,"ch":9,"t":"b","q":"事故调查中，为查明原因应注意____事故现场。","a":["保护"],"e":"现场物证和痕迹对原因分析至关重要。"},{"id":1896,"ch":9,"t":"x","q":"简述化学实验室个人防护装备的种类及选用要点。","a":"1.实验服：应合体、扣好衣扣、袖口收紧，不得穿出实验室；2.护目镜或面罩：有飞溅、腐蚀、粉尘风险时必须佩戴，普通眼镜和隐形眼镜不能替代；3.手套：按化学品种类、浓度和接触时间选择丁腈、丁基橡胶等材质，破损、溶胀应立即更换；4.呼吸防护：毒物种类已知、浓度不高且氧气充足时可用过滤式防毒面具并选配对应滤毒罐，缺氧或高浓度环境应使用自给式呼吸器；5.听力防护：噪声较强时佩戴耳塞或耳罩。"},{"id":1897,"ch":9,"t":"x","q":"简述浓硫酸、氢氟酸、溴和白磷灼伤皮肤后的处置要点。","a":"1.浓硫酸：先用干布轻轻拭去，再用大量清水冲洗，然后涂碳酸氢钠溶液并就医；2.氢氟酸：立即大量清水冲洗，涂敷葡萄糖酸钙凝胶并尽快就医，因其可深达骨骼造成坏死；3.溴：立即用大量水冲洗，再用乙醇擦洗并送医；4.白磷：用湿布覆盖隔绝空气，大量水冲洗并清除可见磷颗粒后送医，不可暴露于空气或涂油膏；5.共同原则：迅速脱离污染源、脱去污染衣物、大量清水持续冲洗、尽快就医。"},{"id":1898,"ch":9,"t":"x","q":"案例：某实验室因试剂瓶倾倒导致约500 mL有机溶剂泄漏并起火，一名学生手部被火焰燎伤。请写出应急处置的先后步骤。","a":"1.立即报警呼救，切断电源、气源，移走附近易燃物；2.组织无关人员沿安全通道疏散，不乘电梯；3.处理伤员：用流动冷水冲洗燎伤部位降温，覆盖清洁敷料后送医；4.判断起火物质性质，用干粉或二氧化碳灭火器扑救初期火灾，必要时用消防沙；5.对未燃泄漏液用砂土、蛭石或吸附棉围堵吸附，防止流入下水道；6.处置人员佩戴合适防护装备，事后保护现场并如实报告，配合调查。"},{"id":1899,"ch":9,"t":"x","q":"简述化学品泄漏的处置步骤及报告要求。","a":"1.立即疏散无关人员，设置警戒，防止泄漏物扩散；2.判明泄漏物质性质，穿戴合适防护用品后围堵泄漏源；3.用吸附材料吸附，或选用合适中和剂中和，注意不相容物质不得混用；4.将废弃物密闭收集，按危险废物处置，清理现场并通风；5.及时向实验室负责人和学校安全管理部门报告，说明物质名称、数量、地点、人员情况和已采取措施；6.有人受伤时先救人并送医，全过程做好记录。"},{"id":1900,"ch":9,"t":"x","q":"某实验室因违规操作使有机溶剂洒落并引燃，请分析应吸取的教训和应采取的应急措施。","a":"1.教训：违规操作、麻痹大意是事故主因；有机溶剂敞口存放和使用，可燃蒸气积聚，遇火源即燃；现场缺乏应急准备，处置不及时。2.应急措施：立即切断电源、移走周围可燃物；用干粉或二氧化碳灭火器扑救，严禁用水；组织人员疏散并报警、报告；有人受伤先救人；火扑灭后保护现场，配合调查，按“四不放过”原则分析原因、落实整改。3.日常要求：规范溶剂存放与操作，加强安全教育与应急演练。"},{"id":1901,"ch":10,"t":"s","q":"实验室废弃物分类中，破碎玻璃器皿、注射针头等应归入（　）","o":["化学性废物","锐器类","生物性废物","放射性废物"],"a":"B","e":"锐器类废物指可能造成刺伤、割伤的物品，应使用专用容器收集。"},{"id":1902,"ch":10,"t":"s","q":"含卤有机废液必须与不含卤有机废液分开收集，主要原因是（　）","o":["两者混合会立即爆炸","处理工艺不同，含卤废物焚烧易生成有毒物质","不含卤废液价格更高","含卤废液不能燃烧"],"a":"B","e":"含卤废物处理方式与不含卤废物不同，混装会增大处置难度和污染风险。"},{"id":1903,"ch":10,"t":"s","q":"有机废液收集容器的材质应满足（　）","o":["普通塑料饮料瓶即可","金属铁桶即可","透明薄玻璃瓶即可","耐腐蚀、不易破碎且密封良好"],"a":"D","e":"收集容器须耐腐蚀、不易破损并密封，防止泄漏和挥发。"},{"id":1904,"ch":10,"t":"s","q":"化学废液容器标签上通常不必标注的是（　）","o":["废物名称与主要成分","市场收购价格","危险特性","产生日期与责任人"],"a":"B","e":"标签应标明成分、危险特性、日期和责任人，与市场价格无关。"},{"id":1905,"ch":10,"t":"s","q":"关于废液装入收集容器的量，正确的做法是（　）","o":["留出适当空间，防止膨胀溢出","越满越好","装至瓶口并加压","装满后立即密封"],"a":"A","e":"废液装量不宜过满，应留出空间以适应温度变化和防止溢出。"},{"id":1906,"ch":10,"t":"s","q":"化学废液暂存区的地面应（　）","o":["铺设普通地毯","做防渗处理并设置围堰或托盘","保持干燥即可，无需处理","直接为未处理的水泥地"],"a":"B","e":"暂存区地面须防渗并设置围堰或防漏托盘，防止泄漏污染环境。"},{"id":1907,"ch":10,"t":"s","q":"危险废物在实验室暂存的时间一般不应超过（　）","o":["一个月","半年","五年","一年"],"a":"D","e":"按危险废物贮存污染控制要求，贮存期限一般不得超过一年。"},{"id":1908,"ch":10,"t":"s","q":"酸性废液与含氰废液混合会产生（　）","o":["氢气","氰化氢","氯气","二氧化硫"],"a":"B","e":"酸与氰化物反应释放剧毒的氰化氢气体，必须严禁混装。"},{"id":1909,"ch":10,"t":"s","q":"含氰废液收集时应保持（　）","o":["强酸性","中性","任意pH","碱性"],"a":"D","e":"含氰废液须在碱性条件下收集，防止生成和逸出氰化氢。"},{"id":1910,"ch":10,"t":"s","q":"金属汞洒落后，常撒布（　）以降低其挥发性","o":["食盐","蔗糖","硫磺粉","碳酸钙"],"a":"C","e":"硫磺粉可与汞反应生成难挥发的硫化汞，降低汞蒸气危害。"},{"id":1911,"ch":10,"t":"s","q":"白磷必须保存在（　）","o":["煤油中","乙醇中","干燥空气中","水中"],"a":"D","e":"白磷在空气中易自燃，须水封保存以隔绝空气。"},{"id":1912,"ch":10,"t":"s","q":"苦味酸长期存放或与金属接触的危险在于（　）","o":["生成更敏感的爆炸性盐","产生剧毒气体","失去酸性","完全挥发"],"a":"A","e":"苦味酸与金属生成苦味酸盐，对摩擦、撞击更敏感，易发生爆炸。"},{"id":1913,"ch":10,"t":"s","q":"叠氮化钠废液不能直接倒入金属管道，原因是（　）","o":["腐蚀塑料","产生氧气","遇水放热","与金属生成敏感爆炸性叠氮化物"],"a":"D","e":"叠氮化物与铜、铅等金属生成敏感易爆的叠氮盐，存在爆炸风险。"},{"id":1914,"ch":10,"t":"s","q":"久置的乙醚在使用前应检验是否生成（　）","o":["过氧化物","甲醇","乙酸","乙醛"],"a":"A","e":"醚类久置可生成过氧化物，受热或摩擦易爆炸，使用前必须检验。"},{"id":1915,"ch":10,"t":"s","q":"废弃化学试剂原瓶处理，正确的做法是（　）","o":["保留原标签并注明废弃，单独存放","撕掉标签当普通垃圾","倒入下水道","与其他废液随意混合"],"a":"A","e":"废弃试剂应保留原标签、注明状态并单独存放，便于识别和处置。"},{"id":1916,"ch":10,"t":"s","q":"破碎玻璃器皿应（　）","o":["直接丢入生活垃圾袋","放入专用耐扎容器或厚纸包裹并标注","堆放在走廊","用水冲入下水道"],"a":"B","e":"碎玻璃须放入耐扎容器或包裹标注，防止刺伤清运人员。"},{"id":1917,"ch":10,"t":"s","q":"锐器盒的使用要求是（　）","o":["可重复使用","用普通纸盒代替","防刺穿、密封，装至规定刻度后封口","装满后用力压实"],"a":"C","e":"锐器盒应防刺穿、可密封，达到规定装量后封口转运。"},{"id":1918,"ch":10,"t":"s","q":"生物废弃物最常用的灭菌方式是（　）","o":["紫外照射30秒","酒精擦拭","冷冻","高压蒸汽灭菌"],"a":"D","e":"高压蒸汽灭菌可有效杀灭病原微生物，是生物废弃物处理的常规方法。"},{"id":1919,"ch":10,"t":"s","q":"放射性废物暂存的主要目的是（　）","o":["等待衰变至豁免水平","便于焚烧","与化学废物混合","出售"],"a":"A","e":"放射性废物应存放衰变，待活度降至豁免水平后按规处置。"},{"id":1920,"ch":10,"t":"s","q":"危险废物必须交由（　）处置","o":["任何废品收购站","有相应资质的单位","实验室自行掩埋","环卫工人"],"a":"B","e":"危险废物须交持有危险废物经营许可证的单位处置，禁止自行处理。"},{"id":1921,"ch":10,"t":"s","q":"危险废物转移联单应当（　）","o":["由产生单位自行留存即可","转移后立即销毁","只交接受单位","随废物转移全程交接并按规定保存"],"a":"D","e":"转移联单随废物全程交接，并按规定期限保存备查。"},{"id":1922,"ch":10,"t":"s","q":"实验室废液（　）","o":["可经下水道排入污水处理厂","严禁排入下水道","稀释后可排放","中和后即可排放"],"a":"B","e":"实验室废液不得排入下水道，须分类收集后交有资质单位处置。"},{"id":1923,"ch":10,"t":"s","q":"危险废物管理台账一般不包括（　）","o":["废物名称与数量","产生日期","实验步骤的详细原理","转移去向"],"a":"C","e":"台账记录废物种类、数量、日期和去向，不含实验原理。"},{"id":1924,"ch":10,"t":"s","q":"从源头减少危险废物产生的最有效措施是（　）","o":["推行微量化实验和绿色化学","增加洗涤用水","将废液混合存放","延长暂存时间"],"a":"A","e":"微量化和绿色化学从源头减少试剂用量和废物产生量。"},{"id":1925,"ch":10,"t":"s","q":"含汞废液应（　）","o":["与其他重金属废液混合","直接排放","加酸酸化","单独收集并专门处理"],"a":"D","e":"汞具有特殊毒性和挥发性，须单独收集并专门处理。"},{"id":1926,"ch":10,"t":"s","q":"含六价铬的废液应（　）","o":["直接排放","单独收集，还原后沉淀处理","与还原剂混合存放","与酸混合"],"a":"B","e":"六价铬毒性大，应单独收集，还原为三价铬后沉淀去除。"},{"id":1927,"ch":10,"t":"s","q":"酸碱废液中和时应（　）","o":["将水倒入浓酸","快速混合","缓慢将酸加入碱中并搅拌、冷却","密闭容器中混合"],"a":"C","e":"中和反应放热，应缓慢加酸、搅拌并冷却，防止飞溅和沸腾。"},{"id":1928,"ch":10,"t":"s","q":"剧毒化学废物应（　）","o":["与普通废液同柜存放","交由学生自行处理","倒入下水道","单独收集、专柜双人双锁管理"],"a":"D","e":"剧毒废物须单独收集并实行双人双锁、专柜管理。"},{"id":1929,"ch":10,"t":"s","q":"危险废物贮存场所应设置（　）","o":["装饰画","危险废物警示标识","吸烟区","食品柜"],"a":"B","e":"贮存场所须设置危险废物警示标识，提醒人员注意风险。"},{"id":1930,"ch":10,"t":"s","q":"少量废液洒落时，首先应（　）","o":["疏散人员并按预案用吸附材料处理","用水冲走","用手直接擦拭","倒入下水道"],"a":"A","e":"洒落时应先疏散人员，再按应急预案使用吸附材料处理。"},{"id":1931,"ch":10,"t":"s","q":"下列不属于危险废物的是（　）","o":["废弃有机溶剂","办公废纸","含重金属废液","过期剧毒试剂"],"a":"B","e":"办公废纸属一般垃圾，其余均具有危险特性。"},{"id":1932,"ch":10,"t":"s","q":"玻璃试剂瓶用完后，正确的处理是（　）","o":["清洗后按普通垃圾丢弃","卖给废品站","按危险废物或按学校规定回收处理","留在实验台"],"a":"C","e":"试剂瓶可能残留化学品，应按危险废物或学校规定回收处理。"},{"id":1933,"ch":10,"t":"s","q":"关于废液收集容器，下列说法正确的是（　）","o":["可兼作饮水杯","可用食品罐代替","可以开口放置","应专瓶专用，标识清楚"],"a":"D","e":"废液容器须专瓶专用并标识清楚，防止误用和混装。"},{"id":1934,"ch":10,"t":"s","q":"沾有化学试剂的滤纸、手套应（　）","o":["作为化学废弃物收集","丢入生活垃圾","冲入下水道","回收再利用"],"a":"A","e":"被化学品污染的耗材属于化学废弃物，应分类收集处置。"},{"id":1935,"ch":10,"t":"s","q":"不相容废物混合存放可能引起（　）","o":["体积减小","燃烧、爆炸或释放有毒气体","颜色变化但无危险","纯度提高"],"a":"B","e":"不相容废物接触可发生放热、燃烧、爆炸或放出有毒气体。"},{"id":1936,"ch":10,"t":"s","q":"危险废物贮存设施应做到（　）","o":["露天堆放","靠近火源","与办公区合并","防风、防雨、防渗、防晒"],"a":"D","e":"贮存设施须防风、防雨、防渗、防晒，避免污染和事故。"},{"id":1937,"ch":10,"t":"s","q":"下列废液需要单独收集的是（　）","o":["稀硫酸","碳酸钠溶液","含氰废液","蒸馏水"],"a":"C","e":"含氰废液毒性大且遇酸放出氰化氢，必须单独收集。"},{"id":1938,"ch":10,"t":"s","q":"一般实验室垃圾与危险废物（　）","o":["可混装","都按危废处理","都按生活垃圾处理","应分类收集、分别处置"],"a":"D","e":"两类废物性质不同，须分类收集并分别处置。"},{"id":1939,"ch":10,"t":"s","q":"实验室不得自行处理危险废物，是指（　）","o":["不得分类","不得焚烧、掩埋或随意倾倒","不得贴标签","不得暂存"],"a":"B","e":"禁止自行焚烧、掩埋或倾倒危险废物，须交有资质单位处置。"},{"id":1940,"ch":10,"t":"s","q":"“减量化”原则在实验设计中的体现是（　）","o":["增加试剂用量","按最小用量设计实验并回收利用","多用一次性器皿","延长反应时间"],"a":"B","e":"按最小用量设计实验并回收利用，可有效减少废物产生。"},{"id":1941,"ch":10,"t":"s","q":"废液容器密封不良的主要危害是（　）","o":["挥发物逸出污染空气并可能引发危险","增加重量","影响外观","降低pH"],"a":"A","e":"密封不良会使有毒有害蒸气逸出，污染空气并可能引发火灾或中毒。"},{"id":1942,"ch":10,"t":"s","q":"存放危险废物的柜子应（　）","o":["保持通风并远离火源、热源","密闭不透气","紧邻暖气片","放在走廊尽头"],"a":"A","e":"危废柜应通风良好并远离火源、热源，防止积聚可燃气和受热。"},{"id":1943,"ch":10,"t":"s","q":"危险废物包装容器出现破损时，应（　）","o":["继续使用","用胶带粘住","倒掉一半","立即更换并清理泄漏物"],"a":"D","e":"破损容器须立即更换，并对泄漏物进行安全清理。"},{"id":1944,"ch":10,"t":"m","q":"实验室废弃物按性质分类，通常包括（　）","o":["化学性废物","生物性废物","放射性废物","建筑装修垃圾"],"a":"ABC","e":"实验室废弃物分为化学性、生物性、放射性和锐器类及一般垃圾，建筑装修垃圾不属此列。"},{"id":1945,"ch":10,"t":"m","q":"化学废液分类收集的常见类别有（　）","o":["含卤有机废液","生活污水","不含卤有机废液","重金属废液"],"a":"ACD","e":"化学废液按含卤有机、不含卤有机、酸碱、重金属、剧毒等分类收集。"},{"id":1946,"ch":10,"t":"m","q":"废液容器标签应标明的内容包括（　）","o":["试剂市场价格","废物名称及主要成分","危险特性","产生日期和责任人"],"a":"BCD","e":"标签须写明成分、危险特性、日期和责任人，便于识别与追溯。"},{"id":1947,"ch":10,"t":"m","q":"化学废液暂存应符合的要求有（　）","o":["通风良好","与食品同柜存放","防渗防漏","远离火源和热源"],"a":"ACD","e":"暂存区应通风、防渗、远离火源热源，不得存放食品。"},{"id":1948,"ch":10,"t":"m","q":"下列混合属于不相容、严禁混存的是（　）","o":["酸与氰化物","同种废液合并","氧化剂与还原剂","酸与硫化物"],"a":"ACD","e":"酸与氰化物、硫化物以及氧化剂与还原剂混合会产生有毒气体或发生剧烈反应。"},{"id":1949,"ch":10,"t":"m","q":"含氰废液的收集与处理应注意（　）","o":["保持碱性","严禁与酸混合","单独收集","可用次氯酸钠氧化破氰"],"a":"ABCD","e":"含氰废液须碱性单独收集，禁与酸接触，可用次氯酸钠氧化处理。"},{"id":1950,"ch":10,"t":"m","q":"金属汞洒落后的处理措施包括（　）","o":["撒硫磺粉","用专用工具收集","加强通风","扫入下水道"],"a":"ABC","e":"汞洒落后应撒硫磺粉、用专用工具收集并加强通风，严禁扫入下水道。"},{"id":1951,"ch":10,"t":"m","q":"防止醚类生成过氧化物引发爆炸的措施有（　）","o":["避光密封低温保存","定期检验过氧化物","长期敞口存放","添加阻聚剂"],"a":"ABD","e":"醚类应避光密封低温保存、定期检验并添加阻聚剂，不得长期敞口存放。"},{"id":1952,"ch":10,"t":"m","q":"下列属于易爆或需特殊管理的废物有（　）","o":["氯化钠","叠氮化钠","苦味酸","白磷"],"a":"BCD","e":"叠氮化物、苦味酸和白磷均具有爆炸或自燃危险，须特殊管理。"},{"id":1953,"ch":10,"t":"m","q":"锐器与碎玻璃的管理要求包括（　）","o":["放入防刺穿容器","容器标注“锐器”","与生活垃圾混装","装满后密封转运"],"a":"ABD","e":"锐器应放入防刺穿、有标识的容器，装满密封后转运。"},{"id":1954,"ch":10,"t":"m","q":"生物废弃物的处理要求包括（　）","o":["高压蒸汽灭菌","使用专用包装并标识","与化学废液混装","灭活后按规处置"],"a":"ABD","e":"生物废弃物须专用包装标识、灭菌灭活后按规处置，不得与化学废液混装。"},{"id":1955,"ch":10,"t":"m","q":"放射性废物的管理要求包括（　）","o":["与普通垃圾混放","使用专用容器并标识","单独存放、专人管理","记录种类和活度"],"a":"BCD","e":"放射性废物须专用容器标识、单独存放专人管理并记录种类和活度。"},{"id":1956,"ch":10,"t":"m","q":"危险废物转移应符合的要求有（　）","o":["交有资质单位处置","填写转移联单","随意倾倒","执行申报登记"],"a":"ABD","e":"危废转移须交有资质单位、填写联单并执行申报登记，严禁随意倾倒。"},{"id":1957,"ch":10,"t":"m","q":"下列行为被禁止的是（　）","o":["废液排入下水道","不相容废物混装","分类收集","随意丢弃废弃试剂"],"a":"ABD","e":"废液排入下水道、混装不相容废物和随意丢弃试剂均被禁止。"},{"id":1958,"ch":10,"t":"m","q":"危险废物管理台账应包括的内容有（　）","o":["名称和类别","数量和来源","贮存和转移去向","实验教学大纲"],"a":"ABC","e":"台账应记录废物名称、类别、数量、来源及贮存转移去向。"},{"id":1959,"ch":10,"t":"m","q":"体现绿色化学与减量化的措施有（　）","o":["微量或半微量实验","增加废弃物产生","试剂回收利用","以低毒试剂替代高毒试剂"],"a":"ACD","e":"微量实验、回收利用和低毒替代均可减少废物产生与危害。"},{"id":1960,"ch":10,"t":"m","q":"剧毒废物的管理要求包括（　）","o":["单独收集","与一般废液同柜存放","双人双锁管理","专柜存放"],"a":"ACD","e":"剧毒废物应单独收集、专柜存放并实行双人双锁管理。"},{"id":1961,"ch":10,"t":"m","q":"废弃试剂及空瓶处理正确的有（　）","o":["保留原标签","直接倒入下水道","注明废弃状态","分类存放"],"a":"ACD","e":"废弃试剂应保留原标签、注明废弃状态并分类存放，不得倒入下水道。"},{"id":1962,"ch":10,"t":"j","q":"含卤有机废液可与不含卤有机废液混合收集。","o":["对","错"],"a":"错","e":"两类废液处理工艺不同，混装会增大处置难度和污染风险。"},{"id":1963,"ch":10,"t":"j","q":"化学废液可以稀释后直接排入下水道。","o":["对","错"],"a":"错","e":"实验室废液严禁排入下水道，稀释不能消除其危害。"},{"id":1964,"ch":10,"t":"j","q":"废液收集容器应留有适当空间，不得装得过满。","o":["对","错"],"a":"对","e":"留出空间可防止废液受热膨胀溢出。"},{"id":1965,"ch":10,"t":"j","q":"危险废物在实验室暂存一般不应超过一年。","o":["对","错"],"a":"对","e":"按危险废物贮存要求，贮存期限一般不得超过一年。"},{"id":1966,"ch":10,"t":"j","q":"酸性废液与含氰废液混合会释放剧毒的氰化氢。","o":["对","错"],"a":"对","e":"酸与氰化物反应生成氰化氢气体，属于典型不相容组合。"},{"id":1967,"ch":10,"t":"j","q":"金属汞洒落后可用扫帚扫入垃圾桶。","o":["对","错"],"a":"错","e":"汞洒落后应撒硫磺粉并用专用工具收集，扫入垃圾桶会造成污染扩散。"},{"id":1968,"ch":10,"t":"j","q":"白磷应保存在水中以隔绝空气。","o":["对","错"],"a":"对","e":"白磷在空气中易自燃，水封可隔绝空气。"},{"id":1969,"ch":10,"t":"j","q":"苦味酸与金属接触可生成更易爆炸的盐。","o":["对","错"],"a":"对","e":"苦味酸盐对摩擦撞击更敏感，爆炸风险更高。"},{"id":1970,"ch":10,"t":"j","q":"久置乙醚可能生成过氧化物，使用前应检验。","o":["对","错"],"a":"对","e":"醚类久置生成过氧化物，受热或摩擦易爆炸。"},{"id":1971,"ch":10,"t":"j","q":"破碎玻璃和针头可装入普通垃圾袋。","o":["对","错"],"a":"错","e":"锐器须放入防刺穿专用容器，不得混入生活垃圾。"},{"id":1972,"ch":10,"t":"j","q":"生物废弃物应先经高压蒸汽灭菌再按规处置。","o":["对","错"],"a":"对","e":"灭菌可杀灭病原微生物，是生物废弃物处理的必要环节。"},{"id":1973,"ch":10,"t":"j","q":"放射性废物应与化学废液混合存放以节省空间。","o":["对","错"],"a":"错","e":"放射性废物须单独存放，混放会增加处理和防护难度。"},{"id":1974,"ch":10,"t":"j","q":"危险废物必须交由有资质单位处置。","o":["对","错"],"a":"对","e":"危废须交持证单位处置，禁止自行焚烧、掩埋或倾倒。"},{"id":1975,"ch":10,"t":"j","q":"危险废物转移联单在转移完成后可由产生单位自行销毁。","o":["对","错"],"a":"错","e":"转移联单须按规定期限保存备查，不得自行销毁。"},{"id":1976,"ch":10,"t":"j","q":"危险废物管理台账应如实记录并保存备查。","o":["对","错"],"a":"对","e":"台账是危废管理追溯的依据，须如实记录并保存。"},{"id":1977,"ch":10,"t":"j","q":"不相容的废物可以同柜存放，只要标签清楚。","o":["对","错"],"a":"错","e":"标签清楚不能消除反应风险，不相容废物必须分开存放。"},{"id":1978,"ch":10,"t":"j","q":"实验室内可以自行焚烧少量有机废液。","o":["对","错"],"a":"错","e":"禁止在实验室内焚烧危险废物，应交有资质单位处置。"},{"id":1979,"ch":10,"t":"j","q":"废液容器可以敞口放置以便观察液面。","o":["对","错"],"a":"错","e":"敞口会导致有害蒸气逸出，废液容器必须密封良好。"},{"id":1980,"ch":10,"t":"j","q":"含汞废液可与其他重金属废液合并收集。","o":["对","错"],"a":"错","e":"汞具有特殊毒性和挥发性，须单独收集专门处理。"},{"id":1981,"ch":10,"t":"j","q":"推行微量实验有利于从源头减少废物。","o":["对","错"],"a":"对","e":"微量实验减少试剂用量，从而减少废物产生。"},{"id":1982,"ch":10,"t":"j","q":"空试剂瓶清洗后即可作为生活垃圾随意丢弃。","o":["对","错"],"a":"错","e":"试剂瓶可能残留化学品，应按危废或学校规定回收处理。"},{"id":1983,"ch":10,"t":"j","q":"危险废物暂存区应远离火源和热源并保持通风。","o":["对","错"],"a":"对","e":"通风和远离火源热源可防止可燃气积聚和火灾事故。"},{"id":1984,"ch":10,"t":"b","q":"实验室废弃物按性质一般分为化学性废物、生物性废物、放射性废物、____和一般垃圾。","a":["锐器类"]},{"id":1985,"ch":10,"t":"b","q":"含卤有机废液应与____有机废液分开收集。","a":["不含卤"]},{"id":1986,"ch":10,"t":"b","q":"废液容器标签应注明废物名称、主要成分、____和产生日期。","a":["危险特性"]},{"id":1987,"ch":10,"t":"b","q":"化学废液装入容器时不得装得过满，应留出____。","a":["适当空间"]},{"id":1988,"ch":10,"t":"b","q":"危险废物在实验室暂存的时间一般不超过____。","a":["一年"]},{"id":1989,"ch":10,"t":"b","q":"酸与氰化物废液混合会生成剧毒的____。","a":["氰化氢"]},{"id":1990,"ch":10,"t":"b","q":"金属汞洒落后常撒____以降低汞蒸气压。","a":["硫磺粉"]},{"id":1991,"ch":10,"t":"b","q":"白磷应保存在____中。","a":["水"]},{"id":1992,"ch":10,"t":"b","q":"久置的乙醚可能生成____，蒸馏前必须检验。","a":["过氧化物"]},{"id":1993,"ch":10,"t":"b","q":"破碎玻璃与针头应放入____容器。","a":["防刺穿"]},{"id":1994,"ch":10,"t":"b","q":"生物废弃物常用____灭菌。","a":["高压蒸汽"]},{"id":1995,"ch":10,"t":"b","q":"放射性废物一般先____存放，待活度降到豁免水平后按规处置。","a":["衰变"]},{"id":1996,"ch":10,"t":"b","q":"危险废物必须交由持有____的单位处置。","a":["危险废物经营许可证"]},{"id":1997,"ch":10,"t":"b","q":"危险废物转移应填写____。","a":["转移联单"]},{"id":1998,"ch":10,"t":"x","q":"简述化学废液分类收集的基本原则和主要类别。","a":"1.分类收集：按化学性质分别收集，严禁不相容废物混装。2.主要类别：含卤有机废液、不含卤有机废液、酸性废液、碱性废液、重金属废液、含氰废液、含汞废液及剧毒废液等。3.容器要求：专瓶专用、耐腐蚀、密封良好并贴标签，注明成分、危险特性和日期。4.管理要求：及时转移，交有资质单位处置。5.禁止将任何化学废液排入下水道。"},{"id":1999,"ch":10,"t":"x","q":"实验室危险废物暂存应符合哪些要求？","a":"1.场所：设专用暂存区，通风良好、阴凉干燥，远离火源、热源和办公区。2.防渗：地面做防渗处理，设置围堰或防漏托盘。3.容器：密封完好、标签清楚，不相容废物分柜存放。4.时限：暂存一般不超过一年，及时转移。5.标识：设置危险废物警示标识。6.管理：专人负责，建立台账，禁止明火和吸烟。"},{"id":2000,"ch":10,"t":"x","q":"某实验室将酸性废液与含氰废液倒入同一废液桶，试分析其危险并说明正确处置方法。","a":"1.危险分析：酸与氰化物反应生成剧毒的氰化氢气体，可经呼吸道吸收导致中毒甚至死亡；敞口或密封不良时气体会逸出，污染实验室空气，遇火还可能引发次生事故。2.正确处置：立即停止混合并疏散人员、加强通风，由专业人员佩戴防护用品处理；含氰废液应保持碱性单独收集，严禁与酸接触，可用次氯酸钠氧化破氰后再交有资质单位处置；同时追查原因，完善分类标签与培训。"}];
